CREATE TABLE IF NOT EXISTS god2_game.xjz_evidence_pack_sources (
  source_path varchar(256) NOT NULL,
  byte_length bigint NOT NULL,
  sha256 char(64) NOT NULL,
  line_count int NOT NULL,
  evidence_pack_sha256 char(64) NOT NULL,
  evidence_status varchar(64) NOT NULL DEFAULT 'CurrentClientCsv',
  packet_evidence_boundary tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (source_path),
  CONSTRAINT ck_xjz_source_boundary CHECK (packet_evidence_boundary IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='XJZ current-client evidence source registry';

CREATE TABLE IF NOT EXISTS god2_game.xjz_god_menu_evidence (
  protocol_id int NOT NULL,
  menu_category_id int NOT NULL,
  name_zh_tw varchar(128) NOT NULL,
  element_zh_tw varchar(16) NULL,
  initial_level int NULL,
  initial_vitality int NULL,
  initial_wrist int NULL,
  initial_intelligence int NULL,
  initial_speed int NULL,
  source_line int NOT NULL,
  evidence_status varchar(64) NOT NULL DEFAULT 'CurrentClientCsv',
  PRIMARY KEY (protocol_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='XJZ god menu initial-attribute evidence';

CREATE TABLE IF NOT EXISTS god2_game.xjz_combat_pet_quality_star_evidence (
  quality_level int NOT NULL,
  quality_value int NOT NULL,
  star_value int NOT NULL,
  source_line int NOT NULL,
  evidence_status varchar(64) NOT NULL DEFAULT 'CurrentClientCsv',
  PRIMARY KEY (quality_level)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='XJZ second-generation combat pet quality/star evidence';

CREATE TABLE IF NOT EXISTS god2_game.xjz_item_effect_visual_evidence (
  source_table varchar(64) NOT NULL,
  effect_key varchar(64) NOT NULL,
  rom_path varchar(256) NULL,
  rtg_path varchar(256) NULL,
  sound_index int NULL,
  category_zh_tw varchar(128) NULL,
  description_zh_tw varchar(500) NULL,
  source_line int NOT NULL,
  mechanical_semantics_status varchar(96) NOT NULL DEFAULT 'VisualOnlyServerAuthorityBlocked',
  PRIMARY KEY (source_table,effect_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='XJZ item/god-item visual effect evidence';

CREATE TABLE IF NOT EXISTS god2_game.xjz_monster_visual_evidence (
  source_table varchar(64) NOT NULL,
  visual_id int NOT NULL,
  name_zh_tw varchar(128) NULL,
  scene_rom varchar(256) NULL,
  enemy_rom varchar(256) NULL,
  ally_rom varchar(256) NULL,
  action_code varchar(32) NULL,
  palette varchar(32) NULL,
  shadow_index int NULL,
  source_line int NOT NULL,
  PRIMARY KEY (source_table,visual_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='XJZ monster scene/battle ROM visual evidence';

CREATE TABLE IF NOT EXISTS god2_game.xjz_mission_text_evidence (
  mission_id int NOT NULL,
  step_no int NOT NULL,
  mission_name_zh_tw varchar(256) NOT NULL,
  step_text_zh_tw text NULL,
  source_line int NOT NULL,
  packet_evidence_boundary tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (mission_id,step_no)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='XJZ mission text/step evidence';

CREATE TABLE IF NOT EXISTS god2_game.xjz_daily_mission_evidence (
  daily_mission_id int NOT NULL,
  branch_id int NOT NULL,
  name_zh_tw varchar(256) NOT NULL,
  start_npc_id int NULL,
  week_mask varchar(16) NULL,
  start_time int NULL,
  end_time int NULL,
  min_rebirth_level int NULL,
  max_rebirth_level int NULL,
  end_npc_id int NULL,
  intro_zh_tw varchar(1000) NULL,
  reward_text_zh_tw varchar(500) NULL,
  repeat_count int NULL,
  source_line int NOT NULL,
  PRIMARY KEY (daily_mission_id,branch_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='XJZ daily mission display/schedule evidence';
