INSERT INTO god2_game.xjz_mission_text_evidence (mission_id,step_no,mission_name_zh_tw,step_text_zh_tw,source_line) VALUES
  (1,1,'[城镇任务]城镇向导','经由枫华镇中的涂谛颂(110/110)口中得知金鳌岛的一些故事，并答应其去寻找在武器店(116/62)附近的宋焍涂。',5),
  (1,2,'[城镇任务]城镇向导','在找到宋焍涂后，该回去找涂谛颂(110/110)交差了！',6),
  (2,1,'[城镇任务]隐形人','枫华镇的田清郎(117/52)因不知名原因变成大家都看不到的隐形人，于是你答应帮他找出问题并助他一臂之力。',8),
  (2,2,'[城镇任务]隐形人','田小光(107/45)口中嚷嚷着什么都不知道，不过你总觉得事有蹊跷～看来这小鬼似乎有什么隐情～',9),
  (2,3,'[城镇任务]隐形人','你总算得到了一些讯息，看来田夫人(107/45)应该知道些什么吧！',10),
  (2,4,'[城镇任务]隐形人','田夫人(107/45)把实情告诉了你，看来你得要回去找田清郎(117/52)谈谈了。',11),
  (2,5,'[城镇任务]隐形人','田清郎(117/52)告诉你他把一个古怪的玉鼎放在截仙遗址的罗浮丘一带(625/91)，看来你可以去拿回这个玉鼎并将计就计好好教教田清郎。',12),
  (2,6,'[城镇任务]隐形人','你已经取得了田清郎所说的玉鼎，可以回去找田清郎(117/52)了。',13),
  (2,7,'[城镇任务]隐形人','你完成了田夫人的托付，可以去跟田夫人(107/45)说一声了！',14),
  (3,1,'[城镇任务]夺舍','枫华镇里有一位没有名字的人，他自称是齐慕(129/44)，而现在在齐家的齐慕其实是叫做白慕(127/73)的另一个人，你接受了这位自称是真正的齐慕的人委托去查访事情的真相。',16),
  (3,2,'[城镇任务]夺舍','你从白慕(127/73)口中得知实情，并受托回去跟真正的齐慕(129/44)说明。',17),
  (3,3,'[城镇任务]夺舍','齐慕(129/44)要你去镇上找一位吴炼(116/62)问问五行精石的下落。',18),
  (3,4,'[城镇任务]夺舍','吴炼(116/62)要你取来三块褐蜗螺的肉和一根鹤羽才肯帮你炼化五行精石。',19),
  (3,5,'[城镇任务]夺舍','你已取得五行精石，可以去找白慕(127/73)了。',20),
  (3,6,'[城镇任务]夺舍','你将五行精石交给了白慕(127/73)，赶快去跟齐慕(129/44)说这个消息吧！',21),
  (4,1,'[城镇任务]凌氏父子','凌云今年二十，其父凌霄天为枫华镇有名的术士，十年前为寻找当年截教仙人封印魔物之法而前往碧游宫后一去不返，十年后其子习法有成，想承父之志并找寻父亲下落，然亦是一去不返，其母华氏在家以泪洗面，你由镇长夫人口中得知此事后决定前往凌家探视华氏并给予适当的协助。',23),
  (4,2,'[城镇任务]凌氏父子','凌夫人哭诉着儿子凌云为了寻找父亲也去了碧游宫，看来你有必要前往碧游宫一趟了。',24),
  (4,3,'[城镇任务]凌氏父子','你救活了凌云，并得知凌霄天仍活着且人在碧游宫第一层，凌云拜托你将一个玩偶交给凌霄天。',25),
  (4,4,'[城镇任务]凌氏父子','你被发狂中的凌霄天攻击，但是你发现他的眼神似乎对手上的玩偶有着一股亲切感，你决定再一探究竟。',26),
  (4,5,'[城镇任务]凌氏父子','你成功的让发狂中的凌霄天恢复神智，看来凌云和凌霄天还活着的消息一定能让凌夫人非常高兴的。',27),
  (5,1,'[城镇任务]镇长的心愿','枫华镇长年事已高，欲寻找接任人选，在得知你成功的帮助了田家后，决定请你由风平、华延、郑楠三人中推荐一名适合人选。',29),
  (6,1,'[城镇任务]传说的仙人','枫华镇的段岚(136/56)为了其父亲的病情而闷闷不乐，你答应他前往截仙遗迹的天云洞找寻传说中的仙人(202/195)。',31),
  (6,2,'[城镇任务]传说的仙人','你找到了段岚口中的人，但这名老者表示他并非仙人，看来你得要把这失望的消息带回去给段岚(136/56)了。',32),
  (7,1,'[城镇任务]金鳌牌坊','你接受了枫华镇曹大娘(71/60)的委托，要把三条兔尾巴送去金鳌牌坊给他丈夫曹尔(602/88)。',34),
  (7,2,'[城镇任务]金鳌牌坊','你已经把兔尾巴交给了曹尔，而他也请你帮忙把三个狐爪送回去给曹大娘(71/60)。',35),
  (8,1,'[城镇任务]挖宝三人组','昆吾镇的吴夫人拜托你前往枫华镇找寻她的三个儿女（吴娃、吴豪、吴宝）。',37),
  (8,2,'[城镇任务]挖宝三人组','你在枫华镇找到了吴娃，并得知吴豪人在截仙遗址的蟠龙湖一带。',38),
  (8,3,'[城镇任务]挖宝三人组','你找到了吴豪并协助他打跑了魔物，可以回枫华镇找吴娃问问吴宝身在何处了。',39),
  (8,4,'[城镇任务]挖宝三人组','吴娃告诉你吴宝人在参天林，看来你可能要花点心思找找了。',40),
  (8,5,'[城镇任务]挖宝三人组','你找到了吴宝，赶快回去跟吴娃说一声吧。',41),
  (9,1,'[城镇任务]珍珠项链','葛城的富商郝冶任愿意花钱买一串珍珠项链，但却苦无头绪，只知道珍珠是枫华镇的特产之一，你答应郝冶任前往枫华镇帮他找一串珍珠项链。',43),
  (9,2,'[城镇任务]珍珠项链','你从赵大娘口中得知需要三十颗珍珠才能做一串珍珠项链。',44),
  (9,3,'[城镇任务]珍珠项链','你已经取得珍珠项链了，可以拿去给郝冶任换钱啦！',45),
  (10,1,'[城镇任务]金鳌老人','你由邓云口中得知金鳌老人的事情，并决定前往参天林找寻这名神秘的金鳌老人。',47),
  (10,2,'[城镇任务]金鳌老人','你找到了邓云口中的金鳌老人，不过老人很快就走了，看来你若想知道些其它的事，可能要多找几次吧！',48),
  (11,1,'[城镇任务]神秘商人','在葛城的客栈中你遇到了一名叫古懂商的人，并答应他找寻他在昆吾镇时被抢的宝物，目前唯一的线索就是店小二口中的消息。',50),
  (11,2,'[城镇任务]神秘商人','你从店小二口中得知昆吾镇一带有个姓张的劫匪，或许在昆吾镇有什么线索。',51),
  (11,3,'[城镇任务]神秘商人','你从张雁口中得知昆吾镇西方有一名抢匪名唤张燕，看来他应该就是抢劫古懂商的人了。',52),
  (11,4,'[城镇任务]神秘商人','你取回了古懂商被抢的宝物，可以回去交差了。',53),
  (12,1,'[城镇任务]拯救神兽','你答应了葛城的白云子的要求，帮忙人在葛城西方的赤楠子渡过难关。',55),
  (12,2,'[城镇任务]拯救神兽','赤楠子请你前往曲湖找他师兄赤青子取回一样物品，以解除天笑道人的妖法。',56),
  (12,3,'[城镇任务]拯救神兽','你已由赤青子手中取得镇天符，快拿去给赤楠子吧！',57),
  (13,1,'[城镇任务]搜宝神偷','葛城最近的治安不太好，有许多大户都遭了小偷，你接受了葛员外(131/204)的委托找回失物，唯一的线索就是钱员外(69/179)和李员外(101/234)曾派人外出探访此事。',59),
  (13,2,'[城镇任务]搜宝神偷','你从钱员外口中得知李员外曾派人前往寻找，或许可以去问问李员外(101/234)。',60),
  (13,3,'[城镇任务]搜宝神偷','李员外告知你可以前往南原部落找李管家(116/100)，应该能有进一步的消息。',61),
  (13,4,'[城镇任务]搜宝神偷','李管家告诉你小偷胡飞人在北圣原一带(324/84)，抢夺钥匙的事就靠你了！',62),
  (13,5,'[城镇任务]搜宝神偷','你从胡飞手中取得钥匙，现在要做的就是前往曲湖的某一间屋子里找寻胡飞的假人宝箱(271/488)取回被偷的东西了。',63),
  (13,6,'[城镇任务]搜宝神偷','你已取回被偷的东西，可以回去找葛员外(131/204)交差了！',64),
  (14,1,'[城镇任务]城镇寻宝','你答应了昆吾镇的燕三郎(119/167)找回他被胡飞盗走的宝物，据说该物被胡飞藏在一线天壁附近的山洞，并以假人(70/92)做为掩饰。',66),
  (14,2,'[城镇任务]城镇寻宝','你已取得燕三郎所要找的宝物－夜明镜，可以回去把东西交还给燕三郎(119/167)了！',67),
  (15,1,'[城镇任务]荒岭孤魂','你答应昆吾镇外的游魂商玭要帮他去曲湖找神算子看有没有法子找回被偷走的玲珑心，让他能够顺利投胎。',69),
  (15,2,'[城镇任务]荒岭孤魂','神算子告诉你可以前往地烈阵找寻明镜道人，他应该有法子解救商玭的噩运的。',70),
  (15,3,'[城镇任务]荒岭孤魂','明镜道人给了你符水，看来商玭的噩运应该可以解脱了！',71),
  (16,1,'[城镇任务]黄昏之恋','葛城的七十老翁公孙望(95/127)当年为了求道而舍弃爱人，如今为了找寻爱人而回到葛城，你答应他前往找寻人在南原部落的孙劭(104/110)打听公孙望爱人的下落。',73),
  (16,2,'[城镇任务]黄昏之恋','孙劭要你前往曲湖边找慕容娟的妹妹慕容萍(281/385)问清事情的来龙去脉。',74),
  (16,3,'[城镇任务]黄昏之恋','慕容萍给了你慕容娟的玉佩，并告诉你事情的原委，请你把玉佩交给公孙望(95/127)。',75),
  (17,1,'[城镇任务]迷穴救赎','你答应了昆吾镇的李木樵委托，前往八卦石洞找寻他的儿子李小文。',77),
  (17,2,'[城镇任务]迷穴救赎','李小文告诉你他需要熊掌和昆吾镇莫大夫的独门秘方续凝胶，你应该可以帮他找来的吧～',78),
  (17,3,'[城镇任务]迷穴救赎','你已经取得了续凝胶，只要有了熊掌就可以去找李小文了！',79),
  (18,1,'[城镇任务]正邪悬念','昆吾镇的小铃求你去找金爷爷，帮忙解除木道人身上的诅咒。',81),
  (18,2,'[城镇任务]正邪悬念','金爷爷告诉你木道人就在镇外西方不远的小蛟河附近，或许你可以去找木道人看能不能帮助他。',82),
  (18,3,'[城镇任务]正邪悬念','木道人把赤钱剑交给了你，请你拿去找曲湖的赤青子帮忙。',83),
  (18,4,'[城镇任务]正邪悬念','赤青子为赤钱剑加持了镇魂符的法力，有了这个，木道人就有救了。',84),
  (18,5,'[城镇任务]正邪悬念','你已经解救了木道人，看来小铃会很开心的。',85),
  (19,1,'[城镇任务]修道三矶','昆吾镇的神矶子认为你俱有不平凡的天命，为了证明他的说法，他请你前往一线天壁找寻他的师兄玄矶子以印证他的卜卦是否正确。',87),
  (19,2,'[城镇任务]修道三矶','你成功的找到了玄矶子，他并交给你一个硫璃水晶要你带回去交给他的师弟神矶子。',88),
  (20,1,'[城镇任务]寻道学艺','你在金光阵遇到了神矶子的大师兄天矶子，他要你去攀龙山道找他的化身，并取回一样信物。',90),
  (20,2,'[城镇任务]寻道学艺','天矶子化身交给你一个水晶符令，要你拿回去给天矶子。',91),
  (21,1,'[城镇任务]天翎居士','在通过了天矶子的考验之后，神矶子请你去见他的师父天翎居士。',93),
  (22,1,'[城镇任务]代商运货','你答应帮人在葛城(200/120)和昆吾镇(154/133)间运送货物以换取些许的酬劳。',95),
  (23,1,'[城镇任务]环岛寻人','你参加了在葛城举办的寻人活动(209/102)，内容是找寻躲藏在圣樵原野和雨龙森林的十个人(葛城)(155/213)、(葛城)(54/64)、(南原部落)(64/113)、(北原部落)(516/197)、(龙口码头)(88/58)、(暮月聚落)(80/56)、(弄月巨木)(697/385)、(摘云巨木)(168/469)、(蛟龙口)(764/234)、(神木集)(123/68)，在取得信物后前往昆吾镇找主办人(185/120)换取奖品。',97),
  (24,1,'[城镇任务]化血迷阵','昆吾镇福老翁其子为人英勇，为求取成仙的机会而去闯各个上古阵法，最后死于化血阵中，福老翁说如果有人能通过化血阵，则将会赠予家传宝物，也算是报了丧子之怨。',99),
  (25,1,'[城镇任务]四神杖','昆吾镇的秦白月请你帮忙从躲藏在雨龙森林里的江红红、林绿绿、孟紫紫、何蓝蓝四人手中取回四神杖。',101),
  (26,1,'[城镇任务]回天有术','你答应了昆吾镇的黄连火找回他的家传宝典，目前唯一线索是东西是在幽原一带被抢的。',103),
  (26,2,'[城镇任务]回天有术','你虽然取得了钥匙，但还是没问到宝典的下落，这可如何是好？真不知该怎么向黄连火交待了！',104),
  (27,1,'[城镇任务]神秘法物','你答应金万丈帮他找来四样物品，分别是真绢、命石、天玉、子烛，你打算先从各个城镇下手找起。',106),
  (27,2,'[城镇任务]神秘法物','你已经找到了真绢，看来接下来应该换个地方找找其它三样东西。',107),
  (27,3,'[城镇任务]神秘法物','命石也被你找到了，剩下两个，看来离目标不远了！',108),
  (27,4,'[城镇任务]神秘法物','就剩下最后一样了，只要找到玉烛就能交差了！',109),
  (27,5,'[城镇任务]神秘法物','四样东西都齐了，是时候回去找金万丈了！',110),
  (28,1,'[城镇任务]流浪三人组','你自葛城的刘家药僮口中得知流浪三人组的消息，但是这药僮要你给他五条兔尾巴才肯告诉你下落。',112),
  (28,2,'[城镇任务]流浪三人组','药僮告诉你他的主人叫刘三祖，他是个商人，所以常往返于葛城和昆吾镇，你要想知道流浪三人组的下落，就要先找到刘三祖。',113),
  (28,3,'[城镇任务]流浪三人组','根据刘三祖口述，流浪三人组在地烈阵中，这可是你花了一千两买来的消息啊！',114),
  (29,1,'[城镇任务]谜之圣者','你在认识了北原部落的谜圣后，决定向他挑战诗谜，不过在这之前，你要先找到并答对他的四个弟子谜天、谜地、谜人、谜空的诗谜才行。',116),
  (30,1,'[城镇任务]百戏艺人','你在葛城遇到了百戏艺人(214/180)，他说只要你完成了他的要求，就是找来鸭毛、兔耳朵和狐牙，他就教你一些戏法。',118),
  (31,1,'[主线剧情任务]仙鹤道僮','你答应枫华镇的仙鹤道僮要完成他所出的考验，首先就是找涂谛颂(110/110)取得枫华镇地图，等完成了再回来找仙鹤道僮吧！',120),
  (31,2,'[主线剧情任务]仙鹤道僮','仙鹤道僮要你去取来一块绒毛鸭的肉和一颗绒毛鸭的蛋。',121),
  (31,3,'[主线剧情任务]仙鹤道僮','元始天尊要你先去找枫华镇的仙鹤道僮(119/119)看看有什么事要交办的。',122),
  (31,4,'[主线剧情任务]仙鹤道僮','仙童在你由狗洞下凡时嘱咐你千万记得去找枫华镇的仙鹤道僮(119/119)。',123),
  (31,5,'[主线剧情任务]仙鹤道僮','仙鹤道僮觉得你身手还不够，要求你先去练练，等过阵子成长了些再来找他。',124),
  (31,6,'[主线剧情任务]仙鹤道僮','根据指示，如果你要了解自己的使命，首先要先去找果力村的仙华僮子(110/114)将你送回到枫华镇，再找枫华镇的仙鹤道僮(119/119)看看有什么事要交办的。',125),
  (32,1,'[主线剧情任务]巨林圣殿','仙鹤道僮(119/119)要你去一趟巨林圣殿找树人族长(212/510)，并接受其试炼，他才会承认你确实有能力离开金鳌岛去冒险。',127),
  (32,2,'[主线剧情任务]巨林圣殿','树人族长告诉你要先取得参北之境的参北长老(223/54)和在四方台的四方长老(251/849)其中任一位的认可才能向圣灵挑战。',128),
  (32,3,'[主线剧情任务]巨林圣殿','参北长老要求你取来五根木材和五条藤蔓才愿意认可你的能力。',129),
  (32,4,'[主线剧情任务]巨林圣殿','四方长老要求你取来五片树叶和五条树根才愿意认可你的能力。',130),
  (32,5,'[主线剧情任务]巨林圣殿','参北长老已认可你的能力，你可以回去找树人族长(212/510)了。',131),
  (32,6,'[主线剧情任务]巨林圣殿','四方长老已认可你的能力，你可以回去找树人族长(212/510)了。',132),
  (32,7,'[主线剧情任务]巨林圣殿','你已完成长老的认可，现在可以向圣灵(247/376)的挑战。',133),
  (32,8,'[主线剧情任务]巨林圣殿','你通过了圣灵的考验，可以再回去找树人族长(212/510)了！',134),
  (32,9,'[主线剧情任务]巨林圣殿','你已经完成了树人族长的试炼，现在就差仙鹤道僮那小鬼(119/119)的一句话了！！',135),
  (32,10,'[主线剧情任务]巨林圣殿','仙鹤道僮告诉你，等你能力更上层楼之后，可以去寻找人在南方某个城镇里的鬼童子，他会告诉你接下来的事',136),
  (33,1,'[主线剧情任务]鬼童密语','你接受了昆吾镇鬼童子的考验，要去找散布在圣樵原野及雨龙森林中的七个鬼童，并将他们的密语组成一句话告诉鬼童子。',138),
  (34,1,'[主线剧情任务]鬼王天君阵','在完成了鬼童的密语之后，昆吾镇鬼童子告诉你李艮的阴谋，希望你能阻止天君阵的启动，并且和你约在红沙阵里碰头。',140),
  (34,2,'[主线剧情任务]鬼王天君阵','鬼童子将你传送至天君阵的地点，并告知你只要依照地水火风的顺序分别击败站在该位上天君的灵体即可以破除天君阵。',141),
  (34,3,'[主线剧情任务]鬼王天君阵','你已成功打倒了站在地水火风四位上的天君，现在应该要回昆吾镇去找鬼童子了。',142),
  (34,4,'[主线剧情任务]鬼王天君阵','鬼童子对你的表现非常满意，他要你休息一下，过两天再来找他问接下来的事。',143),
  (35,1,'[主线剧情任务]鬼王使者','在天君阵之后，昆吾镇鬼童子已被李艮派人所杀，危急之时彩霞仙子将你救出，并告知你事情的原委，为了要完成鬼童子的遗愿，彩霞仙子打算要提升你的能力，不过在这之前，你得要先收集到三十颗魂魄宝珠。',145),
  (35,2,'[主线剧情任务]鬼王使者','在彩霞仙子炼化宝珠之时，你必须要先铲除几个危险人物，首先是化身成人形隐藏在葛城的骷髅鬼。',146),
  (35,3,'[主线剧情任务]鬼王使者','你已经收伏了骷髅鬼，可以去找彩霞仙子回报了。',147),
  (35,4,'[主线剧情任务]鬼王使者','第二个要收伏的就是隐藏在地烈阵中收集邪气的妖尸。',148),
  (35,5,'[主线剧情任务]鬼王使者','你已经击败了妖尸，可以再去找彩霞仙子了。',149),
  (35,6,'[主线剧情任务]鬼王使者','最后一个叫做邪童，目前人在化血阵，他也是杀害鬼童子的人，你可以藉此机会替鬼童子报仇了！',150),
  (35,7,'[主线剧情任务]鬼王使者','你成功的帮鬼童子报仇了，快回去找彩霞仙子问问接下来要做什么吧！',151),
  (35,8,'[主线剧情任务]鬼王使者','彩霞仙子将你送至天君阵，要你将天君阵眼完全封印，以完成鬼童子的遗愿。',152),
  (35,9,'[主线剧情任务]鬼王使者','你击败了鬼使并且成功的封印了天君阵眼，快把这好消息告诉彩霞仙子吧。',153),
  (35,10,'[主线剧情任务]鬼王使者','彩霞仙子要你去找葛城的华清道人，追查五华山遇袭一事的因由',154),
  (36,1,'[主线剧情任务]怨念','葛城的华清道人告诉你其洞府遭逢巨变，炼血皿险些被夺，希望你能去带炼血皿十里亭找他的师叔玄烨真人，并设法查出事情原委。',156),
  (36,2,'[主线剧情任务]怨念','玄烨真人建议你前往望潮台找寻炼气士云霞道人，或许可以找到一些端倪。',157),
  (36,3,'[主线剧情任务]怨念','云霞道人告诉你这事可能跟李艮有关，你可以去昆吾镇外的神木集找一个叫敖丙的人打听看看李艮的下落。',158),
  (36,4,'[主线剧情任务]怨念','敖丙告诉了你实情，并告诉你李艮人在地烈阵入口附近，看来你可以去找李艮问个清楚了！',159),
  (36,5,'[主线剧情任务]怨念','你已经成功打败了李艮，看来是该把这事情告诉敖丙一声。',160),
  (36,6,'[主线剧情任务]怨念','敖丙请求你去向玄烨道长借炼血皿，以炼化李艮记忆中的怨念。',161),
  (36,7,'[主线剧情任务]怨念','玄烨道人请你找来一颗魂魄宝珠，他必须向祖师爷请示才能决定是否将炼血皿借你。',162),
  (36,8,'[主线剧情任务]怨念','你已取得炼血皿，接下来就走一趟神木集去找敖丙吧！！',163),
  (36,9,'[主线剧情任务]怨念','你中了敖丙的计谋！！在千均一发之际，玄烨道人将你救了回来????',164),
  (36,10,'[主线剧情任务]怨念','在玄烨道人口中你终于得知所有的阴谋都是出自敖丙，而你现在要做的就是去找云霞道人问问有没有办法阻止敖丙的计谋了！！',165),
  (36,11,'[主线剧情任务]怨念','云霞道人告诉了你七曜龙筋索的事，而在这之前先要取得七曜神珠，而目前其中四颗神珠在魔家四将手中，而他们曾在望星巨木和摘云巨木一带出没，你先要去设法取得四颗神珠才能回来找云霞道人问其它三颗的下落。',166),
  (36,12,'[主线剧情任务]怨念','云霞道人已经查到其它三颗神珠分别在红沙阵中、金光阵中及八卦迷宫的震之境，而这三颗神珠亦已修成人形，接下来你必须要去找来这三颗神珠给云霞道人才行。',167),
  (36,13,'[主线剧情任务]怨念','云霞道人和你分别带着七曜神珠及龙筋，现在要做的就是去找玄烨道人用炼血皿炼出七曜龙筋索以克制敖丙。',168),
  (36,14,'[主线剧情任务]怨念','现在七曜龙筋索已经炼成，接下来就是交由你带这样神器去制伏敖丙了！！',169),
  (36,15,'[主线剧情任务]怨念','历经千辛万苦，你终于阻止了敖丙，最后就是回去跟玄烨道人告知这好消息了～～',170),
  (36,16,'[主线剧情任务]怨念','事情似乎愈来愈复杂，玄烨道人要你去仙波亭找姜子牙询问此事背后的隐情。',171),
  (37,1,'[主线剧情任务]金鳌仙岛','你在仙波亭答应了姜子牙的要求，将前往曲湖找乾坤智叟接受考验，以证明自己有能力接下更棘手的任务。',173),
  (37,2,'[主线剧情任务]金鳌仙岛','乾坤智叟要你取来五颗魂魄宝珠，用来召唤心魂，只要通过这个考验，即可以回去找姜子牙了！',174),
  (37,3,'[主线剧情任务]金鳌仙岛','你完成了乾坤智叟的考验，接下来就可以回去找姜子牙了！！',175),
  (37,4,'[主线剧情任务]金鳌仙岛','姜子牙送你回到了金鳌岛，并嘱咐你去枫华镇找仙太公童子一趟。',176),
  (38,1,'[主线剧情任务]十绝灵气','你在姜子牙的告知下回到枫华镇找太公童子，并得知了十绝灵气一事，于是你动身前往金鳌岛上的十绝黑洞试图阻止魔界人马取走十绝黑洞的灵气。',178),
  (39,1,'[主线剧情任务]灵聚碧游','在十绝黑洞灵气被夺之后，太公童子要你前往碧游宫阻止魔界人马将灵气传回魔界。',180),
  (39,2,'[主线剧情任务]灵聚碧游','经过连番苦战，你仍来不及阻止王豹等人的行动，你必须要赶快回去找太公童子告知这消息啊！！',181),
  (39,3,'[主线剧情任务]灵聚碧游','太公童子请你把这个消息带去给姜子牙知悉，以研拟下一步对策。',182),
  (39,4,'[主线剧情任务]灵聚碧游','姜子牙要你去找葛城的洞府神像进行转生的仪式。',183),
  (40,1,'[职业任务]剑神之路','你自昆吾镇的昆吾智叟口中得知剑神与剑魔的故事后决定探访此事真相，而线索的开端则是人兽竞技场附近的昆吾长者???',185),
  (40,2,'[职业任务]剑神之路','依据昆吾长者口述，有一名剑魂在弄月巨木一带，你可以去那儿找找～',186),
  (40,3,'[职业任务]剑神之路','你已经打败了风剑魂，风剑魂告诉你另一名剑魂在舞风巨木，看来这事还有后续～',187),
  (40,4,'[职业任务]剑神之路','由火剑魂口中得知你现在已经在某个试炼当中，下一个剑魂就在摘云巨木一带，一切的真相即将解开了！',188),
  (40,5,'[职业任务]剑神之路','林剑魂无奈的告诉你此试炼已经终结，因为最后一个剑魂已经被剑魔传人杀害了，你从林剑魂眼中看到无奈与悲愤，或许，你可以帮助这几位剑魂～～',189),
  (40,6,'[职业任务]剑神之路','林剑魂对你的勇气感到欣慰，也告诉你如果想找到剑魔传人，或许到葛城找一位圣樵姑可以打听出一些消息。',190),
  (40,7,'[职业任务]剑神之路','圣樵姑说要知道剑魔传人的下落，首先要先帮她找来熊掌和穿山甲的皮才行。',191),
  (40,8,'[职业任务]剑神之路','圣樵姑推算出剑魔传人应该在红沙阵当中，看来要想帮剑魂报仇，你必须要走一遭了～',192),
  (40,9,'[职业任务]剑神之路','你终于击败了剑魔传人，看他的表情，似乎有什么话要说吧！',193),
  (41,1,'[职业任务]仙鹤童子','你接受了葛城仙鹤童子的考验，首先要先去南原部落附近找一头会讲话的牛带回一句口讯???',195),
  (41,2,'[职业任务]仙鹤童子','那一头会讲话的怪牛说”风中神牛”就是仙鹤童子要你带回的口讯。',196),
  (41,3,'[职业任务]仙鹤童子','你已经告诉仙鹤童子口讯了，看来是该问问他接下来要做什么来着。',197),
  (41,4,'[职业任务]仙鹤童子','仙鹤童子要你去望星巨木找紫羽仙子，并取回一样物品。',198),
  (41,5,'[职业任务]仙鹤童子','紫羽仙子要你先帮她找来两根鹤羽才肯把东西给你。',199),
  (41,6,'[职业任务]仙鹤童子','你从紫羽仙子手中取得了疗伤药，看来就是要送这东西给仙鹤童子了！',200),
  (41,7,'[职业任务]仙鹤童子','仙鹤童子告诉你去仙靴台找一位秦完，其乃是天君本体，通过他的考验再回来吧！',201),
  (41,8,'[职业任务]仙鹤童子','你已通过秦完的考验，可以回去找仙鹤童子了！',202),
  (42,1,'[职业任务]神医药王','你自神木集的药僮口中得知神医药王一事，药僮答应你只要找来三张熊皮就告诉你其它消息???',204),
  (42,2,'[职业任务]神医药王','药僮建议你前往观汐台一带找人问问“神医药王”的下落。',205),
  (42,3,'[职业任务]神医药王','你跟这名老人说明了来历，或许他知道些什么，应该要再向他打听打听。',206),
  (42,4,'[职业任务]神医药王','这名老者请你把熊掌送去给昆吾镇的妙手大夫，等你回来再告诉你药王的下落。',207),
  (42,5,'[职业任务]神医药王','你已经完成老人的托付，可以回去找他了！',208),
  (42,6,'[职业任务]神医药王','老者告诉你药王说，只要你找来返气药和疗伤药即会见你。',209),
  (43,1,'[职业任务]阴阳使者','你在葛城遇到了圣童子，并得知阴阳使者一事，于是决定动身前往昆吾镇找圣樵老人询问有关阴阳使的事???',211),
  (43,2,'[职业任务]阴阳使者','圣樵老人告诉你古书的秘密，并得知秘密的关键在诗偈「日阴月阳，乾坤对换，日月作引，四字成行；一见日月，时序倒转，阴阳为引，乾坤再换」之中，而要解开这其中奥妙就要先到华岳谷地一带找到阴阳使者才行。',212),
  (43,3,'[职业任务]阴阳使者','你答出了诗偈中的秘密，阴阳使者将你送到了日月圣使面前，看来接下来的关键仍不脱古书中的诗偈「日阴月阳，乾坤对换，日月作引，四字成行；一见日月，时序倒转，阴阳为引，乾坤再换」。',213),
  (43,4,'[职业任务]阴阳使者','日月圣使在你答出秘语后竟将你传到了圣童子面前，看来这个童子不是一般人物哦～',214),
  (43,5,'[职业任务]阴阳使者','在得知童子的身份及解开古书的秘密之后，或许你该走一趟昆吾，把这消息告诉圣樵老人一声。',215),
  (44,1,'[新手任务]基础知识','透过元始天尊的指示学习仙界传基础规则操作。',217),
  (45,1,'[新手任务]赤色仙花','伙房师傅请你去药草园帮忙摘取仙花(140/87)。',219),
  (46,1,'[新手任务]偷摘赤色仙花','直接摘取赤色仙花，不知会有怎样的后果???',221),
  (47,1,'[新手任务]浇水训练','药草师傅给予玉壶，要你协助帮药草园里的五色草丛浇水???',223),
  (48,1,'[新手任务]合成训练','现在去昆仑仙界东南方的恭读房找合成师傅学习合成知识吧！',225),
  (48,2,'[新手任务]合成训练','向武锻师傅(153/157)学习生活技能的基本常识及合成方法。合成的方法便是将师傅给的合成道具龙麟、玄铁分别拖曳到合成接口之中，再按下合成钮即可。',226),
  (48,3,'[新手任务]合成训练','向防锻师傅(153/162)学习生活技能的基本常识及合成方法。合成的方法便是将师傅给的合成道具玄蚕寒丝、破损铠甲分别拖曳到合成接口之中，再按下合成钮即可。',227),
  (48,4,'[新手任务]合成训练','向丹锻师傅(153/174)学习生活技能的基本常识及合成方法。合成的方法便是将师傅给的合成道具血玉髓、碧水珠分别拖曳到合成接口之中，再按下合成钮即可。',228),
  (48,5,'[新手任务]合成训练','向法锻师傅(153/179)学习生活技能的基本常识及合成方法。合成的方法便是将师傅给的合成道具凤羽、水银分别拖曳到合成接口之中，再按下合成钮即可。',229),
  (49,1,'[新手任务]扫地训练','扫地师傅把玉扫交付给你，要你扫大门外树木附近那些调皮又爱乱跑的仙树叶片并将收集到的树叶交给她。',231),
  (50,1,'[新手任务]战斗训练','高大威猛的拳头师傅教导仙界传相关战斗知识及进行战斗训练，不过在过招前他要你先去找在他旁边的仙童。',233),
  (50,2,'[新手任务]战斗训练','拿到了战宠，回去找拳头师傅吧。',234),
  (50,3,'[新手任务]战斗训练','现在可以前往位在昆仑仙界北方的练功房找拳头师傅进行战斗训练了。',235),
  (51,1,'[神仙任务]探望张奎','你答应了高兰英去张奎庙(428/381)找张奎，高兰英说如果没有记错的话，张奎庙的位置应该是在枫华镇和碧游宫之间，不过以高兰英这急惊风的个性，难保不会有忘记的事情。',237),
  (51,2,'[神仙任务]探望张奎','果然和你猜想的一样，高兰英一心急着想去张奎庙(428/381)找张奎，却忘记了要带的东西，不过她毕竟还是位仙人，想变出个代替品来用用，于是她给了你一张配方表，要你去帮她找找这配方表上的东西，你在想如果你没记错的话，枫华镇上似乎有位原料商人(89/84)，他那边应该有这些东西的情报才对。',238),
  (51,3,'[神仙任务]探望张奎','虽然如你所预料的一样，高兰英一心急着想去张奎庙(428/381)找张奎，忘记了要带的东西，但是你却也和她一言不合的吵了起来。不过即使如此，她还是给了你一张配方表，看来她似乎还没有很生气的样子，但是她也不打算告诉你其他的消息了，你在想如果你没记错的话，枫华镇上似乎有位原料商人(89/84)，他那边应该有这些东西的情报才对。',239),
  (51,4,'[神仙任务]探望张奎','你不死心的再去追问高兰英其他的情报，经过了几次的对谈后，你也清楚的了解高兰英的个性并非是位不讲理的神仙，只要够爽快不啰唆，她也不会刁难你。她吩咐你去枫华镇上找原料商人(89/84)问看看，帮她找到她要的那些素材。',240),
  (51,5,'[神仙任务]探望张奎','你帮高兰英找到了她要的素材，你看见高兰英满脸笑意的收下那些素材，并且将这素材收于手上。没多久，那些素材逐渐融合成一体，依高兰英的意思炼制出了一支发钗，你瞧见高兰英望着这发钗傻笑，心里只是一阵发毛。接下来你想应该是要去张奎庙(428/381)见见张奎了，不过不知道高兰英这急性子会不会又误事??????',241),
  (51,6,'[神仙任务]探望张奎','虽然你帮高兰英找到了她要的东西，可是因为你太过于贪心，导致高兰英对你的反感，于是你和她大吵了一架，甚至大打出手。打虽打，但是高兰英似乎还愿意原谅你，她把东西交给你，接下来你想应该是要去张奎庙(428/381)见见张奎了，不过不知道高兰英这急性子会不会又误事??????',242),
  (51,7,'[神仙任务]探望张奎','虽然你和高兰英还是见面就吵，不过感觉上已经没有那样针锋相对的气氛，取而代之的反而像是拌嘴那样，也许这会是好的开始吧。接下来你想应该是要去张奎庙(428/381)见见张奎了，不过不知道高兰英这急性子会不会又误事??????',243),
  (51,8,'[神仙任务]探望张奎','你为了日后的合作而向高兰英道歉，高兰英也很爽快的接受你的歉意，并且收下你帮她找的素材炼制出了一支发钗，你瞧见高兰英望着这发钗傻笑，心里只是一阵发毛。接下来你想应该是要去张奎庙(428/381)见见张奎了，不过不知道高兰英这急性子会不会又误事??????',244),
  (51,9,'[神仙任务]探望张奎','不可避免的，你和高兰英又吵了起来，你在猜想也许是你和高兰英八字不合吧，总是一见面就吵，而且越吵越凶。不管怎么样，高兰英还是愿意让你继续帮她办事，接下来你想应该是要去张奎庙(428/381)见见张奎了，不过不知道高兰英这急性子会不会又误事??????',245),
  (51,10,'[神仙任务]探望张奎','你心里只想到为这办事少根筋，吵架比人凶的高兰英感到悲哀。现在总算可以带齐东西去见张奎(428/381)了吧，你是这么想的，不过天晓得高兰英这少根筋的女人会不会又出什么乱子??????',246),
  (51,11,'[神仙任务]探望张奎','你还是跟高兰英闹翻了，也许是心中还存有一丝的悔意吧，高兰英也不再对你说什么了，你在想不知道高兰英会不会愿意原谅你。再去和她谈谈好了，这次就稍微低头吧，你心里是着么想着的??????',247),
  (51,12,'[神仙任务]探望张奎','你低着头向高兰英道歉，高兰英也爽快的接受你的歉意，她给了你一张素材的配方表，希望你去帮她找她上面写的那些素材。你在想如果你没记错的话，枫华镇上似乎有位原料商人(89/84)，他那边应该有这些东西的情报才对。',248),
  (51,13,'[神仙任务]探望张奎','你看得出来，高兰英虽然满脸不悦，不过还是让你继续帮她工作，看来她还没有完全的厌弃你。她给了你一支发钗，接下来你想应该是要去张奎庙(428/381)见见张奎了，不过不知道高兰英这急性子会不会又误事??????',249),
  (51,14,'[神仙任务]探望张奎','不知道为什么，高兰英这次居然没继续和你吵起来，也许是她也厌倦了吧，你是这样猜想着。她给了你一支发钗，接下来你想应该是要去张奎庙(428/381)见见张奎了，不过不知道高兰英这急性子会不会又误事??????',250),
  (51,15,'[神仙任务]探望张奎','没想到千算万算就是没算到高兰英还有一件东西忘记带给张奎了。这张奎看来相当的神经质，也许是一个人在这破庙中住久了的关系吧？你是这样猜想的。不过现在既然张奎生气了，他也不打算理睬你，看来只好向高兰英说说情况了??????',251),
  (51,16,'[神仙任务]探望张奎','你将高兰英的手帕交给了张奎，对于张奎那样娘娘腔的表现，你也感到相当的讶异。为什么堂堂一位大男人，表现出来的动作却是这样的扭扭捏捏？你始终百思不得其解，不过既然完成了高兰英交代你办的事情，接下来你应该做的，应该就是向你背后的神灵高兰英复命了。',252),
  (51,17,'[神仙任务]探望张奎','你没答应张奎这娘娘腔的要求，张奎也因此闹起了脾气来，看来他似乎暂时不想理睬你，看来只好向高兰英说说情况了??????',253),
  (52,1,'[神仙任务]恶梦','武吉作梦梦到以前不小心打死人的景象，心中不安，希望你带他去枫华镇姜子牙庙(65/57)中询问一下姜子牙的意见???',255),
  (52,2,'[神仙任务]恶梦','你将从庙公那抽来的签给了姜子牙看，姜子牙说这是支下下签，并且也提到了武吉与枫华镇内的守门队长(60/77)还有场恩怨未了。看来一场冲突是在所难免了，不过即使如此，你知道武吉和姜子牙都不希望这件事情会是以流血的场面来作结束??????',256),
  (52,3,'[神仙任务]恶梦','你听从姜子牙的建议，从庙公那抽出了一支签来，不知道为什么，你总有预感这签不会是什么好东西。不过不管怎么样，总还是得让武吉安心。将这支签交给姜子牙解读看看吧??????',257),
  (52,4,'[神仙任务]恶梦','在前往枫华镇姜子牙庙的路上，你遇到了枫华镇守门队长的骚扰，这醉汉一直缠着你，并且对你不断的挑衅。你最后终于忍受不了他的挑衅，和他大打出手。但一般凡人又岂会是你的对手，打没几回合，守门队长就被你给打死了，这和武吉前几天作的恶梦不谋而合。你心里想到了要和武吉或是姜子牙(65/57)谈谈这件事情，不知道他们会有什么样的反应??????',258),
  (52,5,'[神仙任务]恶梦','你在庙公手中抽得一支签后，并没有马上将这支签交给姜子牙解读，出门后就遇到了守门队长这醉汉的纠缠挑衅，而你也不小心失手将他打死，这和武吉前几天作的恶梦不谋而合。你心里想到了要和武吉谈谈这件事情，不知道他会有什么样的反应??????',259),
  (52,6,'[神仙任务]恶梦','虽然守门队长这醉汉不断的纠缠你挑衅你，但是你以柔软的姿态来回应守门队长的挑衅，在付出一点金钱作为代价后，守门队长决定放过你，继续喝他的酒去。也许逃过了一劫吧？你心里是这样想的，不过还是得要和武吉谈谈这件事，也许在你无心之间，已经帮武吉解除了心结也不一定??????',260),
  (52,7,'[神仙任务]恶梦','虽然你已经付钱给了守门队长，但是面对守门队长需索无度的贪婪态度，你终究是压抑不住心中的怒气和守门队长爆发了冲突。而你也不小心失手将他打死，这和武吉前几天作的恶梦不谋而合。你心里想到了要和武吉谈谈这件事情，不知道他会有什么样的反应??????',261),
  (52,8,'[神仙任务]恶梦','在姜子牙不断的耳提面命，还有武吉的心声谈吐之下，你虽然知道要隐忍住守门队长的挑衅，但是无奈还是开打了起来，而你也不小心失手将他打死，这和武吉前几天作的恶梦不谋而合。你心里想到了要和武吉谈谈这件事情，不知道他会有什么样的反应??????',262),
  (52,9,'[神仙任务]恶梦','你凭借你那三吋不烂之舌来面对守门队长的挑衅，你将言词化作利剑，剑剑直刺守门队长的心，最后终于攻破他的心防。原来他一直藉酒装疯，为的就是给原本枫华镇上的人难看。但在你锐利的言词之下，也不得不逼的他低头认错，向你道歉。你成功的解决了一场街头闹剧，也成功的化解了武吉的恶梦心结。和武吉谈谈吧，他应该会很高兴你为他所作的一切。',263),
  (53,1,'[神仙任务]仇恨','张奎他用极为痛苦的神情向你表示要你前往他的庙内(428/381)一趟，也许发生了什么事情了吧？看到他的神情这么痛苦，早点去到他的庙内，问问他的木像神灵，或许就可以知道到底发生了什么事情了吧??????',265),
  (53,2,'[神仙任务]仇恨','你怀疑整件事情是庙公自导自演，所以你和张奎的决定是去找张奎庙的庙公(428/381)问个清楚???',266),
  (53,3,'[神仙任务]仇恨','所有的证据都和那姬姓的人有所关联，于是你向张奎提议，直接去找那姓姬的家伙问个清楚，虽然可能鲁莽了点，不过却也是你现在唯一能想到的方法了。张奎也对你说那姬姓之人就住在枫华镇上，不过不知道是在哪间民宅内(83/103)，现在就去找看看他的下落吧??????',267),
  (53,4,'[神仙任务]仇恨','在还不能够完全确定犯人是谁的情况下，你决定先去和姜子牙(65/57)讨论看看，你考虑到如果这东西真是姬姓子孙所有，那姜子牙应该看得出来才对，而且姜子牙社会历练高，或许他可以提供你更进一步的指导也说不定。',268),
  (53,5,'[神仙任务]仇恨','在听取完姜子牙的意见之后，你决定直接去找那姓姬的家伙(83/103)面对面对质，也许稍微鲁莽了点，不过却也是你现在所能想出的解决方法了。',269),
  (53,6,'[神仙任务]仇恨','在听取完姜子牙的意见之后，你决定去找张奎庙的庙公(428/381)谈谈这件事情，或许他有什么难言之隐也不一定??????',270),
  (53,7,'[神仙任务]仇恨','你从张奎的木像神灵手中取得了一块玉佩，他说这是那犯人仓皇之间不小心遗留下的物品，不晓得庙公那有没有捡到其他什么东西??????',271),
  (53,8,'[神仙任务]仇恨','在收齐张奎木像和张奎庙公有关犯人的证物之后，你还没拿定个主意，你在想或许应该和你身后的张奎神灵讨论看看接下来的行动???',272),
  (53,9,'[神仙任务]仇恨','你向张奎庙的庙公打听他看到的事情，并且取得了一样犯人的证物，但是在还没和张奎木像交谈了解案情的情况之前，你不愿意多加揣测其他的可能???',273),
  (53,10,'[神仙任务]仇恨','当你准备向张奎庙的庙公提出你的质疑时，那庙公借口有事急急忙忙的跑走了，这更加深你对他的怀疑程度，虽然这当中事情是有些矛盾点在，不过面对那庙公的这种态度，你也不得不怀疑他是否还隐瞒你什么。你在猜想，或许你背后的张奎神灵会知道那庙公现在的位置(85/123)。',274),
  (53,11,'[神仙任务]仇恨','在你的盘问之下，张奎庙的庙公也只能乖乖说出全部的原委。当你听完他的话后，你同意让他带走这两样证物，让他拿着去规劝他的养子回头。现在你想应该是可以去枫华镇上见见他养子(83/103)，听看看他为什么要这么做。',275),
  (53,12,'[神仙任务]仇恨','在你不断的逼问之下，庙公终于坦承这件事情是他做的，虽然事情有些矛盾也有些遗憾，但是他也已经亲口认罪，你暂时也找不出其他的证据来证明不是他做的，于是你向庙公收取了一点遮口费后，庙公便急急忙忙的跑了回去。你在想，不知道你背后的张奎神灵是怎么看待这件事实的？',276),
  (53,13,'[神仙任务]仇恨','在你不断的逼问之下，庙公终于坦承这件事情是他做的，虽然事情有些矛盾也有些遗憾，但是他也已经亲口认罪，你暂时也找不出其他的证据来证明不是他做的，于是你口头向庙公规劝了一下后，庙公便急急忙忙的跑了回去。你在想，不知道你背后的张奎神灵是怎么看待这件事实的？',277),
  (53,14,'[神仙任务]仇恨','在经过和庙公的一番对谈之后，你发现庙公在言语交谈中似乎在保护着某人的样子，于是你不打算听信他目前所说的任何话。如今只能再和你身后的张奎神灵来讨论看看下一步该怎么做了。',278),
  (53,15,'[神仙任务]仇恨','你将两样证物交给了姜子牙看，看来姜子牙似乎很有兴趣的样子，就让他看一下吧。',279),
  (53,16,'[神仙任务]仇恨','听姜子牙说犯案的应该是张奎庙公的养子才对，你在想他的养子现在就住在这枫华镇内中，要直接去找他(83/103)吗？但是你也察觉到这庙公和那养子中间似乎有着什么隐情才对，还是应该回张奎庙去问看看那庙公(428/381)比较好？这两种想法不断的在你脑中交错着???',280),
  (53,17,'[神仙任务]仇恨','你感觉到这姬姓的后代脾气实在是很差。你心里想着再和他谈一次看看好了，这次不要用这么直接的语气来试探看看???',281),
  (54,1,'[神仙任务]找碴','邓婵玉这小姐脾气发作了，非得找些乐子给她，否则自己日后日子难过，哪咤(138/47)，委屈你了???',283),
  (54,2,'[神仙任务]找碴','在你被哪咤轰你出庙外后，你和邓婵玉在心有不甘的情绪驱使下，你们决定再硬闯进去哪咤庙(138/47)一次！',284),
  (54,3,'[神仙任务]找碴','对于哪咤将你轰出庙外的这件事情，邓婵玉感到相当的不高兴。这下子没能整到哪咤，反而被哪咤将了一军，原本小姐脾气就很重的邓婵玉，现在更是可怕了！她交给了你一张配方表，要你照着配方表上的需求去收集她所需要的素材，如果你没记错的，在枫华镇客栈旁有位原料商人(89/84)，他那边或许有这些东西的情报也不一定。',285),
  (54,4,'[神仙任务]找碴','当你将素材都交给邓婵玉之后，邓婵玉三两下就炼制出她的独门法宝─五彩石！看来她是准备要用这五彩石来打哪咤吧，可怜的哪咤(138/47)???',286),
  (54,5,'[神仙任务]找碴','邓婵玉识破了你和哪咤的诡计，而你也坦承不晦，并且寻求邓婵玉的原谅。邓婵玉很大方的原谅了你的行为，并要求你现在再回去哪咤庙(138/47)内将哪咤打的落花流水。',287),
  (54,6,'[神仙任务]找碴','你实在是不明白为什么邓婵玉看到锁链和蜡烛后神情就会显的如此的害怕和紧张，不过你可以确定只有一件事情，就是你已经丧失了邓婵玉对你的信任了。虽然你不是很在乎，但是现在的你只想快点去枫华镇找哪咤(138/47)讲这件事情，你相信哪咤听了这件事情后一定会很开心的。',288),
  (54,7,'[神仙任务]找碴','你没想到进入了哪咤庙之后，竟然被哪咤识破你前来的意图，只见到哪咤舞起他的火尖枪后你和邓婵玉就被轰出庙外了。现在应该要和邓婵玉商讨一下该怎么对付哪咤吧？你是这样想的，不过此一同时你也想到依邓婵玉这小姐脾气，突然被来个这么一下子，她的脸色恐怕会更难看吧。',289),
  (54,8,'[神仙任务]找碴','经过一番苦战，你总算是战胜了由哪咤的火尖枪所召唤出的生物了！同时也把火尖枪给收了起来，看到哪咤气的跳脚的样子，你也能稍微体会到为什么邓婵玉会这么喜欢整哪咤了。现在把这火尖枪给邓婵玉看看，她应该会高兴才对。',290),
  (54,9,'[神仙任务]找碴','你接受了哪咤要反整邓婵玉的提议，哪咤要你准备一点东西来给他，你在想如果你没记错的，枫华镇客栈旁边有位原料商人(89/84)，或许可以从他身上得知哪咤要的东西的情报吧???',291),
  (54,10,'[神仙任务]找碴','当你向哪咤现出了五彩石之后，你见到哪咤从原本毫不在乎吊儿啷当转变成害怕与惊慌的神情。再经过一番激战后，你成功的打败了由哪咤和黄天化的法宝所召唤出来的生物，也将这两把武器从哪咤手中给收走了。这下子邓婵玉应该是乐歪了才对，因为你不只是让哪咤痛哭流涕，还意外的发现了哪咤与黄天化的关系，这下子够让她向其他仙人说个好几天吧。',292),
  (54,11,'[神仙任务]找碴','你按照哪咤的吩咐将收集来的东西给了哪咤，哪咤便迅速的炼制出了一把看似普通的蜡烛出来，他说这东西必须要搭配一种武器来使用才能达到恶整邓婵玉的目的。虽然你不是很明白到底应该需要什么武器，但是当你看着哪咤那付鬼灵精怪的神情后，你脑中不知道为什么突然浮现出锁链的样子???',293),
  (55,1,'[神仙任务]收徒','石矶娘娘委托给你一件事，就是帮她物色适当的弟子人选，她希望你到枫华镇上面看看有没有人愿意接受石矶娘娘爱的教导。此时你就想起来枫华镇上好像有三个人曾经说过想要找个师傅的，似乎是王化宇(95/78)，李力(99/109)和鱼轩硕(116/44)三人的样子???',295),
  (55,2,'[神仙任务]收徒','经过了一番访问的过程后，你终于帮石矶娘娘寻找到三名想拜师学艺的弟子。于是石矶娘娘要你帮她寻找一些素材，她要用来炼制她的门徒之证。你在想，如果你没记错的话，在枫华镇客栈旁有位原料商人(89/84)，应该可以在那商人身上打听到那些素材的情报才对。',296),
  (55,3,'[神仙任务]收徒','石矶给了你她的门徒之证，并要求你帮她从那三位候选人中挑选一位来当作她的弟子。',297),
  (55,4,'[神仙任务]收徒','你答应了石矶娘娘的请求，入她的门下，从此之后你就是石矶的门徒了，但是因为还必须要将那些束修还给之前找的王化宇(95/78)，李力(99/109)和鱼轩硕(116/44)三位候选人，所以你很担心到时候他们会是什么样的看法???',298),
  (55,5,'[神仙任务]收徒','你帮石矶娘娘挑选那位王化宇作为石矶娘娘的入门弟子，但是因为还必须要将那些束修还给之前找的李力(99/109)和鱼轩硕(116/44)两位候选人，所以你很担心到时候他们会是什么样的看法???',299),
  (55,6,'[神仙任务]收徒','你帮石矶娘娘挑选那位李力作为石矶娘娘的入门弟子，但是因为还必须要将那些束修还给之前找的王化宇(95/78)和鱼轩硕(116/44)两位候选人，所以你很担心到时候他们会是什么样的看法???',300),
  (55,7,'[神仙任务]收徒','你帮石矶娘娘挑选那位鱼轩硕作为石矶娘娘的入门弟子，但是因为还必须要将那些束修还给之前找的王化宇(95/78)，李力(99/109)两位候选人，所以你很担心到时候他们会是什么样的看法???',301),
  (55,8,'[神仙任务]收徒','你已经替石矶娘娘决定好了弟子人选，和石矶娘娘说一下你的决定吧???',302),
  (56,1,'[神仙任务]健忘','玉鼎真人又犯了健忘的老毛病，要你到他的庙内(535/303)一趟，他有些事情要亲自问一下他那木像神灵???',304),
  (56,2,'[神仙任务]健忘','你将枫华镇药师开给黄佑的药单还有炼制成药丸所需的素材都交给了玉鼎真人，好在他的脑袋还记的住一点基本的炼丹技术，只是这药丸真能帮助的了黄佑吗？你心里不禁泛起了一丝的疑问，不过事到如今也别无他法了，只能将这药丸交给黄佑(71/47)，接着就只能看他的生命力和运气了???',305),
  (56,3,'[神仙任务]健忘','玉鼎真人的健忘还真不是普通的厉害，难怪会来这庙参拜的人会越来越少，不过当务之急，还是得先找到病人的信息才对，你心里是这么想的。就在你想到这件事情的同时，你也想到当时庙公应该在场吧，或许那位庙公(535/303)知道什么有关那位病人的事情才对???',306),
  (56,4,'[神仙任务]健忘','玉鼎真人的木像神灵在你对话的刺激下，终于想起了他还有个保险措施，就是记忆药丸，只要帮玉鼎真人找齐他要的素材后，玉鼎真人的木像神灵应该就可以想起之前的种种事情才对。你在想，如果你没记错的话，枫华镇客栈旁边好像有位原料商人(89/84)，或许他会知道这些素材的事情吧。',307),
  (56,5,'[神仙任务]健忘','就在你把制作记忆药丸所需的素材交给玉鼎真人后，玉鼎真人急忙的将这药丸炼制出来并且服下。没多久你就见到玉鼎真人的木像神灵泛起了丝丝的笑意，因为他不只恢复了记忆，而且也想起了到底谁欠了他多少债务。不过这些都不是重点，重点是他恢复记忆后将治疗黄佑的药丸给了你，现在你心里只想快点将这药丸送到黄佑那(71/47)，并祈求黄佑他要努力的撑下去，否则就白费了你一番的苦心了。',308),
  (56,6,'[神仙任务]健忘','即使你知道那庙公是位密医的事情，但你还是听信了他的话。那庙公要你帮他收集一些素材来制作药丸医治黄佑的病。你在想，如果你没记错的话，在枫华镇客栈旁有位原料商人(89/84)，或许可以从他身上探听到有关那些素材的消息才对。',309),
  (56,7,'[神仙任务]健忘','你帮庙公收集完素材后，只见他一口气将这些素材丢入火炉里烹煮，也不晓得是不是心理因素，你总觉得这么错不太妥当，不过也别无他法了。现在只能尽快的将药丸带给黄佑(71/47)，并相信这庙公所制作的药丸能帮助的了黄佑他了???',310),
  (56,8,'[神仙任务]健忘','你见到一位躺在病床上的瘦弱老人，心里不禁起了一丝怜悯的心，但是该如何帮助这名老人呢？你记得好像有听说过玉鼎真人庙的庙公是位经验丰富的药师，但是不知道该不该找他帮忙。还是该叫玉鼎想想办法，不过他那颗脑袋到底管不管用你也不敢保证。还是该问看看黄佑他自己的意思？又或是找看看有没有高等的药师神灵可以帮忙的？瞬间有太多的想法流进你的脑袋中，你无法在一时间想出一个完美的解决方法出来???',311),
  (56,9,'[神仙任务]健忘','原来枫华镇上有位药师曾看过黄佑，当你知道这件事情的时候脸上神情显的轻松不少。这样看来这件事情就简单多了，只要帮他把这些素材准备好，由玉鼎来炼制药丸应该就没问题了吧？你是这样想的。不过同时你也想到，如果你没记错的话，在枫华镇客栈旁有位原料商人(89/84)，或许他会知道有关这些素材的消息吧。',312),
  (56,10,'[神仙任务]健忘','在到处打听之下，你终于找到神农氏了，并且请求他的帮助。虽然神农氏答应了你的请求，要你帮他收集点素材来给他，不过感觉上他似乎更希望玉鼎能以自己的能力来解决的样子。不过不管如何，既然神农答应，那就绝对是万无一失。至于素材的问题，你直觉得想到了枫华镇客栈旁的原料商人(89/84)，或许他那边会有这些素材的情报吧？',313),
  (56,11,'[神仙任务]健忘','经过了一番努力，你总算是求得了神农炼制的药丸了，现在只要快点将这药丸送到黄佑(71/47)那边就应该没有问题才对。',314),
  (56,12,'[神仙任务]健忘','由于你的言语刺激，使得黄佑的病情急速加重。没多久，黄佑就咽了下最后的一口气。原本一心想救人的你，面对这种情形，也说不出什么话来。而你看着身后的玉鼎真人，他也是一脸错愕，看来也是被吓到了???',315),
  (57,1,'[神仙任务]真理？？','小敏请你救治她的父亲，去看看那女孩父亲的伤势，再和慈航道人做讨论或许会比较好一点???',317),
  (57,2,'[神仙任务]真理？？','你顺从慈航道人的意愿，将毒药给他服下，过没多久，只见慈航脸色从白变成紫在变成红色，最后变回白色后就交给你他的血清。现在只要把这血清交给小敏(91/65)就好了吧？你心里是这么想的???',318),
  (57,3,'[神仙任务]真理？？','你要求小敏必须付出一点钱来作为医药费，虽然你的做法慈航有些不认同，不过他也没多说些什么就是了。和慈航道人讨论看看医病的方法好了，你现在心里是这么想的???',319),
  (57,4,'[神仙任务]真理？？','虽然你收取了小敏高额的医疗费用，不过这一切都是为了要知道对小敏来说，她父亲在她心目中的份量有多重。你也答应了要帮助小敏，你在想，或许和慈航道人讨论一下会比较好，虽然慈航道人很有可能对你所做的举动感到不满???',320),
  (57,5,'[神仙任务]真理？？','在经过一番思量之后，你决定将这独要给小敏吃下，是因为亲子血液相通，制作出来的血清效果也会比由旁人制作出来的要好上许多。但是这代价却是小敏的生命，不能辜负小敏的一番心意，赶紧将血清给她父亲(91/65)服下吧！',321),
  (57,6,'[神仙任务]真理？？','依照慈航道人的指示，你找到了神农，并且向神农提出了你的请求。神农在答应你的请求后，给了你一张配方单，要你收集配方单上所需的素材来给他。你在想，如果你没记错的话，在枫华镇客栈旁有位原料商人(89/84)，也许可以从他那边获得一些素材方面的信息。',322),
  (57,7,'[神仙任务]真理？？','你小心翼翼的从神农手中接过了这毒药，至于要给慈航，你自己，还是给小敏服用，你正反复思索这个问题中???',323),
  (57,8,'[神仙任务]真理？？','经过你的考虑之下，你决定由自己来试毒，神农也在旁辅助你。但即使是有神农的神力加护，你还是差点命丧黄泉，由此可见这毒性之猛烈，要是给一般人服用的话则必死无疑。如今你手上所持有的，便是由你自己的血液中淬取出来的抗毒血清，赶紧把这东西拿给小敏吧。虽然你已经可以想象到小敏她的反应会如何了???',324),
  (58,1,'[神仙任务]抉择','在和崇黑虎好友苏护的后代苏信豪见过面之后，你对这枫华镇杂货铺二老板的印象还不错，但总觉得他太多礼了一点。在听完他和你以及崇黑虎诉苦之后，你们决定要去打听看看崇伯虎(134/55)那边的情形是如何???',326),
  (58,2,'[神仙任务]抉择','经过与双方的接触后，你大致了解了双方冲突的事情，在你和崇黑虎的讨论之后，你们决定要站在崇伯虎那边，去和苏信豪(86/71)进行劝说???',327),
  (58,3,'[神仙任务]抉择','经过与双方的接触后，你大致了解了双方冲突的事情，在你和崇黑虎的讨论之后，你们决定要站在苏信豪那边，去和崇伯虎(134/55)进行劝说???',328),
  (58,4,'[神仙任务]抉择','经过与双方的接触后，你大致了解了双方冲突的事情，在你和崇黑虎的讨论之后，你决定谁都不帮，但是崇黑虎却决定要好好的教训一下那两个小子。看到他现在兴致冲冲的样子，你不好也不敢阻挠他。苏信豪(86/71)和崇伯虎(134/55)，你心里在暗暗的为这两人祈祷着???',329),
  (58,5,'[神仙任务]抉择','目前的你正夹杂在崇家与苏家的恩怨之中，你不知道该帮哪边，而且你还不知道崇黑虎是怎么看待这件事情。你在想也许可以和崇黑虎讨论看看这件事情???',330),
  (58,6,'[神仙任务]抉择','你完成了苏信豪的请托后，看到崇黑虎还在为这两家的事情烦恼，于是你想听看看崇黑虎对这件事情的看法???',331),
  (58,7,'[神仙任务]抉择','由于你选择站在崇伯虎那边，所以苏信豪也听不进你对他所说的话，于是两方大打出手。结果不用看，当然是你赢了，不过却也让苏信豪对你的敌视程度大大的提高了。接着你想和崇黑虎谈谈接下来应该怎么办才好???',332),
  (58,8,'[神仙任务]抉择','虽然你选择站在崇伯虎那边，不过在金钱的利诱之下，你还是倒戈帮助苏信豪。崇黑虎对此事颇有微词，但也对你莫可奈何。接着就是回过头去对付崇伯虎(134/55)了！你心里是这样盘算着的。',333),
  (58,9,'[神仙任务]抉择','在惊慌声与求救声之下，你结束了对苏信豪的教训，不过看着崇黑虎一脸打不过瘾的神情，你突然想问看看崇黑虎现在目前的盘算。',334),
  (58,10,'[神仙任务]抉择','在和崇黑虎大哥崇侯虎的后代崇伯虎见过面之后，你对这落魄礼貌又不佳的流浪汉印象不太好，但是崇黑虎倒是不怎么在意这件事情。在听完他和你以及崇黑虎诉苦之后，你们决定要去打听看看苏信豪(86/71)那边的情形是如何???',335),
  (58,11,'[神仙任务]抉择','由于你选择站在苏信豪那边，所以崇伯虎也听不进你对他所说的话，于是两方大打出手。结果不用看，当然是你赢了，不过却也让崇伯虎对你的敌视程度大大的提高了。接着你想和崇黑虎谈谈接下来应该怎么办才好???',336),
  (58,12,'[神仙任务]抉择','虽然你选择站在苏信豪那边，不过在金钱的利诱之下，你还是倒戈帮助崇伯虎。崇黑虎对此事颇有微词，但也对你莫可奈何。接着就是回过头去对付苏信豪(86/71)了！你心里是这样盘算着的。',337),
  (58,13,'[神仙任务]抉择','由于你反过头来对付苏信豪，所以当他见到你说出那句话后除了感到诧异之外，还感到意外的愤怒！但即使是如此，他还是打不赢身为仙童以及有神灵附身的你。接着你想和崇黑虎谈谈接下来应该怎么办才好???',338),
  (58,14,'[神仙任务]抉择','由于你反过头来对付崇伯虎，所以当他见到你说出那句话后除了感到另他厌恶的背叛感之外，还有意外的愤怒！但即使是如此，他还是打不赢身为仙童以及有神灵附身的你。接着你想和崇黑虎谈谈接下来应该怎么办才好???',339),
  (58,15,'[神仙任务]抉择','在惊慌声与求救声之下，你结束了对崇伯虎的教训，不过看着崇黑虎一脸打不过瘾的神情，你突然想问看看崇黑虎现在目前的盘算。',340),
  (58,16,'[神仙任务]抉择','你完成了崇伯虎的请托后，看到崇黑虎还在为这两家的事情烦恼，于是你想听看看崇黑虎对这件事情的看法???',341),
  (59,1,'[神仙任务]瘟神','你找到了言就元一家了，也从言就元妻子手中得到了言就元的病发皮肤，现在最要紧的就是找人来帮忙检验一下这皮肤上的东西，以及病发原因。也许到附近的药师神庙中问一问会有更详细的结果吧？',343),
  (59,2,'[神仙任务]瘟神','你在枫华镇上遇到了三个古怪的家伙，看来不太像是枫华镇的人，而且旁人似乎看不见他们的样子。不过不管如何，现在还是必须先知道言就元(73/115)的病情是如何。你在想，或许应该找神农(93/273)来问看看吧???',344),
  (59,3,'[神仙任务]瘟神','虽然眼前这三人应该是瘟神的手下没错，但是你也考虑到天意不可违的仙界条例。所以你答应了那瘟神手下们的提议，去帮他们收集炼制瘟疽伞的素材。突然之间，你想到了曾经在枫华镇客栈旁有看过一位原料商人(89/84)，他那边应该有这类材料的信息才对???',345),
  (59,4,'[神仙任务]瘟神','你成功的阻止了瘟神准备荼毒凡间的预谋，虽然瘟神的手下在你离去前撂下了狠话，但是你听的出来那不过是吓吓三岁小孩的言语罢了。也许这件事情就这样结束了吧，你是这样想的。但是不知道你身后的杨任对于这件事情有着什么样的看法。',346),
  (59,5,'[神仙任务]瘟神','虽然你及时的挽救回言就元的性命，但是却败给了瘟神的手下们。经过此战之后你才知道自己与瘟神的实力上有着相当悬殊的差距，而你身后的杨任似乎也是抱持着同样的看法。你想知道杨任接下来有没有任何的打算，和他谈谈吧。',347),
  (59,6,'[神仙任务]瘟神','瘟神的三位手下在还没取得你的同意之下便强行灌输功力到你的体内，你虽然凭借着神灵护体以及平时锻炼下来的强健身体免强撑住了。当你看见这把瘟疽伞自你手中完成后，便对这散发出邪恶气息的法宝感到恐惧以及害怕，但是你还是得将这把伞交给那瘟神的三手下(132/128)才行???',348),
  (59,7,'[神仙任务]瘟神','你没想到这一切竟然都是瘟神为了要在凡间除掉你和杨任所策划出来的计谋，但是你凭借着平时锻炼出来的功力以及不屈不饶的意志，打败了瘟神的手下，但这同时，也是向瘟神提出了挑战书。你看着身后的杨任一脸不知所措的样子，不知道在想些什么。或许该问看看他的想法吧？你是这样想的。',349),
  (59,8,'[神仙任务]瘟神','你没想到这一切竟然都是瘟神为了要在凡间除掉你和杨任所策划出来的计谋，虽然你极力的抵抗，但还是禁不住那三人的连续攻击。经过此战之后你才知道自己与瘟神的实力上有着相当悬殊的差距，而你身后的杨任似乎也是抱持着同样的看法。你想知道杨任接下来有没有任何的打算，和他谈谈吧。',350),
  (59,9,'[神仙任务]瘟神','你将从神农那求来的药方交给了言就元的夫人。神农既然出手了，那就应该没问题了吧？当你在这样自言自语时你又想到一件事。问看看杨任的意见吧，如果没有意外的话，接着就要对付瘟神的三位手下了(132/128)，你是这样想的。',351),
  (59,10,'[神仙任务]瘟神','虽然有点亡羊补牢的意味在，可是看来应该还是太晚了一点，你看这身后的杨任不发一语，不知道他心中是怎么盘算着的，或许应该问看看他的意见吧？',352),
  (59,11,'[神仙任务]瘟神','你把你看到的病情还有皮肤交给了神农看，神农马上就被你拿出来的东西吓了一大跳，神农表明这很有可能是天意，而瘟神只是下凡实现天意而已。不过做事小心的神农还是给了你一瓶药，要你自己决定该怎么做。如果真是天意的话，那就不妨帮助瘟神手下们(132/128)吧。但你也不忍心见到凡人受苦，还是赶紧把这药交给言就元一家(73/115)好了。这两个想法一直在你脑海里角力着。',353),
  (59,12,'[神仙任务]瘟神','原来神农已经暗中将瘟疽伞给偷换过来了，看来即使是天意，为了不致使天下生灵涂炭，神农还是愿意挺身而出帮助凡人。但是这次并不是天意，而是吕岳假天意之名行逞凶之实。这件事情应该可以告个段落了吧，总之先和身后的杨任谈看看好了，你是这样想的。',354),
  (59,13,'[神仙任务]瘟神','虽然你输给了瘟神的手下，不过神农早已在暗中监视这整件事情的来龙去脉，并且将那瘟疽伞给偷换了过来。看来即使是天意，为了不致使天下生灵涂炭，神农还是愿意挺身而出帮助凡人。但是这次并不是天意，而是吕岳假天意之名行逞凶之实。这件事情应该可以告个段落了吧，总之先和身后的杨任谈看看好了，你是这样想的。',355),
  (60,1,'[神仙任务]怪事','在听完姜子牙的事情之后，你从姜子牙手中拿走一点柴火当作证物，不过听姜子牙说庙公(65/57)好像也发现些什么东西的样子???',357),
  (60,2,'[神仙任务]怪事','你现在手上除了有柴火和打火石这两样证物之外，还从姜子牙和庙公的口中得知这恶作剧的人只有姜子牙看的见，庙公看不见。此时你心里便联想到这人恐怕不是凡人，但是你心里还是没个主意，或许李靖会知道些什么吧，问看看他好了???',358),
  (60,3,'[神仙任务]怪事','在和太乙真人的对谈中，你发现太乙真人相当的溺爱他的徒弟哪咤，只要是提到哪咤的事情，你就会发现太乙真人的态度会突然有很大的转变。也因为如此，当你提起姜子牙的事情，和你怀疑嫌犯是哪咤后，太乙真人的脸色突然大变，并且表示不再相信你的言论，看来你暂时是无法从太乙真人那边得到更多的讯息了。不过不知道还有没有其他的神仙愿意帮你的忙???',359),
  (60,4,'[神仙任务]怪事','在和太乙真人的对谈中，你发现太乙真人相当的溺爱他的徒弟哪咤，只要是提到哪咤的事情，你就会发现太乙真人的态度会突然有很大的转变。于是你采迂回的态度，巧妙地避开了哪咤的话题，最后终于得到了太乙真人的帮助，他要你去帮他找点素材来炼制玲珑宝塔。此时你突然想起来，好像曾经在枫华镇客栈旁看过一位原料商人(89/84)，或许可以从他那得到那些素材的消息也不一定???',360),
  (60,5,'[神仙任务]怪事','你从太乙真人手中接过这玲珑宝塔，看来到时候哪咤(138/47)是绝对逃不出你的手掌心了。',361),
  (60,6,'[神仙任务]怪事','也许是天意吧，原本你不打算来到这伏羲庙的，可是当你看到伏羲时，伏羲却已经知道你来这的意图，并且早已准备好交给你一个法宝。有了这法宝，进入哪咤庙(138/47)时，哪咤是不会发现你的存在的，这样应该更容易对付他了吧???',362),
  (60,7,'[神仙任务]怪事','在获得柴火和打火石这两样证物以及和李靖讨论之后，你斩钉截铁的认定了犯人就是哪咤。当你怒气冲冲的进入了哪咤庙找哪咤理论时，你没想到哪咤除了嘴硬之外，还很冲动。你们两人一言不合就当场打了起来，好不容易你终于打赢了哪咤，但哪咤此举让李靖相当的不悦，你很想和李靖谈谈这件事情???',363),
  (60,8,'[神仙任务]怪事','你使用了伏羲给你的隐身符，偷偷的潜进哪咤庙里，听到了哪咤对自己的犯罪行为沾沾自喜，还计划准备下一次的行动。就在此时，你身后的李靖终于受不了，借用你的声音骂了出来，此举也吓到了哪咤，逼使着哪咤和你们打了起来。好不容易你终于打赢了哪咤，但哪咤此举让李靖相当的不悦，你很想和李靖谈谈这件事情???',364),
  (60,9,'[神仙任务]怪事','当你进到哪咤庙和哪咤对质时，你对哪咤嘴硬不认错的态度感到相当的火大。于是你祭出了玲珑宝塔，哪咤一见此塔便吓的屁滚尿流，但是还是硬着头皮和你打起来。最后你成功的将哪咤给封进了玲珑宝塔中，原本应该是很高兴的时候，但是你却见到李靖还是绷着那张脸不知道在想些什么事情，去问看看李靖在想些什么事吧???',365),
  (60,10,'[神仙任务]怪事','你使用了伏羲给你的隐身符，偷偷的潜进哪咤庙里，听到了哪咤对自己的犯罪行为沾沾自喜，还计划准备下一次的行动。就在此时，你身后的李靖终于受不了，借用你的声音骂了出来，同时也祭出了玲珑宝塔，哪咤一见此塔便吓的屁滚尿流，但是面对你强势的攻击，哪咤不得已也只能硬着头皮和你打起来。最后你成功的将哪咤给封进了玲珑宝塔中，原本应该是很高兴的时候，但是你却见到李靖还是崩着那张脸不知道在想些什么事情，去问看看李靖在想些什么事吧???',366),
  (61,1,'[神仙任务]寻宝','原本你还在担心要去哪里找普贤真人所说的宝物波动，没想到在枫华镇客栈中就发现到了挖宝界中拥有响铛铛名号的流浪三人组中的一人。你从他那要到了一只钥匙，接着就是要找到这宝藏的位置了，你直觉得环顾了客栈的四周，并且感觉到倒在地上的醉汉似乎有种宝藏的味道。至于为什么会有这种感觉，也许是普贤真人他所谓的第七感带给你的影响吧???',368),
  (61,2,'[神仙任务]寻宝','当你手中有了看不懂得藏宝图和不知道哪个宝箱的钥匙后，普贤真人显得相当的激动，看来他已经准备好要去寻宝了???',369),
  (61,3,'[神仙任务]寻宝','当你将你做的蠢事和浪蹈讲之后，浪蹈对你这种外行的手法感到相当的不可思议，好在他还有复制好几把钥匙，再去开一次吧???',370),
  (61,4,'[神仙任务]寻宝','原本你还在担心要去哪里找普贤真人所说的宝物波动，没想到在枫华镇中找到了挖宝界中拥有响铛铛名号的挖宝三人组中的一人。你从她那要到了一个叫寻宝器材，上面清楚的标示着离你最近的宝箱位置。但是因为你还没有任何开锁工具的缘故，所以吴娃建议你可以去找枫华镇上的董古(107/93)问看看开锁器的事情???',371),
  (61,5,'[神仙任务]寻宝','当你手中有了宝藏的寻宝器和一串开锁器后，普贤真人显得相当的激动，看来他已经准备好要去寻宝了???',372),
  (61,6,'[神仙任务]寻宝','原本你还在担心要去哪里找普贤真人所说的宝物波动，没想到在枫华镇客栈中就发现到了一位醉汉，你花了一点酒钱从他的手中换得了藏宝图。虽然看不太懂，但是普贤真人还是很兴奋。有了藏宝图接着就是要找钥匙了！突然间，你好像感应到什么的样子，你盯着客栈中的另外一人─浪蹈，你的直觉告诉你，他身上有你想要知道的信息！至于为什么会有这种感觉，也许是普贤真人他所谓的第七感带给你的影响吧???',373),
  (61,7,'[神仙任务]寻宝','原本你还在担心要去哪里找普贤真人所说的宝物波动，没想到在枫华镇中找到了一位叫做董古的老人，他提供给你一串开锁器让你去开宝箱，并且告诉你他的挖宝器具都是提供给在挖宝界拥有响铛铛名号的挖宝三人组，那挖宝三人组的老大吴娃(124/122)现在就在枫华镇中，不妨去问看看她可不可以提供宝物的信息给你吧。',374),
  (61,8,'[神仙任务]寻宝','你将误触宝箱机关的事情跟董古说了一遍，董古摇了摇头后就再给了你一把开锁器，希望这次不会再失败了！',375),
  (61,9,'[神仙任务]寻宝','由于你愚蠢的行为，导致钥匙断裂无法再使用。你想了想，大概也只能再去问看看浪蹈(93/85)他那还有没有钥匙了???',376),
  (61,10,'[神仙任务]寻宝','你解开了这宝箱中重重的谜题，在开启宝箱的一瞬间，你突然觉得很感动，也许你的挖宝第七感也随着这件事情而觉醒了吧！当你从宝箱中取出一把锋利异常的吴钩剑后，只见到你身后的普贤真人表情凝重，不知道他到底发生什么事情了???',377),
  (61,11,'[神仙任务]寻宝','由于你误触机关，导致你的开锁器被宝箱的机关给绞断无法再使用，虽然觉得很泄气，不过也只能再去问看看董古(107/93)那还有没有开锁器了???',378),
  (62,1,'[神仙任务]玩偶','你接受了枫华镇驯兽师的提议，只要帮他拔几根豹斑驹的鬃毛回来给他，他就会给你金光圣母渴望获得的豹斑驹玩偶。那驯兽师给了你一根红罗卜，要你到枫华镇南方去找看豹斑驹(370/284)、(361/503)、(295/412)的踪迹，听驯兽师讲说豹斑驹很敏感的，跑的也很快，恐怕一不小心，就会失去牠的踪迹???',380),
  (62,2,'[神仙任务]玩偶','你将豹斑驹的鬃毛交给了枫华镇的驯兽师，你对于那驯兽师对着这鬃毛又亲又闻的病态态度感到相当的恶心。在经过一阵子的缠绵之后，驯兽师马上从他的怀中取出了一只豹斑驹的玩偶给你，你迅速的接过这玩偶后就马上离开那病态的驯兽师了。将玩偶交给金光圣母吧，她应该会很高兴才对???',381),
  (62,3,'[神仙任务]玩偶','你接受了枫华镇一位美食家的提议，只要用他提供给你的绳子将豹斑驹绑回来给他的话，他就会给你一只豹斑驹的玩偶。听他说，豹斑驹的位置就在枫华镇的南方(370/284)、(361/503)、(295/412)，但是不好抓，因为豹斑驹很敏感很敏捷，跑的也很快，恐怕一不小心，就会失去牠的踪迹???',382),
  (62,4,'[神仙任务]玩偶','你将那根被豹斑驹咬烂的绳子拿给美食家看，那名美食家非但没有生气，反而很高兴。看来这世间奇怪的人还真不少。为了让你顺利的完成任务，于是那美食家又交给你一颗苹果，要你拿去喂豹斑驹(370/284)、(361/503)、(295/412)吃。虽然明眼人都看得出来这苹果好像有些问题的样子???',383),
  (62,5,'[神仙任务]玩偶','你将豹斑驹带回风华镇来给那美食家，美食家一看到豹斑驹就欣喜若狂，他赶紧从怀中取出豹斑驹的玩偶给你后眼睛就直盯着奄奄一息豹斑驹看，这举动让你觉得不太舒服，不过反正都拿到了豹斑驹的玩偶了，拿给金光圣母看看，她应该会很高兴吧???',384),
  (62,6,'[神仙任务]玩偶','你在枫华镇的南方发现到了豹斑驹的踪影，于是你跟上前去，想用红萝卜来引诱豹斑驹过来。但是这豹斑驹似乎是已经察觉到你的意图了，只咬下一口红萝卜后就马上跑走了。你听见后面的金光圣母不高兴的语气，要你马上再追过去找那该死的豹斑驹(370/284)、(361/503)、(295/412)???',385),
  (62,7,'[神仙任务]玩偶','这次你学乖了，假意慢慢的前进并用红萝卜吸引豹斑驹的注意，想趁机偷拔豹斑驹的鬃毛。但是豹斑驹还是故技重施，又咬了一口后跑走了。你又听见身后金光圣母的抱怨声，不过看来金光圣母好像玩上瘾的样子，虽然嘴巴上说气死了，但还是要你再追上去找到豹斑驹(370/284)、(361/503)、(295/412)。',386),
  (62,8,'[神仙任务]玩偶','这是你第三次的失败了，金光圣母依旧在你身后抱怨，但是看来她还是不打算放弃的样子，要你继续追上去(370/284)、(361/503)、(295/412)。反正动腿的也不是她，她爱怎么使唤就怎么使唤，你心里也是这样在埋怨金光圣母的。',387),
  (62,9,'[神仙任务]玩偶','也许这真是神兽吧，像是真有灵性一般，在知道你前来的目的别无恶意之后，那豹斑驹就再也不跑开了，要拔牠的鬃毛现在就是最好的时机！快点上吧！',388),
  (62,10,'[神仙任务]玩偶','当你在枫华镇南方顺利的发现到豹斑驹的踪迹之后，你就放慢你的脚步，打算慢慢的接近豹斑驹后，再丢出手中的绳子。只是这如意算盘还是被豹斑驹敏捷的反应给打坏了，豹斑驹把你抛出的绳子给咬的稀烂后就跑走了，在跑走的过程中还不时的发出嘶嘶声像是在挑衅你一样。现在只能将这条被咬烂的绳子拿回去问看看枫华镇的美食家(105/85)，看他那还有没有什么可以用来抓豹斑驹的东西了???',389),
  (62,11,'[神仙任务]玩偶','这次你将美食家给你的苹果远远的丢向豹斑驹，那豹斑驹像是没有发现到你的样子，低头就啃食起你丢出的苹果。果然没多久后，豹斑驹马上就软倒在地上，你趁机将豹斑驹抱起，并准备将豹斑驹带回枫华镇去找那美食家(105/85)交差???',390),
  (62,12,'[神仙任务]玩偶','费尽了千辛万苦，你总算是从豹斑驹的背上拔下了一撮鬃毛，看来终于可以回去和枫华镇的驯兽师(60/108)交差了，你心里是这么想的。',391),
  (63,1,'[神仙任务]下凡','昏倒在地上的年轻人嘴里喃喃念着赤精子和父亲这两句话后就昏倒了，只不过为什么一个凡人会知道赤精子的名字，要问看看赤精子吗???不过赤精子还是一如往常面无表情的样子，你也猜想的到他会说出什么话来。不知道站在这年轻人附近的施小青(79/58)会不会知道这年轻人的身分???',393),
  (63,2,'[神仙任务]下凡','你在那年轻人的背上找到了一根医疗用的针，看来是有人故意这么做的！不知道现场有没有人注意到这件事情，但至于要怎么弄醒这小子，你是一点头绪也没有，也许赤精子会知道吧？但是看他面无表情的样子，你又担心他会再给你一道闭门羹???',394),
  (63,3,'[神仙任务]下凡','你从这年轻人的口中得知道一个惊人的事实，这年轻人竟然是赤精子的弟子，因私自下凡而被仙界的监视者监视着。你很想保护他，但是这样又势必要与监视者起冲突，这监视者目前身份不清，不过你由那根刺入这年轻人背后大穴的医疗用针来推测这监视者应该是枫华镇炼丹房中的驻店药师(84/119)才对???',395),
  (63,4,'[神仙任务]下凡','你在和监视者战完后，得知自己的药已经被他偷换走了，但是不死心的你还是将手上的药灌进了那年轻人的口中。没多久，那年轻人便醒了过来，但是他已经丧失了之前所有的记忆，变成了一般的凡人。此时你突然发现，你身后总是面无表情的赤精子眉头竟然皱了起来，不知道他是想到了些什么事情???',396),
  (63,5,'[神仙任务]下凡','你从施小青的口中得知这根针的由来，竟然是来自枫华镇炼丹房驻店药师之手！只是现在救人要紧，要去救他吗(77/46)？还是要先察清楚事情的来由(84/119)？你突然间开始犹豫不决了起来???',397),
  (63,6,'[神仙任务]下凡','你将那年轻人的症状告诉了枫华镇炼丹房的驻店药师知道，他听完后便开了一副药方，虽然你注意到这驻店药师讲话语气有些奇怪，但也不以为意。总之现在要赶紧将那年轻人(77/46)弄醒才对吧？你是这样告诉自己的???',398),
  (63,7,'[神仙任务]下凡','原来那名驻店药师竟然就是仙界中的监视者？然而你却也接受了他的提议，要洗去那名年轻人的记忆。监视者要求你帮他找些素材来制作孟婆汤，你突然就想到你曾经在枫华镇客栈旁见过一位原料商人(89/84)，或许他那边有这些素材的信息吧???',399),
  (63,8,'[神仙任务]下凡','你将素材给了监视者后，没多久，监视者就捧着一碗汤出来，并表明要你去喂那年轻人(77/46)。既然路都走到这边了，再怎么样也只能硬着头皮走下去！也许对那名年轻人来说，洗去不该在这世间的记忆是件好事也不一定，你是这样告诉自己的???',400),
  (63,9,'[神仙任务]下凡','你无意间得知这驻店药师竟然就是监视者的事情，在情急之下，你和监视者便打了起来。虽然你成功的击败了监视者，但是却也因为这样而中了监视者的计谋，他已经将你的药给偷换走了，而且也趁你前来炼丹房的路上，已经让那年轻人喝下了孟婆汤。但即使是如此，你还是坚持要把这药给那年轻人(77/46)吃下???',401),
  (63,10,'[神仙任务]下凡','当你把那年轻人唤醒后，你开始仔细端察那根针，并且怀疑这是驻店药师所为。在经过对质后，那药师坦承不晦，但却也透露出一个更惊人的事实，其实他就是监视者。在驻店药师表明身份后，你知道一场战斗是无可避免了，所幸最后你是还站在场上的一人。监视者在被你打败后就准备回仙界告状去，而赤精子却直盯着你瞧，不知道他在想些什么事情???',402),
  (63,11,'[神仙任务]下凡','当你把那年轻人唤醒后，你便火速的前往枫华镇炼丹房内找驻店药师对质。在经过对质后，那药师坦承不晦。当驻店药师表明身份后，你知道一场战斗是无可避免了，所幸最后你是还站在场上的一人。监视者在被你打败后就准备回仙界告状去，而赤精子却直盯着你瞧，不知道他在想些什么事情???',403),
  (63,12,'[神仙任务]下凡','虽然赤精子一副就是不想帮忙的样子，不过好在神农没有赤精子这样的冷血。神农要你帮他收集一些素材来制作回气散来救醒那年轻人。此时你便想到你曾经在枫华镇客栈旁边看过一位原料商人(89/84)，也许可以从他身上得知一些有关素材的情报才对。不过对于这针的事情，你还是很在意，难道真有仙人会从中阻挠吗？',404),
  (63,13,'[神仙任务]下凡','虽然你从神农那边求得了回气散，但是对于这根针的事情你还是非常的在意。这针看起来像是治疗用的，难会是某位药师所有？你对于目前的事情有两种想法，一是先去追查这根针的下落，另一是先将那名年轻人救醒。虽然已经有个明确的目标了，但你始终还是拿不定主意???',405),
  (64,1,'[神仙任务]除妖','云中子感觉到枫华镇中有妖气，经过你一番明查暗访后，才发现周杨似乎就是云中子所感应到的目标。你看到你身后的云中子似乎还想说什么似的，保险起见，还是问看看好了???',407),
  (64,2,'[神仙任务]除妖','在确定了跟着周杨的妖物的真面目后，云中子给了你一把斩妖除魔用的桃木剑，同时也希望你能寻求看看其他神仙的帮助，如果真找不到有神仙愿意帮忙的话，那也只好就这样上了???',408),
  (64,3,'[神仙任务]除妖','在找不到任何神仙愿意帮忙的情况下，你和云中子就直接攻向正在吸取周杨阳气的妖孽，最后你成功的打败了那妖孽，也将那妖孽打回原形，不过看来云中子还在为这件事情烦恼着，不知道他的想法是怎么样的???',409),
  (64,4,'[神仙任务]除妖','你借着使用云中子的桃木剑和姜子牙的缚鬼护符来削弱这妖孽的力量，最后你成功的打败了那妖孽，也将那妖孽打回原形，不过看来云中子还在为这件事情烦恼着，不知道他的想法是怎么样的???',410),
  (64,5,'[神仙任务]除妖','你借着使用云中子的桃木剑和伏羲的八卦镜来削弱这妖孽的力量，最后你成功的打败了那妖孽，也将那妖孽打回原形，不过看来云中子还在为这件事情烦恼着，不知道他的想法是怎么样的???',411),
  (64,6,'[神仙任务]除妖','当你祭出云中子的桃木剑来封锁妖孽的逃跑路径，还有用伏羲的八卦镜来使妖孽现出原形，最后再用上姜子牙的缚鬼护符来镇压妖孽的力量。你成功的打败了那妖孽，也将那妖孽打回原形，不过看来云中子还在为这件事情烦恼着，不知道他的想法是怎么样的???',412),
  (64,7,'[神仙任务]除妖','你对于你的失误而对周杨道歉，那周杨也愿意原谅你的过失。这样原本还在烦恼不已的云中子稍微宽颜了一点，不过看来云中子还在为这件事情烦恼着，不知道他的想法是怎么样的???',413),
  (64,8,'[神仙任务]除妖','你听从云中子的建议，来和伏羲借一样可以隐蔽身上气味的法宝。然而伏羲却好像早已知道你们的来意，已经准备好法宝来供你使用。接着就是带着这隐身符和周杨接触(57/46)，应该就可以看到那妖孽的真面目了。',414),
  (64,9,'[神仙任务]除妖','你一听到云中子想借助其他神仙的力量时，马上就联想到伏羲这位先知。而伏羲这位先知也不负其名，已知你会来此处求他帮忙了，于是大方的借出了他的法宝─八卦镜供你使用。有了这法宝后，你对于降服妖孽一事便显得更有自信了???',415),
  (64,10,'[神仙任务]除妖','你到了姜子牙庙想寻求姜子牙的帮忙，姜子牙在知道你的来意之后，便借出了他镇压鬼怪用的法宝─缚鬼护符。有了这法宝后，你对于降服妖孽一事便显得更有自信了???',416),
  (64,11,'[神仙任务]除妖','在深夜时分，你佩带着伏羲的隐身符躲藏在周杨附近观察着。倏然间！你见到一抹黑影突然出现在周杨的身后，之后就看见周杨便陷入了永无止境的恶梦，不时的在那边低喃着梦呓。你回过头看，见到云中子正低头在沉思的样子，不知道他有没有什么主意???',417),
  (65,1,'[神仙任务]夫妻','土行孙要去见邓婵玉的庙(610/578)中见邓婵玉，不管是谁看都知道这绝对没好事????????????',419),
  (65,2,'[神仙任务]夫妻','虽然受了点伤，不过在土行孙细心的呵护之下，妳的伤势马上就痊愈了。之后土行孙还交给了妳一个配方表，要你去帮他找点素材来教训邓婵玉。妳突然想起了好像曾经在枫华镇客栈旁见过一位原料商人(89/84)，也许可以从他那边得到一些情报吧。',420),
  (65,3,'[神仙任务]夫妻','土行孙对邓婵玉将你们赶出庙外的这种行为感到相当的气愤。一天到晚总是被她压着，太久没教训她反而不知道我凶起来的模样？土行孙是如此说着。于是他给了你一份配方表，要你帮他找点素材来对付邓婵玉，你突然想起了好像曾经在枫华镇客栈旁见过一位原料商人(89/84)，也许可以从他那边得到一些情报吧。',421),
  (65,4,'[神仙任务]夫妻','妳收下土行孙用来对付邓婵玉用的绑仙绳，只是邓婵玉会有这么好打发吗？妳不禁也这样问着自己???',422),
  (65,5,'[神仙任务]夫妻','你收下土行孙用来对付邓婵玉用的绑仙绳，只是邓婵玉会有这么好打发吗？你不禁也这样问着自己???',423),
  (65,6,'[神仙任务]夫妻','妳听了土行孙的话后就跑去找邓婵玉聊天，不过当邓婵玉见到妳和土行孙手牵着手走进她的庙内后，也不免醋劲大发，将妳和土行孙轰出庙外。妳看着身后的土行孙正为了这件事情气的跺脚，嘴巴里不知在咒骂些什么事情???',424),
  (65,7,'[神仙任务]夫妻','在土行孙接到邓婵玉的通知之后你和土行孙便火速的赶往邓婵玉的庙内。也不知道邓婵玉是哪根筋不对了，硬是无理取闹的将你们从她的庙中赶了出来。你看着身后的土行孙正为了这件事情气的跺脚，嘴巴里不知在咒骂些什么事情???',425),
  (65,8,'[神仙任务]夫妻','也许是一时脑充血吧，你在还没有任何准备的情况下就与邓婵玉发生了冲突，虽然你还是打赢了，不过却也让这夫妻两人的裂痕更加的明显。看着身后的土行孙依旧是不停的在咒骂着，不知道他现在心里在想些什么事情???',426),
  (65,9,'[神仙任务]夫妻','虽然你祭出了土行孙的法宝─绑仙绳，但是却不见邓婵玉惊恐的神情，反而是引起了邓婵玉如烈火般的攻势。虽然你还是打赢了，不过却也让这夫妻两人的裂痕更加的明显。看着身后的土行孙依旧是不停的在咒骂着，不知道他现在心里在想些什么事情???',427),
  (65,10,'[神仙任务]夫妻','虽然你祭出了土行孙的法宝─绑仙绳，和姜子牙的打神皮鞭，但是却不见邓婵玉惊恐的神情，反而是引起了邓婵玉如烈火般的攻势。虽然你还是打赢了，不过却也让这夫妻两人的裂痕更加的明显。看着身后的土行孙依旧是不停的在咒骂着，不知道他现在心里在想些什么事情???',428),
  (65,11,'[神仙任务]夫妻','虽然你祭出了土行孙的法宝─绑仙绳，和太乙真人的九龙神火烛，但是却不见邓婵玉惊恐的神情，反而是引起了邓婵玉如烈火般的攻势。虽然你还是打赢了，不过却也让这夫妻两人的裂痕更加的明显。看着身后的土行孙依旧是不停的在咒骂着，不知道他现在心里在想些什么事情???',429),
  (65,12,'[神仙任务]夫妻','邓婵玉见到你祭出绑仙绳、打神皮鞭以及九龙神火烛后，脸上的表情登时变的惊慌失措。在战斗的过程中你也发现邓婵玉打起来软手软脚的，几乎是任你宰割。看来这鞭烛绳真的是邓婵玉的罩门。不过等你打完之后你却发现邓婵玉一脸幸福满足的样子，只觉得奇怪。也许土行孙会知道些什么吧???',430),
  (65,13,'[神仙任务]夫妻','姜子牙在听完土行孙的烦恼之后，决定借法宝打神鞭给土行孙，让他用这东西来对付邓婵玉，顺便看看能不能帮助他们夫妻合好。但是听姜子牙言词闪烁，避重就轻的，你在猜想，这对夫妻的相处之道应该和常人不一样吧???',431),
  (65,14,'[神仙任务]夫妻','太乙真人在听完土行孙的烦恼之后，决定借法宝九龙神火烛给土行孙，让他用这东西来对付邓婵玉，顺便看看能不能帮助他们夫妻合好。但是听太乙真人言词闪烁，避重就轻的，你在猜想，这对夫妻的相处之道应该和常人不一样吧???',432),
  (66,1,'[婚姻任务]气喘的媒婆','想要结婚，就要媒婆说媒，可是媒婆的气喘病却发作了，帮媒婆去找伊史仁(85/119)拿药吧。',434),
  (66,2,'[婚姻任务]气喘的媒婆','伊史仁说要三个红花蝶的卵和三个蚌精产的干贝才能炼药。',435),
  (66,3,'[婚姻任务]气喘的媒婆','三帖行气药拿到了，快去交给媒婆(118/113)吧。',436),
  (67,1,'[婚姻任务]鸳鸯对戒','坚贞的信物，代表着永恒的心，去武器店找吴炼(118/62)询问如何制作信物吧。',438),
  (67,2,'[婚姻任务]鸳鸯对戒','对戒的材料需要飞禽类怪物身上的发光的羽毛一个、蚌类怪物身上的珍珠一个、以及碧游宫附近岩石类怪物身上的圣洁的白金一个',439),
  (67,3,'[婚姻任务]鸳鸯对戒','已经拿到了对戒，先回去找媒婆(118/113)问要如何使用吧！',440),
  (68,1,'[婚姻任务]能量补充','坚贞的信物，要如何才能完全展现它的神秘光辉，找颗寻人宝珠给月老，让月老帮助你展现鸳鸯对戒神秘的光辉吧。',442),
  (69,1,'[城镇任务]枫华商人','你要找的是３０个兔尾巴，这些你可以在枫华镇外的兔子身上找到！',444),
  (69,2,'[城镇任务]枫华商人','你要找的是３０个狐爪，这些你可以在枫华镇外的仙狐身上找到！',445),
  (69,3,'[城镇任务]枫华商人','你要找的是３０个褐蜗螺的肉，这些你可以在碧游宫附近的褐蜗螺身上找到！',446),
  (69,4,'[城镇任务]枫华商人','你要找的是３０个狐皮，这些你可以在截仙遗址的大灰狐身上找到！',447),
  (69,5,'[城镇任务]枫华商人','你要找的是３０个蚌精产的干贝，这些你可以在截仙遗址的蚌精身上找到！',448),
  (69,6,'[城镇任务]枫华商人','你要找的是３０个鹤羽，这些你可以在碧游宫附近的云鹤身上找到！',449),
  (69,7,'[城镇任务]枫华商人','你要找的是３０个树妖的根，这些你可以在参天林的树精身上找到！',450),
  (69,8,'[城镇任务]枫华商人','你要找的是３０个虫壳，这些你可以在风吼黑洞的食土蚤身上找到！',451),
  (69,9,'[城镇任务]枫华商人','你要找的是３０个毛虫怪的卵，这些你可以在天绝黑洞的大毛虫身上找到！',452),
  (70,1,'[城镇任务]捉迷藏','你在枫华镇外遇到小孩曹布道，并答应和他玩捉迷藏，要抓到他五次才算赢。',454),
  (71,1,'[新手任务]守门师傅的最爱','扫地师傅要你带着瓶中花和仙叶来找守门师傅，但似乎还少了一样重要物品。',456),
  (72,1,'[新手任务]变化师傅－白狐','你把仙桃给了那个在昆仑仙界四处晃的变化师傅－白狐，但他就这么走掉了，看来你要好好的和他周旋，才能换取到仙界的秘宝。',458),
  (73,1,'[新手任务]天尊的试炼','元始天尊要你完成一些事情才能让你下凡。首先要去「恭读房」(134/151)找「生活技能师傅」学习一些关于合成的基本常识，再到神仙秘室(197/124附近)选择一位自己喜欢的神仙，最后到练功房(185/99)跟「拳头师傅」学习战斗训练并取得拳头师傅的认可，等完成这些事再回来找元始天尊。',460),
  (73,2,'[新手任务]天尊的试炼','你已完成了天尊的托付，快跟天尊谈话吧！',461),
  (74,1,'[神仙任务]武德之功','你接受了高兰英的武德试炼，她要你前往南原部落将在那边作怪的凶猛老虎(205/764)的头提回来给她，她答应你如果你顺利通过她的试炼的话，她会给予你她的神灵??????',463),
  (74,2,'[神仙任务]武德之功','经过一番激斗，你成功的打死了在南原部落那作怪的凶猛老虎，并且割下了牠的头。接着就是提回去给高兰英(225/644)看看了。',464),
  (74,3,'[神仙任务]武德之功','你将那老虎的头拿给高兰英后，接着就准备和高兰英(225/644)战斗吧。',465),
  (74,4,'[神仙任务]武德之功','高兰英在战斗结束后给了你一颗象征武德之功的徽章，接下来就是拿着这徽章再和高兰英木像(225/644)谈话吧！',466),
  (75,1,'[神仙任务]武德之戒','你接受了武吉的武德试炼，他要你去雨龙森林，找一位专门盗砍山林的山老鼠黄晓侯(196/411)，并且给他一点教训。并且他也说了千万不要杀了他，只要给他一点教训就好了。',468),
  (75,2,'[神仙任务]武德之戒','在刚刚的战斗中，你不小心将黄晓侯打成重伤，虽然可能有违背武吉对你的教诲，不过现在也只能硬着头皮回去和武吉(156/333)复命而已了???',469),
  (75,3,'[神仙任务]武德之戒','在刚刚的战斗中，你成功的教训了一下黄晓侯，他吓的跪在地上跟你求饶。你完美的达成了武吉交代你的工作，回去跟武吉(156/333)交差吧！',470),
  (75,4,'[神仙任务]武德之戒','你不小心就将黄晓侯这山老鼠打成重伤，武吉对你这种行为感到非常不谅解，接着就准备和武吉(156/333)战斗吧！对付武吉可不能手下留情喔！',471),
  (75,5,'[神仙任务]武德之戒','你成功的给了黄晓侯一点教训，武吉对你懂得控制自己的力量这点感到相当的满意，接着就准备和武吉(156/333)战斗吧！对付武吉可不能手下留情喔！',472),
  (75,6,'[神仙任务]武德之戒','在战斗结束后，武吉给了你一颗代表武德之戒的徽章，接着就拿着这徽章再和武吉木像(156/333)谈话吧！',473),
  (76,1,'[神仙任务]武德之胆','你接受了张奎的武德试炼，张奎给了你一件衣物后就出手偷袭你，将你的血量和法术降到一定的数值。张奎要你想办法用这点血量还有法术撑到去高兰英庙(225/644)将这衣物交给高兰英，这是对你在路上闪躲怪物还有头脑反应的一种考验。你可以想办法取巧，但还是要想办法将血量和法术控制在这么低的情况下见高兰英才行！',475),
  (76,2,'[神仙任务]武德之胆','你顺利的见到了高兰英，但是真正的考验却还在后面，你还是必须要依靠着这点血量和法术，想办法撑回去见张奎。这是对你在路上闪躲怪物还有头脑反应的一种考验。你可以想办法取巧，但还是要想办法将血量和法术控制在这么低的情况下回到张奎庙(428/382)中见到张奎才行！',476),
  (76,3,'[神仙任务]武德之胆','你漂亮的通过了张奎给你的试炼，接着就是和张奎战斗了，相信张奎不会这么卑鄙让你用这么一点血量跟他打斗的，放心的上吧！',477),
  (76,4,'[神仙任务]武德之胆','在战斗结束后，张奎交给你一个代表武德之胆的徽章。接着就拿着这徽章再和张奎木像(428/382)谈话吧！',478),
  (76,5,'[神仙任务]武德之胆','你口头上答应了要接受张奎的试炼，不过张奎木像(428/382)却没跟你说试炼的内容，而且表情还相当的神秘，不知道他葫芦里卖的会是什么药。现在也只好开口问他试炼的内容吧！',479),
  (77,1,'[神仙任务]武德之义','你接受了邓婵玉的武德试炼，他要你去葛城见两个人，一个是罗姥姥(101/189)，一个是苏毅(55/195)(室内)。先见过这两人后，再从中帮他们仲裁一下吧。',481),
  (77,2,'[神仙任务]武德之义','你已经见过了罗姥姥，也从她那边听到了一些事情，接着就是去见苏毅(55/195)(室内)了。',482),
  (77,3,'[神仙任务]武德之义','你已经见过了苏毅，也从他那边听到了一些事情，接着就是去见罗姥姥(101/189)了。',483),
  (77,4,'[神仙任务]武德之义','你已经见过罗姥姥(101/189)和苏毅(55/195)这两人了，接着就是要决定谁是谁非的时候了。',484),
  (77,5,'[神仙任务]武德之义','你决定帮助罗姥姥，接着就是去见苏毅(55/195)(室内)，要他放过罗姥姥，给老人家一条生路吧。',485),
  (77,6,'[神仙任务]武德之义','你决定帮助苏毅，接着就是去见罗姥姥(101/189)，要她赶紧交出房租，不然就请快点离开这里吧。',486),
  (77,7,'[神仙任务]武德之义','你完成了邓婵玉交托给你的任务，回去见她(611/578)吧！',487),
  (77,8,'[神仙任务]武德之义','在战斗结束后，邓婵玉给了你一个代表武德之义的徽章，代表你通过了她的试炼。接着就拿着这徽章，再和邓婵玉木像(611/578)谈话吧！',488),
  (77,9,'[神仙任务]武德之义','你向苏毅传达了罗姥姥的意思，而苏毅也答应让步了。虽然看起来有点可怜，不过要是他不让步的话，可怜的就是老人家了！接下来就是回去邓婵玉庙(611/578)和邓婵玉木像谈谈吧！',489),
  (77,10,'[神仙任务]武德之义','你向罗姥姥传达了苏毅的意思，没想到罗姥姥竟然对你吐露了实情。原来罗姥姥并不是没人供养，而且如果不是你出面的话，罗姥姥似乎还打算持续侵占这房子下去。现在罗姥姥终于愿意搬回去和孩子一起住了，快点把这好消息跟苏毅(55/195)说吧！',490),
  (78,1,'[神仙任务]药师的资格','你接受了石矶娘娘的药师试炼，石矶娘娘要你去葛城找一位病患(76/183)(室内)，帮他诊断一下病情。',492),
  (78,2,'[神仙任务]药师的资格','你见到那名病患，他的病征是睡不着觉，也许他需要的一些可以帮助他入眠的药品吧。石矶娘娘用天音通知你，可以去葛城的炼丹房(176/89)那看看有没有可以用的药品，还有炼丹房外面有在卖些特殊的药材(228/136)，到时或许都用的上吧。',493),
  (78,3,'[神仙任务]药师的资格','你成功的治好了程承的失眠症，现在就可以回去向石矶娘娘(391/415)禀报你治疗的成果了！',494),
  (79,1,'[神仙任务]药师的条件','你虽然接受了玉鼎真人这个健忘大王的药师试炼，他要你前去北原部落治疗一位病患(463/192)，先去看看那位病患，了解一下病情吧。',496),
  (79,2,'[神仙任务]药师的条件','你见到了那名病患，他的病征看来似乎很严重，被蜜蜂螫伤眼睛，被石头绊倒伤到下巴以及牙齿，又被熊踩到胸口。玉鼎真人用天音通知你说不知道葛城炼丹房(176/89)内有没有药可以同时治疗这三种状况的，还有炼丹房外面有在卖些特殊的药材(228/136)，到时或许都用的上吧。',497),
  (79,3,'[神仙任务]药师的条件','你成功的治好了阳明景的眼睛，牙齿和骨头的问题。接着就可以回去和玉鼎真人(535/303)交差了，不过不知道他有没有忘记这回事就是了。',498),
  (80,1,'[神仙任务]药师的基础','你接受了慈航道人的药师试炼，他要你到神木集中帮他治疗一位病患(116/136)，先去那边了解一下他的病情吧。',500),
  (80,2,'[神仙任务]药师的基础','你见到了那名病患，不过他现在似乎是陷入了一种疯狂的状态，也需是需要冷静一下吧。慈航道人用天音通知你说不知道葛城炼丹房(176/89)内有没有可以让他暂时安定心神的药品，还有炼丹房外面有在卖些特殊的药材(228/136)，到时或许都用的上吧。',501),
  (80,3,'[神仙任务]药师的基础','你将沉香安神丸放入了窦成的嘴巴里，没多久后他就从极度疯狂的状态下安定了下来。不过他感觉身体麻麻的，你分析这是被毒素入侵到了身体后才会有的情形。你记得刚刚再葛城炼丹房(176/89)内似乎有在卖一味可以解百毒的药，不妨再去那一趟吧。',502),
  (80,4,'[神仙任务]药师的基础','你完全的治好了窦成的病，接着就可以回去和慈航道人(177/152)交差了。',503),
  (81,1,'[神仙任务]偷窃','你接受了崇黑虎这大老粗谋士试炼，他要你去葛城帮他仲裁一件事情，这事是发生在王鸿(142/170)，蔡靖德(53/162)和亦懋(86/222)三人之间的纷争。你必须先从三人的言词中找出一人作为你信赖的对象。',505),
  (81,2,'[神仙任务]偷窃','你接受了王鸿的说法，按照王鸿的讲法，你现在应该去找蔡靖德(53/162)和亦懋(86/222)两人问看看???',506),
  (81,3,'[神仙任务]偷窃','在谈话的过程中你发现到蔡靖德这人积极的把这件事的矛头指向了亦懋，虽然你觉得这点颇让人怀疑他的动机，不过你还是接受了蔡靖德的说法。按照蔡靖德的说法，你现在应该去找王鸿(142/170)和亦懋(86/222)两人问看看???',507),
  (81,4,'[神仙任务]偷窃','在你和亦懋的谈话过程中，你发现亦懋这人讲话结结巴巴，并且将像是受人指使的将整件事的矛头指向了王鸿，虽然你觉得这点颇让人怀疑他的动机，不过你还是接受了亦懋的说法。按照亦懋的说法，你现在应该去找王鸿(142/170)和蔡靖得(53/162)两人问看看???',508),
  (81,5,'[神仙任务]偷窃','你觉得蔡靖德与亦懋的说法有些古怪，或许回去找王鸿(142/170)问看看有关这件事情吧???',509),
  (81,6,'[神仙任务]偷窃','你觉得王鸿的说法与亦懋的有矛盾之处，或许回去找蔡靖德(53/162)问清楚会比较好吧???',510),
  (81,7,'[神仙任务]偷窃','你觉得蔡靖德和王鸿的说法有些问题，或许再回去找亦懋(86/222)问清楚会比较好吧???',511),
  (81,8,'[神仙任务]偷窃','也许王鸿是因为受不了朋友间的互相诬陷吧，他拿出了他们三人一起结拜时的东西，并且要你去找那亦懋(86/222)和蔡靖德(53/162)问清楚，要他们摸着自己的良心说话???',512),
  (81,9,'[神仙任务]偷窃','蔡靖德与亦懋都异口同声的指称王鸿才是真正的犯人，难道犯人真是王鸿(142/170)吗？去问看看他好了???',513),
  (81,10,'[神仙任务]偷窃','虽然王鸿对你这看法有不同的声音，不过目前你手里能掌握的证据将答案都指向了亦懋，难道真是亦懋(86/222)不成？还是去问看看他好了???',514),
  (81,11,'[神仙任务]偷窃','亦懋最后终于受不了将实情全都吐露了出来，而你也比对过这两份文件的笔迹，的确是出自同一人之手。看来犯人是蔡靖得没错了！快回去找蔡靖德(53/162)吧！',515),
  (81,12,'[神仙任务]偷窃','看来你冤枉了好人，不知道崇黑虎对这件事情会有什么看法，回崇黑虎庙见崇黑虎(363/223)去吧???',516),
  (81,13,'[神仙任务]偷窃','终于逮到犯人了，不过蔡靖德却也因为这样而畏罪自杀，这件事明明一开始还只是朋友之间的玩笑而已，看来有些玩笑还真是开不得。不知道王鸿(142/170)对于我们帮他找到真相的这件事情会有什么样的看法???',517),
  (81,14,'[神仙任务]偷窃','这件事情总算是告一段落了，虽然有点遗憾，不过还是要将这件事情向崇黑虎交代一下。回去和崇黑虎庙里和崇黑虎(363/223)谈谈吧???',518),
  (82,1,'[神仙任务]智能','你接受了杨任的谋士试炼，杨任要你在夹龙纵谷的找到三个凉亭(550/675)、(432/470)、(401/198)附近的上古仙石，并且回答他们的问题后再回来和他复命???',520),
  (82,2,'[神仙任务]智能','你漂亮的回答了仙石对你提出的问题，上古仙石给了你一块仙石碎片，等收集到三颗位在夹龙纵谷(550/675)、(432/470)、(401/198)附近的上古仙石的仙石碎片后就可以回去找杨任庙找杨任木像(570/518)复命了。',521),
  (82,3,'[神仙任务]智能','虽然你回答了三颗仙石的问题，但是你最后还是得必须通过杨任这关，回答杨任((570/518))的问题，你就可以取得杨任的神灵了。',522),
  (83,1,'[神仙任务]谎言','虽然你接受了李靖的试炼，不过李靖还没有将试炼的内容透露给你。看他一脸严肃的神情，想必这次的试炼应该不是很好过才是???',524),
  (83,2,'[神仙任务]谎言','听郑立讲说他当年见到的杀人凶手是昆吾镇的宣逢(146/107)，不过不知道他讲的到底是真的还是假的???',525),
  (83,3,'[神仙任务]谎言','听郑中讲说他当年见到的杀人凶手是昆吾镇的宜逢(89/173)，不过不知道他讲的到底是真的还是假的???',526),
  (83,4,'[神仙任务]谎言','你见到了宣逢，你一再的逼问他当初杀人的动机和用意。最后，他终于受不了你咄咄逼人的态度而自杀了。显然这问题还没有被解决，再去问看看李靖(253/322)有没有解决之道好了。',527),
  (83,5,'[神仙任务]谎言','你见到了宜逢，当你指认出他是当初的凶手时，他就像是见到鬼一样，但之后你手中的斧头自你手中脱离飞击向他时你才知道，这一切都是附在这把凶器上的那些亡灵搞的鬼。你看着宜逢(89/173)因为被斧头击中而奄奄一息的求着你移开这斧头，至于要不要帮他，就看你的决定了。',528),
  (83,6,'[神仙任务]谎言','你拔出了卡在宜逢身上的斧头，但是这把不洁之斧却在你手中蠢蠢欲动。也许是因为见到当初杀人凶手的缘故吧，你认为还是将这斧头交给李靖(253/322)解决好了。',529),
  (83,7,'[神仙任务]谎言','李靖交给你一座净魂宝塔，只要把这座宝塔带到宜逢身边，和宜逢(89/173)接触后，这座净魂宝塔就会净化那把斧头了。',530),
  (83,8,'[神仙任务]谎言','你成功的解决了李靖给你的任务。现在就回去找李靖(253/322)吧。',531),
  (83,9,'[神仙任务]谎言','李靖要你带着这柄斧头去葛城找郑立(78/188)郑中(63/205)两兄弟，不过这对兄弟一个会讲实话令一个只会讲谎话，你可得要注意一点啊???',532),
  (84,1,'[神仙任务]玩具','看来金光圣母真的是闷坏了，从她一副不耐烦的样子就可以看出端倪来了，她希望你去葛城找一位玩具商人(220/128)，帮她带点玩具回来。',534),
  (84,2,'[神仙任务]玩具','你见到了玩具商人，不过商人却要你帮他除去一群害他不能顺利进货的狼群(387/239)，先将那狼群打败后再去回去找玩具商人(220/128)吧。',535),
  (84,3,'[神仙任务]玩具','你击退了那群狼群，并将狼皮交给了那玩具商人，不过那玩具商人竟然要你去昆吾镇客栈(148/128)内找一位葛城的地主，并且要你帮他跟那位地主交付营业执照的租金，直到现在，你才知道这位商人是有么的奸诈???',536),
  (84,4,'[神仙任务]玩具','你排除了万难，终于从那奸诈的玩具商人手中获得了稀奇的玩具，现在就快点把这玩具拿去给金光圣母庙(77/86)内的金光圣母木像吧。',537),
  (85,1,'[神仙任务]父爱','你接受了普贤真人给你的任务，他要你去昆吾镇找一位叫做林雄的人(89/121)，看他有什么需求，并且帮助他。',539),
  (85,2,'[神仙任务]父爱','你见到了林雄，但是他却要你帮他找一个叫做桃仙水的东西，这种奇怪的东西也许普贤真人木像(201/50)会知道吧???',540),
  (85,3,'[神仙任务]父爱','普贤真人放宝箱的位置在圣樵原野幽原台附近(445/425)，赶快去那找找吧！',541),
  (85,4,'[神仙任务]父爱','你成功的拿到了桃仙水，接着就是交给位在昆吾镇上的林雄(89/121)了！',542),
  (85,5,'[神仙任务]父爱','林雄想利用桃仙水和一本不知名的书，制造出一个骷髅人来当作他女儿的保镳，看来似乎是成功了。不过你看这骷髅怎么看怎么怪，不知道林雄打算怎么操控它，快点和林雄(89/121)谈谈吧！',543),
  (85,6,'[神仙任务]父爱','你完成了普贤真人交代你的工作，快回去普贤真人庙(201/50)，和普贤真人木像复命去吧。',544),
  (86,1,'[神仙任务]力量','你接受了云中子的任务，他要你去北原部落中找两个人，一是张勤(453/197)，一是刘群(475/210)。',546),
  (86,2,'[神仙任务]力量','你击退了埋伏在北原部落附近的马贼啰喽，并获得了一把破刀和马贼的头皮。这破刀看来向是刘群(475/210)父亲的东西，至于头皮，也许张勤(435/197)会有兴趣吧。把这两样东西分别交给这两人后，再回去和云中子庙(112/408)和云中子商量一下接下来的事情吧！',547),
  (86,3,'[神仙任务]力量','云中子要你从张勤(435/197)和刘群(475/210)中选择把力量交给两人中的其中一人，事成之后，再回云中子庙(112/408)和云中子交差吧！',548),
  (86,4,'[神仙任务]力量','你将仙气护腕交给了张勤，不过看到张勤获得力量后就开始嚣张起来，你的心里便觉得很不舒服。也许真是看走眼了吧，不过无论如何，你都完成了云中子交代你的事情。快点回去云中子庙(112/408)和云中子谈谈吧！',549),
  (86,5,'[神仙任务]力量','你有意将仙气护腕交给刘群，不过这孩子却不愿意收下。虽然你觉得这小子有点不知好歹，不过他肯靠自己的力量修练，这点对他来说应该也算是件好事。不过无论如何，你都完成了云中子对你交代是事情，快点回去云中子庙(112/408)和云中子谈谈吧！',550),
  (87,1,'[神仙任务]卖花女孩','难得赤精子愿意和你说这么长的话，也难得赤精子会委托你进行任务，看来要取得他进一步信任的话，还是乖乖的照他的心意去做会比较好。赤精子要你到葛城去找一位卖花的小女孩(194/101)买一朵花来给他。快点去吧！',552),
  (87,2,'[神仙任务]卖花女孩','卖花的小女孩跟你说她的卖花用的花篮被一个人抢走了，那人就躲在葛城闻仲庙附近的树下面(64/142)，快去把他找出来，并将花篮要回来吧！',553),
  (87,3,'[神仙任务]卖花女孩','你将那葛城卖花女孩的花篮要了回来，快点将这花篮还回去给那葛城卖花女孩(194/101)吧！',554),
  (87,4,'[神仙任务]卖花女孩','那小女孩给了你一朵鲜花，这应该就是赤精子想要的花吧，将这花带到赤精庙(93/243)中给赤精子吧。',555),
  (87,5,'[神仙任务]卖花女孩','赤精子突然感应到葛城那卖花女孩(194/101)有危险了，快去救她啊！',556),
  (87,6,'[神仙任务]卖花女孩','听这卖花女孩说有位凶恶大汉(175/110)在市集处大吵大闹，还嚷着要找仙花，难保他等会下手的目标不会是卖花女孩啊！还是快点去将打发掉那凶恶大汉吧！',557),
  (87,7,'[神仙任务]卖花女孩','你成功的吓阻了那位凶恶大汉继续逞凶下去。这下子那女孩应该就安全了吧，快回去和赤精子(93/243)复命吧！',558),
  (87,8,'[神仙任务]卖花女孩','你答应凶恶大汉要将女孩的花篮拿过来给他检查，去和葛城那卖花女孩(194/101)谈谈吧，希望她会乖乖的把东西交出来，不过你已经可以想到这花篮的下场了，想必这小女孩一定会很难过???当你在这么想的同时，在你的脑袋里又出现了另一个想法，难道真没有可以圆满解决的方法吗???',559),
  (87,9,'[神仙任务]卖花女孩','你从那鬼鬼祟祟的人手上得到了那凶恶大汉要的仙花，快点把这东西给那凶恶大汉(175/110)。否则他可能会对那名卖花女孩不利！',560),
  (87,10,'[神仙任务]卖花女孩','这花篮惨遭凶恶大汉的蹂躏，那卖花的女孩一定会很伤心的，但无论如何还是必须告诉她这坏消息，快把这坏掉的花篮拿去给卖花的女孩(194/101)吧。',561),
  (87,11,'[神仙任务]卖花女孩','那女孩收走破烂的花篮后便跑走不理你了。只好摸着鼻子乖乖回去找赤精子(93/243)吧。',562),
  (87,12,'[神仙任务]卖花女孩','你将仙花交给凶恶大汉后，凶恶大汉很满意的离去了，看来这名卖花女孩也得以安全了。既然如此，那就快点回去赤精子庙(93/243)和赤精子交差吧。',563),
  (87,13,'[神仙任务]卖花女孩','经过了这么久，赤精子总算愿意原谅你了，他愿意将时间移回到当初交代你事情的那一刻起。赤精子要你到葛城去找一位卖花的小女孩(194/101)买一朵花来给他。快点去吧！',564),
  (87,14,'[神仙任务]卖花女孩','你小心地捧着那卖花女孩的花篮，到底能不能保证这花篮不会被那凶恶大汉毁损呢？其实你一点把握都没有。不过既然答应了人，也只能硬着头皮继续干下去，快点把这花篮交给那凶恶大汉(175/110)吧！',565),
  (87,15,'[神仙任务]卖花女孩','在刚刚的那场战斗中，你明显不敌那凶恶大汉，于是你趁隙跑走了想另寻办法。\\n此时你脑袋里出现两种想法，一是回去帮助凶恶大汉哄那卖花女孩(194/101)，要她乖乖的将花篮交出来。另一是袒护那小女孩，重整旗鼓后再回去和那凶恶大汉(175/110)一决生死！',566),
  (88,1,'[神仙任务]笔友？','虽然你接受了土行孙的任务，不过土行孙没有跟你说要如何做。你看着土行孙正低头皱着眉头好像在想事情似的，但是没一会儿又看着他一个人在那使劲的傻笑着。不知道他到底想到了些什么事情，还是问问他好了???',568),
  (88,2,'[神仙任务]笔友？','你见到玉婵了，不过她一眼就识破你并不是信中那名高大威猛的土行孙，现在只好回土行孙庙(522/435)和土行孙商讨一下之后的事情吧。',569),
  (88,3,'[神仙任务]笔友？','土行孙交给你一份信物要你在带回葛城去见玉婵(204/163)，看来土行孙似乎还没有放弃的样子。',570),
  (88,4,'[神仙任务]笔友？','虽然你大约听出了玉婵好像是你认识的某人的样子，但是她还是吩咐你回去见土行孙(522/435)。不过你多少也是抱着一点看好戏的心态来看待这件事情。',571),
  (88,5,'[神仙任务]笔友？','看来一切都是邓婵玉的神灵在作怪，但是见土行孙这副狼狈的模样，你实在忍不住想帮他一把。快点将这葫芦交给土行孙庙外的邓婵玉(522/435)吧！',572),
  (88,6,'[神仙任务]笔友？','你成功的骗得了邓婵玉的目光，看来里面的土行孙也可以松一口气了，现在在进入土行孙的庙内(522/435)和土行孙谈谈吧。',573),
  (88,7,'[神仙任务]笔友？','土行孙交给你一束鲜花，要你到葛城帮他见一位叫做玉婵的女孩(204/163)，这是他在凡间交的笔友，不过你很怀疑土行孙他是怎么寄信出去的。',574),
  (89,1,'[主线剧情任务]重返仙界','仙鹤道僮要你去碧游宫附近找三个狐爪回来，这次不知又要做什么用了',576),
  (89,2,'[主线剧情任务]重返仙界','在拿了你的狐爪后，仙鹤道僮送你回到了昆仑仙界，要你去药草园找仙童(148/85)拿一样东西回来给他',577),
  (89,3,'[主线剧情任务]重返仙界','你从药草园仙童手中取得了仙鹤道僮所说的东西，原来是守门师傅的仙桃，这下可好了，最好赶快把东西给仙鹤道僮(119/119)，不然就惨了！',578),
  (89,4,'[主线剧情任务]重返仙界','仙鹤道僮嘱咐你说等那天你可以只身挑战参天林的树精时再回来找他，不知又会有什么事了',579),
  (90,1,'[职业任务]职业师傅的磨练','职业师傅要先出个问题考考你，证明你有资格接受他的考验',581),
  (90,2,'[职业任务]职业师傅的磨练','职业师传要你去找来十个半妖刀的碎片给他(525/274)',582),
  (90,3,'[职业任务]职业师傅的磨练','职业师这次要你去昆仑仙界取来破山剑的材料－玄铁，不过要找谁好呢～',583),
  (90,4,'[职业任务]职业师傅的磨练','武缎师傅说玄铁在拳头师傅那，看来又要去找那大老粗了',584),
  (90,5,'[职业任务]职业师傅的磨练','你已经取得玄铁了，拿回去给职业师傅吧！',585),
  (90,6,'[职业任务]职业师傅的磨练','职业师傅这次要和你进行五连战，中途退缩可就的要重新再来了！',586),
  (91,1,'[职业任务]职业师傅的磨练','职业师傅要先出个问题考考你，证明你有资格接受他的考验',588),
  (91,2,'[职业任务]职业师傅的磨练','职业师传要你去找来十块幽魂身上的布料给他(525/274)',589),
  (91,3,'[职业任务]职业师傅的磨练','职业师傅要你去找仙界的幻魔镜，这东西在一位仙童的手上，他目前在圣樵原野上的曲湖、北原部落、幽原一带之中某处乱晃，要找他就要快',590),
  (91,4,'[职业任务]职业师傅的磨练','你找到了仙童，不过这家伙不肯把东西给你，看来要再找他谈谈',591),
  (91,5,'[职业任务]职业师傅的磨练','你已取得了幻魔镜了，拿去给职业师傅吧',592),
  (91,6,'[职业任务]职业师傅的磨练','职业师傅要与你进行对战，不过你必须要遇到他的本尊战胜才有用，否则只是空谈',593),
  (92,1,'[职业任务]职业师傅的磨练','职业师傅要先出个问题考考你，证明你有资格接受他的考验',595),
  (92,2,'[职业任务]职业师傅的磨练','职业师传要你去找来十片火甲兵的皮甲给他(525/274)',596),
  (92,3,'[职业任务]职业师傅的磨练','职业师傅要你去找葛城炼丹房老板，帮他一个忙才算完成这次的考验',597),
  (92,4,'[职业任务]职业师傅的磨练','炼丹房老板要麻烦你找十个蘑菇和十五个蜻蜓的尾巴及十个狐牙给他',598),
  (92,5,'[职业任务]职业师傅的磨练','你已经完成炼丹房老板的请求了，该回去找职业师傅了',599),
  (92,6,'[职业任务]职业师傅的磨练','职业师傅要与你进行对战，打赢就算通过考验了',600),
  (93,1,'[职业任务]职业师傅的磨练','职业师傅要先出个问题考考你，证明你有资格接受他的考验',602),
  (93,2,'[职业任务]职业师傅的磨练','职业师传要你去找来十个鬼魅的衣服碎片给他(525/274)',603),
  (93,3,'[职业任务]职业师傅的磨练','职业师傅要你回昆仑仙界找小四圣兽的玄武，他会给你一个简单的考试，先通过再说吧',604),
  (93,4,'[职业任务]职业师傅的磨练','你完成了小玄武的考试，可以回去找职业师傅了',605),
  (93,5,'[职业任务]职业师傅的磨练','职业师傅要和你用猜拳做为这次的考验，你必须连胜三场才算过关',606),
  (94,1,'[新手任务]瓶中花与仙草粉','拳头师傅要你先去找旁边的仙童，其它的等会再说',608),
  (94,2,'[新手任务]瓶中花与仙草粉','练功房的仙童要你帮他找来伙房师傅(184/152)的瓶中花和药草园师傅(135/92)的仙草粉，有了这两样东西，他愿意用一个好东西跟你交换',609),
  (95,1,'[城镇任务]奶奶的回忆','老奶奶需要你到鲤鱼岛上找一本画册(642/463)',611),
  (95,2,'[城镇任务]奶奶的回忆','拿到画册了，得需要赶快回去找老奶奶(101/140)',612),
  (95,3,'[城镇任务]奶奶的回忆','上头的钥匙锁还未打开，你得快去找武器店老板试试看',613),
  (95,4,'[城镇任务]奶奶的回忆','武器店老板要你去找住在葛城东方的一位男子(224/125)',614),
  (95,5,'[城镇任务]奶奶的回忆','终于打开画册的钥匙，你要赶快把画册拿回去给老奶奶(101/140)',615),
  (96,1,'[城镇任务]思慕','你受到白秋蓉的委托，必须尽快找到她梦中那位男子，并把手镯转交给他(105/149)',617),
  (96,2,'[城镇任务]思慕','收到周献扬委托转交的情书，你必须拿给白秋蓉(99/89)',618),
  (97,1,'[城镇任务]相亲照','受到红大娘的任务委托，你必须先去找春花(206/137)询问画像的下落',620),
  (97,2,'[城镇任务]相亲照','从春花的口中提示里，画像似乎在一位姑娘(206/137)的手里',621),
  (97,3,'[城镇任务]相亲照','你拿到盈盈姑娘的发钗，得必须帮她把发钗给合成店师傅修复，她才肯把画像交出来',622),
  (97,4,'[城镇任务]相亲照','你已经取得修好的发钗，把发钗交给盈盈姑娘(206/137)，她会遵守诺言',623),
  (97,5,'[城镇任务]相亲照','取得遗失的画像，得要赶快还给红大娘(201/98)。',624),
  (97,6,'[城镇任务]相亲照','红大娘要你把画像赶快交给法宝屋附近徘徊的红苑姑娘(232/89)。',625),
  (98,1,'[城镇任务]神医','受到柳爷爷的请托，你必须求助李大夫(58/200)的帮忙',627),
  (98,2,'[城镇任务]神医','你必须收集李大夫单子上面所列的药材',628),
  (98,3,'[城镇任务]神医','大夫要你快把药带回去给柳爷爷(189/130)服下',629),
  (99,1,'[城镇任务]酒鬼','你必须让孟国良(71/180)和孟华(238/80)他们夫妻俩和好如初，事成之后他们俩自然会给答谢之礼。',631),
  (100,1,'[城镇任务]富豪的酒单','春花要你把欠账酒单钱向季承远(96/84)收取',633),
  (100,2,'[城镇任务]富豪的酒单','季承远把钱都交给他的总管处理，你必须找到季家的总管(83/113)',634),
  (100,3,'[城镇任务]富豪的酒单','季总管请你把错误的账单拿回去告知春花(206/137)',635),
  (100,4,'[城镇任务]富豪的酒单','正确的酒单请你转交给季总管(83/113)',636),
  (100,5,'[城镇任务]富豪的酒单','季总管请你把酒钱交给春花(206/137)',637),
  (101,1,'[城镇任务]爱哭鬼','游大娘请你帮忙她，了解为何小雄(76/233)每天都哭不停',639),
  (101,2,'[城镇任务]爱哭鬼','小雄的数学考卷，要请你帮忙拿给游大娘(227/140)过目',640),
  (101,3,'[城镇任务]爱哭鬼','游大娘请你帮忙她，把这些钱向杂货店老板购买糖给小雄',641),
  (101,4,'[城镇任务]爱哭鬼','你手里这些的糖果是要给小雄(76/233)的',642),
  (102,1,'[城镇任务]爷爷的草鞋','爷爷的草鞋坏掉了，需要你帮忙拿给防具店老板修理。',644),
  (102,2,'[城镇任务]爷爷的草鞋','防具店老板要你拿着材料单，收集十个兔皮来给他。',645),
  (102,3,'[城镇任务]爷爷的草鞋','草鞋已经修理好了，你得赶快拿回去给老爷爷(189/130)。',646),
  (103,1,'[城镇任务]躲猫猫','陪小朋友一起玩躲猫猫游戏，抓到三个小朋友之后就可以获得奖品',648),
  (104,1,'[城镇任务]满汉全席','冯恺请你帮忙把菜单上的物品都收集回来，就可以得到奖赏',650),
  (105,1,'[城镇任务]算命师的预言','算命师要你拿着这支凶签到杨婆婆(175/75)那儿，询问解签方法',652),
  (105,2,'[城镇任务]算命师的预言','你已经得到杨婆婆下一步的提示，尽快把令牌带往火云碑守卫(166/484)那儿。',653),
  (105,3,'[城镇任务]算命师的预言','此钥匙就是开启火云碑宝箱的重要关键，宝箱的地点就位于这座岛(174/460)上。',654),
  (105,4,'[城镇任务]算命师的预言','此玉佩应为杨婆婆所拥有的，证明你通过她给你的考验，拿到此玉佩必须赶紧交给杨婆婆(175/75)。',655),
  (105,5,'[城镇任务]算命师的预言','杨婆婆要你把这符咒交给普贤真人庙里的庙公(201/50)。',656),
  (106,1,'[城镇任务]来求好运','算命师要你拿着这支吉签到庙公(201/50)那儿，询问解签方法',658),
  (106,2,'[城镇任务]来求好运','庙公要你把单子上面所列的物品，每一样都带回来给他',659),
  (107,1,'[城镇任务]庙公的委托','算命师要你拿着这支普签到庙公(201/50)那儿，询问解签方法',661),
  (107,2,'[城镇任务]庙公的委托','庙公要你帮忙他到李大夫(58/200)那里询问他的病因',662),
  (107,3,'[城镇任务]庙公的委托','王道仙人把上天下地唯我独尊金光万灵丹给予你，得赶快让庙公(201/50)服下',663),
  (107,4,'[城镇任务]庙公的委托','李大夫要你到十里亭，去找一名王道仙人(234/805)求助。',664),
  (108,1,'[城镇任务]绣花鞋','你已经接受冯荷亭的委托，找寻绣花鞋的任务，对话中有提示到游小雄(76/233)好像知道这件事情的经过。',666),
  (108,2,'[城镇任务]绣花鞋','游小雄告诉你，那天的事情或许表妹晓庭(186/162)知情',667),
  (108,3,'[城镇任务]绣花鞋','晓庭告诉你，她并不知道，而且当天晓兰堂姐也在场，要你去问问看晓兰(137/173)。',668),
  (108,4,'[城镇任务]绣花鞋','晓兰提示你，那天似乎有看见一位身穿淡绿色衣服的小男孩(56/125)，拿走那双绣花鞋。',669),
  (108,5,'[城镇任务]绣花鞋','这双就是冯荷亭找寻的绣花鞋，你得赶快还给她(216/138)',670),
  (109,1,'[神仙任务]报复邓婵玉','你接受了哪咤的提议，准备对邓婵玉进行报复，邓婵玉的下场会是如何呢？',672),
  (110,1,'[神仙任务]替天行道？','你接受了瘟神手下的请求，替他完成瘟神的任务，只是这么做是对的吗？你不禁也问起了自己',674),
  (111,1,'[城镇任务]仙女的羽衣','霓裳要你到昆吾镇里，找寻她的崔馨姊妹，并询问修补羽衣的方法',676),
  (111,2,'[城镇任务]仙女的羽衣','崔馨要你到大蛟河附近找找迷糊仙童',677),
  (111,3,'[城镇任务]仙女的羽衣','仙童指引你往一线天壁附近找刘姥姥',678),
  (111,4,'[城镇任务]仙女的羽衣','刘姥姥要你把朱雀羽毛交给崔馨',679),
  (111,5,'[城镇任务]仙女的羽衣','崔馨已经把羽衣修复好了，请你交给霓裳。',680),
  (112,1,'[城镇任务]打水任务','孟昕要你打完八桶水，之后交给他领奖品',682),
  (113,1,'[城镇任务]收妖','万大娘要你帮忙救救他家的老爷，并且到仙靴台找一名仙姑。',684),
  (113,2,'[城镇任务]收妖','仙姑把破碎镜石交给你，要你帮忙去水岚草地收妖去。',685),
  (113,3,'[城镇任务]收妖','狐妖把收妖镜石交给你，要你拿回去给万大娘。',686),
  (114,1,'[城镇任务]幽灵神剑','李侠委托你去招厄亭寻问仙人，那把遗失的幽灵神剑的下落。',688),
  (114,2,'[城镇任务]幽灵神剑','疯仙人提示你往渡厄亭方向找玄天乌鸦。',689),
  (114,3,'[城镇任务]幽灵神剑','玄天乌鸦指引你往舞风巨木找寻森林守护神。',690),
  (114,4,'[城镇任务]幽灵神剑','森林守护神要你去和天兵蒋豪进行一场决斗。',691),
  (114,5,'[城镇任务]幽灵神剑','天兵蒋豪败给了你，你得赶紧找森林守护神对话。',692),
  (114,6,'[城镇任务]幽灵神剑','森林守护神把幽灵神剑交给了你，此刻赶紧把神剑送还给李侠去。',693),
  (115,1,'[城镇任务]家书','陈静要你帮忙送家书，拿给人在水岚草地的哥哥陈义雄。',695),
  (115,2,'[城镇任务]家书','哥哥看过家书知道你的来意，请你把她的消息，带回去给他妹子。',696),
  (116,1,'[城镇任务]送货','防具店老板要你帮忙送物品给四象台附近的大老板旺财、石敢当附近的樵夫郑协隆、舞风巨木附近的猎人春枝这三人。',698),
  (117,1,'[城镇任务]逃跑新娘','陈章民要你帮忙找寻他的新娘林若茵，你不如往仙鱼石柱一带去寻找看看。',700),
  (117,2,'[城镇任务]逃跑新娘','林若茵似乎欲言又止，有种说不出的苦衷，你不如回去问问陈章民，到底是发生了什么事情。',701),
  (117,3,'[城镇任务]逃跑新娘','既然是误会一场，赶紧把这消息告诉林若茵去。',702),
  (117,4,'[城镇任务]逃跑新娘','林若茵已经知道整件事情原是误会一场，赶紧把这好消息告诉陈章民去。',703),
  (118,1,'[城镇任务]缉捕七星石大盗','镇长要你帮忙去抓七星石大盗',705),
  (118,2,'[城镇任务]缉捕七星石大盗','军官吴翰斌把逮捕令交给你，线索上显示犯人当天，是一位身穿红衣男子正逃往西南方，大约是往神木集的方向。',706),
  (118,3,'[城镇任务]缉捕七星石大盗','张衡景提示他弟弟有可能会出现在某个岛上',707),
  (118,4,'[城镇任务]缉捕七星石大盗','张宏钰表示自己所做的过错，希望镇长能够原谅他，并且把七星石给交了出来。',708),
  (119,1,'[城镇任务]雕刻师的心愿','雕刻师要你帮忙他去望星巨木那儿，捡回十个小木头做雕刻的素材。',710),
  (120,1,'[城镇任务]帮帮忙','林戈吉小朋友要你帮忙他，采集药单上的素材，蜻蜓的翅膀十个，鹤羽十个。',712),
  (121,1,'[城镇任务]占卜的真相','文考打算为你占卜，不过希望你先去找来剑一的技能书，他才肯为你占卜。',714),
  (122,1,'[城镇任务]武器店老板的物品','帮武器店老板收回，寄放在技能书店和防具店的物品(锁链的鞭身，飞镖的镖身)。',716),
  (123,1,'[城镇任务]能吃是福','莫青(92/73)请你带回十条兔尾巴，还有绒毛鸭的肉一块。',718),
  (124,1,'[城镇任务]贪吃的菲菲','菲菲(70/122)委托你带回香菇、褐蜗螺的肉、兔尾巴、 绒毛鸭的肉、绒毛鸭的蛋好让她填饱肚子。',720),
  (125,1,'[城镇任务]蜂蜜大补汤','林大娘(71/105)拜托你带回三十个蜂蜜',722),
  (126,1,'[城镇任务]帮忙送货','林夫人请你帮忙将三条兔尾巴送去卖给镇上的杂货店换取金钱',724),
  (126,2,'[城镇任务]帮忙送货','杂货店老板把钱交给你了，请你拿回去给林夫人(72/49)',725),
  (127,1,'[城镇任务]肉与绒毛鸭的蛋','方老丈手上有五颗绒毛鸭的蛋，想要玩家帮忙找炼丹房老板换五块绒毛鸭的肉',727),
  (127,2,'[城镇任务]肉与绒毛鸭的蛋','你已经拿到五块绒毛鸭的肉了，得赶紧把绒毛鸭的肉拿到方老丈(131/74)',728),
  (128,1,'[城镇任务]香菇绒毛鸭的肉汤','方玟(67/122)想要煮香菇绒毛鸭的肉汤给家人喝，请玩家帮忙找三个香菇和三块绒毛鸭的肉',730),
  (129,1,'[城镇任务]童年的礼物','帮邓天(83/109)找一个发光的羽毛，他要拿来送给吕小妹的礼物',732),
  (130,1,'[城镇任务]赵顺的订情信物','赵顺需要你拿三十块兔皮给他娘(120/78)做皮草加工',734),
  (130,2,'[城镇任务]赵顺的订情信物','你得转告赵顺(112/100)，等过些日子赵大娘会把加工好的皮草，亲自交给他',735),
  (131,1,'[城镇任务]吃的联姻','莫青(92/73)想要娶菲菲(70/122)为妻，但是需要你的帮忙',737),
  (132,1,'[城镇任务]毛叔的斧头','帮毛叔(532/246)找寻斧身零件- 1 阶三个，用来修理斧头用的。',739),
  (133,1,'[神仙任务]圣母的娃娃','玩偶家小男孩请你帮他找制作玩偶的材料，让他参加玩偶大赛。',741),
  (133,2,'[神仙任务]圣母的娃娃','雕刻家小女孩请你帮忙收集骨质材料让他制作玩偶的骨杖。',742),
  (133,3,'[神仙任务]圣母的娃娃','娃娃拿到了，可以跟圣母交差了。',743),
  (134,1,'[神仙任务]张奎的木像','张奎请你去昆吾镇找人帮忙修补木像，看来最好先去客栈打听打听附近有什么人是这方面的高手',745),
  (134,2,'[神仙任务]张奎的木像','在雨龙森林的渡厄亭和招厄亭分别住着匠心老师傅和巧手小师匠，看来找其中一位帮忙就可以了！',746),
  (134,3,'[神仙任务]张奎的木像','匠心老师傅说要你去昆吾镇武器店买一组雕刻刀组，再去望星巨木里面找一株神木取得木材，有了这两样物品才能帮你修补张奎木像',747),
  (134,4,'[神仙任务]张奎的木像','匠心老师傅说还少一样可为雕刻刀开光的磨刀石，这问题恐怕就得问问张奎了！',748),
  (134,5,'[神仙任务]张奎的木像','张奎想到可以跟邓婵玉借五光石，所以现在快去找邓婵玉吧',749),
  (134,6,'[神仙任务]张奎的木像','已经借到了五光石，看来老师傅可以为张奎的木像雕刻了',750),
  (134,7,'[神仙任务]张奎的木像','老师傅说明天就应该好了，那等明天再看看吧！',751),
  (134,8,'[神仙任务]张奎的木像','巧手小师匠说要你去弄月巨木旁的小巿集找一位简殇的人拿雕刻刀组，再去望星巨木里面找一株神木取得木材，有了这两样物品才能帮你修补张奎木像',752),
  (134,9,'[神仙任务]张奎的木像','巧手小师匠说明天就应该好了，那等明天再看看吧！',753),
  (135,1,'[神仙任务]传家金壶','玉鼎真人要你去找庙公问问传家金壶的事',755),
  (135,2,'[神仙任务]传家金壶','庙公告诉你这已是四十年前的事，看来要好好问问玉鼎了',756),
  (135,3,'[神仙任务]传家金壶','玉鼎要你去找金赞，他说印象中好像是葛城的人，看来可以去春满楼打听打听',757),
  (135,4,'[神仙任务]传家金壶','店小二说城郊东边的巿集有个叫金万叹的人，可以去跟他打听看看',758),
  (135,5,'[神仙任务]传家金壶','金万叹口述其祖已亡殁，玉鼎的记忆力果然不可靠，接下来可要问问他怎么办了',759),
  (135,6,'[神仙任务]传家金壶','玉鼎的健忘又犯了，这下可好了，或许去找找玉鼎木像会有什么下文吧！',760),
  (135,7,'[神仙任务]传家金壶','知道了玉鼎为什么健忘好了又犯的原因，现在要紧的还是找仙鹤道僮帮忙回去昆仑仙界找伙房师傅要金壶吧！',761),
  (135,8,'[神仙任务]传家金壶','虽然是假金壶，不过金万叹应该认不出来才是，这就拿去交给他吧！',762),
  (135,9,'[神仙任务]传家金壶','给了金壶，金家的命运就靠他自己了，接下来玉鼎心情应该好多了吧！',763),
  (136,1,'[神仙任务]大小姐的恶作剧','找普贤真人问问剜目刑具的下落',765),
  (136,2,'[神仙任务]大小姐的恶作剧','去枫华镇找董古打听剜目刑具的下落',766),
  (136,3,'[神仙任务]大小姐的恶作剧','剜目刑具到手了，现在可以问问邓大小姐到底想做什么了吧',767),
  (136,4,'[神仙任务]大小姐的恶作剧','找普贤真人问问震天箭的下落',768),
  (136,5,'[神仙任务]大小姐的恶作剧','去葛城找古懂商问问震天箭的下落',769),
  (136,6,'[神仙任务]大小姐的恶作剧','接下来就动身往截仙遗址极南台附近不远的小岛上找石矶娘娘吧',770),
  (136,7,'[神仙任务]大小姐的恶作剧','杨任的庙在夹龙纵谷的仙波亭附近，快去找他吧',771),
  (136,8,'[神仙任务]大小姐的恶作剧','东西也给杨任了，看来邓大小姐应该满意了吧！',772),
  (136,9,'[神仙任务]大小姐的恶作剧','震天箭到手了，现在要问问邓大小姐接下来要做什么了',773),
  (136,10,'[神仙任务]大小姐的恶作剧','想不到石矶娘娘一点也不在意，看来邓大小姐可失算了',774),
