  (137,2,'[神仙任务]邓婵玉的要求','邓婵玉要你去找来三十个狼皮给她的木像',777),
  (137,3,'[神仙任务]邓婵玉的要求','邓婵玉要你去找来三十个豹皮给她的木像',778),
  (137,4,'[神仙任务]邓婵玉的要求','你已经把邓婵玉要的东西给了木像，可以跟她交差了',779),
  (138,1,'[神仙任务]张魁与高岚樱','高兰英要你去看看那个张魁到底在苦个什么劲',781),
  (138,2,'[神仙任务]张魁与高岚樱','张魁要求你帮他去跟枫华镇的赵大娘购买天女珍珠项链',782),
  (138,3,'[神仙任务]张魁与高岚樱','赵大娘请你帮他收集珍珠三个和发光的羽毛一个才愿意出售『天女珍珠项链』',783),
  (138,4,'[神仙任务]张魁与高岚樱','你已经取得了『天女珍珠项链』，拿回去给张魁吧！',784),
  (138,5,'[神仙任务]张魁与高岚樱','总算搞定张魁的事了，看看高兰英的反应吧！',785),
  (138,6,'[神仙任务]张魁与高岚樱','在高兰英的威胁下，你答应她去问那个高岚樱是怎么回事',786),
  (138,7,'[神仙任务]张魁与高岚樱','高岚樱要求你帮他找『百兽锅』的材料',787),
  (138,8,'[神仙任务]张魁与高岚樱','完成了高岚樱的委托，看看高兰英有什么想法吧！',788),
  (139,1,'[神仙任务]五魔岗','李靖感应到庙里有事，请你立刻去查探一下',790),
  (139,2,'[神仙任务]五魔岗','得知有小孩遭到五魔岗的人抓走，你和李靖可以研究一下要怎么办',791),
  (139,3,'[神仙任务]五魔岗','你们决定就直闯五魔岗救人去',792),
  (139,4,'[神仙任务]五魔岗','你们决定先问问庙公详情再做打算',793),
  (139,5,'[神仙任务]五魔岗','庙公说该小孩可能来自葛城，或许葛城城主口中可以探听到什么消息',794),
  (139,6,'[神仙任务]五魔岗','知道了实情，接下来好好跟李靖讨论是否要去救人吧',795),
  (139,7,'[神仙任务]五魔岗','你和李靖决定在救人前先去登岚山道找找有没有被卢家父子偷走的东西',796),
  (139,8,'[神仙任务]五魔岗','有了宝物，可以去五魔岗救人了',797),
  (139,9,'[神仙任务]五魔岗','东西给了寨主，现在就去找卢晓他们吧',798),
  (139,10,'[神仙任务]五魔岗','已经打败了寨主，现在就去找卢晓他们吧',799),
  (139,11,'[神仙任务]五魔岗','你已经救了卢晓，看来事实真相不如你们预期，和李靖好好谈谈吧',800),
  (139,12,'[神仙任务]五魔岗','你成功救了卢家三口，李靖应该也很高兴吧',801),
  (140,1,'[神仙任务]盗宝计中计','在开始寻宝前，普贤要你先去找金光圣母借天眼结一用',803),
  (140,2,'[神仙任务]盗宝计中计','在开始寻宝前，普贤要你先去找土行孙借地动尺一用',804),
  (140,3,'[神仙任务]盗宝计中计','已经跟圣母借到了天眼结，接下来就看普贤表演了',805),
  (140,4,'[神仙任务]盗宝计中计','已经跟土行孙借到了地动尺，接下来就看普贤表演了',806),
  (140,5,'[神仙任务]盗宝计中计','普贤感应到宝物被藏在攀龙山道，这就动身去找吧',807),
  (140,6,'[神仙任务]盗宝计中计','普贤感应到宝物被藏在一线天壁附近的山洞里，这就动身去找吧',808),
  (140,7,'[神仙任务]盗宝计中计','已经找到了宝物，问问普贤接下来该怎么做吧',809),
  (140,8,'[神仙任务]盗宝计中计','普贤决定要先找个好地方藏宝，就是位在鲤鱼岛仙鱼石柱的西南方林子里的一条十分隐秘的小径，现在就去藏宝吧！',810),
  (140,9,'[神仙任务]盗宝计中计','宝物藏好了，先把天眼结还给圣母吧',811),
  (140,10,'[神仙任务]盗宝计中计','宝物藏好了，先把地动尺还给土行孙吧',812),
  (140,11,'[神仙任务]盗宝计中计','快回去藏宝的地方让普贤好好感受一下宝物的波动吧',813),
  (140,12,'[神仙任务]盗宝计中计','宝箱里空无一物，这下可好了，快问问普贤吧！！',814),
  (141,1,'[神仙任务]石矶娘娘的课程指导','身为石矶娘娘的爱徒，但是却连最基本的问题都不知道，石矶娘娘为了指导你，于是要你收集炼制金创药的素材各二十份。',816),
  (141,2,'[神仙任务]石矶娘娘的课程指导','身为石矶娘娘的爱徒，但是却连最基本的问题都不知道，石矶娘娘为了指导你，于是要你收集炼制金创药的素材各二十份。',817),
  (141,3,'[神仙任务]石矶娘娘的课程指导','身为石矶娘娘的爱徒，漂亮的答对石矶娘娘对你提出的问题，石矶娘娘的下一堂指导，便是要你切身实地的去找寻炼制疗伤药的素材，各十份。',818),
  (141,4,'[神仙任务]石矶娘娘的课程指导','石矶娘娘对你提出了第二道题目，但是你依旧不知道答案为何，但是石矶娘娘秉持着一贯的教育理念，要你切身实地去体验这药物的功用，所以又要你去收集炼制疗伤药的素材十份。',819),
  (141,5,'[神仙任务]石矶娘娘的课程指导','石矶娘娘对你提出了第二道题目，你依旧漂亮的答对，石矶娘娘秉持着一贯的教育理念，要你切身实地去体验这药物的功用，所以又要你去收集炼制疗伤药的素材十份。',820),
  (141,6,'[神仙任务]石矶娘娘的课程指导','石矶娘娘的徒弟王化宇要求石矶娘娘让他见见难得一见的素材：巨水蛭的尾巴和红顶鹤的蛋各三十个，所以这个责任自然转嫁到拥有石矶娘娘神灵的你身上来了。乖乖的帮石矶娘娘准备这些上课用的材料吧！',821),
  (141,7,'[神仙任务]石矶娘娘的课程指导','你帮石矶准备好上课用的材料了，石矶也对王化宇说明了炼制药物的理论。但是还是要看结果，虽然石矶娘娘觉得王化宇应该没有问题，但是还是怕他自信过剩，导致意外的产生?????????',822),
  (141,8,'[神仙任务]石矶娘娘的课程指导','石矶娘娘的徒弟李力在研习石矶娘娘的书籍时产生了点疑问，就是石矶的书里没有素材的附图，所以为了帮助石矶的教学，你要帮忙石矶收集上课用的素材：红鹰的蛋和褐蜗螺的肉各三十份来给李力。',823),
  (141,9,'[神仙任务]石矶娘娘的课程指导','你帮石矶准备好上课用的材料了，石矶也对李力说明了炼制药物的理论。但是还是要看结果，虽然石矶娘娘觉得李力应该没有问题，但是还是希望他循序渐进，以免产生意外?????????',824),
  (141,10,'[神仙任务]石矶娘娘的课程指导','石矶娘娘忘记帮鱼轩硕准备上课要用的素材了，为了怕悟性低的鱼轩硕实验失败，所以石矶想要你帮他收集炼制金创药的素材绒毛鸭的肉和绒毛鸭的蛋各三十份来。',825),
  (141,11,'[神仙任务]石矶娘娘的课程指导','你帮石矶准备好上用要用的材料了，虽然石矶事前已经教过鱼轩硕炼制药物的理论和方法，但是看到鱼轩硕一脸疑惑的样子，你不禁要帮他捏把冷汗。',826),
  (141,12,'[神仙任务]石矶娘娘的课程指导','鱼轩硕说要准备上课用的素材，可是是什么又没说，看来问问石矶娘娘比较妥当。',827),
  (142,1,'[神仙任务]小小的冒险','你答应了要给那孩子一把匕首和一件柳叶甲好让他实现冒险的梦想，不过就这年纪的孩子来说，想出去冒险是不是还太早了一点?????????',829),
  (142,2,'[神仙任务]小小的冒险','你拒绝了那孩子，毕竟这个年纪还是不太适合出去外面冒险，不过你没料到这孩子不服输，硬是一个人跑去幽原台附近，武吉怕他出什么意外，你还是快点到幽原台那去找那孩子好了?????????',830),
  (142,3,'[神仙任务]小小的冒险','你给了那孩子一把匕首和一副柳叶甲，原本看他高兴的样子你以为这件事就这样结束了，没想到这孩子因为喝了点酒，太过兴奋，说是要一个人去幽原台那将怪物揪出来。你心理想说如果不快把他追回来，到时候要是出了什么意外，这责任又要算在你头上了。',831),
  (142,4,'[神仙任务]小小的冒险','你解决了准备要袭击这孩子的老虎，但这孩子却早已昏死过去，但是当再度转醒过来后，你才发现这孩子是殷洪的大哥殷郊。他告诉你有关仙界上面的动态，不过一切也仅只是传言而已，他们兄弟为了要警告下凡仙人和仙童，不惜触犯仙规，直闯凡间，投胎在一般凡人身上。但是他话还没说完，那殷郊的意识便被这孩子原本的意识所取代，又变成一般凡人了??????',832),
  (143,1,'[神仙任务]治病','你答应了张农要帮他找药来医治他爹，不过看看这些药尽是些高价格的药物，你在思索如果身上钱不够的话，看有没有其他仙童可以帮忙磨药或是由你来收集素材给会磨药的仙童来磨。',834),
  (143,2,'[神仙任务]治病','你决定不帮张父，因为你觉得这样似乎对他的身体不太好，为了健康着想，你答应了张农的要求帮他找药来医治他爹，不过看看这些药尽是些高价格的药物，你在思索如果身上钱不够的话，看有没有其他仙童可以帮忙磨药或是由你来收集素材给会磨药的仙童来磨。',835),
  (143,3,'[神仙任务]治病','你答应张父，要完成他这小小的愿望，让他抽上一口水烟，和吃上一盘麻婆豆腐，虽然你也知道这样对他来说不是好事，但是你也不想看到他这样因病受苦。',836),
  (143,4,'[神仙任务]治病','你找到了张父最爱的厨师，并且向他要盘麻婆豆腐，但是偏偏他手边没有这几样食材，他想要你帮他找齐这些食材，或许到时候还可以不用付钱就可以得到这盘麻婆豆腐了',837),
  (143,5,'[神仙任务]治病','快炒手就是快炒手，虽然脾气不太好，但是该有的水平还是在，不愧是葛城第一大厨，弄出来的麻婆豆腐香辣扑鼻的味道让你的口水都快流了出来????',838),
  (143,6,'[神仙任务]治病','你打开了张农的箱子，把他藏起来的水烟袋取了出来，虽然你知道抽烟是不好的行为，但是这时候也只能便宜行事了。',839),
  (143,7,'[神仙任务]治病','你把东西交给了张父，虽然这么做可能是加速他的病情，但你并不觉得有什么不妥，不过，慈航可不这么认为了',840),
  (144,1,'[神仙任务]争夺','你为了要替崇黑虎找点事情做，于是便跑到葛城找了个包打听，想从他身上找点事做做，于是这包打听给了你一点讯息，一位叫做李群的年轻人不太正常，他就住在葛城的西南边，也许他的事情可以打发一下崇黑虎的时间??????',842),
  (144,2,'[神仙任务]争夺','眼前的年轻人似乎是药物中毒的样子，现在处于一种极为亢奋疯狂的状态，还好他还保有点意识。你拿走他的药方，去帮他找素材，你在想收集好素材后便去向神农求助好了??????',843),
  (144,3,'[神仙任务]争夺','你收过了交易凭证后仔细一看，上面签署的是苏信豪的名字，再仔细核对笔迹，可以确定是苏信豪所写。崇黑虎看了之后全身颤抖，大骂说要让苏信豪和崇伯虎一起下地狱瞧瞧做坏事的下场！',844),
  (144,4,'[神仙任务]争夺','苏信豪找你的原因是要你去帮忙他保护一批货物，那批货物现在就在南方的龙口码头那??????',845),
  (144,5,'[神仙任务]争夺','你拿走了苏信豪的玉佩，并且让崇黑虎送他下地狱一趟，崇黑虎说希望他这次真能学到乖，同样的，你也这么希望。',846),
  (144,6,'[神仙任务]争夺','你把这些种子还给苏信豪，他也答应会和崇伯虎合好，不过事情真会这么顺利吗？只有静待时间发展了，现在你所要做的就是和崇黑虎讨论一下下一步的行动??????',847),
  (144,7,'[神仙任务]争夺','崇伯虎还是一样那么没礼貌，而且似乎私底下还是和苏信豪在暗斗着，他希望你能去苏信豪那探探他的口风，不过你得先想办法把自己藏起来，或许去找看看伏羲会是个好主意??????',848),
  (144,8,'[神仙任务]争夺','你手持伏羲给的隐身符并且顺利的听到了苏信豪下一步的行动，紧接着崇伯虎又希望你到龙口码头那先绊住苏信豪的行动，并且也给了你一个护符。他说只要和龙口码头附近的苏信豪谈话后，他自然就会出现在你附近??????',849),
  (144,9,'[神仙任务]争夺','虽然崇伯虎还是这么的嘴硬，但是还是乖乖的答应了你的要求，不过不知道他是不是真的能和苏信豪好好的相处，你相信这在短时间内是看不出来的??????',850),
  (144,10,'[神仙任务]争夺','你把崇伯虎最重要的印章给拿走了，并且让崇黑虎送他下地狱一趟，崇黑虎说希望他这次真能学到乖，同样的，你也这么希望。',851),
  (144,11,'[神仙任务]争夺','你不知道为什么苏信豪不让王顺把货物搬上岸来，但是现在摆放货物的船底已经开始进水了，王顺希望你帮他找些素材来填补船底??????',852),
  (144,12,'[神仙任务]争夺','你火速的把这些东西给弄齐后就交给了王顺，在交付素材的同时，苏信豪也赶抵了这里。不过他看跑的这么喘这么狼狈，你忍不住想问看看他到底是发生了什么事情??????',853),
  (144,13,'[神仙任务]争夺','你等苏信豪稍微不喘的时候问他情形，但就在他讲没几句话后，崇伯虎带了一群人也到了此地，看他们各个凶神恶煞的样子，难保不会发生什么争执??????',854),
  (144,14,'[神仙任务]争夺','你决定把这药钵还给崇伯虎，顺便也对苏信豪进行劝说。你看到苏信豪还沉醉在胜利的喜悦中，于是很大方的答应你要原谅崇伯虎，只要他先道歉的话。如果是真的，那还真是件好消息，快点把这东西还给跑回枫华镇上的崇伯虎吧！',855),
  (144,15,'[神仙任务]争夺','在你和苏信豪谈过话之后，你看见这护符飞到你身后化作一道火光。倏然！崇伯虎和一群人便从火光中走出来，看来两方人马即将有所冲突了??????',856),
  (144,16,'[神仙任务]争夺','你帮助崇伯虎，打跑了苏信豪一干人，也从苏信豪的身上得到了一包种子，同时你也注意到了崇伯虎贪婪的眼神，但是这包种子似乎也是苏信豪等人所要保护的东西。你有预感，这东西要给谁，或许就关系到了这两家能不能合好的关键??????',857),
  (144,17,'[神仙任务]争夺','你帮助了苏信豪，保护他的货物，打跑了崇伯虎一群人，同时也在崇伯虎身上得到一个药钵。在这同时你也注意到了苏信豪贪婪的眼神，但是听说这药钵是崇伯虎心爱之物。你有预感，这东西要给谁，或许就关系到了这两家能不能合好的关键??????',858),
  (144,18,'[神仙任务]争夺','你决定把这种子还给苏信豪，并劝崇伯虎得饶人处且饶人，虽然他答应了不再找苏信豪麻烦，不过你不敢肯定这是他心理的话。不过如果是真的，那还真是件好消息，快点把这东西还给跑回枫华镇上的崇伯虎吧！',859),
  (144,19,'[神仙任务]争夺','伏羲似乎早就知道事情的样子，不过他身边却没有可以给你的护符，或许许多仙童都来找伏羲要过这东西吧。如今想要得到伏羲隐身符的方法就只有乖乖的帮伏羲做事了??????',860),
  (144,20,'[神仙任务]争夺','你总算把伏羲交代的东西收集好了，在交给伏羲之后，伏羲也给了你一张隐身符。现在你就可以大大方方的进出苏信豪工作的地方，探听他的口风和消息了。',861),
  (144,21,'[神仙任务]争夺','你将收集来的素材还有药物的清单都交给了神农，依照神农的功力是绝对不会出错的。果然没多久，你就从神农手中接过一颗药丸，神农还嘱咐你说快点给那年轻人服下。',862),
  (144,22,'[神仙任务]争夺','你手持伏羲给的隐身符并且顺利的听到了苏信豪下一步的行动，或许这就是崇伯虎想知道的事吧?????',863),
  (145,1,'[神仙任务]挚爱','杨任接获到神农氏的密令，要你和他前去葛城探听一下有关瘟神吕岳的消息。在葛城包打听那没问到吕岳的事情，反而问到了有关盗墓者的消息。你在猜想也许这两件事情有所相关也不一定，反正就先跑苏彦那一趟就是了??????',865),
  (145,2,'[神仙任务]挚爱','你不确定是不是真的被苏彦的真情给说服了，又或者只是抱着看热闹的想法，看事件会有什么样的后续。总之你答应苏彦帮他找那剩下来最后的三样素材，他说只要有这三样素材，他的妻子就可以再度复活在这世间。只是，你一直觉得奇怪的就是那张炼金材料单是谁开给苏彦的??????',866),
  (145,3,'[神仙任务]挚爱','你应苏彦的要求把素材带到曲湖中间的小岛上，在那把素材交给了苏彦，你见他把他妻子的尸体抱出来，那尸体被苏彦用冰封保存，看起来好像还活着似的，只差没呼吸而已。你见苏彦把东西拼拼凑凑，嘴里不知道在念些什么，突然一阵爆炸把你震的眼睛睁不开来，然而在睁开眼睛的瞬间，你见到了苏彦的妻子，站了起来??????',867),
  (145,4,'[神仙任务]挚爱','苏彦被丧失意志的莹莹以利爪撕裂身体，他在气绝身亡前交给你一张禁制护符，希望你帮忙杀死他一生的挚爱。只是想到为了莹莹，苏彦已经花费了这么多年的光阴和金钱，却换得这种下场，你的心里不禁一阵唏嘘。至于莹莹现在的位置，也许杨任会知道吧??????',868),
  (145,5,'[神仙任务]挚爱','你被莹莹这突如其来的举动给吓傻了，以致于眼睁睁的看见莹莹用利爪撕裂苏彦的肉体，直到莹莹像发了封似的往葛城方向狂奔后你才回过神来。不过在你眼前的苏彦已仅是一息尚存而已了??????',869),
  (145,6,'[神仙任务]挚爱','你按照莹莹的要求，说出了苏彦预设的禁语，取走绑在莹莹脖子上的项链后。只见到莹莹对你微一微笑，手伸向着苏彦，身体瞬间化做一堆尘土，随风飘散去??????',870),
  (145,7,'[神仙任务]挚爱','你赶在莹莹尚未到达葛城前就将莹莹给制服住了，此时的莹莹已不再是苏彦的爱妻，而是只存在着生存本能的野兽而已。于是你痛下杀手了结了莹莹，也从她身上得到一颗诡异的心脏，看起来像是人工制成的，杨任建议你将这证物带会去给神农看看，或许里头有些什么线索也不一定??????',871),
  (146,1,'[神仙任务]护卫与传说','你为了提升杨任的自信心，于是自告奋勇到了葛城和包打听接下了一份工作，这工作原本看起来似乎很简单的样子，只要能够保护一位叫做方雯的年轻女性到达目的地就行了，但是当你听到她是要前去探索一个传说的起源时，你就知道这事情已经开始变的麻烦了??????',873),
  (146,2,'[神仙任务]护卫与传说','这方雯看起来似乎很细心，刻意的把每天所见所闻的消息写在日记上头交给你，以免她出意外了却没有人知道她发现到了什么。但是当你看见她说做就做的行动力之后，你就对这看似文静的女孩彻底的改观了??????',874),
  (146,3,'[神仙任务]护卫与传说','花了一段时间，你终于追上了方雯的脚步，在一路上你特别注意路上有没有受伤或是死亡的人，怕的就是见到方雯的尸体躺在路上，好险在这南原部落中你见到的是活蹦乱跳的小女孩方雯。就在你接过她日记之后，她马上就急着前往下一个目的地，你脑袋里突然觉得这种行为很不智，但是却来不及叫住她??????',875),
  (146,4,'[神仙任务]护卫与传说','千里迢迢赶路，你好不容易又追上了方雯，看到还是活力充沛的方雯之后原本很担心的你，心里就瞬间感觉到宽松了许多。你见到方雯以极兴奋的语气对你说目前她发现到的东西，并且把日记交给你时，你心中突然出现了一种莫名其妙的不安感，或许是错觉吧，你这样的安慰着自己??????',876),
  (146,5,'[神仙任务]护卫与传说','你好不容易终于赶到了洞窟里面，却见到满地的骷髅和吓的不知所措的方雯和王硕，但就在此时，妖物出现了！！牠趁你不注意时扑向了王硕，张开大口将王硕吞入肚子里，现场只遗留一根王硕的手指头。而方雯则是整个人吓呆住了，那妖物却是自顾自的将嘴里的王硕骨头给吐出来，一根一根的啃食着??????',877),
  (146,6,'[神仙任务]护卫与传说','当你再度回到这洞窟时，那妖物却早已不见踪影了，现场只遗留下数堆骷髅，和一位肚子被咬掉一大半的女性，你仔细一看，原来是方雯，她倒在地上嘴里不知道在念些什么，脸因疼痛与恐惧而扭曲变形??????',878),
  (146,7,'[神仙任务]护卫与传说','在你听到方雯要李方帮忙传给你知道的消息和日记的同时，你心里暗暗的叫了一声糟糕！这两个人似乎真的发现到食人魔传说中的食人魔踪影了，但是她们却没有带任何武器和配备，甚至不等你到，她们两个就独自出发探险了，你知道这行为是相当要不得以及危险的，但是无论如何，你一定要到一线天壁附近的洞窟去寻找她们的踪影才行！！',879),
  (146,8,'[神仙任务]护卫与传说','经过一段时间的缠斗，你终于收伏了这头害人无数的虎精，并且从牠的尸体里发现了许多骷髅堆，有些尸骸甚至还没被虎精给消化掉，让你看的怵目惊心的，至于方雯则是还呆呆的跪坐在地上，也许需要你推她一把，把她推醒吧??????',880),
  (147,1,'[神仙任务]真正的心声','有个叫做王升的家伙躲在赤精子庙后面，虽然赤精子不表示任何意见，但是你还是愿意帮这看起来像是被人追杀的家伙一把，帮他收集治疗他伤势的材料。不过此时你心里却有另一个声音说为何要帮这人，去葛城里通知他大哥或是叫官兵来捉拿他不也不错??????',882),
  (147,2,'[神仙任务]真正的心声','你帮王升收集了他所需要的药材来疗伤以及衣服来做绷带后，他交给你一把红柄破刀，他说这把刀是他帮派的象征，要你将这柄刀交给葛城的杨虎队长，并且向他说这刀和尸体是在龙口码头那发现的??????',883),
  (147,3,'[神仙任务]真正的心声','虽然你成功的骗过了杨虎队长，但是王升的大哥王鹏像是猎狗一样跟了过来，他现在就在赤精子庙外面，你心里正犹豫不决，到底是该保护他到底，还是要与王鹏合作，免去这场不属于你的争执??????',884),
  (147,4,'[神仙任务]真正的心声','你让王升一个人走出去，后来你听到外头有许多吆喝声和器物击打的声音，过没多久后这声音就停了??????',885),
  (147,5,'[神仙任务]真正的心声','你向王鹏透露了王升的所在地，他要你先去赤精子庙看住王升，以免他逃掉，同时也听到他说尽量不要让杨虎队长知道这件事情，看来他是想要杀人灭口了??????',886),
  (147,6,'[神仙任务]真正的心声','经过一番苦战，你顺利的打赢了王鹏一干人，并且从他手上夺走了赤刀帮用来追杀王升的通缉状，你成功的保卫住王升的命，快点和王升讲这好消息啊！',887),
  (147,7,'[神仙任务]真正的心声','你心里在经过一番交战后，你决定向王鹏让步，并答应他要交出王升出来，虽然对王升来说这不是个好消息，但是却可以省去你一番恶战，你的嘴角不禁泛出一丝笑意??????',888),
  (147,8,'[神仙任务]真正的心声','你成功的取得了杨虎队长的信任，杨虎队长一群人在你目光的欢送下，浩浩荡荡的往龙口码头方向前进去了??????',889),
  (147,9,'[神仙任务]真正的心声','你和杨虎队长透露了王鹏的计划和王升的所在地，杨虎队长乐的喜不可支，他预计可以将这两方人马一网打尽，而他也吩咐你快点到赤精子庙那边监视王鹏和王升两边人马，他随后就到??????',890),
  (147,10,'[神仙任务]真正的心声','有个叫做王升的家伙躲在赤精子庙后面，赤精子不表示任何意见，你也不清楚到底要不要帮他。不过此时你心里却有另一个声音说为何要帮这人，去葛城里通知他大哥或是叫官兵来捉拿他不也不错??????',891),
  (148,1,'[神仙任务]小偷是谁','土行孙所收藏的宝物都不翼而飞，现在要你帮忙找出小偷到底是谁 ？',893),
  (148,2,'[神仙任务]小偷是谁','玉鼎真人指示你到雨龙森林里去找迷糊仙童，或许迷糊仙童可以打听到什么消息。',894),
  (148,3,'[神仙任务]小偷是谁','迷糊仙童说他有一样法宝，可以得知小偷是谁，但是需要仙女姐姐的玉凝圣水，方才可以发挥作用。',895),
  (148,4,'[神仙任务]小偷是谁','仙女姐姐要你帮忙找寻她妹妹的下落，特征是身穿蓝衣年约十岁左右，名叫臻儿的女孩，若你帮忙达成此任务之后，她才肯把圣水送给妳，',896),
  (148,5,'[神仙任务]小偷是谁','仙童拿到此圣水施法于八卦，但却因为对方的法术太过高强，而无法发挥作用，于是仙童要你带着此道具，一一向每个神仙做确认。',897),
  (148,6,'[神仙任务]小偷是谁','玉鼎真人想起被邓婵玉捉弄，自己失忆的所做的事情，不小心脱口而出幕后主使人，深感害怕，所以准备要躲起来。',898),
  (148,7,'[神仙任务]小偷是谁','邓婵玉招认自己的罪行，心有不甘于是和土行孙大吵了起来，这下你可能要两头跑了。',899),
  (148,8,'[神仙任务]小偷是谁','土行孙要你立刻带他去找在仙界的邓婵玉算账！',900),
  (148,9,'[神仙任务]小偷是谁','你已经拿到了圣水，可以回去找迷糊仙童了。',901),
  (148,10,'[神仙任务]小偷是谁','你找到了臻儿了，可以回去跟仙女姐姐交差啦。',902),
