  (150,1,'[神仙任务]圣母的娃娃二','圣母跟要新的娃娃当生日礼物。',922),
  (150,2,'[神仙任务]圣母的娃娃二','玩偶家的小男孩要求用仿制蓝宝石﹝小﹞三十个，绒毛鸭的蛋三十个，绒毛鸭的肉三十个当作制作娃娃的费用。',923),
  (150,3,'[神仙任务]圣母的娃娃二','雕刻家的小女孩要求帮他找建材，分别是树妖木材三十个、树妖的藤蔓三十个、桧木木料三十个、废木料三十个。',924),
  (150,4,'[神仙任务]圣母的娃娃二','玩偶已经到手了，跟圣母交差吧。',925),
  (151,1,'[神仙任务]养颜秘药','高兰英抱怨最近太过劳累，使得他没空保养皮肤，要求去找养颜圣品来补一下。',927),
  (151,2,'[神仙任务]养颜秘药','药童说欠缺人蔘，没法配药，快去腾云柱那附近找找人蔘吧。',928),
