  (151,4,'[神仙任务]养颜秘药','可恶的千年人蔘别跑，一定要抓到你来配药。',930),
  (151,5,'[神仙任务]养颜秘药','要配『爱你漂亮丸』，需要上等的雪莲，妙手大夫说风云顶那附近应该找得到。',931),
  (151,6,'[神仙任务]养颜秘药','『天上天下唯我独尊十全大补丸』，希望这东西高兰英会喜欢吧',932),
