  (152,1,'[神仙任务]渡劫','云中子要你前往葛城找寻闻仲后人闻英一趟',937),
  (152,2,'[神仙任务]渡劫','你已经见过闻英，看他似有难言之隐，又像是有志难伸，还是先跟云中子回报吧',938),
  (152,3,'[神仙任务]渡劫','云中子给了你一个锦囊，要你去拿给闻英',939),
  (152,4,'[神仙任务]渡劫','闻英要你先去认识一下陈知州大人，他人应该葛城府衙附近',940),
  (152,5,'[神仙任务]渡劫','你见过陈知州了，看起来不过是个贪官，不是个大人物，回去看看闻英怎么说吧',941),
  (152,6,'[神仙任务]渡劫','闻英要你再去找一次知州大人，不过这次是开门见山的说，看他到底会有什么反应',942),
  (152,7,'[神仙任务]渡劫','你揭穿了陈知州的真面目，不过却在剎那间被击败，醒来已是在飞龙瀑布旁了，看来要快把这消息告诉闻英才行',943),
  (152,8,'[神仙任务]渡劫','你取得了仙酒，决定前往八卦石洞找寻妖狐的元神',944),
  (152,9,'[神仙任务]渡劫','你打败了妖狐元神，也取得了陈知州的骸骨，现下就先回去找闻英一趟吧',945),
  (152,10,'[神仙任务]渡劫','闻英说妖狐化身成陈知州向曲湖一带逃去了，接下来是该把妖狐给了结了的时候',946),
  (152,11,'[神仙任务]渡劫','你已经杀了妖狐，也取下首级，回去找闻英报喜讯吧',947),
  (152,12,'[神仙任务]渡劫','顺利解决了闻英的困扰，快向云中子报告吧！',948),
  (152,13,'[神仙任务]渡劫','云中子要你去从葛城的辛小环身上打听看看有什么消息',949),
