  (152,16,'[神仙任务]渡劫','辛小环要你找哮天犬和金棍，这东西并非凡物，只好问问云中子该怎么办了',952),
  (152,17,'[神仙任务]渡劫','云中子要你去找来三十个树妖木材和十个狐皮和十个狐爪，如此才能变出金棍和哮天犬',953),
  (152,18,'[神仙任务]渡劫','你已经取得了云中子给你的金棍和哮天犬印，先去找辛小环再说',954),
