  (152,20,'[神仙任务]渡劫','有了八卦火种，看来化身成陈知州的妖狐命不久矣，这就找牠去吧',956),
  (153,1,'[神仙任务]张奎的补偿','张奎要你前往昆仑仙界向伙房师傅收集瓶中花、药草师傅收集三份仙草粉，并设法经由守门师傅的帮助取得圣兽的唾液，最后请李靖来帮他制作洗髓拔毛丹',958),
  (153,2,'[神仙任务]张奎的补偿','总算拿到了洗髓拔毛丹，快拿给张奎吧！',959),
