  (156,4,'[神仙任务]武吉的宿命','昆吾镇长将森林大火一事告知了你们，就看看武吉要如何做了',976),
  (156,5,'[神仙任务]武吉的宿命','再问问镇长，看有没有更多的线索吧',977),
  (156,6,'[神仙任务]武吉的宿命','镇长说大火在望星巨木一带发生，和武吉讨论一下要怎么办吧',978),
