  (156,8,'[神仙任务]武吉的宿命','想不到那么容易就找到线索了，邬文化一口坦承恶行，看来他是冲着武吉来的，快问问武吉要怎么办吧',980),
  (156,9,'[神仙任务]武吉的宿命','武吉决定再次将邬文化打倒，以阻止他再危害人间',981),
  (156,10,'[神仙任务]武吉的宿命','总算打赢了邬文化，也算是了结武吉的一段宿命吧',982),
