  (157,2,'[神仙任务]普贤的整人计划','把制作好的诱饵装备分别放置在参北之境和四方台跟驾雾柱及镇岳碑附近的普贤宝箱内。',986),
  (157,3,'[神仙任务]普贤的整人计划','去找宋谛涂制作参天林跟夹龙纵谷的藏宝图。',987),
  (157,4,'[神仙任务]普贤的整人计划','把参天林跟夹龙纵谷的藏宝图分别拿给枫华镇的挖宝三人组吴娃跟流浪三人组浪蹈吧！',988),
  (157,5,'[神仙任务]普贤的整人计划','到普贤神庙里启动诱饵装备的陷阱吧。',989),
  (157,6,'[神仙任务]普贤的整人计划','该去验收成果了，去看看挖宝三人组跟流浪三人组被整的如何。',990),
  (158,1,'[神仙任务]记忆恢复！？','玉鼎对自己脑袋不灵光的事耿耿于怀，求你走一趟神农庙，拜托神农氏为其治疗',992),
  (158,2,'[神仙任务]记忆恢复！？','神农氏表示自己也无能为力，看来玉鼎要失望了',993),
  (158,3,'[神仙任务]记忆恢复！？','玉鼎建议去找找金光圣母看看，要去找圣母，当然要准备点东西了，去枫华镇的杂货铺买五彩缤纷糖果吧',994),
  (158,4,'[神仙任务]记忆恢复！？','你决定再去找一次神农氏，看是不是真的没法子',995),
  (158,5,'[神仙任务]记忆恢复！？','神农给了你一张药单，找齐这些素材再说吧',996),
  (158,6,'[神仙任务]记忆恢复！？','神农拿给了你几颗黑不隆咚的药丸，就给玉鼎试试吧',997),
  (158,7,'[神仙任务]记忆恢复！？','玉鼎真人吃了药全身不对劲，快问问神农氏吧',998),
  (158,8,'[神仙任务]记忆恢复！？','神农说拿错药了，这会又拿了一包散给你，也不知玉鼎这次吃了会怎么样',999),
  (158,9,'[神仙任务]记忆恢复！？','拿到糖果了，现在就动身去找金光圣母',1000),
  (158,10,'[神仙任务]记忆恢复！？','金光圣母给了你一张药单，不管有没有用了，反正死马当活马医，先去找齐药材再说',1001),
  (158,11,'[神仙任务]记忆恢复！？','金光圣母给了一道难题，有了药材却没人配药！？唯一线索是神木集的玄天乌鸦，就去找找吧',1002),
  (158,12,'[神仙任务]记忆恢复！？','召厄亭，看来有了一线曙光，虽然不知道要找谁，反正去四处问问就是了',1003),
  (158,13,'[神仙任务]记忆恢复！？','原来疯仙人就是金光圣母口中的老祖宗？不过，要他答应帮忙可要先打过他召唤出来的圣兽才行',1004),
  (158,14,'[神仙任务]记忆恢复！？','总算拿到了，这颗怪怪的药丸希望真的能帮到玉鼎',1005),
  (159,1,'[神仙任务]五魔岗魔人？','李靖觉得庙里有事，央求你回庙里一趟',1007),
  (159,2,'[神仙任务]五魔岗魔人？','庙公说庙外有位姑娘似乎有什么难言之隐，过去问问吧',1008),
  (159,3,'[神仙任务]五魔岗魔人？','五魔岗魔人！？看李靖脸上一阵青红，先问问他好了',1009),
  (159,4,'[神仙任务]五魔岗魔人？','按理说，五魔岗的人不致于如此，去问问五魔岗寨主是怎么回事好了',1010),
  (159,5,'[神仙任务]五魔岗魔人？','看来这号人物和五魔岗并无关连，问问李靖要怎么办吧',1011),
  (159,6,'[神仙任务]五魔岗魔人？','李靖要你赶紧再问问寨主那个烈风云的下落',1012),
  (159,7,'[神仙任务]五魔岗魔人？','寨主说了烈风云人在参天林的某个黑洞，看李靖怎么打算吧',1013),
  (159,8,'[神仙任务]五魔岗魔人？','你们决定身入参天林去找藏匿在某个黑洞里的烈风云',1014),
  (159,9,'[神仙任务]五魔岗魔人？','你打败了烈风云，竟然从他身上拿到了乾坤圈？这东西不是哪咤的吗？快问问李靖怎么回事吧',1015),
  (159,10,'[神仙任务]五魔岗魔人？','李靖要你快去哪咤庙里找他问问事情到底是怎么回事',1016),
  (159,11,'[神仙任务]五魔岗魔人？','想不到哪咤竟然转了性，这下李靖可乐了，也好，这事也算了结了吧',1017),
  (160,1,'[神仙任务]作怪','李靖说要去探访一下太乙真人，这就出发吧',1019),
  (160,2,'[神仙任务]作怪','李靖要你和他一起前往幽原台附近查探，寻找妖气来源的任何蛛丝马迹',1020),
  (160,3,'[神仙任务]作怪','顺风耳怎么话说起来如此不得体，看看千里眼是不是也一样',1021),
  (160,4,'[神仙任务]作怪','千里眼和顺风耳很是奇怪，问问李靖有什么想法吧',1022),
  (160,5,'[神仙任务]作怪','桃柳精的本体隐藏在翠玉林里，这下有了方向，准备一下就去收拾这不知好歹的妖物吧',1023),
  (160,6,'[神仙任务]作怪','总算解决了桃柳精，跟李靖分享一下战胜的喜悦吧',1024),
  (161,1,'[神仙任务]宝贝夜壶','土行孙正为他遭殃的夜壶而伤心，希望你能走一遭姜子牙庙，问问姜子牙有没有法子帮他',1026),
  (161,2,'[神仙任务]宝贝夜壶','姜子牙说可以去葛城找神算杨国书看看，或许能查出什么端倪',1027),
  (161,3,'[神仙任务]宝贝夜壶','杨国书指引你去找葛城的富豪季承远，不过他这个人似乎并不好说话',1028),
  (161,4,'[神仙任务]宝贝夜壶','杨国书这次说另一个夜壶碎片应该在他娘杨婆婆身上，这就在葛城里找找吧',1029),
  (161,5,'[神仙任务]宝贝夜壶','总算拿到了第一个碎片，回去问问神算杨国书有没有其它碎片的下落吧',1030),
  (161,6,'[神仙任务]宝贝夜壶','总算拿到了第二个碎片，再回去问问神算杨国书有没有其它碎片的下落吧',1031),
  (161,7,'[神仙任务]宝贝夜壶','在杨国书给了第三个碎片并告知最后一个碎片落在雨龙森林的四象台，这就动身去那找找吧，看是被谁捡走了',1032),
  (161,8,'[神仙任务]宝贝夜壶','这旺财完全没有想把东西给你的打算啊！这可怎么跟土行孙交差呢',1033),
  (161,9,'[神仙任务]宝贝夜壶','土行孙建议去普贤真人的庙里休息一下，再想想有什么法子吧',1034),
  (161,10,'[神仙任务]宝贝夜壶','想不到普贤真人竟然给了你最后一个碎片！这可是天大的好消息啊，快问问土行孙要怎么把这夜壶组合起来吧',1035),
  (161,11,'[神仙任务]宝贝夜壶','东西总算备齐了，这就去葛城找邓婵玉口中的仙鹤道僮吧',1036),
  (161,12,'[神仙任务]宝贝夜壶','终于把夜壶给弄回来了，快跟土行孙交差吧！',1037),
  (162,1,'[神仙任务]抉择','慈航要你去昆吾镇寻找求助者为何人。',1039),
  (162,2,'[神仙任务]抉择','接受了孙慕容的请托，首先必须去水岚草地查端倪。',1040),
  (162,3,'[神仙任务]抉择','慈航要你去水岚草地调查这件事情的始末。',1041),
  (162,4,'[神仙任务]抉择','慈航怀疑古井的女鬼就是犯人。',1042),
  (162,5,'[神仙任务]抉择','打赢了傲慢的古井女鬼。',1043),
  (162,6,'[神仙任务]抉择','古井女鬼说出整件事情的始末，跟慈航讨论一下要怎么办吧。',1044),
  (162,7,'[神仙任务]抉择','决定是否要救人，或者放弃。',1045),
  (162,8,'[神仙任务]抉择','慈航给你的药单上，有着详细记载药品的出处。',1046),
  (162,9,'[神仙任务]抉择','药品已经收集，慈航要你把药品带给孙慕容。',1047),
  (163,1,'[神仙任务]土行孙十大板','土行孙要你去找太乙真人帮忙送东西。',1049),
  (163,2,'[神仙任务]土行孙十大板','太乙真人不敢招惹邓婵玉，所以拜托你转告邓婵玉有此事。',1050),
  (163,3,'[神仙任务]土行孙十大板','邓婵玉感到受委屈了，决定要离家出走，这时候刚好遇到土行孙外出。',1051),
  (163,4,'[神仙任务]土行孙十大板','邓婵玉离家出走了，土行孙请你帮他到昆仑仙界请教众神仙，有谁知道邓婵玉的下落。',1052),
  (163,5,'[神仙任务]土行孙十大板','金光圣母要土行孙回去好好反省，并且写一封文情并茂的悔过书，她才愿意告知下落。',1053),
  (163,6,'[神仙任务]土行孙十大板','土行孙百般不愿意写了信来，金光圣母说她会帮忙转交，至于事情会不会有下文，她不敢作保证。',1054),
  (163,7,'[神仙任务]土行孙十大板','土行孙灵机一动，想到邓婵玉会不会又躲回庙里，请玩家到鸿蒙境邓婵玉庙里查看。',1055),
  (163,8,'[神仙任务]土行孙十大板','邓婵玉要原谅土行孙没问题，但是要你拿着这个大木棍，朝着土行孙打十大板。',1056),
  (163,9,'[神仙任务]土行孙十大板','终于完成邓婵玉交差的使命，顺道把这跌打损伤功夫膏药拿给土行孙去。',1057),
  (163,10,'[神仙任务]土行孙十大板','邓婵玉一怒之下把你丢回了枫华镇，问问土行孙怎么办好了',1058),
  (164,1,'[神仙任务]本命丹炉','石矶娘娘要求你去收集白银十个、精金二十个、蓝色矿石三十个、仿制钻石(小)一个来当作炼制本命丹炉的材料',1060),
  (164,2,'[神仙任务]本命丹炉','娘娘说了，接下来要走一趟哪咤神庙，去请哪咤用三昧真火淬炼仿制钻石(小)',1061),
  (164,3,'[神仙任务]本命丹炉','哪咤已经帮忙了，再问问娘娘接下来要做什么吧',1062),
  (164,4,'[神仙任务]本命丹炉','到石矶娘娘的神庙准备炼制本命丹炉',1063),
  (164,5,'[神仙任务]本命丹炉','找石矶娘娘的徒弟王化宇，并且帮助他用元神修练本命丹炉',1064),
  (164,6,'[神仙任务]本命丹炉','找石矶娘娘的徒弟李力，并且帮助他用元神修练本命丹炉',1065),
  (164,7,'[神仙任务]本命丹炉','找石矶娘娘的徒弟鱼轩硕，并且帮助他用元神修练本命丹炉',1066),
  (164,8,'[神仙任务]本命丹炉','辛好及时阻止了王化宇的魔化，否则后果不堪设想，快跟娘娘报告结果好了',1067),
  (164,9,'[神仙任务]本命丹炉','辛好及时阻止了李力的魔化，否则后果不堪设想，快跟娘娘报告结果好了',1068),
  (164,10,'[神仙任务]本命丹炉','总算帮李力炼好了，快跟娘娘报告吧！',1069),
  (164,11,'[神仙任务]本命丹炉','总算帮鱼轩硕炼好了，快跟娘娘报告吧！',1070),
  (165,1,'[神仙任务]商会战争','苏信豪派遣到南方葛城的手下们被人用邪术给化作石头了！苏信豪拜托你前往他们被化作石头的地点查看一下他们的情况，并且帮帮他们。你一时间还不知道该怎么处理这状况，不过不知道身为谋士的崇黑虎知不知道该怎么解决这件麻烦的事情???',1072),
  (165,2,'[神仙任务]商会战争','在经过了这么多的事件后，你决定在府衙外守候着苏信豪，以避免其他闲杂人等意图闯入府衙内。过没多久，你就见到苏信豪缓缓从府衙内走了出来。不过见到他眉头深锁，不知道是不是还有什么话想跟你说???',1073),
  (165,3,'[神仙任务]商会战争','虽然苏信豪看起来似乎很急的样子，但是面对你的要求，苏信豪也没有多说半句闲话。看来苏信豪是真的有意要与崇伯虎合好。这应该是件好事才对，快点去见见崇伯虎吧！',1074),
  (165,4,'[神仙任务]商会战争','看着苏崇两家又开始联络后，你见到身后的崇黑虎脸上总是紧绷着的表情向是舒缓多了的样子。不过接着苏信豪就对你说他现在所处的苦境。他派遣到南方葛城的手下们被人用邪术给化作石头了！苏信豪拜托你前往他们被化作石头的地点查看一下他们的情况，并且帮帮他们。不过你一时间还不知道该怎么处理这状况，不过不知道身为谋士的崇黑虎知不知道该怎么解决这件麻烦的事情???',1075),
  (165,5,'[神仙任务]商会战争','原来一切都是南方商会所做的！看来之后葛城与枫华镇之间的冲突是在所难免了！不过在此之前，苏信豪希望你带着礼物去见崇伯虎，在这危难中正是促进两家调解的最佳时机，快点去见崇伯虎吧！',1076),
  (165,6,'[神仙任务]商会战争','原来一切都是南方商会所做的！看来葛城与枫华镇之间的冲突是势在必行了！现在苏信豪派遣你当他的先行部队，要你先一步到南方商会去抢会旗。只要会旗一到手，按照商会战争的规矩，只能乖乖的承认战败。在考虑你有崇黑虎护深的情形下，派遣你前去抢会旗是最佳的选择了！快点前往南方商会吧！',1077),
  (165,7,'[神仙任务]商会战争','因为你的失误，而造成了苏信豪三名手下不幸丧生。但是这样子却也更加深了苏信豪对南方商会的仇视程度，他打算直接发动商会战争。现在苏信豪派遣你当他的先行部队，要你先一步到南方商会去抢会旗。只要会旗一到手，按照商会战争的规矩，只能乖乖的承认战败。在考虑你有崇黑虎护深的情形下，派遣你前去抢会旗是最佳的选择了！快点前往南方商会吧！',1078),
  (165,8,'[神仙任务]商会战争','原来崇苏这两家人还曾经是结拜兄弟，只是为什么现在会变成这样水火不容的局面呢？你不得而知，不过苏信豪也确实的听从了崇伯虎的建议，打算从葛城府衙那下手。走正途，不用私下火并的方式来解决现有的尴尬局面。不过南方商会的人在打听到消息后会不会对苏信豪先行下手呢？你不得而知。不过现在你能做的，就只有先到葛城府衙那保护苏信豪顺利的进入府衙内了！',1079),
  (165,9,'[神仙任务]商会战争','你利用苏信豪对你的信任顺利的骗取到罂粟花的种子，现在只要回去南方商会和南方商会的会长复命就好了。',1080),
  (165,10,'[神仙任务]商会战争','面对突如其来的袭击，虽然你眼捷手快的阻止了飞箭，但却无法完全改变飞箭的飞行轨道。当你抬头向前望时只看到苏信豪倒地不起，胸口还插进一把箭，生死未卜。然而放冷箭的凶手却在你身后笑着，看到此情此景，你不由得怒火中烧了起来???',1081),
  (165,11,'[神仙任务]商会战争','苏信豪平安无事的从葛城走回枫华镇，而枫华镇与葛城之间的工会冲突也在苏信豪踏入葛城府衙之后得以一个和平的收场，相信两地之后的贸易应该不会有太大的阻碍了。而苏信豪也正准备正式的向崇伯虎提出和解协议，以后两家人应该可以尽释前嫌和平共处了。你看着身后的崇黑虎嘴角难得露出一点笑意，看了只觉得恶心，不过他看起来似乎有话想说的样子，不知道想说些什么就是了???',1082),
  (165,12,'[神仙任务]商会战争','在听完苏信豪的告解之后，你完全无法原谅苏信豪之前的所作所为，而苏信豪却也早有准备等事件完成之后就要引咎自杀。如今枫华镇与葛城的事情虽然得以完满的解决，但是枫华镇上却少了一位杂货铺的二当家，这职务，苏信豪在死前还吩咐你交代给崇伯虎来完成。现在就去枫华镇上去找崇伯虎谈谈这件事情吧。',1083),
  (165,13,'[神仙任务]商会战争','在你成功的击退了暗地放冷箭的杀手之后，你回过身去探苏信豪的脉搏，发现苏信豪并无生命危险。原来是崇伯虎的护身符帮苏信豪挡下了这一箭！看来这一切都是天意，苏信豪吸了口气后便站了起来琅呛的走进了葛城府衙内，现在就只能在外面静静的等苏信豪出来了。你看着身后的崇黑虎眉头深锁，看来似乎很担心苏信豪的样子???',1084),
  (165,14,'[神仙任务]商会战争','面对这杀手无情且猛烈的攻势下，你虽然极力抵抗，但是在孤立无援的状况下，你还是败下了阵来。等你悠悠醒过来，看到的却是满身染满鲜血的苏信豪。他挣扎的用尽最后一分力量，吩咐你将这护身符交给崇伯虎，并且将杂货铺二掌柜的位置让给他后就咽下最后一口气了。你无法挽回苏信豪的性命，你现在唯一能做的，就是按照他的吩咐，回枫华镇向崇伯虎说出一切实情，并交代苏信豪的话给崇伯虎知道而已了???',1085),
  (165,15,'[神仙任务]商会战争','虽然这杀手功夫高强，但面对有神灵加护的你来说，并不是什么强敌。你将他击退后，看着躺在地上的苏信豪，你在担心不知道他到底有没有事。还是快点过去看看他好了???',1086),
  (165,16,'[神仙任务]商会战争','这场仗你败的难看，幸亏你有神灵加护，不然恐怕站起来的地方就会是阎王殿了。但是苏信豪可没有神灵护体，不知道他在葛城的状况到底是怎样了。快点回葛城看看他的情况吧！',1087),
  (165,17,'[神仙任务]商会战争','经过了一番冲突，你顺利的抢到了南方商会的会旗，现在就快点把这会旗带回枫华镇给苏信豪吧！',1088),
  (165,18,'[神仙任务]商会战争','因为苏信豪似乎有太多事情瞒着你，所以你被南方商会会长给说服要回头对付苏信豪。现在就回去枫华镇和苏信豪要求援助吧，不过可千万不要说露了嘴让事迹败露喔！',1089),
  (165,19,'[神仙任务]商会战争','你将南方商会会长派出来的杀手给打的七零八落，看着眼前目瞪口呆的南方商会会长，你只觉得这家伙现在看起来实在是相当渺小的人物而已。如果现在问他他叫什么名字，他应该会连祖宗十八代的姓氏都报出来吧。现在应该是和他谈判的好时机！快和他谈谈吧！',1090),
  (165,20,'[神仙任务]商会战争','石矶娘娘给了你一瓶可以解除石化状态的药剂，不过为了因应受术者被石化的情况，所以石矶娘娘减少了部分的剂量，只能使用在石化程度低的那人身上而已。这药剂是淋在其他受术者上面，可能会导致整个石化力场的崩坏，进而让三位受术者瞬间化为飞灰。所以要谨慎使用啊！',1091),
  (165,21,'[神仙任务]商会战争','石矶娘娘给了你一瓶可以解除石化状态的药剂，不过为了因应受术者被石化的情况，所以石矶娘娘没有增减任何剂量，所以这只能使用在石化程度一般的那人身上而已。这药剂是淋在其他受术者上面，可能会导致整个石化力场的崩坏，进而让三位受术者瞬间化为飞灰。所以要谨慎使用啊！',1092),
  (165,22,'[神仙任务]商会战争','石矶娘娘给了你一瓶可以解除石化状态的药剂，不过为了因应受术者被石化的情况，所以石矶娘娘增强了剂量，所以这只能使用在石化程度很严重的那人身上而已。这药剂是淋在其他受术者上面，可能会导致整个石化力场的崩坏，进而让三位受术者瞬间化为飞灰。所以要谨慎使用啊！',1093),
  (165,23,'[神仙任务]商会战争','石矶娘娘要你带回在这三人身上的碎片，赶快到那三人的所在位置，好好调查一下吧！',1094),
  (165,24,'[神仙任务]商会战争','你收集了被石化者其中之一的碎片，等搜集齐三片碎片后就可以带回去给石矶娘娘看了。',1095),
  (165,25,'[神仙任务]商会战争','你成功的让其中一位恢复了部分的状态，但因为这石化力场的关系，所以还不能完整的解除这石化状态。现在快点拿着空瓶子在回去仙界和石矶娘娘要药剂吧！',1096),
  (165,26,'[神仙任务]商会战争','由于你一时的疏忽，而导致被石化的三人瞬间就被石化力场给吞噬掉，化为尘土了。现在只好回枫华镇上和苏信豪报告这件悲剧了???',1097),
  (165,27,'[神仙任务]商会战争','你成功的解除了苏信豪那三名手下的石化状态了。他们在临走之前将南方商会对他们发出的通缉令交托给你，要你将这通缉令带回去给苏信豪。',1098),
  (165,28,'[神仙任务]商会战争','也许因为拉不下脸的关系，崇伯虎虽然口头上答应不再和苏信豪起争执，但却不愿意直接对着苏信豪说，而要透过你这中间人来帮他们居中调解。现在就回枫华镇杂货铺中找苏信豪谈话吧。',1099),
  (165,29,'[神仙任务]商会战争','看着崇伯虎的醒悟，你心里感到万分的庆幸。而崇伯虎似乎也在观察南方商会的行动，他要你帮他带一句话回去给苏信豪，要他小心南方商会的那群人。',1100),
  (166,1,'[阵法任务]','可以前往天绝阵（参天林300，626）挑战秦天君的考验，怪物强度大约在40级左右。',1102),
  (166,2,'[阵法任务]','可以前往地烈阵（雨龙森林308，528）挑战赵天君的考验，怪物强度大约在50级左右。',1103),
  (166,3,'[阵法任务]','可以前往红沙阵（夹龙纵谷355，750）挑战张天君的考验，怪物强度大约在60级左右。',1104),
  (166,4,'[阵法任务]','可以前往化血阵（穿龙瀑布壁洞78，83）挑战孙天君的考验，怪物强度大约在70级左右。',1105),
  (166,5,'[阵法任务]','可以前往金光阵（八卦迷宫离之境101，89）挑战金光镜的考验，怪物强度大约在80级左右。',1106),
  (167,1,'[神仙任务]宿敌','你听完崇黑虎对你说的事情后，便火速的前往枫华镇找哪咤探查一下他的情况。但还是晚了一步，不过幸好哪咤功力深厚，没受到什么伤。唯一伤到的地方是眼睛，现在他的眼睛睁不开来，他要你去帮他收集五份蟠桃水和五份蟾蜍油来帮他洗眼睛。',1108),
  (167,2,'[神仙任务]宿敌','你眼见情形不对，正准备要脱离这战场时，只见已决心一死的崇黑虎还继续的和高继能的蜈蜂们拼斗着。你好说歹说总算是在关键的时刻说服了好斗的崇黑虎，你们利用哪咤给的替身护符逃往仙界去。在这途中，你想起来高继能以前是被崇黑虎击败的事情，不知道当时崇黑虎是怎么解决他的，问看看崇黑虎也好。',1109),
  (167,3,'[神仙任务]宿敌','即使哪咤说话再怎么不客气，你最终还是隐忍了下来，治疗好了哪咤的眼睛。哪咤除了告知你高继能现在的下落是在截仙遗址的极南台附近之外，还给了你一个法宝，看这法宝造型有些奇特，不知道是有着什么样的用途？',1110),
  (167,4,'[神仙任务]宿敌','你从药草师傅手中接过浇水壶，那原本应该是崇黑虎独门法宝的红葫芦才对。既然这东西是被普贤真人炼化成另一种型态的法宝，那普贤真人应该有办法再把他变回来或是再改变一次这法宝的型态吧？',1111),
  (167,5,'[神仙任务]宿敌','看来普贤真人似乎真有一套的样子，他将浇水壶炼化成土块，你接过这土块后发觉这土块虽然轻，但你不管使多大的劲也无法改变这土块的形状。看到你这么做之后，你想起了普贤真人对你说的，这东西只有找仙界中力量最大的人才可以改变这形状。仙界中力量最大的？你想了想，好像只有拳头师傅才够格被这么称呼吧？',1112),
  (167,6,'[神仙任务]宿敌','你从普贤真人的手中接过了崇黑虎的红葫芦，听说只要揭开了红葫芦的盖子，铁嘴神鹰就会从里面飞出，并听从操控者的使唤。看来有了这铁嘴神鹰，应该就足以对付高继能的那群蜈蜂了吧？再回截仙遗址去找高继能报仇雪耻吧！',1113),
  (167,7,'[神仙任务]宿敌','你跟拳头师傅大打一架后，拳头师傅总算是愿意帮你捏这土块了。你有时真搞不懂，为什么这家伙和崇黑虎一样总是爱用暴力来解决问题。不过算了，反正你也达成了你的目的，还是快点将这变形的土块拿给普贤真人吧。',1114),
  (167,8,'[神仙任务]宿敌','同一件事情总是可以找到不同的解决方式！你利用言语的力量，成功的说服了拳头师傅帮你捏土块，避免了一场不必要的战斗。现在就快点将这土块拿给普贤真人吧！',1115),
  (167,9,'[神仙任务]宿敌','卑鄙的小人！高继能用言语骗你与他单挑，但却在战前趁你不注意，用他的宝贝蜈蜂将你打成重伤，随后便又召唤出更多的蜈蜂出来与你战斗。看来不想办法破解高继能的蜈蜂，你就无法将高继能击败。也许现在撤退想一个权宜之计才是最重要的吧！你虽然这么想着，但是崇黑虎似乎还打算继续抵抗下去，看来不劝劝他是不行的！',1116),
  (167,10,'[神仙任务]宿敌','在高继能祭出他得意蜈蜂的同时，你也揭开了崇黑虎的红葫芦。霎时，只见到数只铁嘴神鹰伴随着一道金光从崇黑虎的红葫芦内跑了出来。这些铁嘴神鹰没多久就将那群蜈蜂啄个遍体鳞伤。没有了那群蜈蜂的护卫，高继能也禁不住你和崇黑虎的攻击，没多久就败下了阵来。看着高继能逃之夭夭，崇黑虎也不打算继续追逐下去，不知道崇黑虎心里是在盘算什么，还是过去问看看他好了。',1117),
  (168,1,'[神仙任务]夺回','真是误交损友，原本和崇伯虎一起的朋友趁崇伯虎不注意便将他身边的东西都抢走了。崇伯虎要你帮他去三个地方夺回他被原本的同伴抢走的东西。崇伯虎说那群人会藏匿的地点有三个，一个是截仙遗址小天云池附近。一个是在圣樵原野火云碑那边。还有一个则是在夹龙纵谷的云峰部落里面。快点去这三个地方把东西给找回来给崇伯虎吧！',1119),
  (168,2,'[神仙任务]夺回','比起那些被偷的东西，你更在乎崇伯虎是否真的愿意原谅苏信豪，毕竟这是崇黑虎这次下凡的心愿之一。将这封信交给苏信豪吧，这应该是开启双方沟通协调的好时机才是。',1120),
  (168,3,'[神仙任务]夺回','你将苏信豪要给崇伯虎的东西带了过去，也知道了苏崇两家为何会交恶的原因。一切都是由人心所生出的罪恶啊。但亡羊补牢犹未晚矣，既然崇伯虎有心回头，你也不再多说什么了。目前最重要的，就是帮崇伯虎把被偷的东西给夺回来吧！崇伯虎说那群人会藏匿的地点有三个，一个是截仙遗址小天云池附近。一个是在圣樵原野火云碑那边。还有一个则是在夹龙纵谷的云峰部落里面。快点去这三个地方把东西给找回来给崇伯虎吧！',1121),
  (168,4,'[神仙任务]夺回','听崇伯虎讲说不敢再碰罂粟花这害人的东西，可是你也不知道该如何处理这玩意儿。也许崇黑虎会有办法吧，不妨问看看他好了。',1122),
  (168,5,'[神仙任务]夺回','在你将崇伯虎的信件交给苏信豪后，你便静静的听着苏信豪对当年所作所为的道歉。最后他要你带着一样东西回去交给崇伯虎，看来他也有诚意要与崇伯虎和解，快点去跟崇伯虎说这消息吧！',1123),
  (168,6,'[神仙任务]夺回','你答应了那名盗匪，收他的钱放过他。但是该怎么跟崇伯虎交代呢？就在此时，有个声音自你心里传来说，管他的，反正就直接和崇伯虎实话实说就好了。',1124),
  (169,1,'[神仙任务]误会','你听从杨任的话，到了暮汐村找到了刘玉。在交谈过后，你发现刘玉是位很老实很认命的一位妇人。你不明白这种人会惹到什么样的麻烦。在事情还尚未完全明白的情形下，你无法多做什么臆测。当你正在想事情时，却被在地上一人独自游玩的琪钧给打乱了思绪。看着这小女孩孤独游戏的背影，你不自觉的同情了她起来。过去和她谈一谈吧！你此时的心理是这样想着的。',1126),
  (169,2,'[神仙任务]误会','你看着杨任修好的娃娃，突然有股思念从这娃娃中流入到你的脑袋里。你很清楚的看到这些年来，琪钧身旁的同伴一个一个的不见，到现在唯一的同伴只剩下一只破旧的玩具娃娃而已。你感受到这股思念充满着天真与寂寞，但是却又包含着一股暖意，好像是杨任的精神波动。看来杨任也是放心不下这个孤单的孩子。唉，还是快点把这娃娃交还给琪钧吧。',1127),
  (169,3,'[神仙任务]误会','一个天真的女孩，丝毫不考虑你是不是会害她，就缠着你要你陪她玩。也许可以从她身上知道些什么事情吧？还是快去把她找出来吧！',1128),
  (169,4,'[神仙任务]误会','一个天真的女孩，丝毫不考虑你是不是会害她，就缠着你要你陪她玩。也许可以从她身上知道些什么事情吧？还是快去把她找出来吧！',1129),
  (169,5,'[神仙任务]误会','一个天真的女孩，丝毫不考虑你是不是会害她，就缠着你要你陪她玩。也许可以从她身上知道些什么事情吧？还是快去把她找出来吧！',1130),
  (169,6,'[神仙任务]误会','也许真是怕你跑掉了吧，琪钧说什么也要把跟在她身旁的娃娃交给你修理，但毕竟你是有任务在身的人，不可能长久的陪在她身边。把这娃娃交给杨任吧，他应该会有办法的。',1131),
  (169,7,'[神仙任务]误会','看来这群妖猴就是让这暮汐村小孩失踪的主要原因了！虽然你打败了牠们，但是牠们还是趁你不注意时将琪钧带走。这次可换成是你没有主意了，不过你不知道杨任那家伙会不会有办法???',1132),
  (169,8,'[神仙任务]误会','也许是这些年来一直忍受孤独的结果吧，琪钧的心理并没有你想象的那么脆弱，但是你还是有点担心的看着她离开。不知道这一路上会不会出事，还是快点回去暮汐村和她母亲刘玉联络吧！',1133),
  (169,9,'[神仙任务]误会','你成功的解决了袁洪这野性不改的仙人，以后暮汐村的村民应该不用在害怕小孩子会突然莫名其妙的消失了吧。不过比起这件事，你更关心琪钧的状况，不知道她有没有被吓着，还是快过去看看她吧！',1134),
  (169,10,'[神仙任务]误会','冤家路窄！你总算是在这荒山野岭中遇见了瘟神吕岳，他利用袁洪来帮他抓小孩来作他病毒的实验，并且让袁洪吃掉那些实验失败的作品。身为仙人连杨任也看不下去！这仙人真是罪大恶极！好在今日终于是死在你手下。你也总算是帮了枫华镇的言就元夫妇和葛城苏彦莹莹还有暮汐村中等人报仇。不过现在不是感动的时候，不知道琪钧有没有受伤，还是快点过去问看看她吧！',1135),
  (169,11,'[神仙任务]误会','你要杨任变出一点戏法来哄哄琪钧这寂寞的小女孩。看着琪钧高兴的样子，你的心情也感觉温暖多了。但也许真是怕你跑掉了吧，琪钧说什么也要把跟在她身旁的娃娃交给你修理，但毕竟你是有任务在身的人，不可能长久的陪在她身边。把这娃娃交给杨任吧，他应该会有办法的。',1136),
  (170,1,'[神仙任务]戒','赤精子的话还是像以前那样难懂，不过毕竟你已经待在他身旁有段时间了，对于他的表达方式也算有些了解。当你依照他的话，赶到了姜子牙庙后，姜子牙告诉你有下凡仙童和他说南方神木集那有个叫做郑伦的人在利用赤精子的名字来招摇撞骗，要你和赤精子赶去那看看。',1138),
  (170,2,'[神仙任务]戒','难得赤精子会主动提供你法宝，看来他也无法忍受有人利用他名号吧？也或许是他讨厌有人自称是他徒弟的关系吧？总之，现在就再回去找郑伦，拆他的台子去！',1139),
  (170,3,'[神仙任务]戒','呼哈哈哈，我是男塾塾长江田岛平八！！',1140),
  (170,4,'[神仙任务]戒','在接触过他之后，你觉得如果你不是仙童的话很有可能也会被他所骗。不过不知道赤精子会作何感想？也许会毫不在乎吧？你是这么猜想着。',1141),
  (170,5,'[神仙任务]戒','这法宝的幻术可不是像郑伦那样的三脚猫功夫而已，而是真正的将他变成了一头牛。看到他惊慌失措的神情，你忍不住暗暗的笑了出来。也许这样的教训应该够了吧？再去问看看郑伦他，看他的反应如何吧。',1142),
  (170,6,'[神仙任务]戒','这法宝的幻术可不是像郑伦那样的三脚猫功夫而已，而是真正的将他变成了一个老人。看到他惊慌失措的神情，你忍不住暗暗的笑了出来。也许这样的教训应该够了吧？再去问看看郑伦他，看他的反应如何吧。',1143),
  (170,7,'[神仙任务]戒','你从郑伦的口中得知他施展这幻术的力量来源是你手中的这只戒指。听他说这只戒指是他在参天林参北之境修炼时遇到一个神秘女子，那女子交给他的。只是不管你怎么听就是觉得不太寻常，也许你应该要去那边看一看吧。',1144),
  (170,8,'[神仙任务]戒','你不断的以言语来刺激郑伦，最后终于激怒了他，在一股不知名的力量下，郑伦突然变身成魔物像你扑了过来！经过了一番打斗，你成功的收拾了郑伦，而郑伦倒下的尸体没多久就化为飞灰随风而逝。唯一留在地上的，就只有一枚戒指，看来这就是他力量的来源，而给郑伦戒指的这名女子应该就是你下一步该去找寻的目标吧！',1145),
  (170,9,'[神仙任务]戒','你从郑伦的口中得知他施展这幻术的力量来源是你手中的这只戒指。听他说这只戒指是他在参天林参北之境修炼时遇到一个神秘女子，那女子交给他的。只是不管你怎么听就是觉得不太寻常，也许你应该要去那边看一看吧。',1146),
  (170,10,'[神仙任务]戒','你不断的以言语来刺激郑伦，最后终于激怒了他，在一股不知名的力量下，郑伦突然变身成魔物像你扑了过来！经过了一番打斗，你成功的收拾了郑伦，而郑伦倒下的尸体没多久就化为飞灰随风而逝。唯一留在地上的，就只有一枚戒指，看来这就是他力量的来源，而给郑伦戒指的这名女子应该就是你下一步该去找寻的目标吧！',1147),
  (170,11,'[神仙任务]戒','在参天林中，你见到了给予郑伦力量的诡异女子，虽然你知道这女子不会是什么好东西，但是她的低声呢喃却使你着了迷。在听完她低柔的话语后，你心中所有的欲望就像是被无限放大一样不断的在你脑海中环绕着。最后你终于屈服在欲望底下，说出了她希望你说出的话。你自甘堕落以自身的精气与她做交换，现在的你除了面对面无表情的赤精子外也只能再回到枫华镇上找姜子牙交差了。',1148),
  (170,12,'[神仙任务]戒','在参天林中，你见到了给予郑伦力量的诡异女子，虽然你知道这女子不会是什么好东西，但是她的低声呢喃却使你着了迷。在听完她低柔的话语后，你心中所有的欲望就像是被无限放大一样不断的在你脑海中环绕着。你知道你不能够说出她想听的话。最后你缓缓的吐出一句拒绝她的话语后，你觉得你的思想又像是回到你掌控中了，你成功打败了这吸精女妖，快点回去枫华镇和姜子牙交代这件事情吧！',1149),
  (171,1,'[城镇任务]朵朵的请托','朵朵请你帮忙收集熊掌三十个，巨鹰爪三十个，穿山甲的皮三十个。',1151),
  (172,1,'[城镇任务]惊喜','帮石爷爷收集三十个蓝色矿石，你就会得到意外的惊喜。',1153),
  (173,1,'[城镇任务]思切','段昊思念妻儿，请托你到葛城里找寻他妻儿，段红以及段扬。',1155),
  (173,2,'[城镇任务]思切','段扬告诉你，你往葛城郊外不远之处找去，就可以看见她娘的坟了。',1156),
  (173,3,'[城镇任务]思切','你已经找到段红的墓碑，现在必须赶紧回去告诉段昊这件事情。',1157),
  (173,4,'[城镇任务]思切','段昊告诉你，要你先过去墓碑等他，因为它必须先准备克服万难，前往段红的墓碑。',1158),
  (174,1,'[城镇任务]布娃娃','尚湘把布娃娃交给你，要你前往找暮汐村的银杏奶奶，找她来修补。',1160),
  (174,2,'[城镇任务]布娃娃','银杏奶奶要你去收集六张熊掌， 三个蓝色矿石来给她。',1161),
  (174,3,'[城镇任务]布娃娃','尚湘的布娃娃终于修补好了，你赶快把布娃娃拿给她。',1162),
  (175,1,'[城镇任务]圣兽仙童','枫华镇的圣兽仙童(128/122)要你带回一颗绒毛鸭的蛋和一块绒毛鸭的肉还有五条兔尾巴和他换一只神兽',1164),
  (176,1,'[城镇任务]夹龙之旅','你答应了要保护吕荥嘉在夹龙纵谷里的安全，他的第一站就是腾云柱，这就动身吧！',1166),
  (176,2,'[城镇任务]夹龙之旅','吕荥嘉来到腾云柱后下一个要去的地方是醒魂碑，快快动身吧！',1167),
  (176,3,'[城镇任务]夹龙之旅','接下来要去的地方就是驾雾柱了，不过吕荥嘉好像有点心神不宁，看来还是小心点走好。',1168),
  (176,4,'[城镇任务]夹龙之旅','吕荥嘉的不安感日益增加，下一个景点是镇岳碑，这就走吧，希望别发生什么事才好。',1169),
  (176,5,'[城镇任务]夹龙之旅','不幸的事还是发生了，吕荥嘉被人绑走了，绑匪要你带着三万两去风云顶赎人呢！',1170),
  (176,6,'[城镇任务]夹龙之旅','你花了三万两保了吕荥嘉的平安，快看看他有没有什么事吧！',1171),
  (176,7,'[城镇任务]夹龙之旅','你打跑了绑匪并且救回了吕荥嘉，快看看他有没有怎么样吧！',1172),
  (177,1,'[城镇任务]七星尊者','你向七星尊者取得了破军卷轴，这就带着十张穿山甲的皮去龙口码头那找破军尊者吧！',1174),
  (177,2,'[城镇任务]七星尊者','你向七星尊者取得了武曲卷轴，这就带着十颗蓝色矿石去北原部落那找武曲尊者吧！',1175),
  (177,3,'[城镇任务]七星尊者','你向七星尊者取得了廉贞卷轴，这就带着十个巨鹰爪去攀龙山道那找廉贞尊者吧！',1176),
  (177,4,'[城镇任务]七星尊者','你向七星尊者取得了文曲卷轴，这就带着十个熊掌去登岚山道那找文曲尊者吧！',1177),
  (177,5,'[城镇任务]七星尊者','你向七星尊者取得了禄存卷轴，这就带着十张熊皮去暮月聚落那找禄存尊者吧！',1178),
  (177,6,'[城镇任务]七星尊者','你向七星尊者取得了巨门卷轴，这就带着十个豹爪去风雨亭一带那找巨门尊者吧！',1179),
  (177,7,'[城镇任务]七星尊者','你向七星尊者取得了贪狼卷轴，这就带着十个大红花种子去南原部落那找贪狼尊者吧！',1180),
  (178,1,'[城镇任务]城镇闯通关','你接受了葛香成的邀请，参加他们七人办的挑战赛，第一关就是去找在暮月聚落的岳暮！',1182),
  (178,2,'[城镇任务]城镇闯通关','你通过了岳暮的关卡，第二关是南原部落的南宫原。',1183),
  (178,3,'[城镇任务]城镇闯通关','你打败了南宫原，第三关是人在昆吾镇的吴昆。',1184),
  (178,4,'[城镇任务]城镇闯通关','吴昆要你找来十根鹤羽和十个马贼身上的普通的钱袋才算过关，这就去找吧！',1185),
  (178,5,'[城镇任务]城镇闯通关','你通过了吴昆的关卡，第四关听说是脾气不太好的穆神棘，他人在神木集，准备好了就动身吧！',1186),
  (178,6,'[城镇任务]城镇闯通关','你打赢了穆神棘，第五关是暮汐村的戏牧。',1187),
  (178,7,'[城镇任务]城镇闯通关','你猜拳赢了戏牧，第六关是云峰部落的云丰，听说此人武艺高强，可要小心点了！',1188),
  (178,8,'[城镇任务]城镇闯通关','经过一番激战，你终于打败了云丰，接下来是最后一关了，第七关就是人在葛城的葛香成，快回去找他吧！',1189),
  (179,1,'[城镇任务]夺宝奇谋','你答应了河隆川要帮他找回父亲的宝藏，可是有两张重要的纸条分别在挖宝三人组的吴娃和流浪三人组的浪云手中，他们人应该还在村内，先去找他们取回纸条再回来跟河隆川讨论下一步吧！',1191),
  (179,2,'[城镇任务]夺宝奇谋','两张纸条上分别写了一句话，这两句话应是关键，看来要自己仔细拖敲想想了！这时河隆川也给了你另一个方向，如果真解不出来，就去找对宝物特别有兴趣的神明问问吧。',1192),
  (179,3,'[城镇任务]夺宝奇谋','普贤真人轻松的解开了谜语，地点就是仙鱼石柱，这就动身去看看吧！',1193),
  (179,4,'[城镇任务]夺宝奇谋','你由仙鱼石柱的凹糟里取出了卷轴，这时后面好像有人，先去看看吧！',1194),
  (179,5,'[城镇任务]夺宝奇谋','卷轴上只有一首诗，看来答案应该在这里面，这下又要好好推敲了，或是再去找普贤真人呢？',1195),
  (179,6,'[城镇任务]夺宝奇谋','普贤真人再度轻松的解开了诗谜，地点是暮月聚落，在那应该有什么特别的东西是关键物品，还好聚落不大，找东西应该不难。',1196),
  (179,7,'[城镇任务]夺宝奇谋','你打开了宝箱，里面有张纸条，你还来不及看纸条时，你觉得又有人来到你的背后了！',1197),
  (179,8,'[城镇任务]夺宝奇谋','这张纸条上的数字让人完全摸不着头绪，你看了看手中的线索，只有遗书和数字，看来这数字谜并不是普通的难解了。',1198),
  (179,9,'[城镇任务]夺宝奇谋','普贤真人决定不帮你，不过他给你一个方向，答案就在你的手上，你看了看手中的线索，只有遗书和数字，看来要推敲答案就要从这着手了吧？',1199),
  (179,10,'[城镇任务]夺宝奇谋','你总算找到了这块隐密的地板，不过上面好像有道数字锁？就在你思考的同时，后面有两个争吵的声音，还是先去看看再回来开吧，不然都不好思考了！',1200),
  (179,11,'[城镇任务]夺宝奇谋','经过千辛万苦，你终于拿到了河隆川父亲留给他的物品，这就回去找河隆川吧！',1201),
  (180,1,'[城镇任务]肚子疼','薛三郎肚子疼痛不已，请托你帮忙带回穿山甲的皮五个。',1203),
  (181,1,'[城镇任务]魔物缠身','你答应若涵即刻出发到八卦迷宫的坤之境，去营救智海大师的灵魂。',1205),
  (181,2,'[城镇任务]魔物缠身','妖魔已经被你给打败，你获得的镇碑宝剑得交给若涵来处理。',1206),
  (182,1,'[城镇任务]寻亲','倪奶奶希望你能够把这封信，交给暮汐村的女儿倪梅雪。',1208),
  (182,2,'[城镇任务]寻亲','倪梅雪允诺了你，你赶快把这消息带回去给倪奶奶吧！',1209),
  (183,1,'[城镇任务]传家宝','你答应了薛老爷帮忙他取回薛家宝物，据说那宝物隐藏在八卦迷宫的坤之境里头。',1211),
  (183,2,'[城镇任务]传家宝','你从妖魔手中拿到了一把钥匙，你得找找看那个宝箱在坤之境的哪里。',1212),
  (183,3,'[城镇任务]传家宝','宝箱打开之后，赫然发现一颗绝美的夜明珠就出现在你眼前，看来这宝石拥有者应该就是薛老爷了。',1213),
  (184,1,'[城镇任务]调查真相','从村长口中得知右龙岭最近似乎不太宁静，有一名村民名叫做王猛，似乎知道这件事情的背后不为人知的秘密。',1215),
  (184,2,'[城镇任务]调查真相','王猛口中的那块奇异的木头，似乎不是一个单纯的事件，你必须前往右龙岭那里好好调查。',1216),
  (184,3,'[城镇任务]调查真相','你打赢了这个千年吸精妖魅，也化解了这个城镇的厄运，至于那个琉璃晶石，似乎隐藏者其他的用途。',1217),
  (184,4,'[城镇任务]调查真相','琉璃晶石的光芒，净化了王猛身上的诅咒，你赶快把这件好消息告诉村长吧！',1218),
  (185,1,'[城镇任务]合成店老板的委托','帮合成店老板送货，给住在甘城山坡上的郑旭。',1220),
  (186,1,'[城镇任务]武器店老板的任务','帮武器店老板收集一些武锻材料。',1222),
  (187,1,'[城镇任务]法宝店的老板的任务','帮忙法宝屋老板拿鸡饲料给他娘。',1224),
  (188,1,'[城镇任务]炼丹房老板的任务','帮忙老板收集一些炼丹用的材料。',1226),
  (189,1,'[城镇任务]杂货店老板的委托','帮忙老板送一些粮草给住在甘城的怪婆婆。',1228),
  (190,1,'[城镇任务]冯爷爷讲故事','李爷爷想要跟你玩猜谜，猜对就让你把奖品带回家。',1230),
  (191,1,'[城镇任务]防具店老板的委托','老板要你去找客栈旁边的羽嫣姑娘，把她所订制的衣裳拿给她。',1232),
  (192,1,'[城镇任务]真假千金','城主要你暗地调查，他女儿黎儿的病情。',1234),
  (192,2,'[城镇任务]真假千金','刘黎儿似乎很讨厌你的到访，不如回去在和城主商量接下去该怎么办？',1235),
  (192,3,'[城镇任务]真假千金','城主告诉你城里有一名法力高强的巫师，或许找到他可以帮到什么忙？',1236),
  (192,4,'[城镇任务]真假千金','你已经成功把妖怪封印住了，赶快去向城主禀告这整件事情吧！',1237),
  (193,1,'[城镇任务]中毒事件','瑾香儿向你哭诉家里双亲相继往生的事件，但是香儿认为内情似乎不是这么单纯，话语中提及炼丹房里的袁大夫那里似乎可以得到一丝线索。',1239),
  (193,2,'[城镇任务]中毒事件','没想到袁大夫语出惊人的表示，不只瑾香儿的父母受害，居住在五龙山上的居民有着不少这样的症状，袁大夫要你前往五龙山那里调查事件。',1240),
  (193,3,'[城镇任务]中毒事件','浑天元吞吞吐吐说出背后的藏镜人，原来是狂雉聚落族长处心积虑想要拿下甘城。',1241),
  (193,4,'[城镇任务]中毒事件','狂雉聚落族长答应你，不再对甘城存有非分之想，另外他拿了解药给你，你把解药拿给浑天元就可以解除甘城的中毒危机。',1242),
  (193,5,'[城镇任务]中毒事件','浑天元已经把解药放在五龙山的泉水中，你赶紧转告瑾香儿这件事情。',1243),
  (194,1,'[城镇任务]真假千金','城主耳里听到来自下人彼此间互传的谣言，于是他请你调查她女儿是否有怪异的举止。',1245),
  (194,2,'[城镇任务]真假千金','刘黎儿不接受你的好意，而且很生气的把你赶出去，这时候你问她也问不出所以然，不如回去找城主问该怎么解决。',1246),
  (194,3,'[城镇任务]真假千金','城主也拿女儿没办法，只有请求你去找甘城巫师，看能不能知道黎儿到底发生了什么事情。',1247),
  (194,4,'[城镇任务]真假千金','巫师冷笑了许久，拿出一张特别的符咒，要你带着这个东西找刘黎儿。',1248),
  (194,5,'[城镇任务]真假千金','原来刘黎儿遭受到妖魅的附身，才会进而做出这样诡异的举止，你赶快去禀告城主说这事儿。',1249),
  (195,1,'[城镇任务]温小宝的烦恼','温小宝要你帮忙她找回亲生母亲，他母亲就住在临冰镇里面的杂货店。',1251),
  (195,2,'[城镇任务]温小宝的烦恼','既然温喜媚愿意回去照顾温小宝，这件事情实在令人动容，你赶快告诉小宝这事吧！',1252),
  (196,1,'[城镇任务]解毒','陈颖的母亲被毒蛇给咬伤，需要你前往龙吉公主的庙里，找一位神童询问。',1254),
  (196,2,'[城镇任务]解毒','浩天指示你到普陀低地附近找一位小男孩。',1255),
  (196,3,'[城镇任务]解毒','童童指示你把十个章鱼嘴(鸭肉先代替)给他，他就把蜈蚣干无条件给你。',1256),
  (196,4,'[城镇任务]解毒','童童告诉你块把东西交给陈颖吧！',1257),
  (197,1,'[城镇任务]嫣红的眼泪','唐府小姐的贴身的奶妈告诉你，山寨大王把小姐掳走，你必须前往山寨之地拯救小姐。',1259),
  (197,2,'[城镇任务]嫣红的眼泪','小姐全身不停的颤抖，说到这里二十四小时都有守卫看着她，你必须先打倒门口的守卫。',1260),
  (197,3,'[城镇任务]嫣红的眼泪','山寨守卫不敌你的战略输个精光，接下来要挑战就是山寨中的老大山寨大王。',1261),
  (197,4,'[城镇任务]嫣红的眼泪','打倒山寨大王的你，已经顺利救出小姐来了，快告诉奶妈这件好消息吧！',1262),
  (198,1,'[城镇任务]走失小猫儿','孟馨告诉你她最疼爱的小猫走失了，听说她的奶妈有看见小猫踪影，这个线索就是我们要找的其中之一。',1264),
  (198,2,'[城镇任务]走失小猫儿','奶妈已经告诉你说，她是上市集的时候在炼丹房附近瞧见小猫踪影，你往第二条线索找找看吧！',1265),
  (198,3,'[城镇任务]走失小猫儿','费了九牛二虎之力你终于抓到小猫，赶紧向孟馨交代去。',1266),
  (198,4,'[城镇任务]走失小猫儿','孟馨告诉你小猫的脚受伤了，可能是流浪在外头所致，要你带往炼丹房老板那里医治，你快点去吧！',1267),
  (198,5,'[城镇任务]走失小猫儿','炼丹房老板帮你把小猫的脚伤医治好了，猫咪高兴的在你怀里咕噜咕噜叫着，赶紧把猫咪交给孟馨吧！',1268),
  (199,1,'[城镇任务]秦爷爷最爱的蛋黄酥','秦爷爷请你到后院里去捡十颗鸡蛋给他。',1270),
  (199,2,'[城镇任务]秦爷爷最爱的蛋黄酥','秦爷爷说还缺了些许的面粉和杆面棍，要麻烦你到镇上的杂货铺去帮他买来。',1271),
  (199,3,'[城镇任务]秦爷爷最爱的蛋黄酥','终于完成秦爷爷所需要的物品，你赶快把东西拿给他老人家吧！',1272),
  (200,1,'[城镇任务]真爱约定一','家住寒霞镇上的樊亦飞与甘城城主的女儿相爱，但是城主认为两人阶级相差悬殊屡屡阻止两人的相爱，樊亦飞被逼到已经走投无路，希望你能帮他说服城主。',1274),
  (200,2,'[城镇任务]真爱约定一','城主出了一个难题要你达成这项任务，就是找寻龙御鼎这东西的下落，这下只有找刘黎儿帮忙，说不定她知道该怎么办。',1275),
  (200,3,'[城镇任务]真爱约定一','刘黎儿告诉你到海口村找愚爷爷，他平时喜欢收集一些古怪的东西，或许问他可以知道这东西的下落。',1276),
  (200,4,'[城镇任务]真爱约定一','愚爷爷要你带来三十块牛肉解嘴馋，你快点去带来他要的这些东西吧！',1277),
  (200,5,'[城镇任务]真爱约定一','愚爷爷把你要的龙御鼎给了你，虽然他口中所说这玩意是庸品，但是不如姑且一试。',1278),
  (200,6,'[城镇任务]真爱约定一','城主很开心收下龙御鼎这玩意，也同意你们的交往，但是从城主嘴中一抹笑意，似乎知道这隐藏着什么事情，只是不去揭穿开来这事，你快去告诉樊亦飞这件好消息吧！',1279),
  (201,1,'[城镇任务]真爱约定','樊亦飞听说黎儿的父亲生病了，请你送一篮水果过去城主那里。',1281),
  (201,2,'[城镇任务]真爱约定','刘黎儿把药单拿给你，要你帮忙找这个药材回来。',1282),
  (201,3,'[城镇任务]真爱约定','黎儿为了父亲熬夜煮了这碗汤药，你快快把药端给他父亲饮用。',1283),
  (201,4,'[城镇任务]真爱约定','城主要你回去传达，叫樊亦飞该准备准备迎娶的事宜。',1284),
  (202,1,'茶水师傅的委托','元始天尊似乎有事找你，先回仙界一趟吧。',1286),
  (202,2,'茶水师傅的委托','天始天尊要你前往龙口码头找茶水师傅问问如何去北方极地大陆。',1287),
  (202,3,'茶水师傅的委托','茶水师傅要你去仙界问问法宝合成师傅如何做出传说中的七海神针',1288),
  (202,4,'茶水师傅的委托','法宝师傅表示要修复七海神针需要圣洁的白金七份和金刚针，圣洁白金鸿蒙境的石怪会掉落，而金刚针就要去神仙房间问问高兰英了。',1289),
  (202,5,'茶水师傅的委托','高兰英要你送锦盒去张奎庙一趟。',1290),
  (202,6,'茶水师傅的委托','高兰英要你送剑兰去邓婵玉庙一趟。',1291),
  (202,7,'茶水师傅的委托','东西交给张奎了，回去找高兰英吧！',1292),
  (202,8,'茶水师傅的委托','东西交给邓婵玉了，虽然邓大小姐看起来很不高兴，不过这是她们两人的事，还是快回去跟高兰英复命好了。',1293),
  (202,9,'茶水师傅的委托','你拿到了金刚针，只要备齐七份圣洁白金就可以去找法宝合成师傅了！',1294),
  (202,10,'茶水师傅的委托','你已经拿到了七海神针，快去龙口码头找茶水师傅交差吧！',1295),
  (203,1,'临冰镇的瘟疫','你捡到一包不知名粉末，心想也许有什么用途，不过船快到岸了，还是先下船四处打探一下消息吧！',1297),
  (203,2,'临冰镇的瘟疫','你答应镇长要帮忙解决瘟疫一事，镇长给了你一条线索，就从镇上西方第一个发病的李家仅存的小孩李冰儿查起吧！',1298),
  (203,3,'临冰镇的瘟疫','李冰儿给了你一封信，上面写了「盲人出厢房」，看来是个字谜，解开这谜应该就能找到一些线索了。',1299),
  (203,4,'临冰镇的瘟疫','你从床上的暗格拿到了笔记本，快问问李冰儿有什么其它线索吧。',1300),
  (203,5,'临冰镇的瘟疫','李冰儿告诉你可以去找镇上的常药师，他是李父的好友，或许也知道些什么！',1301),
  (203,6,'临冰镇的瘟疫','你自常药师处取得了毒痘样子，看来拿去给神农氏应该可以找到解毒配方。',1302),
  (203,7,'临冰镇的瘟疫','神农给了你解毒配方，快拿去给常药师吧！',1303),
  (203,8,'临冰镇的瘟疫','配方已经交给常药师了，这就回去跟镇长交差吧！',1304),
  (204,1,'洗冤','你醒来发现身在不知何处的牢里，先四处观察一下好了！',1306),
  (204,2,'洗冤','你被带到城主面前，先和城主谈谈再说吧！',1307),
  (204,3,'洗冤','城主相信你的话，并告诉你是常药师告的密，看来该去找常药师问清事情原委。',1308),
  (204,4,'洗冤','常药师似有难言之隐，还是去问问镇长好了！',1309),
  (204,5,'洗冤','镇长表示常药师怪怪的，或许可以再去找常药师问出些什么隐情。',1310),
  (204,6,'洗冤','你又被关入牢中，先观察看看有没有办法出去吧！',1311),
  (204,7,'洗冤','你看到守卫只有一人，或许可以打倒他离开这牢里。',1312),
  (204,8,'洗冤','你终于出了牢房，现在应该回临冰镇再查查是谁陷害你的，镇长不可信，那就从李冰儿问起吧！',1313),
  (204,9,'洗冤','李冰儿提到常药师说你是凶手，或许该去找常药师问问了。',1314),
  (204,10,'洗冤','你看到常药师已死，手指着床头，先看看有什么端倪。',1315),
  (204,11,'洗冤','你拿到了一个木盒，快打开看看吧！',1316),
  (204,12,'洗冤','知道了事情始末，看来夏羽和侯异便是关键人物，你忽然想到某个曾有一面之缘的人，这就动身去那个人说的地方找他吧！（如果想不起来，就去找姜子牙问问是谁好了。）',1317),
  (204,13,'洗冤','姜子牙告知夏羽和侯异其实就是指夏侯翼，这人应该在海口村，快去找他吧！',1318),
  (204,14,'洗冤','你的冲动害死了大小章鱼，你决定去找夏侯翼这家伙算账，此时想到杨戬的天眼或许能帮你什么，这就先去找杨戬吧！',1319),
  (204,15,'洗冤','你觉得这事应该就是夏侯翼搞的鬼，一定要尽快找到他才行，这时你想到杨戬的天眼或许能帮你什么，这就先去找杨戬吧！',1320),
  (204,16,'洗冤','杨戬告知你夏侯翼人在草原遗迹里的某处，这就动身找他算账去！',1321),
  (204,17,'洗冤','终于打败了夏侯翼，也将牠封印起来了，快交给城主洗清自己的冤屈吧！',1322),
  (204,18,'洗冤','终于打败了夏侯翼，也救回了小章鱼，先把小章鱼还给大章鱼再说！',1323),
  (204,19,'洗冤','你把小章鱼还给了大章鱼，接下来，是该把夏侯翼这鸟精交给城主洗清自己的冤屈了！',1324),
  (205,1,'北海眼','城主说他累了，看来想探听三大神器的事可能要明天再来找城主问问了。',1326),
  (205,2,'北海眼','由城主口中得知玄天印最后一次现身是在北海眼的申公豹庙，这就去打听一下吧。',1327),
  (205,3,'北海眼','申公豹要你去北狄、红鹰、西涯、狂雉找这四个聚落的长老取得四颗法石才肯告知玄天印的下落，看来要先取得四颗法石再回来找他吧！',1328),
  (205,4,'北海眼','申公豹将你传到了顽石古阵里，先四处调查看看吧！',1329),
  (205,5,'北海眼','你由顽石阵中的使者口中得知申公豹的目的，决定找他理论一番！',1330),
  (205,6,'北海眼','你打败了申公豹，跟顽石阵中的使者交差吧！',1331),
  (206,1,'讨伐山猪大王','杨坤告诉你村子最近遭受山猪的侵袭，北狄族长那里有在招募勇士砍杀山猪的首级，你有兴趣可以去问问看我们的村长。',1333),
  (206,2,'讨伐山猪大王','北狄族长告诉你这些山猪非常奸险狡猾，如果你取得山猪大王首级就会获得一笔可观的金钱，山猪群都在顽石古阵那边附近出没。',1334),
  (206,3,'讨伐山猪大王','小山猪嘶吼的叫声划破天际，你已经处理掉一只小猪。',1335),
  (206,4,'讨伐山猪大王','第二只小猪你也把牠解决掉了，接下来你要面对的是山猪大王。',1336),
  (206,5,'讨伐山猪大王','你已经取得山猪大王的首级，接下来你要与北狄族长报告。',1337),
  (207,1,'女孩别哭','秦小媛告诉你妹妹在草原遗迹失踪了，因为如此小媛被继母和姐姐赶出家门外。',1339),
  (207,2,'女孩别哭','你找到了秦小米并且从他口中得知一些消息，这下你得赶快告诉心急如焚的姐姐秦小媛。',1340),
  (207,3,'女孩别哭','秦小媛意外得知这个消息，感到非常讶异与心痛，她告诉你继母与姐姐住在西涯聚落，请你救救她们姊妹俩。',1341),
  (207,4,'女孩别哭','你意外发现二姐身上布满妖气，虽然二姐暂时呈现昏迷状，现在你要对付的是家中大姐，你更加确定大姐身上那团迷雾是一股很强妖气。',1342),
  (207,5,'女孩别哭','你与大姐决斗后发现，她身上布满的那团迷雾，居然与继母身上的谜雾一样，接下来你即将面对可怕的继母。',1343),
  (207,6,'女孩别哭','怎么想都不会想到，原来继母是魔物化身的，把这件事情的来龙去脉告诉小媛吧！',1344),
  (208,1,'矮人族的复仇之一','你通过了矮人族长老的试炼，也接受了铲除恶人石怪的任务，长老请你把这张卷轴交给狂雉聚落的矮人巫师。',1346),
  (208,2,'矮人族的复仇之一','巫师指引你恶人石怪的方向，就在北方地图上的猛兽崖，你过去可得注意自身安危。',1347),
  (208,3,'矮人族的复仇之一','石怪非常顽固但是你终于打败了一只，现在眼前还有四只你得可努力把怪物清完。',1348),
  (208,4,'矮人族的复仇之一','石怪非常顽固但是你终于打败了二只，现在眼前还有三只你得可努力把怪物清完。',1349),
  (208,5,'矮人族的复仇之一','石怪非常顽固但是你终于打败了三只，现在眼前还有二只你得可努力把怪物清完。',1350),
  (208,6,'矮人族的复仇之一','石怪非常顽固但是你终于打败了四只，现在眼前还有一只你得可努力把怪物清完。',1351),
  (208,7,'矮人族的复仇之一','你终于清光所有石怪，快去找矮人族长老报告吧！',1352),
  (209,1,'矮人族的复仇之二','矮人族长老语重心长告诉你恶人石怪再度出来作怪，所以要你前往红鹰聚落去询问赏金猎人关于怪物出没的地点。',1354),
  (209,2,'矮人族的复仇之二','听说是在寒霞镇和二龙河之间看见恶人石怪的，你往那附近四处调查调查看看吧！',1355),
  (209,3,'矮人族的复仇之二','恶人石怪告诉你，这件事情不是他做的，他认为一定是还有别人，这下你也只有回头询问赏金猎人，是否能够提供更明确的线索。',1356),
  (209,4,'矮人族的复仇之二','搞了半天是赏金猎人弄错对象了，正确的出没地是在普陀低地附近，接到这个消息你往那里看看。',1357),
  (209,5,'矮人族的复仇之二','经过一场大战你终于获胜了，虽然全身已经精疲力尽，这个好消息你得亲自跟族长报告。',1358),
  (210,1,'仙道20职业任务','师傅请你去收集鸭蛋素材后把东西交给他。',1360),
  (210,2,'仙道20职业任务','师傅认可你的能力，所以请你到北方地图草原上找一头凶猛无比的狼，先决条件是必须打赢牠。',1361),
  (210,3,'仙道20职业任务','你已经打赢了这匹狼，快去和老师傅复命吧！',1362),
  (211,1,'药师20职业任务','师傅请你去收集鸭蛋素材后把东西交给他。',1364),
  (211,2,'药师20职业任务','师傅要你把手上的药材拿给海口村的黄姓妇人，赶快去吧！',1365),
  (211,3,'药师20职业任务','黄莲的小儿子生了重病，你答应帮她收集鸭肉这些药材。',1366),
  (211,4,'药师20职业任务','黄莲很开心你做到了答应她的事情，要你快去回去向师傅复命。',1367),
  (212,1,'剑客20职业任务','师傅请你去收集鸭肉素材后把东西交给他。',1369),
  (212,2,'剑客20职业任务','师傅要你前去城里武器店附近，找一位姓虎的人士。',1370),
  (212,3,'剑客20职业任务','你通过虎爷的考验，赶紧去向师傅报告去。',1371),
  (213,1,'谋士20职业任务','师傅请你去收集鸭毛素材后把东西交给他。',1373),
  (213,2,'谋士20职业任务','师傅要你回答下列关于阵法这些问题。',1374),
  (213,3,'谋士20职业任务','师傅要与你进行一场决斗考验。',1375),
  (214,1,'[职业任务]挑战！','在焰霜镇武道场师傅的一再邀请之下，你答应他要连续挑战场内的弟子与师傅们。不过这一失败可是得要重新再来过的啊???',1377),
  (214,2,'[职业任务]挑战！','你成功的打赢了武道场师傅的四场挑战，武道场师傅除了感叹他终于找到他师傅四圣道人的真正想找的人，希望你有机会能去见他师傅一面的这件事之外。还给了你一张证书，说是可以到焰霜镇中的武器店中找一位打铁老伯换取一件奖品。',1378),
  (214,3,'[职业任务]挑战！','你跟焰霜镇的打铁老伯要了一柄斧头，但是老伯说他缺了一块特殊的矿石材料。那矿石就在强化五色神牛的手中，你必须杀了他，将这矿石取回来让打铁老伯打造你要的斧头。',1379),
  (214,4,'[职业任务]挑战！','你跟焰霜镇的打铁老伯要了一件铠甲，但是老伯说他缺了十五份钢材来作为材料。那钢材就在怒暴巨熊的肚子里，你必须收集十五份钢材，将钢材带回来让打铁老伯打造你要的铠甲。',1380),
  (215,1,'[职业任务]风水','你在焰霜镇外偶遇一名流浪风水师，他告诉了你焰霜镇上的地理风水已遭到破坏，需要你的协助帮忙。你所能做的，就是帮忙这名流浪风水师，收集金、木、水、火等四种属性的水晶。并将一定数量的各种属性水晶分别放入东方的青龙雕像、西方的白虎雕像、南方的朱雀雕像以及北方的玄武雕像当中即可。',1382),
  (215,2,'[职业任务]风水','你再度的封印了当年被四座雕像镇压住的魔物们。暂时保住了焰霜镇未来一百年内的安全。同时你也得到了这名流浪的风水师的信任，他对你说出了他到处流浪的意义是在于帮他师傅四圣道人找到理想中的传人。如今这传人就站在他面前。如今他的愿望除了你有机会能去见他师傅一面的这件事之外，还给了你一张证书，说是可以到焰霜镇中的合成店里找老板换取一件奖品。',1383),
  (216,1,'[职业任务]必要之恶','你答应要帮焰霜镇中一位受伤的药师收集药材来救治他的三个病人。这药师要的材料是十张怒爆熊皮，三个熊铃铛以及三份炽热之心。熊皮和小熊铃铛这两个素材可以在外面的怪物尸体上找到，至于炽热之心就只有在焰霜镇中骗吃骗喝的江湖郎中有而已。',1385),
  (216,2,'[职业任务]必要之恶','为了帮助那受伤的药师，你决定跟着这江湖郎中演一场他所谓的华丽复活剧大作战计划来骗人。他要你再他讲出台词时作出适当的动作以及反应。首先你必须先进行躺下来的动作才可以进行这出戏剧，而最后是要以招手这个动作来结束这出戏剧。',1386),
  (216,3,'[职业任务]必要之恶','你精湛的演技骗取了许多路人的眼泪，同时也帮江湖郎中赚进了大量的金钱。看他笑的合不拢嘴的样子，就可以知道他到底噱了多少钱。虽然你良心上有些过意不去，不过为了那名受伤药师的病人，你也只能默默的忍受良心的苛责与煎熬，让无知的人买走江湖郎中贩卖的不知名药物。等你收集好十张怒爆熊皮，三个熊铃铛后就可以找要你帮忙你收集药材的受伤药师进行制药的工作了。',1387),
  (216,4,'[职业任务]必要之恶','你那拙劣的演技实在是无法骗到路人，虽然没有骗到人让你的良心稍微好过一点，不过却对你现在进行的事情一点帮助都没有。江湖郎中说他愿意再给你一次机会重头再来，希望这次你能够好好的把握。',1388),
  (216,5,'[职业任务]必要之恶','你将你收集来的药材拿给受伤药师，他勉强的撑起身子用你给的药材来去调制汤药，就在汤药完成的同时，他也失去了意识。在他昏迷之前，他说到三名病人居住在焰霜镇内的西边，接下来就看你的了，将这三碗药拿去给三名不同病症的病人服用吧。',1389),
  (216,6,'[职业任务]必要之恶','你完成了流浪药师交代你的工作，他对于你的药物的知识以及临场的反应都感到佩服不已。他除了给你一张药师之证以及感叹他终于帮他师傅四圣道人找到真正的传人，希望你有机缘能见他师傅一面之外，还说这张证书可以拿到焰霜镇上的炼丹房找老板换取一件奖品。',1390),
  (217,1,'[职业任务]案外案','你不幸遇到焰霜镇上的一位讨人厌的老兵，在他半劝半引诱之下，你签下了暂时入伍的证书。他交给你一个抹布，要你去擦拭位在焰霜镇外东西南北四个方位的雕像，要你擦完之后找他回报。就你来看，这老兵根本就是在凹人做去上面指派给他的事情而已。',1392),
  (217,2,'[职业任务]案外案','在你辛辛苦苦的擦拭完东西南北四座雕像的同时，你隐约的也发现到似乎有什么事情不太对劲的样子。当你回去和老兵报到后，他又指派你一项任务，要你去镇上的武道馆带一群出公差抓逃兵的士兵回来报到。',1393),
  (217,3,'[职业任务]案外案','为了要抓逃兵，那几名士兵还带了武道馆的师傅一起前去，却被一个带着逃兵的谜般女子打个大败。这名女子到底会是谁？不过现在的你比较关心的，还是那几名伤兵的伤势情况，你应该要快点去找焰霜镇上的炼丹房老板讨药来给他们服下才对。',1394),
  (217,4,'[职业任务]案外案','很不巧的，焰霜镇炼丹房的老板说前一阵子有位很能干的药师来帮他的忙，因为他能不用药就将病人治好，于是老板为了节省药材，所以一些低等级的药材都已经没有存货了。要制作跌打药的话，必须收集五份熊胆以及五份牛头骨来才行。',1395),
  (217,5,'[职业任务]案外案','你将辛苦取得的药材交给了炼丹房的老板制药，没多久后，老板就将几颗药丸交给你，要你带去武道场给武道场的师傅。如此一来应该就可以治好那些伤兵的伤吧。',1396),
  (217,6,'[职业任务]案外案','你将药丸交给武道场的师傅后，师傅要你先回去找老兵报到，他将药给伤兵服下后就会带去见老兵了。而你突然想起了老兵那付不耐烦又讨厌的嘴脸以及令人生气的讲话方式，这点让你不禁打了个冷颤，你想着还是赶快去找老兵交差要紧，不然等会他不知道会不会出什么鬼主意来整你也说不定。',1397),
  (217,7,'[职业任务]案外案','这名老兵以一种相当正式的语气对你说话着，他要你去冰火庙那帮忙搜寻那些逃兵的下落。也许这一切事情都跟那谜般的女人有关系吧？',1398),
  (217,8,'[职业任务]案外案','原来那名女子是不服气师傅，于是想要证实自己的力量给师傅看。为了这点事情，她除了伤害同门，破坏焰霜镇的风水，以及赔了那些逃兵的性命之外，同时也赔上了自己的性命。在她临死前她说也许你就是她师傅理想中的传人也说不定，希望有缘，能让她师傅见到你这句话后断气了。你在她身上搜到了一张谋士之证，也许这东西能带回去给那老兵看，当作是你解决这件事情的依据吧。',1399),
  (218,1,'[转生任务]玉虚符录','转生金童给了你一本玉虚符录，上面记载的如何封神转生，赶快打开来看看吧！',1401),
  (218,2,'[转生任务]玉虚符录','符录第一页写着：转生封神者，需先备有玄冰烈火二珠以炼制凛熇神珠，玄冰珠为寒冰阵袁天君所有，烈火珠则为烈焰阵白天君所有，寒冰阵与烈焰阵位于太极境两仪岛上之雪晶洞及烈焱穴中，有能者方能取之。看来得要先找到这两颗珠子再来看看符录的下一页写什么吧。',1402),
  (218,3,'[转生任务]玉虚符录','符录第二页写着：炼制凛熇神珠需太极境两仪岛上冰火庙之玄炉方能功成。看来要走一趟冰火庙才行。',1403),
  (218,4,'[转生任务]玉虚符录','乾坤道人表示要炼制凛熇神珠需要五个牛头骨及五个海豹头骨为引（此二物可自焚熇战牛及海洋企鹅豹骑兵身上获得），先去收集这些东西再说吧！',1404),
  (218,5,'[转生任务]玉虚符录','神珠已经到手，再看看玉虚符录上写什么吧。',1405),
  (218,6,'[转生任务]玉虚符录','符录第三页写着：太极境两仪岛、石塔、雪女像。应该是一个地点吧！先到那再看看玉虚符录怎么写。',1406),
  (218,7,'[转生任务]玉虚符录','符录第五页写着：封神者，备凛熇神珠以打通玄关，玄关一过，天眼即开，再备转生天珠，以凝聚精气神三元，方能完成转生。转生天珠收于幽冥结界，由千年雪女负责看守，唯通过雪女考验者方能入内取之。',1407),
  (218,8,'[转生任务]玉虚符录','符录第六页写着：转生天珠位于幽冥结界之中，能者取之。 先四处检查看看好了。',1408),
  (218,9,'[转生任务]玉虚符录','符录第七页写着：备齐凛熇神珠及转生天珠，前往葛城找洞府神像，即可重返太虚，进行封神转生。',1409),
  (218,10,'[转生任务]玉虚符录','已取得转生天珠，看看玉虚符录上写什么吧。',1410),
  (219,1,'[城镇任务]人鱼的宿命','郑樵告诉你他所经历的这件事情，希望你可以询问附近的居民，并且把那夜拾获的珍珠项链交给你。',1412),
  (219,2,'[城镇任务]人鱼的宿命','老渔夫告诉你一个故事，与这情是否有关联必须要你自己用心体会，他指着西南方那就是传说之地。',1413),
  (219,3,'[城镇任务]人鱼的宿命','你找到那个女孩，辗转间那女孩娓娓道出这件事情的经过，并且请你转告郑樵珍珠项链希望留在他身边。',1414),
  (219,4,'[城镇任务]人鱼的宿命','郑樵拿出了小花束，希望你带给那位女孩。',1415),
  (219,5,'[城镇任务]人鱼的宿命','女孩眼角泛着泪光，一跃海中里面化为泡影。',1416),
  (220,1,'[城镇任务]上等好茶','周爷爷要你去杂货铺老板那儿拿点茶叶回来，还有玉泉水要找客栈的店小二购买。',1418),
  (220,2,'[城镇任务]上等好茶','你已经跟杂货铺老板购买到茶叶了，接下来要去客栈店小二买玉泉水。',1419),
  (220,3,'[城镇任务]上等好茶','两样东西你都已经买齐了，可以回去跟周爷爷交代了。',1420),
  (221,1,'[城镇任务]刁蛮的大小姐','大小姐赵怀玉不耐烦的告诉你，她奶奶居住在天寒高原上，要你去那里找她奶奶拿药。',1422),
  (221,2,'[城镇任务]刁蛮的大小姐','老奶奶交给你人蔘还有天山雪莲，带回去给赵怀玉服用。',1423),
  (222,1,'[城镇任务]镇长夫人的烦恼','镇长夫人非常担心镇长的病情，你不如前往焰霜镇长所在地去调查看看。',1425),
  (222,2,'[城镇任务]镇长夫人的烦恼','看来镇长大人病的不轻，这下你要回去找镇长夫人商量看看。',1426),
  (222,3,'[城镇任务]镇长夫人的烦恼','镇长夫人告诉你，城里合成屋附近有个名为神药子的人，专治各种疑难杂症，要你前往那儿询问看看。',1427),
  (222,4,'[城镇任务]镇长夫人的烦恼','神药子要你把药单上面的素材找来给他。',1428),
  (222,5,'[城镇任务]镇长夫人的烦恼','神药子把药材给处理好了，要你带回去给镇长大人服用。',1429),
  (222,6,'[城镇任务]镇长夫人的烦恼','镇长大人服用下去效果奇佳，你赶快回去禀告镇长夫人吧！',1430),
  (223,1,'[城镇任务]小矮人的恶作剧','喜欢恶作剧的小矮人，这回要你去拔镇长大人的头发，只要成功他就送你一个礼物。',1432),
  (223,2,'[城镇任务]小矮人的恶作剧','镇长大人对你在身旁打转感到不耐烦～～',1433),
  (223,3,'[城镇任务]小矮人的恶作剧','镇长大人发起火来了～～示意你要离开。',1434),
  (223,4,'[城镇任务]小矮人的恶作剧','镇长大人面色铁青，怒吼着要你别烦他。',1435),
  (223,5,'[城镇任务]小矮人的恶作剧','你拿到镇长大人的头发了，赶快拿去给小矮人去。',1436),
  (224,1,'[城镇任务]海贼的藏匿地','老胡告诉你海贼出没这件事情，那天晚上在阴阳河附近捕鱼所看见的。',1438),
  (224,2,'[城镇任务]海贼的藏匿地','柳如月告诉你，她曾经在烈焱穴附近看过海贼的洞穴。',1439),
  (224,3,'[城镇任务]海贼的藏匿地','守卫不敌你强大的攻击力，于是他帮你开启这一道石门。',1440),
  (224,4,'[城镇任务]海贼的藏匿地','海贼王允诺你要离开这片土地，这好消息你还不赶快告诉老胡去。',1441),
  (225,1,'[城镇任务]酒壶的主人','店小二要你帮忙把这个酒壶，拿给刚刚踏出门外的客人，客人的特征就是他身穿一件蓝丝袍的衣裳，体型略为瘦高，不过刚刚应该喝了不少酒，所以脚步有点不稳，你往客栈周围找找看。',1443),
  (225,2,'[城镇任务]酒壶的主人','你看着眼前这位仁兄，酒醉到连路都走不好～～',1444),
  (225,3,'[城镇任务]酒壶的主人','这位仁兄酒醉的意识不清楚，非常难以沟通',1445),
  (225,4,'[城镇任务]酒壶的主人','这位仁兄终于认得自己遗留的酒壶，你赶快回去找店小二交差吧！',1446),
  (226,1,'[城镇任务]争夺家产','杨老爷的魂魄死不瞑目，他要你去处罚他两个儿子，大儿子杨魁小儿子是杨震。',1448),
  (226,2,'[城镇任务]争夺家产','杨魁答应你不会再为了家产和弟弟争吵。',1449),
  (226,3,'[城镇任务]争夺家产','杨震很不甘愿答应你不会和兄长为了家产争吵，你赶快把这好消息带给杨老爷吧！',1450),
  (227,1,'[城镇任务]忠犬旺福','石原郎找寻他的爱犬旺福，前几天在岛上火焰山炽炎低地附近打猎时旺福不幸走失，主人给你这条线索，要你找寻这只猎犬的下落。',1452),
  (227,2,'[城镇任务]忠犬旺福','这只狗狗对你流露出友善的眼神，你深相信这只狗儿应该就是石原郎走失那条狗，你得赶快告诉石原郎这件事情。',1453),
  (228,1,'[城镇任务]水利工程弊案','长老对于钱老爷包下水利工程此事非常生气，由于钱老爷贪钱不顾人民安危，硬是把工程的材料偷工减料，现在长老怀疑负责水利工程的包晓通与钱老爷是共犯。',1455),
  (228,2,'[城镇任务]水利工程弊案','包晓通对于自己的处境非常无奈，而且也明确表达自己对于这件事情的看法，他希望你能和钱老爷商议这件事情的严重性。',1456),
  (228,3,'[城镇任务]水利工程弊案','钱家奴才不让你通行，执意要与你对决，没想到却败在你的手下。',1457),
  (228,4,'[城镇任务]水利工程弊案','钱老爷因为这件事情被传开了，却恼羞成怒教唆家仆来打你，没想到败在你的手下，只好把当初约定的那张水利工程契约单给交出来。',1458),
  (229,1,'[新手任务]迎取神仙','现在可以去昆仑仙界东北方的神仙密室迎取神仙了。',1460),
  (230,1,'[活动任务]维纳斯的巧克力','维纳斯要做一份巧克力，请你去南原部落找赛姬帮忙',1462),
  (230,2,'[活动任务]维纳斯的巧克力','赛姬要你先找到在南原部落外围四周、高兰英庙及十里亭的五株五色仙花才肯给你她的祝福',1463),
  (230,3,'[活动任务]维纳斯的巧克力','得到了赛姬的祝福，带着花回去找维纳斯吧',1464),
  (230,4,'[活动任务]维纳斯的巧克力','有了卅个巧克力，维纳斯请你去找邱比特，希望能唤回昔日的爱神',1465),
  (231,1,'[主线任务]仙霞童子','仙霞童子要你带着竹简去找镇上的董九和古黎聊聊，等问完话再回去找他',1467),
  (231,2,'[主线任务]仙霞童子','根据仙界指示，你必须找到在果力村上的仙霞童子，才能知道这次的使命为何',1468),
  (232,1,'[主线任务]初访九黎','仙霞童子要你去找一位叫罗博的人，他住在茄城里的某间房子里',1470),
  (232,2,'[主线任务]初访九黎','现在人死了，看来事情并不单纯，外面声音吵杂，先出去看看吧',1471),
  (232,3,'[主线任务]初访九黎','事情看起来很混乱，还是先回去找仙霞童子再做打算吧',1472),
  (232,4,'[主线任务]初访九黎','仙霞童子要你准备好十把泥土及十件衣服碎片，这些东西可以去茄城北方的敌人身上找找',1473),
  (232,5,'[主线任务]初访九黎','完成了易容，先按照仙童建议去茄城客栈打听打听消息好了',1474),
  (232,6,'[主线任务]初访九黎','听白采说城主那应该有不少信息可以取得，先去看看吧',1475),
  (232,7,'[主线任务]初访九黎','城主不在，桌上有些书，也许有什么线索',1476),
  (232,8,'[主线任务]初访九黎','客栈里有人，先打听打听吧',1477),
  (233,1,'[主线任务]天晴密谈','看来局势日益严峻，有必要前往天晴楼一探',1479),
  (233,2,'[主线任务]天晴密谈','茄城城主发现了你，看来是要运用些技巧获得其信任才能探得消息',1480),
  (233,3,'[主线任务]天晴密谈','依城主的消息，看来有必要去蚩尤神殿一趟，看看什么叫机关部队',1481),
  (233,4,'[主线任务]天晴密谈','一进入神殿，你便感受到阵阵莫名的压迫，看来这里面的确有调查的必要',1482),
  (233,5,'[主线任务]天晴密谈','这神殿里有不少落单的机关部队，应该可以从它们身上取得三十份的木材',1483),
  (233,6,'[主线任务]天晴密谈','木材够了，由左边开始一个一个放在机关部队附近吧',1484),
  (233,7,'[主线任务]天晴密谈','一群神秘的黑衣人挡住出口，似乎来着不善，看来一阵恶斗在所难免',1485),
  (233,8,'[主线任务]天晴密谈','历经辛苦终于击退这群实力坚强的黑衣人，同时耳际传来仙霞童子要你回果力村去找他的声音',1486),
  (234,1,'[新手任务]果力名产','果力村的厨师梁祯(108/110)希望你拿回五个蜗牛肉给他',1488),
  (235,1,'[新手任务]防具店老板的物品','果力村防具店老板(90/118)将东西寄放在果力村法宝屋(113/77)和果力村炼丹房(96/71)，只要你帮他取回，他就会给你一些奖励啦！',1490),
  (236,1,'[新手任务]青梅竹马','果力村的李乐(113/69)需要一笔钱好登门提亲，希望你能帮他找来五个冬虫夏草',1492),
  (237,1,'[新手任务]爱心便当','果力村的阿银婶(69/72)需要十个蜗牛肉来完成她为儿子准备的便当',1494),
  (238,1,'[新手任务]御寒衣物','果力村的马老伯(68/116)因为天气寒冷，请你帮他找寻二十个兔皮来制作御寒的衣物',1496),
  (239,1,'[城镇任务]平均灌溉','茄城的成范永(82/66)打了一桶14升的水，可是有两片农地需要灌溉，现在只有14升、9升与4升三个水桶，如何让水平均的灌溉到两片农地上呢?',1498),
  (240,1,'[城镇任务]自然的反扑','茄城附近的蔘林由于滥垦滥伐导致虫族大规模的反常袭击，茄城的卫兵李承希望你能够去打到虫族的女王来阻止牠们',1500),
  (240,2,'[城镇任务]自然的反扑','你已经打倒了虫族女王，该马上向茄城的卫兵李承回报',1501),
  (241,1,'[城镇任务]为了九黎!!','茄城的侍卫官钟元希望你去调查城外那位诡异的九黎人',1503),
  (241,2,'[城镇任务]为了九黎!!','原来城外那个诡异的九黎人是蛇族的间谍，这件事要马上让茄城的侍卫官钟元知道',1504),
  (242,1,'[城镇任务]真诚的友情','茄城的金熙与果力村的张佑有着深厚的友情，但是因为九黎族与人类间的仇恨日益加深越来越少联络，金熙希望玩家能够帮他送信给张佑(75/123)',1506),
  (242,2,'[城镇任务]真诚的友情','果力村的张佑收到茄城的金熙(119/88)来信后，写了封回信希望玩家转交回去给他',1507),
  (243,1,'[城镇任务]准备供品','茄城的老农夫朴乡伊为了感谢蚩尤带来今年的农作物大丰收，希望你能帮他找来三个青龙爪、三个白虎牙、三个朱雀羽、三个玄武甲与三个麒麟角这些珍贵稀有的素材',1509),
  (244,1,'[城镇任务]闹事的飚车族','许多的年轻九黎人骑着机车在深夜里喧哗吵闹，茄城的权相佑希望你能够去教训这些小鬼',1511),
  (244,2,'[城镇任务]闹事的飚车族','这些爱深夜飚车的年轻人看来已经受到应得的教训了，回去茄城跟权相佑说一声吧',1512),
  (245,1,'[城镇任务]战争准备','茄城的工程师崔宋需要许多九黎木作为制作木连弩的材料',1514),
  (246,1,'[城镇任务]霞岚山极速传说','茄城的藤元海苦恼无法在霞岚山创下新的飚车纪录，希望你能够帮他找来十个蜗牛黏液与二十个蜘蛛唾液作为改造机车的材料',1516),
  (247,1,'[城镇任务]驱逐害虫','茄城的农夫车允浩(143/150)苦恼于虫族常来偷吃农作物，希望你帮他消灭这些害虫，你需要带给他五个巨瓢虫卵、五个甲虫虫蛹、五个蜘蛛毒囊与五个蜗牛壳来证明你杀了不少虫子',1518),
  (248,1,'[城镇任务]蛇族的入侵','茄城的侍卫官钟元收到蛇族有许多士兵伪装成九黎人模样的消息，希望你能去取得蛇族秘密计划书好了解蛇族的企图',1520),
  (249,1,'[取神任务]杨戬的试炼','杨戬要你前往果力村调查一位身穿白色的九龙袍，头戴红色归元巾，手持蓝色玉麟鞭的女人。',1522),
  (249,2,'[取神任务]杨戬的试炼','白石彩在你眼前化作一道飞雪飘往果力村外，快去追她吧！',1523),
  (249,3,'[取神任务]杨戬的试炼','你识破了白石彩的幻术，但是她不服输的又化作一道飞雪往更远的西北处了，快去追她吧！',1524),
  (249,4,'[取神任务]杨戬的试炼','你狠下心给予了白石彩致命一击，让她魂飞魄散，虽然你除去了一个可能会危害人间的雪女，可是却违背了杨戬当初对你的教诲，接着你应该要回到杨戬庙，问看看他的反应吧。',1525),
  (249,5,'[取神任务]杨戬的试炼','你心里一软，放手让她回去，在她向你道谢的同时，你感受到心里的一股暖意，也许这正是杨戬要你处理这件事情的理由吧。你现在应该回到杨戬庙，问看看他的反应。',1526),
  (250,1,'[取神任务]云霄三姊妹的试炼','你遇到了三位奇妙的仙人姊妹，她们要你帮忙把位在天晴楼南方一个昏倒的人给救醒。然而要救醒他，你就必须要知道心肺复苏术的顺序，一步一步按照顺序来处理吧。至于急救结果不管成功失败，都回去和云霄三姊妹谈谈会比较好一点。',1528),
  (251,1,'[取神任务]闻仲的试炼','闻仲大老爷要你帮他照顾一盆植物，你必须先前往仙界和药草师傅谈谈才行。',1530),
  (251,2,'[取神任务]闻仲的试炼','药草师傅给了你五瓶药水和一盆植物以及两本书，书中记载了药水的效用以及仙界植物的来由。看来药草师傅相当希望你能够好好的栽培出一株好植物出来。',1531),
  (251,3,'[取神任务]闻仲的试炼','看来你的栽培失败了，和药草师傅谈谈吧，或许他会再给你一次机会的。',1532),
  (251,4,'[取神任务]闻仲的试炼','经过你悉心的照顾下，原本的幼苗已经顺利长大了，该是将他交给药草师傅看闻仲看看你辛勤栽培的结果了。',1533),
  (252,1,'[取神任务]雷震子的试炼','雷震子要你到果力村帮忙一名叫做小桃的人类女性，或许你现在应该就前往该处和她接触才对。',1535),
  (252,2,'[取神任务]雷震子的试炼','你接受了小桃提议，前往莫莫聚落的西方，找一颗果树，在果树旁有两台机车停放在那，应该不难找到。',1536),
  (252,3,'[取神任务]雷震子的试炼','你准备摘取的水果被亚可夫夺走了，或许你应该回城找小桃商量看看。',1537),
  (252,4,'[取神任务]雷震子的试炼','你击退了想要从你手中抢走水果的亚可夫，而且看来他跟小桃那失踪的朋友有关系，或许你该回城找小桃和她提起这件事看看。',1538),
  (252,5,'[取神任务]雷震子的试炼','小桃要你前往桃儿岭帮忙她救出她的朋友小雅。',1539),
  (252,6,'[取神任务]雷震子的试炼','你击败了亚可夫，成功的将小雅救出来，你现在应该做的或许就是该让小桃知道这各消息。',1540),
  (252,7,'[取神任务]雷震子的试炼','小桃想用这些水果借花献佛给雷震子，正巧你也要回去跟雷震子报告他交代你的任务，快点回去和雷震子讲这消息吧。',1541),
  (252,8,'[取神任务]雷震子的试炼','亚可夫终于倒地了，不过你有注意到他身后的女子似乎是被刚刚的战斗给吓到了，一动也不动的，或许你应该过去问看看她的状况才是。',1542),
  (253,1,'[神仙任务]争取时间','杨戬要你前往枫华镇找姜子牙木像聊一聊。',1544),
  (253,2,'[神仙任务]争取时间','杨戬给了你一瓶凡体药膏，可以盖过你身上的仙灵之气，不过使用地点得在他师傅─玉鼎真人的庙外，用这药膏吸引猎物上门。',1545),
  (253,3,'[神仙任务]争取时间','你故意装做不敌，让那掘地虫咬走杨戬幻术变成的手臂，据杨戬说现在那掘地虫应该就昏迷在金鳌牌坊那。他给了你一把手术用刀，因为掘地虫重生速度很快，只要约十秒的时间他就会再度爬起来，所以你必须要在这时间内对他开刀取出心脏方能完全的杀掉它。',1546),
  (253,4,'[神仙任务]争取时间','由于你开刀的速度以及顺序有错所以导致掘地虫逃跑，或许你应该在跟杨戬谈谈接下来的应对方针。',1547),
  (253,5,'[神仙任务]争取时间','杨戬对于你精确的下刀位置以及开刀的速度感觉到相当的佩服，也因为这样你才能顺利的解决这只不死的怪物，赶快把这颗心脏拿给杨戬看看吧。',1548),
  (253,6,'[神仙任务]争取时间','这条掘地虫似乎相当的狡猾，躲过了你的致命一击后看情势不对，于是便钻地逃跑。让你白忙一场，或许真该要像杨戬所说的，要故意输给牠才对???',1549),
  (254,1,'[神仙任务]喧闹的一天','任性的琼霄要你带她们三姊妹到截仙遗址的小天云池游玩(324，157)，你希望一路上是开开心心的，不过看到云霄和琼霄的谈话后，你开始觉得这种希望应该是一种奢求了。而且在同时，你也有种不吉祥的预感，如果在小天云池那有看到什么怪异的事情或是人物，最好还是通知那三个姊妹知道一下会比较好一点???',1551),
  (254,2,'[神仙任务]喧闹的一天','在你面前有昏倒在地的人，但是在你身后却有三名吵的不可开交的姊妹，在这各时候应该是要以病人为主才对吧???',1552),
  (254,3,'[神仙任务]喧闹的一天','你们施展了医疗法术将那昏倒的人救醒，或许你应该去问看看他昏倒在这儿的理由才是。',1553),
  (254,4,'[神仙任务]喧闹的一天','这人一醒来就大喊着怪物，或许从小就生长在此地的吵架三姊妹应该知道这件事情???',1554),
  (254,5,'[神仙任务]喧闹的一天','鬼灵精怪的琼霄提出了一个方法可以把在湖底的怪物给引出来，就是用钓的。你必须要准备一支钓竿和一块新鲜的蚌肉来合成出钓具引牠出来。即使你似乎不太同意这做法，但是云霄看来兴致勃勃，你恐怕也无法打断她的兴致。',1555),
  (254,6,'[神仙任务]喧闹的一天','看来琼霄的方法奏效了，不过她却误算了大姊对于钓鱼的热爱与技术，在一次一大群的魔物侵袭下，你最终还是失败了。不过琼霄又提出了另一个方法，就是利用它们的天性来进行攻击，要完成这计划，你必须先去抓一只等级约在十六级以下的火焰蟹来才行。',1556),
  (254,7,'[神仙任务]喧闹的一天','你成功的解决了这群发情的螃蟹，你现在该做的应该是问看看云霄三姊妹她们，并且祈祷她们不要再吵架了。',1557),
  (254,8,'[神仙任务]喧闹的一天','你成功的解决了这群螃蟹，你现在该做的应该是问看看云霄三姊妹她们，并且祈祷她们不要再吵架了。',1558),
  (255,1,'[神仙任务]猫捉老鼠','你漂亮的回答了闻仲提出的谜题，但是接着却要面对闻仲给予你的任务，就是去仙界挑战白狐，也就是变化师傅，帮闻仲讨回面子。',1560),
  (255,2,'[神仙任务]猫捉老鼠','你不慌不忙的面对变化师傅对你提出的问题，并且机智的回答出正确的答案。变化师傅在脑羞下又提出了一个挑战，不过怎么看都有问题。现在你该做的应该是去昆仑仙界上的青龙石碑那看看变化师傅在搞什么鬼。',1561),
  (255,3,'[神仙任务]猫捉老鼠','这次的挑战是变化师傅赢了，不过这件事怎么看怎么有问题，或许你应该问看看闻仲的意见才是。',1562),
  (255,4,'[神仙任务]猫捉老鼠','面对这么卑鄙又好胜的变化师傅，你这次真的是无言了???不知道闻仲是不是也这么想，也许你该去问看看他的意见才是???',1563),
  (256,1,'[神仙任务]戒?续篇','雷震子接获了师傅云中子的命令要他前往葛城旁的赤精子庙中和赤精子接洽事情。',1565),
  (256,2,'[神仙任务]戒?续篇','面对着充满压迫感的赤精子，你战战兢兢的回答他的问题，而你的答案似乎也符合他的期待。所以他给予你一个任务，要你帮他解决掉之前跟着他一起四处冒险的下凡仙童。因为那名仙童无法克服心中的欲望而落入了参天林的吸精女妖的手中，成为了黑暗的一部份。首先你必须先帮赤精子收集到他要的材料???',1566),
  (256,3,'[神仙任务]戒?续篇','你帮赤精子收集好材料，制作出五雷符咒，看来应该是可以将吸精女妖给打回原形。接着你应该要前往参天林去解决吸精女妖，以及帮解决掉曾经跟着赤精子的下凡仙童???',1567),
  (256,4,'[神仙任务]戒?续篇','面对吸精女妖的种种诱惑，你丝毫不为所动的一一回绝，并且坚定的要替天行道。而且你也成功的将吸精女妖给完全的打败了。接下来应该要回赤精子庙跟赤精子回报这令人振奋的消息才是。',1568),
  (256,5,'[神仙任务]戒?续篇','赤精子似乎不是很满意你的答案，于是把你给轰了出来，虽然你也不是第一次知道赤精子这神仙相当难伺候了???不过你看到身后的雷震子似乎对你的遭遇有种同情的感觉，或许他可以提供你一点意见也说不定???',1569),
  (256,6,'[神仙任务]戒?续篇','你运起真气，祭出赤精子给你的五雷符咒将吸精女妖这妖孽打回原形，当你看见这女妖的原形竟然是一个丑恶的老太婆时，不禁感叹许多人都是被华丽的外表所蒙蔽而不知道内心的丑恶???现在你该做的，应该就是和被打回原形的吸精女妖接触，并且打败她，为民除害才是！',1570),
  (257,1,'[职业任务]害虫','也许是身为剑客的关系吧，你挺拔的身材往往都吸引到路人的目光，这次也不例外。不过通常被人叫住都没好下场，往往都是劳力工作，当然，这次也不例外。这次你的任务是要去茄城东南面城墙外帮一个农夫(119/324)清除害虫，对你来说应该是小事一件。',1572),
  (257,2,'[职业任务]害虫','这农夫的田里一共有九处被虫啃食过，赶快拿着农夫给你的农药灌进这些虫洞中吧。',1573),
  (257,3,'[职业任务]害虫','你成功的驱除了侵蚀农夫田的害虫，接下来应该是要回去和那军官(69/97)回报才是。',1574),
  (257,4,'[职业任务]害虫','这名军官要你去和他的长官接洽，他长官就在茄城东北某处的菜园(217/269)中，赶快去找他吧。',1575),
  (257,5,'[职业任务]害虫','这名长官要你去和三名前线士兵接洽，取回他们在前线的报告。他们三人分别在云霄三姊妹庙外(444/166)还有莫莫聚落附近(320/247)以及桃儿岭西北海岸在线(427/225)。',1576),
  (257,6,'[职业任务]害虫','你完成了这名长官的托付，接着就回去和九黎人军官(69/97)拿你应有的回报吧。',1577),
  (258,1,'[职业任务]迷之幻兽？','谋士在外人眼中是一群充满着机智，以及具备敏锐反应的人。也许就是因为这一个特质，往往一些怪事或是难以处理的复杂工作都会落在你的肩膀上。这次，你又接受了一个怪异的请求，就是帮忙分析这不知名的兽毛，或许住在茄城城内北方香菇屋中的生物学家(140/66)会给你一个答案也说不定。',1579),
  (258,2,'[职业任务]迷之幻兽？','也许这次你遇到了一个神秘的生物也说不定，不过总之你现在该做的，就是依照生物学家的指示，去茄城北方杀几只云蜗牛，取得蜗牛黏液回来给他。',1580),
  (258,3,'[职业任务]迷之幻兽？','这名生物学家真的很会使唤人，为了帮助他了解这生物的真正样貌，你现在应该依照生物学家的吩咐，到莫莫聚落附近的菜园中找到他装着笔记本的箱子(312/240)，并且帮他把笔记本带回来。',1581),
  (258,4,'[职业任务]迷之幻兽？','按照生物学家所说的，你现在应该沿着茄城旁边的河流左岸往北走，到河流最曲折的那边的某处菜园中应该就可以见到他说的那个传说生物(212/192)了。',1582),
  (258,5,'[职业任务]迷之幻兽？','呃???你实在是没想到他们所说的传说生物竟然是南方随处可见到的鸭子???也许正所谓是少见多怪吧???不过你也不愿意泼那生物学家的冷水，还是乖乖的把这小家伙带回去给他看看吧(140/66)。记得要装备在身上喔！',1583),
  (258,6,'[职业任务]迷之幻兽？','这生物学家还要你带两只回来，你心中除了无奈之外还是无奈???',1584),
  (259,1,'[职业任务]五行与机械?首篇','仙道可以操作天地自然之力，也就是五行，然而在这机械充斥的国度中，你的身分与气质似乎无法完全融入其中。这次你就碰到了一个麻烦，一个对五行有着偏见的九黎机械技师要求你帮他做事来赎罪，虽然你不知道你欠了他什么，不过基于想找事情来做的心态，你还是答应他要帮他和茄城内的武器店(112/153)、技能书商(109/136)、合成屋(94/132)以及杂货铺老板(102/153)要东西。',1586),
  (259,2,'[职业任务]五行与机械?首篇','你帮那机械技师凑齐了他要的四样东西，紧接着他就要开始修理他的机器人，不过你心中有种不好的预感就是了???',1587),
  (259,3,'[职业任务]五行与机械?首篇','你成功的使用五行的力量来帮这机器人补充动力，而那机械技师则是在旁边看的目瞪口呆，也许这也是一种技术交流的契机吧。总之先把在旁边看的目瞪口呆的家伙给叫回现实世界才是首要的工作。',1588),
  (259,4,'[职业任务]五行与机械?首篇','武器店老板要你帮忙他寻找十五份蜘蛛体液，那些东西可以在茄城北方的翠绿鬼面蛛身上找到。',1589),
  (259,5,'[职业任务]五行与机械?首篇','杂货铺老板要你帮他去向城外西北方的一个萝卜人(108/257)讨债，只要帮他把债讨回来，杂货铺老板就会给你你要的东西。',1590),
  (259,6,'[职业任务]五行与机械?首篇','急坏了的合成屋老板要你帮忙将货物火速的送到城内西边菜园中给一位着急的九黎人(66/65)，你现在只剩下一分钟不到的时间可以完成这任务了???',1591),
  (259,7,'[职业任务]五行与机械?首篇','穷极无聊的技能书商老板要跟你猜拳打发时间，只要连赢他三场，他就会把你要的东西给你。',1592),
  (259,8,'[职业任务]五行与机械?首篇','你从武器店、杂货铺、合成屋和技能书商老板那取得了机械技师要拿来修理机器人用的材料之一，如果收集完毕了，那你应该就要和机械技师谈谈接下来的步骤。如果还没完全收集完毕，或许你应该要再跟这四位老板谈一谈才是。',1593),
  (260,1,'[职业任务]水质检测','身为药师，看到路上有人需要帮助时，你绝对是全力以赴。当然，今天的你也是如此。但也因为你的多管闲事，让你多了一项工作，就是帮忙当地的药剂师做水质检测的工作。他要你到茄城东北方那条河流尾端(163/302)还有到莫莫聚落南方那条河流尾端(324/249)，以及到九黎半岛最南端那边附近(83/395)，一共三处来帮忙装水。',1595),
  (260,2,'[职业任务]水质检测','你辛苦奔波，带了三瓶水质检测用的水回来给药剂师化验，而化验结果现在就在你手上。现在的你必须带着这些东西沿着九黎半岛最西边的海岸线往北走，找到水质研究员(120/147)，并且把东西交给他，要他写出一份报告出来。',1596),
  (260,3,'[职业任务]水质检测','也许是天生的奔波命吧，现在你必须要把这份报告带回去给那名药剂师(104/158)。',1597),
  (260,4,'[职业任务]水质检测','药剂师在看过水质评估报告后决定要制作药剂帮忙减轻水中的重金属污染物质，所以现在他吩咐你必须前往莫莫聚落南方菜园处杀死一种叫做人面蛛的蜘蛛(306/248)，取得他的毒囊，并且在取得毒囊后的五分钟内将毒囊交给药剂师才行。',1598),
  (260,5,'[职业任务]水质检测','现在准备工作都已经完成了，不过药剂师显然对这份工作兴致缺缺，他要你帮忙他把三瓶调和剂倒入你当初取水的地点上(163/302)、(324/249)、(83/395)，完成后再回报给他知道。',1599),
  (261,1,'[职业任务]农夫之子','你或许想起来之前你在帮忙那农夫清除害虫时，那农夫嘴巴里一直喃喃的念着他外出不归的孩子。现在他向九黎军方要求指定要你帮忙他找回他孩子，或许你现在应该去城外找那农夫谈清楚这件事情才是。',1601),
  (261,2,'[职业任务]农夫之子','农夫他孩子最后的目的地是杨戬庙西边那块绿地附近，也许你能够在那边找到他孩子的踪迹也不一定。',1602),
  (261,3,'[职业任务]农夫之子','你赶走了这群准备狩猎农夫孩子的北方人类后，在他们身上找到了镣铐钥匙，也许用这东西就可以打开农夫孩子身上的镣铐吧。',1603),
  (261,4,'[职业任务]农夫之子','农夫的孩子在把种子交给你后就力尽而亡，为了不辜负他的心意，现在你唯一能做的就是尽快的把这种子平安的送到他父亲的手中，但是这种子在过两分钟就会失去新鲜度了???',1604),
  (261,5,'[职业任务]农夫之子','为了能够用这种子栽培出全新的作物，农夫要你帮忙他制作特制泥土三份，每一份特制泥土要用五份甲虫虫壳以及一份金创药来进行合成，将三份泥土交给农夫吧。',1605),
  (261,6,'[职业任务]农夫之子','据农夫说北方的侦查兵也为了这传说中的种子而追到此处了，你现在要做的就是在农夫种出作物之前保护他，在三分钟内会出现五团敌人，你必须在三分钟内解决完这些追兵才行！',1606),
  (261,7,'[职业任务]农夫之子','你解决完最后一名追兵了，赶快去问看看农夫的情况如何！',1607),
  (261,8,'[职业任务]农夫之子','解决完了北方的追兵之后，你和农夫成功的培育出了新一代的种子，但是你想起来和那九黎人军官的约定，你心里想着也许该把这成品给他看看才对???',1608),
  (262,1,'[职业任务]怀璧其罪','这名生物学家似乎迷上了这只鸭子，还帮他取了名字。现在他要你帮他训练他的可鲁，要把他的等级从十八级升到二十五级。',1610),
  (262,2,'[职业任务]怀璧其罪','经过了一番努力，你成功的训练起这只可鲁，在培育的过程中你发现牠身上的确有股特殊的力量，牠和其他的宠物的确有些许的不同。但你现在该做的是把可鲁带回牠的出生地，让牠看看牠生长的地方。',1611),
  (262,3,'[职业任务]怀璧其罪','看来北方的人类也耳闻到这生物的传说，而且也已经盯上了你，你现在最好是将可鲁带回去给生物学家那吧。',1612),
  (262,4,'[职业任务]怀璧其罪','你听从了北方人类的建议，把可鲁野放掉，不过你接下来还是得给生物学家一个交代才是???',1613),
  (262,5,'[职业任务]怀璧其罪','生物学家相当的害怕他的可鲁会被北方人类带走，他要你帮他找到十份坚韧木材来制作兽栏，这些东西可以在桃儿岭那附近的桃岭树精身上得到。',1614),
  (262,6,'[职业任务]怀璧其罪','当你好不容易收集齐生物学家要的东西后，却听到了一个你不想听到的消息，就是可鲁已经被北方人掳走了，位置就在桃儿岭的洞穴中，而且对方还请了猎人英雄来对付你???',1615),
  (262,7,'[职业任务]怀璧其罪','你成功的击退了信心满满的猎人英雄，他也按照承诺将可鲁交还给你。现在你该做的应该就是带着可鲁回去给生物学家看看。',1616),
  (263,1,'[职业任务]五行与机械?续篇','也许是见识过你可以随心所欲的操控着自然五行的力量，这次机械技师倒是很客气的拜托你帮忙他制作机器人。他要你帮忙取得三样材料来制作他机器人的动力源，分别是完美木材、能量增幅仪和能量封印珠。你可以在桃岭树精、二星九黎人以及赤条蜘蛛身上取得这些东西。',1618),
  (263,2,'[职业任务]五行与机械?续篇','当你收集完他要的材料后，他要求你帮他制作出封印着五行力量的水晶来进行五行相生的合成。你要依照五行相生的顺序，将封印着五行属性的水晶各十颗，并且依照相生的原则进行合成，来制作出五颗不同属性的融合水晶来。',1619),
  (263,3,'[职业任务]五行与机械?续篇','你成功的制作出五颗融合水晶，而那机械技师很高兴的收下这些水晶，来制作机器人的动力源。接着你应该要前往桃儿岭附近去见他的老板─九黎军事开发部军官了。',1620),
  (263,4,'[职业任务]五行与机械?续篇','你亲眼目睹到你所协力制作出来的机器人是用来作为杀戮用途的同时，你隐然感觉到心中的不满以及怒气。但你也无法改变这已经发生的事实。你现在应该做的是过去看看那些北方人类的状况，也许他们还有一丝气息吧???',1621),
  (263,5,'[职业任务]五行与机械?续篇','突然在你面前出现了一个动作极为敏捷的北方人类，他迅速的击倒了比他高大许多的机械人，并且往你走过来，看他没怀着好意，也许你应该要先下手为强才是。',1622),
  (263,6,'[职业任务]五行与机械?续篇','你成功的打败了这名自称为草原之狼─布拉什的男人，同时也保护了你身后的那两个九黎人，现在你应该做的应该是和他们谈谈才是。',1623),
  (264,1,'[职业任务]逼供','也许肮脏的事情你见多了，但是却也未曾接受过帮助刑求的请求。你曾经帮忙过的药剂师要你到莫莫聚落西边河岸旁找位处刑官，帮助他完成刑求的目的。',1625),
  (264,2,'[职业任务]逼供','从和刑求官的谈话中你得知那名药剂师似乎也参与过不少刑求的案子，不过似乎是越来越没有兴趣在帮助刑求上。所以才会把这责任推到你身上来，不过最终他还是无法完全离开这案子。刑求官要求你通知药剂师，要他帮忙制作自白剂来对付这次的嫌犯。你现在应该要回去和药剂师接洽才是。',1626),
  (264,3,'[职业任务]逼供','药剂师要你帮他收集十份蜘蛛唾液来制作自白剂，但是从你和他的对话中可以知道，他似乎也相当的无奈???',1627),
  (264,4,'[职业任务]逼供','这自白剂似乎可以逼迫任何人说出实话来，现在你应该要带着这瓶自白剂回去给刑求官才是???',1628),
  (264,5,'[职业任务]逼供','从这里开始，你才知道这刑求官可怕的地方，他要你去桃儿岭那收集十片头皮来给那北方人类看，这种残忍的行为目的就是要让他打从心底后悔曾经做出的事情???',1629),
  (264,6,'[职业任务]逼供','在收集头皮的过程中你意外的得到了一封密函，上面写着有关潜伏在九黎国内的北方人类名册，如果找到的话，也许就可以将潜伏在九黎国境内的北方人类一网打尽。但是位置还无法得知，唯一的线索就是在刑求官手中的北方人类─夏尔曼的身上。或许你应该去问看看他，或是逼迫他交出这名册出来才是。',1630),
  (264,7,'[职业任务]逼供','夏尔曼愿意说出名册的位置，不过前提条件是要把他妻子带过来，他妻子就在果力村内北边的南瓜屋中，你现在要做的应该就是前往该处找到她。',1631),
  (264,8,'[职业任务]逼供','夏尔曼的妻子身体相当的衰弱，每隔一分钟要是没有接受治疗，她随时都有可能死亡，所以你该做的就是一边前进，一边在固定时间内用治疗法术帮助她才是。',1632),
  (264,9,'[职业任务]逼供','你成功的把她带到夏尔曼的身边，不过你看见旁边的刑求官似乎没安什么好心眼，或许你该过去问看看刑求官才对。',1633),
  (264,10,'[职业任务]逼供','刑求官当着你的面把夏尔曼的太太给毒死???借口说要为他太太治病，但却是将毒药灌入她口中???这种残忍的行径连你都看不下去???不过你想到药剂师给你的忠告，也硬是忍受了下来。接着你应该要去问看看夏尔曼有关名册的事情???',1634),
  (264,11,'[职业任务]逼供','夏尔曼把名册放在天晴楼一楼里，不过你对他的话语感觉到有些不对劲，也许你该趁早取得这名册，并且火速赶回来才是???',1635),
  (265,1,'牛郎织女','你答应牛郎要找他父亲，看他交给你的宝珠似非凡物，或许可以看看宝珠能不能用',1637),
  (265,2,'牛郎织女','你被传到了一个不知名的地方，看起来又不像阴间，不管了，先看看牛父有没有在附近吧',1638),
  (265,3,'牛郎织女','找到了牛父，顺道把信送回去给牛郎吧',1639),
  (265,4,'牛郎织女','牛郎请你帮忙收集七颗鹊糖，四处找找吧，也许有怪物会掉落',1640),
  (265,5,'牛郎织女','牛郎请你把他和织女的好事告知牛父，再用用宝珠吧',1641),
  (265,6,'牛郎织女','你再度传到了这不知名的地方，去找找牛父吧',1642),
  (265,7,'牛郎织女','牛父交给你一个锦囊，看来牛郎可能有事发生，快回去找他吧',1643),
  (265,8,'牛郎织女','牛郎说织女被人抓走了，是仙界的人，先看看牛父给的锦囊，或许有什么对策',1644),
  (265,9,'牛郎织女','打败了天将，知悉的事情始末，先把消息告诉牛郎再说吧',1645),
  (265,10,'牛郎织女','牛郎最后请你帮他再找一次牛父，再用用宝珠吧',1646),
  (265,11,'牛郎织女','你又来到了这不知名的地方，去找找牛父吧',1647),
  (265,12,'牛郎织女','根据锦囊内的讯息，或许回枫华镇去找仙鹤童子上一趟昆仑仙界可以找到那位王母天将',1648),
  (266,1,'[主线任务]蚩尤使者','仙霞童子要你前往九黎北岛的果城继续调查镇岳结及王者荒魂的下落',1650),
  (266,2,'[主线任务]蚩尤使者','在用计得到守门的九黎人信任后，受邀前往晋见住在城内的九黎国领导人九黎主教',1651),
  (266,3,'[主线任务]蚩尤使者','在见过主教后，得知城外东边有大军操演，先去那打听打听吧',1652),
  (266,4,'[主线任务]蚩尤使者','大队长请你代为巡视驱赶果城周遭的蛇族先锋，并带回二十个闇蛇牙',1653),
  (266,5,'[主线任务]蚩尤使者','在从大队长手中拿到闇蛇炼后，得知九黎工坊亦有部队在训练，不管大队长的法螺如何吹，你还是决定去九黎工坊看看',1654),
  (266,6,'[主线任务]蚩尤使者','想不到小队长也是法螺功高手，你不得已要再为其除去在九黎工坊内搞乱的两部蛇族机关人，看来先处理这事再回来跟这小队长周旋吧',1655),
  (266,7,'[主线任务]蚩尤使者','果然有人在监视着你，不过你决定继续查下去，先回果城客栈打听打听再说',1656),
  (266,8,'[主线任务]蚩尤使者','你感觉全身无力，还是先离开客栈再说吧',1657),
  (266,9,'[主线任务]蚩尤使者','在危急之际你被一阵光带到了这里，前面有个黑衣人，先去问问他吧',1658),
  (267,1,'[主线任务]蚩尤神殿','黑衣人告诉你有必要再前往蚩尤神殿一趟，或许能再找到些什么吧',1660),
  (267,2,'[主线任务]蚩尤神殿','在遭遇到伏击后，看来这镇岳结有着诡异的结界，先回去找仙霞童子商谈对策比较妥当',1661),
  (268,1,'[主线任务]王者荒魂','当仙霞童子跟你表示有人可以帮你之时，你感觉有人来到你身旁了，看看是谁吧',1663),
  (268,2,'[主线任务]王者荒魂','黑衣人表示王者荒魂在岚壁迷穴，他给了你一封信，要你带去给蛇族女王，等取得王者荒魂后到祈雨台找他',1664),
  (268,3,'[主线任务]王者荒魂','蛇族女王要你去找在迷穴里的火战、山御、林智、风敏四位蛇使，并通过考验带回四颗印石，以证明你的能力',1665),
  (268,4,'[主线任务]王者荒魂','蛇族女王要你把交付给你的小蛇烛阴锻练到三十级并且通过位在岚壁迷穴中的风吼阵之后再回来',1666),
  (268,5,'[主线任务]王者荒魂','蛇族女王的最后一个考验是与你来一场对决，只要胜了的话，那王者荒魂就入手了',1667),
  (268,6,'[主线任务]王者荒魂','你已经由蛇族女王手中拿到了王者荒魂，快去祈雨台找黑衣人吧',1668),
  (268,7,'[主线任务]王者荒魂','就当黑衣人施法之际，蚩尤的人马果然出现，一场火并在所难免了',1669),
  (268,8,'[主线任务]王者荒魂','你顺利的打败了蚩尤的人马，先去看看黑衣人施法的结果如何',1670),
  (269,1,'[主线任务]决战罗喉','黑衣人要你立刻前往蚩尤神殿取回镇岳结',1672),
  (269,2,'[主线任务]决战罗喉','九黎主教出现在你面前，而且看起来似乎是要跟你决一死战的样子',1673),
  (269,3,'[主线任务]决战罗喉','你打败了九黎主教，不过彭遵的火影却出现在你面前',1674),
  (270,1,'[主线任务]重返太虚','黑衣人出手相救击退了彭遵的火影，你将王者荒魂交给他之后，他要你带镇岳结回去找仙霞童子报告此行的结果',1676),
  (271,1,'[职业任务]蛇族第一勇士','你对这小蛇进行了简单的包扎，但似乎没什么成效，你决定去准备点金创药来比较实际',1678),
  (271,2,'[职业任务]蛇族第一勇士','小蛇起身快速朝东北沿河岸走了去，先追过去看看再说吧',1679),
  (271,3,'[职业任务]蛇族第一勇士','腹涎转身向果城跑了去，应该就是去找那个叫穆瓜的九黎人吧，快跟上去看看',1680),
  (271,4,'[职业任务]蛇族第一勇士','你的大胆推论引起了腹涎想追求真相的意愿，就在牠离去后，你惊觉不妥，快去岚壁迷穴找那个查哈，或许能来得及',1681),
  (271,5,'[职业任务]蛇族第一勇士','你看到腹涎全身是血，似是受了重击，先去看看牠吧',1682),
  (271,6,'[职业任务]蛇族第一勇士','你看着腹涎无助的死在你面前，自责的你决定帮腹涎报仇，教训这个蛇族第一勇士',1683),
  (272,1,'[职业任务]英涛的心愿','你必须带着英火珠在五分钟内到祈雨台一带，只要在时限内到达，便可以看到奇异的火光，在那里便是英涛父亲埋藏玉镯的地方了',1685),
  (272,2,'[职业任务]英涛的心愿','你时间担误太久了，英火珠从你眼前消失了，看来要回去再找一下英涛了',1686),
  (272,3,'[职业任务]英涛的心愿','你按的钮好像是错的，英火珠从你眼前消失了，看来要回去再找一下英涛了',1687),
  (272,4,'[职业任务]英涛的心愿','你成功的取得玉镯，回去找英涛吧',1688),
  (272,5,'[职业任务]英涛的心愿','英涛请你找回三十朵仙人掌花，这花可以在九黎工坊北方的仙人掌林找到',1689),
  (273,1,'[职业任务]流浪道人','流浪道人要你先从青采聚落开始，并给了你一张纸条，上面写着「四叶盆栽菇房旁，南瓜门旁大花开，木桶孤置椒田外，伊人就在茄城藏」',1691),
  (273,2,'[职业任务]流浪道人','你依纸条的提示找到了胡萝泊，他要你先找来三十个剑心蛇肉，这东西在岚壁迷穴的暴怒蛇游侠身上可以得到',1692),
  (273,3,'[职业任务]流浪道人','胡萝泊在收了你三十块剑心蛇肉后，要再问你一个问题，只要答对就可以得到流浪道人的信物',1693),
  (273,4,'[职业任务]流浪道人','你拿到了信物，回去找流浪道人吧',1694),
  (274,1,'[职业任务]九黎工坊的机关人','酒梨技师说他需要十五个润滑油和十五个机件及三十条蜘蛛丝，润滑油和机件可以在九黎工坊内的九黎电眼和九黎破山等身上取得，而蜘蛛丝则是在果城北方的白玉蜘蛛身上，收集好就带到九黎工坊给酒梨技师吧',1696),
  (274,2,'[职业任务]九黎工坊的机关人','酒梨技师要你把十五瓶润滑油以1:2的分别倒入机关人胸前的左右两个孔，再将十五个机件依头手身脚的顺序按2:1:1:1比例装好',1697),
  (274,3,'[职业任务]九黎工坊的机关人','你搞砸了，要重新再收集十五瓶润滑油和十五个机件了（润滑油和机件可以在九黎工坊内的九黎电眼和九黎破山等身上取得）',1698),
  (274,4,'[职业任务]九黎工坊的机关人','你搞砸了，要重新再收集十五瓶润滑油了（润滑油可以在九黎工坊内的九黎电眼和九黎破山等身上取得）',1699),
  (274,5,'[职业任务]九黎工坊的机关人','技师交给你弹绳，将这东西一起旋在机关人上吧',1700),
  (274,6,'[职业任务]九黎工坊的机关人','你完成了技师的交代，把剩下的弹绳还他吧',1701),
  (275,1,'[城镇任务]教主的密令','九黎国的主教们知道金熙暗中与人类有所连络，主教密使要求你去杀了茄城的金熙',1703),
  (276,1,'[城镇任务]品种改良','果城的发明家李相担心攻占九尾国之后原来九黎国的农作物会水土不服，所以想对农作物作品种的改良，需要你去帮他寻找二十个药草、二十五个树妖的根与三十个树妖的叶',1705),
  (277,1,'[城镇任务]气象制造机','果城的发明家李相想利用控制气候的方式来培育植物的生长，首先你去帮他寻找十五根白虎牙与十五个金之精',1707),
  (277,2,'[城镇任务]气象制造机','果城的发明家李相的气候制造机第一次的实验失败了，于是要你再去帮他寻找十五根青龙爪与十五个水之精',1708),
  (277,3,'[城镇任务]气象制造机','果城的发明家李相的气候制造机第二次的实验相当成功，继续要你再去帮他寻找十五根麒麟角与十五个木之精',1709),
  (278,1,'[城镇任务]修理机关水井','果城的赖以维生的机关水井故障了，工程师俞浚为了修复它，希望你能帮他拿来十五根水管',1711),
  (279,1,'[城镇任务]与蛇族的战争','果城的侍卫长卢毓邀请你加入对抗蛇族的战争，第一道命令是取得十五个蛇鳞、二十个蛇牙与二十五个蛇胆',1713),
  (280,1,'[城镇任务]增强防御','果城的侍卫长卢毓要你往果城北边九尾国的关卡向战备官辛平报到',1715),
  (280,2,'[城镇任务]增强防御','战备官辛平要你即刻调度三十个机枪弹药桶来给他',1716),
  (281,1,'[城镇任务]虫虫危机','果城的农夫慕容星请玩家协助消灭一定数量的害虫，用三十个瓢虫翅膜、三十个甲虫虫壳与三十个蜘蛛丝来证明你消灭了不少害虫',1718),
  (282,1,'[城镇任务]自由的种子','果城的斐达率领着一群反抗军想要推翻九黎主教的极权统治，请你带给他三十个玉米弹壳、三十个南瓜轮胎与三十个破损的机翼充实反抗军的战备物资',1720),
  (283,1,'[城镇任务]新战车测试','果城的工程师休博为了开发新型战车，需要玩家去帮他寻找十五个连弩板机作为制作材料',1722),
  (283,2,'[城镇任务]新战车测试','果城的工程师休博为了测试新型战车的威力，要玩家去与实验战车丙型战斗',1723),
  (283,3,'[城镇任务]新战车测试','实验战车丙型被你打坏了，去与果城的工程师休博回报吧',1724),
  (284,1,'[城镇任务]实验机关人','果城的工程师休博再度开发了新型的机关人，需要玩家去帮他寻找三十个连弩板机作为制作材料',1726),
  (284,2,'[城镇任务]实验机关人','果城的工程师休博为了测试新型机关人的威力，要玩家去与机关人萝卜号战斗',1727),
  (284,3,'[城镇任务]实验机关人','机关人萝卜号又被你打坏了，去与果城的工程师休博回报吧',1728),
  (285,1,'[取神任务]哪咤的试炼','哪咤要你到果城寻找一群捡走混天绫的九黎人',1730),
  (285,2,'[取神任务]哪咤的试炼','将混天绫到北边的萝泊那的南岸洗一洗',1731),
  (286,1,'[取神任务]龙吉公主的试炼','祈雨台西北方的两国交界附近有一群九黎国的人在围捕九尾国的人民，龙吉希望你帮忙龙吉维护这边地区的平衡',1733),
  (287,1,'[取神任务]黄飞虎的试炼','黄飞虎要你在一柱短香(约十五分钟)时间内进入仙人掌林里，取得墨精石回来交给他',1735),
  (288,1,'[取神任务]太乙真人的试炼','太乙真人要你到果城寻找化名为夏吉的千面人并逮捕他',1737),
  (288,2,'[取神任务]太乙真人的试炼','太乙真人交付给你的任务失败了，再回去跟祂谈谈吧。',1738),
  (288,3,'[取神任务]太乙真人的试炼','你成功的逮到了千面人，快回去跟太乙真人报告吧。',1739),
  (289,1,'[神仙任务]蚌精与婴儿','袭击你的小蚌精留下了一张信纸，问问哪咤对于这件事的看法',1741),
  (289,2,'[神仙任务]蚌精与婴儿','哪咤给了你一迭信纸要你仔细的研究一下，内容都是看不懂的奇怪符号',1742),
  (289,3,'[神仙任务]蚌精与婴儿','你从这迭信纸中分析出了在青采聚落与萝泊附近有个手中抱着婴儿的蚌精需要帮助',1743),
  (289,4,'[神仙任务]蚌精与婴儿','蚌壳精要求你沿着萝泊岸边往北走，以婴儿作饵引诱出螃蟹精并且消灭它',1744),
  (289,5,'[神仙任务]蚌精与婴儿','螃蟹精已经被你消灭了，与蚌壳精和哪咤谈谈接下来该怎么做吧',1745),
  (290,1,'[神仙任务]疯狂的纵火犯','龙吉公主要你到在玉弥山脚的玉弥洞附近阻止疯狂的纵火者',1747),
  (290,2,'[神仙任务]疯狂的纵火犯','疯狂的纵火者在临死前点燃了预先设置好的稻草堆，玉弥山陷入一片火海',1748),
  (290,3,'[神仙任务]疯狂的纵火犯','龙吉公主要你在三分钟内用圣水龙珠扑灭附近的火势',1749),
  (291,1,'[神仙任务]黑杀星','黄飞虎感应到有团妖气往九黎北岛的哪咤庙而去，哪咤可能身处危险之中',1751),
  (291,2,'[神仙任务]黑杀星','害人无数的黑杀星高继能又回到凡间了，必须赶快去九黎工坊阻止他',1752),
  (292,1,'[神仙任务]头痛的徒儿','太乙真人放心不下他那捣蛋的徒儿哪咤，先去石矶娘娘庙一趟看看石矶娘娘有没有哪咤的消息',1754),
  (292,2,'[神仙任务]头痛的徒儿','石矶娘娘提到邓婵玉抱怨哪咤的事情，该去邓婵玉庙问问看',1755),
  (292,3,'[神仙任务]头痛的徒儿','拿着哪咤用来欺负邓婵玉的证物，到九黎半岛的哪咤庙兴师问罪吧',1756),
  (292,4,'[神仙任务]头痛的徒儿','哪咤往西边逃跑了，快追上去抓住祂',1757),
  (292,5,'[神仙任务]头痛的徒儿','哪咤使出法术消失在你眼前，问问太乙真人该怎么让哪咤现出原形',1758),
  (292,6,'[神仙任务]头痛的徒儿','哪咤已经被你打回庙里了，取得太乙真人的同意后好好教训他一顿',1759),
  (293,1,'[主线任务]妖狐入魔','仙霞童子送你前往九黎九尾交界的宁蒙关，那里有些从九尾国来的人，或许能探听到什么消息',1761),
  (294,1,'[主线任务]谯云峰火','根据胡里的叙述，谯云关似乎发生了什么事，去调查看看吧',1763),
  (294,2,'[主线任务]谯云峰火','你觉得这里气氛有点诡异，先四处看看，或许有什么端倪',1764),
  (294,3,'[主线任务]谯云峰火','在击退敌人后，你听到耳后有人告诉你到南原冰屋一趟，有要事相商，虽不知要找谁，不过先去那四处问问再说吧',1765),
  (294,4,'[主线任务]谯云峰火','王贵人要你先去九天冰屋找胡喜媚问问有什么新的消息了',1766),
  (295,1,'[主线任务]冰魂谷','胡喜媚告诉你彭遵等人已经去了冰魂谷找圣兽玄武，快动身去协助玄武吧',1768),
  (295,2,'[主线任务]冰魂谷','你在击退狼族后感应到仙霞符上有股灵气，似乎是仙霞童子在符上写了什么，赶紧打开来看看吧',1769),
  (295,3,'[主线任务]冰魂谷','仙霞童子要你先协助狼族，而狼王之子呼延正在极冻高原上，先去找牠再做打算',1770),
  (295,4,'[主线任务]冰魂谷','狼王奈特在皇狼穴中，虽然可能是趟艰辛的战斗，不过还是要去会会这被控制的狼族之王',1771),
  (295,5,'[主线任务]冰魂谷','你醒来只看到地上一排字「欲破术印，先取狼刃。无迹妖阵，唯战可破。」，看来你要解救狼王先要找到狼刃，还是先去问问呼延吧！',1772),
  (295,6,'[主线任务]冰魂谷','根据呼延的口述，狼刃被彭遵以无迹妖阵锁在噬狼穴，看来除了硬闯也没别的法子了',1773),
  (295,7,'[主线任务]冰魂谷','你已顺利取得狼刃，再回去皇狼穴找奈特吧',1774),
  (295,8,'[主线任务]冰魂谷','经历一场激战，你终于取下狼王背上的术印，彭遵的人已经到谷底找玄武，快去吧，晚了就来不及了',1775),
  (295,9,'[主线任务]冰魂谷','圣兽玄武奄奄一息，快去冰魂谷内的飘渺洞和紫金洞找来十个玄砂和十个武胆救玄武吧',1776),
  (296,1,'[主线任务]神秘黑衣人','玄武要你速回九天冰屋去找胡喜媚，彭遵的下一个目标就是妲己手上的王者荒魂，连这都失去的话可就麻烦了',1778),
  (296,2,'[主线任务]神秘黑衣人','胡喜媚要你先去极光台找一个黑衣人，他应该有法子可以救妲己',1779),
  (296,3,'[主线任务]神秘黑衣人','黑衣人要你在十分钟内找到他放在冰狼湖附近的一个宝箱并取出其中物品',1780),
  (296,4,'[主线任务]神秘黑衣人','东西拿到了，快交给黑衣人吧',1781),
  (296,5,'[主线任务]神秘黑衣人','时间超过了，看来要再回去找黑衣人问问怎么办',1782),
  (297,1,'[主线任务]血染荒魂','黑衣人给了你一瓶血水，要你带着去找在九天冰屋地下迷宫里的妲己，只要淋上王者荒魂，则妲己便有救了',1784),
  (298,1,'[主线任务]计锁罗喉','在惊险之际胡喜媚救你逃离彭遵面前，现在要设法将彭遵困在红水阵，首先你要先取得红水阵王天君身上的葫芦水，再带着它去找彭遵，不能久战，要一直逃跑，引诱彭遵到红水阵中将其困住',1786),
  (298,2,'[主线任务]计锁罗喉','你总算把彭遵暂时困在红水阵里了，先逃离这里快回去神殿找王贵人吧',1787),
  (299,1,'[主线任务]妖狐元神','在你困住彭遵后，王贵人要你立刻去极光台找黑衣人，问问有什么法子可以让妲己醒转',1789),
  (300,1,'[主线任务]血战神殿','黑衣人要你快回九天冰屋的神殿去协助王贵人她们抵御彭遵，至于妲己的元神他会去取回的',1791),
  (300,2,'[主线任务]血战神殿','经历一连串事件后，妲己终于清醒了，先跟她谈谈吧',1792),
  (301,1,'[主线任务]天界复命','总算完成了这项任务，回去跟仙霞童子交差吧',1794),
  (302,1,'[转生任务]九黎新能源','蛇族女王表示虽然欲与九黎国和好，但近日又听闻九黎有新能源开发，为求安全起见，请仙童协助调查，最好的方法，自然是直接去找跟仙童有些交情的九黎主教了',1796),
  (302,2,'[转生任务]九黎新能源','九黎主教要你将能源装置带去给在玉弥洞的工程师铁风',1797),
  (302,3,'[转生任务]九黎新能源','铁风表示这次的实验需要七个「地元气魂石」以及一个「天元灵魄玉」。地元气魂石可以从玉弥穿山甲身上获得，天元灵魄玉在落魂阵中的姚天君身上，而落魂阵的入口就在玉弥洞内。',1798),
  (302,4,'[转生任务]九黎新能源','铁风表示能源提炼，要把地元气魂石放到甲型炼炉跟乙型炼炉里面。要诀是甲三乙四。这数量是很重要的因素，如果放置正确的数量，就可以把能源提炼出来了。',1799),
  (302,5,'[转生任务]九黎新能源','看来你失败了，要重新收集玉弥穿山甲身上的地元气魂石七个才行',1800),
  (302,6,'[转生任务]九黎新能源','看来铁风的工程实验失败了，机关人暴走，把报告书交回去给九黎主教吧',1801),
  (302,7,'[转生任务]九黎新能源','事情水落石出，回去找蛇族女王报告结果吧',1802),
  (302,8,'[转生任务]九黎新能源','根据仙霞童子的交待，只要你的能力达到可以封神转生的资格，就可以去找葛城洞府神像进行封神转生了',1803),
  (302,9,'[转生任务]九黎新能源','你把东西都放好了，跟铁风回报一声吧',1804),
  (303,1,'[城镇任务]珍珠项链','帮小美向珠宝店的王大叔询问珍珠项链的事情。',1806),
  (303,2,'[城镇任务]珍珠项链','王大叔还缺25颗「大颗珍珠」才能制作项链。有些「岁星弯刀铜甲狐」身上会带着「大颗珍珠」，快帮王大叔搜集吧。',1807),
  (303,3,'[城镇任务]珍珠项链','好不容易把珍珠项链制作完成，快点回去交给小美吧。',1808),
  (304,1,'[城镇任务]贪吃的孩子','帮阿豪到城外搜集20条飞貂尾巴，打「冻原飞貂」就可以得到。',1810),
  (305,1,'[城镇任务]造桥铺路','帮大工头把挡在南原出城路上正中央的树移除。',1812),
  (305,2,'[城镇任务]造桥铺路','树砍倒了，快回去通知大工头吧。',1813),
  (306,1,'[城镇任务]说话的马','帮忙玛老伯看看他家里养的马发生了什么事情吧。',1815),
  (306,2,'[城镇任务]说话的马','你已经成功把附在马身上恶灵驱除了，快去通知玛老伯吧。',1816),
  (307,1,'[城镇任务]神秘失踪案件','帮赖小瓜到南边找找他的萝卜吧。',1818),
  (307,2,'[城镇任务]神秘失踪案件','你找到萝卜了，把萝卜带回去给赖小瓜吧。',1819),
  (308,1,'[城镇任务]植树的学问','到东南方找净瓶水守护兽，带回净瓶水给松柏生。',1821),
  (308,2,'[城镇任务]植树的学问','快把净瓶水带回去给松柏生，救活小树苗。',1822),
  (309,1,'[城镇任务]植树的学问','到北方找玄土守护兽，带回玄土给松柏生。',1824),
  (309,2,'[城镇任务]植树的学问','把玄土交给松柏生，你就可以种活这颗树了。',1825),
  (310,1,'[城镇任务]吃小孩的狼','帮小花的娘调查可疑的说书人。',1827),
  (310,2,'[城镇任务]吃小孩的狼','把小花的红衣服带回去给小花的娘。',1828),
  (311,1,'[城镇任务]传家之宝','到狼穴里搜集10张「角刃巨狼」身上的白金狼皮，向左老伯证明你的实力',1830),
  (312,1,'[城镇任务]挑战魔王','到北边的瞭望台寻找五尾王的第一把武器。',1832),
  (312,2,'[城镇任务]挑战魔王','你得到了五尾王的第一把武器，回去找九尾族老者询问之后的事情。',1833),
  (312,3,'[城镇任务]挑战魔王','到东边的瞭望台寻找五尾王的第二把武器。',1834),
  (312,4,'[城镇任务]挑战魔王','你得到了五尾王的二把武器，回去找九尾族老者询问挑战五尾王的信息。',1835),
  (313,1,'[城镇任务]挑战魔王','带着英灵剑与英灵枪到冰魂谷打破封印，向五尾王证明自己的勇气与武技。',1837),
  (313,2,'[城镇任务]挑战魔王','五尾王的封印已经被打破，准备好就直接挑战五尾王吧！',1838),
  (314,1,'[城镇任务]家和万事兴','帮阿乐问一下君君要怎么样才能原谅阿乐。',1840),
  (314,2,'[城镇任务]家和万事兴','搜集10个冰魂谷的巨狼身上的狼金铃给君君',1841),
  (314,3,'[城镇任务]家和万事兴','君君已经愿意原谅阿乐了，快回去通知阿乐吧。',1842),
  (315,1,'[城镇任务]神药无敌','帮小九在九天冰屋内寻找薛神医，配制可以治疗小九父亲的灵药。',1844),
  (315,2,'[城镇任务]神药无敌','薛神医需要30个天山草菇，这种草菇只会生长在「深谷长牙象」身上。',1845),
  (315,3,'[城镇任务]神药无敌','薛神医已经派人把药送给小九了，快回去看看状况吧！',1846),
  (316,1,'[城镇任务]爱妻便当','帮盈盈在这九天冰屋内找到冲哥，转送给他爱妻便当吧。',1848),
  (316,2,'[城镇任务]爱妻便当','冲哥很开心（？）的吃完便当，真是太好了，快回去告诉盈盈这件事吧。',1849),
  (317,1,'[城镇任务]救命灵药','到妲己神殿帮小虎取得15个灵狐之气回来。',1851),
  (318,1,'[取神任务]黄天化的银锤','黄天化请你走一趟在九黎平原上的哪咤庙，跟哪咤取回他的银锤',1853),
  (318,2,'[取神任务]黄天化的银锤','邓婵玉要你去土行孙的庙里叫他写封正式的道歉信过来才要把银锤给你',1854),
  (318,3,'[取神任务]黄天化的银锤','你拿到银锤了，回去跟黄天化交差吧',1855),
  (318,4,'[取神任务]黄天化的银锤','你拿到土行孙的信了，这就立刻回去拿给邓婵玉那大小姐吧',1856),
  (318,5,'[取神任务]黄天化的银锤','哪咤拗不过你，告诉你银锤在邓婵玉那，看来得要上她的庙一趟了',1857),
  (319,1,'[取神任务]赵公明的针炙学','赵公明给了三根针给你，先问问他这是要做啥用的好了',1859),
  (319,2,'[取神任务]赵公明的针炙学','赵公明教了几个穴位的概念，第一个穴位是迎香穴，此穴位是用来减轻肩膀酸痛的。第二个是天柱穴，天柱穴位是用来疏经活络，可减轻头痛等问题。第三个是风池穴，多用来治疗晕眩等症状。第四个是肩井穴，是用来治疗手腕筋肉疼痛的穴位.。第五个是人中穴，可用来治疗小腿抽筋。第六个是神阙穴，可治疗便秘等症状。同时赵公明要你去南原冰穴治疗三名九尾国信徒。分别为陈羽、赖肯和杨鹏。',1860),
  (319,3,'[取神任务]赵公明的针炙学','看来是扎错针了，回去跟赵公明问问怎么办吧',1861),
  (320,1,'[取神任务]姜子牙的诗谜','姜子牙给了你一张诗谜，要你解开诗谜并取回一个物品',1863),
  (320,2,'[取神任务]姜子牙的诗谜','你已取得姜子牙所说的东西了，回去找他吧',1864),
  (321,1,'[取神任务]申公豹的计谋','申公豹要你走一趟昆仑仙界找金光圣母和普贤真人拿些东西回来交差',1866),
  (321,2,'[取神任务]申公豹的计谋','普贤真人要你先去一趟枫华镇找董古拿回之前仙童由田清郎手中拿到并卖给董古的玉鼎才肯给你寻宝器',1867),
  (321,3,'[取神任务]申公豹的计谋','你取得普贤的寻宝器了，剩下金光圣母了',1868),
  (321,4,'[取神任务]申公豹的计谋','你取得金光圣母的娃娃了，去找普贤吧',1869),
  (322,1,'[神仙任务]黄天化的孝心','黄天化想替父亲做一个靠腰枕，目前需要的材料有十张狼皮和十份毛小球的毛鬃，这东西在冰魂谷外可以找到',1871),
  (322,2,'[神仙任务]黄天化的孝心','在经历了魔家四将的偷袭后，黄天化决定还是先把东西送去给父亲黄飞虎再说吧',1872),
  (322,3,'[神仙任务]黄天化的孝心','东西总算交给黄飞虎了，不过黄天化似乎还是有心事的样子',1873),
  (323,1,'[神仙任务]黑虎','赵公明要你立刻跟他去找一趟在九尾国境内神仙庙内的姜子牙木像',1875),
  (323,2,'[神仙任务]黑虎','赵公明要你去准备一根破烂的绳子和神秘红布，这东西在冰魂谷的狼人队长和狼人头目身上可以拿到',1876),
  (323,3,'[神仙任务]黑虎','趟公明将补兽夹交给了你，再去找那头黑虎吧',1877),
  (323,4,'[神仙任务]黑虎','这黑虎十分狡猾，看来不是那么好对付，先问问赵公明有什么看法吧',1878),
  (323,5,'[神仙任务]黑虎','姜子牙表示在冰狼湖一带有一头黑虎，希望你去解决掉牠',1879),
  (323,6,'[神仙任务]黑虎','你完成任务了，没想到那头黑虎跟赵公明还有些渊源，先问看看赵公明吧',1880),
  (323,7,'[神仙任务]黑虎','你成功解决黑虎了，去找姜子牙一趟吧',1881),
  (324,1,'[神仙任务]阴谋','姜子牙感应到昆仑仙界的杨任有事相邀，请你就走一趟仙界吧',1883),
  (324,2,'[神仙任务]阴谋','有关宝物问普贤就对了，走一趟隔壁的仙道密室问问普贤吧',1884),
  (324,3,'[神仙任务]阴谋','杨任给了你一根棍棒，看起来似乎不是凡物，先问问姜子牙有什么看法',1885),
  (324,4,'[神仙任务]阴谋','普贤要你去北方找来五个长毛象的骨头和五个三足草的皮草才能分析这棍棒',1886),
  (324,5,'[神仙任务]阴谋','普贤在分析完后表示此物是次级仙物，或许你可以去北方的冰魂谷内噬狼穴找找线索',1887),
  (324,6,'[神仙任务]阴谋','终于阻止了吕岳的计谋，看看姜子牙对此事有什么想法吧',1888),
  (325,1,'[神仙任务]申公豹的复仇','申公豹威胁你做一件事，就是将神针插在枫华镇上姜子牙庙附近的土上',1890),
  (325,2,'[神仙任务]申公豹的复仇','你把针插上了，问看看申公豹还想怎样吧',1891),
  (325,3,'[神仙任务]申公豹的复仇','申公豹给了你一个骷髅头，要你拿去埋在九天冰屋的姜子牙庙附近',1892),
  (325,4,'[神仙任务]申公豹的复仇','申公豹给了你一个纸人符，要你立刻动身前往极光台一趟',1893),
  (325,5,'[神仙任务]申公豹的复仇','申公豹要你在极光台这拿出纸人符并在其上扎上七七四十九针',1894),
  (325,6,'[神仙任务]申公豹的复仇','你把东西埋了，问看看申公豹还想怎样吧',1895),
  (326,1,'[城镇任务]娶个老婆好过年','张洋委托你帮忙他完成承接自元兰的工作',1897),
  (326,2,'[城镇任务]娶个老婆好过年','张洋委托你帮忙他完成承接自张豪的工作',1898),
  (326,3,'[城镇任务]娶个老婆好过年','张洋委托你帮忙他完成承接自陈伟的工作',1899),
  (327,1,'[主线任务] 九黎的警讯','果城的九黎主教受到攻击了！ 请尽速前往救援。',1901),
  (327,2,'[主线任务] 九黎的警讯','向 果城村民-农夫慕容星 询问看看有没有什么特殊的地方。',1902),
  (327,3,'[主线任务] 九黎的警讯','仙霞童子传讯过来了 - 打开仙霞符吧',1903),
  (328,1,'[主线任务] 神秘的灰衣人','城外 (127/327) 有位灰衣人… 听村民形容好像会隐形…',1905),
  (328,2,'[主线任务] 神秘的灰衣人','妲己神殿的狐狸带有神奇的力量。需要收集30个灵狐之气才能完成联络用卡片，先去处理这件事情吧。',1906),
  (328,3,'[主线任务] 神秘的灰衣人','灰衣人传送消息，翻开神秘卡片看看吧',1907),
  (329,1,'[主线任务] 九尾的警告','皇狼穴 狼王奈特 卡片上面的提示代表现在狼王正在受到攻击吗!?',1909),
  (329,2,'[主线任务] 九尾的警告','蛇族的牙齿带有剧毒，搭配上封印就可以完全封印七尾王，需要收集30个蛇牙才足够。',1910),
  (329,3,'[主线任务] 九尾的警告','灰衣人传送消息，翻开神秘卡片看看吧',1911),
  (330,1,'[主线任务] 再见蛇族女王','好像不希望你休息的样子… 卡片显示蛇族受到攻击，向蛇族女王询问看看吧。',1913),
  (330,2,'[主线任务] 再见蛇族女王','天君打过来了!?  蛇族女王的房间外 (283/80) 有动静…去探查看看吧。',1914),
  (330,3,'[主线任务] 再见蛇族女王','神秘卡片把你传送到青采聚落 (88/58) 这是怎么一回事！？',1915),
  (330,4,'[主线任务] 再见蛇族女王','灰衣人传送消息，翻开神秘卡片看看吧',1916),
  (331,1,'[主线任务] 灰衣人的真面目','灰衣人到底是谁? 难道不是仙霞童子派来协助的人吗? 看来… 要向仙霞童子询问一下了。',1918),
  (331,2,'[主线任务] 灰衣人的真面目','万刃车阵位于蚩尤神殿3F，把躲藏在里面的彭遵击倒吧。',1919),
  (331,3,'[主线任务] 灰衣人的真面目','仙霞童子传讯过来了 - 打开仙霞符吧',1920),
  (332,1,'[主线任务] 再战罗侯','彭遵躲藏在万刃车阵内 (40/167)，打到他结束一切吧。',1922),
  (332,2,'[主线任务] 再战罗侯','仙霞童子传讯过来了 - 打开仙霞符吧',1923),
  (333,1,'[主线任务] 封神转生','虽然打倒彭遵但却被其他人救走…回去跟仙霞童子报告吧。',1925),
  (333,2,'[主线任务] 封神转生','当你能力足够的时候，就可以到葛城洞府神像进行转生。',1926),
  (333,3,'[主线任务] 封神转生','仙霞童子传讯过来了 - 打开仙霞符吧',1927),
  (334,1,'[取神任务] 妲己的回忆','对于想要取得妲己神灵的你，提出了一点小要求。妲己神殿的小房间内有个物品去拿回来给妲己。',1929),
  (334,2,'[取神任务] 妲己的回忆','这妲己说的东西吗？看起来只是个不知名的饰品，拿回去给妲己看看吧。',1930),
  (334,3,'[取神任务] 妲己的回忆','妲己请你找回第二样东西，这次在钟乳石迷宫4F深处(34/36)。当初遇到入魔妲己的地方。',1931),
  (334,4,'[取神任务] 妲己的回忆','找到一个不知名的长针，拿回去给妲己鉴定看看是否为妲己需要的物品。',1932),
  (334,5,'[取神任务] 妲己的回忆','妲己要求将两样物品合而为一，不过这两样物品无法直接合成。先问看看胡喜媚有没有办法。',1933),
  (334,6,'[取神任务] 妲己的回忆','胡喜媚好像对于那两样物品很熟识，不过却不会修理。那这次去找王贵人问看看好了',1934),
  (334,7,'[取神任务] 妲己的回忆','王贵人说只要在妲己神殿收集三十个灵狐之气，便能修复物品。看起来那样东西是某个人送给妲己的礼物。',1935),
  (334,8,'[取神任务] 妲己的回忆','原来两样物品是一个发饰，这样就算完成任务了。赶快把发饰拿给妲己完成委托。',1936),
  (335,1,'[取神任务] 王贵人的需求','王贵人提出需要古老的琴谱，想到古老的东西…挖宝三人组应该会知道一些事情才对，听说吴娃为了挖宝特地跑到樵云关内，问问看她有什么收获吧',1938),
  (335,2,'[取神任务] 王贵人的需求','吴娃没有古老琴谱的消息，那就去 南原冰穴 /c9( 130/135 )/c3 问看看董古有没有古老琴谱吧。',1939),
  (335,3,'[取神任务] 王贵人的需求','你花点小钱取得了王贵人想要的琴谱，回去拿给王贵人吧。',1940),
  (336,1,'[取神任务] 饥饿的胡喜媚','第一次见到想要吃自己的神仙，就算要完成考验也不能献上自己吧。枫华镇有个美食家，问问看最近有没有什么新奇美食。',1942),
  (336,2,'[取神任务] 饥饿的胡喜媚','美食菜单记载需要 20个蛇牙、30个蛇鳞 和 10个蛇胆 方可做出料理，岚壁迷穴是蛇族的聚集地，看要来要去那边收集食材',1943),
  (336,3,'[取神任务] 饥饿的胡喜媚','美食做好了，拿去给胡喜媚品尝吧。',1944),
  (337,1,'[神仙任务] 妲己的回忆 II','妲己感应到九天冰屋2F /c3( 187/119 )/c9有人需要帮助，去调查看看。',1946),
  (337,2,'[神仙任务] 妲己的回忆 II','妲己想要和你商量一下关于这件事情',1947),
  (337,3,'[神仙任务] 妲己的回忆 II','去极光台 /c3( 296/97 )/c9 消灭未知妖怪，为民除害。',1948),
  (337,4,'[神仙任务] 妲己的回忆 II','去极光台 /c3( 296/97 )/c9 找看看是否有掉落的东西',1949),
  (337,5,'[神仙任务] 妲己的回忆 II','回去问问看九天冰屋2F /c3( 187/119 )/c9的无名幽魂，认不认得这个物品',1950),
  (337,6,'[神仙任务] 妲己的回忆 II','樵云关外 /c3( 136/371 )/c9 有一个伤心的女子，拿着这个玉佩去问问看她是否认识。',1951),
  (338,1,'[神仙任务] 王贵人的需求 II','王贵人又想要古老的琴谱了，去问问南原冰穴 /c3( 130/135 )/c9的董古还有没有吧。',1953),
  (338,2,'[神仙任务] 王贵人的需求 II','董古提出要求，除非能将非常古老的琴谱还原才有可能给予将其给予你。跟王贵人商量看看吧。',1954),
  (338,3,'[神仙任务] 王贵人的需求 II','制作还原药水需要收集30个灵狐之气，向妲己神殿出发吧。',1955),
  (338,4,'[神仙任务] 王贵人的需求 II','王贵人将还原药水做好了，拿去给南原冰穴的董古看看吧',1956),
  (338,5,'[神仙任务] 王贵人的需求 II','琴谱是修好了但是发现有缺页，再问问王贵人该怎么办才好。',1957),
  (338,6,'[神仙任务] 王贵人的需求 II','董古好像少说了些话，去问问他非常古老的琴谱是否本身就有残缺',1958),
  (338,7,'[神仙任务] 王贵人的需求 II','董古嫌你麻烦丢了一本琴谱给你，拿去给看看王贵人喜不喜欢吧。',1959),
  (339,1,'[神仙任务] 胡喜媚的另一面','胡喜媚这次要挟你要帮她找到新奇有趣的美食，目前毫无头绪，去问问看妲己和王贵人看看他们家的小妹喜欢什么好了',1961),
  (339,2,'[神仙任务] 胡喜媚的另一面','询问过妲己与王贵人，感觉胡喜媚好像保留了什么话没说，再问一次看看好了。',1962),
  (339,3,'[神仙任务] 胡喜媚的另一面','原来这次不是想要吃东西，谯云关外 /c3( 136/371 )/c9有特殊的气息… 那就前往调查吧。',1963),
  (339,4,'[神仙任务] 胡喜媚的另一面','特殊的气息原来是个伤心的女子，她好像在找某个人…问看看胡喜媚有没有办法。',1964),
  (339,5,'[神仙任务] 胡喜媚的另一面','九尾族的问题就是要问专家，去询问妲己有没有相关消息。',1965),
  (339,6,'[神仙任务] 胡喜媚的另一面','感觉妲己所说的不是个好消息，先去极光台/c3( 296/97 )/c9调查看看吧。',1966),
  (339,7,'[神仙任务] 胡喜媚的另一面','胡喜媚要你跟她谈一下，看来她也想到结局应该是…',1967),
  (339,8,'[神仙任务] 胡喜媚的另一面','胡喜媚要你去谯云关外 /c3( 136/371 )/c9跟伤心的女子说，她想找的人已经凶多吉少的消息。',1968),
  (339,9,'[神仙任务] 胡喜媚的另一面','这样算是完成任务了…吧… 跟胡喜媚报告吧…',1969),
  (340,1,'[神仙任务]等级上限提升','拿着晋级徽章，进入妲己神殿，寻找勇气的真谛、智慧的表征与力量的极至，通过三者的考验得到凭证。',1971),
  (340,2,'[神仙任务]等级上限提升','任务所需物品已经凑齐了，快回去找战斗仙人吧。',1972),
  (341,1,'[主线任务] 妲己的忧虑','妲己感受到不详的气息，想请仙童到妲己神殿一趟，有事委托调查。',1974),
  (341,2,'[主线任务] 妲己的忧虑','妲己感应到整个冰霜高地围绕着一股不祥力量。首先调查：/c3谯云关/c9寻宝三人组 - 吴娃，她手上的道具应该能查出一些讯息。',1975),
  (342,1,'[主线任务] 危机的征兆','吴娃给予的「探查针」会对异物起反应，四处找寻看看是否有所异常',1977),
  (342,2,'[主线任务] 危机的征兆','找到一个令旗，还有其他反应',1978),
  (342,3,'[主线任务] 危机的征兆','找到二个令旗，还有其他反应',1979),
  (342,4,'[主线任务] 危机的征兆','找到第三个令旗，似乎还剩下两个反应',1980),
  (342,5,'[主线任务] 危机的征兆','找到第四个令旗，剩下最后一个反应',1981),
  (342,6,'[主线任务] 危机的征兆','找到最后一个令旗，回去找吴娃归还「探查针」',1982),
  (342,7,'[主线任务] 危机的征兆','五色令旗破损，吴娃建议回去神殿找妲己，判断五色令旗的功用',1983),
  (343,1,'[主线任务] 消灭六尾','狼王奈特也担心六尾王就是所谓的阵法道具，拿着「狼王信印」去/c3傲狼穴找「封印守卫」(48/53)/c9询问看看。',1985),
  (343,2,'[主线任务] 消灭六尾','妲己似乎有事相谈，透过神灵分身问看看好了。',1986),
  (343,3,'[主线任务] 消灭六尾','妲己建议向狼、蛇两族提出警讯，那先去比较近的狼族…向狼王奈特询问六尾王的封印状况。',1987),
  (344,1,'[主线任务] 生命的价值','妲己说蛇族发现了极有可能是阵法道具的物品，但似乎是有什么隐情，使蛇族女王不愿破坏那个物品，看来有必要亲自走一趟。',1989),
  (344,2,'[主线任务] 生命的价值','蛇族女王不忍心伤害这未诞生的生命，却也担心这蛋会让更多的子民陷入危机，想请仙童将蛋孵化后，再来讨论如何除去幼兽体内的邪恶之力。',1990),
  (344,3,'[主线任务] 生命的价值','妲己似乎有事相谈，透过神灵分身问看看好了。',1991),
  (344,4,'[主线任务] 生命的价值','之前令旗因为破损无法详细调查，现在终于有线索了。将「邪恶幼兽」带去给妲己神殿的妲己看看吧。',1992),
  (344,5,'[主线任务] 生命的价值','妲己成功解除幼兽体内的邪恶，也发现阵法范围远比想象的大…破解方法还在构思，在那之前就将幼兽交还给蛇族女王。',1993),
  (344,6,'[主线任务] 生命的价值','妲己似乎有事相谈，透过神灵分身问看看好了。',1994),
  (344,7,'[主线任务] 生命的价值','回去找蛇族女王看看。',1995),
  (345,1,'[主线任务] 破邪显正','妲己想要制作法宝放置在特定位置阻挠阵法运作，收集/c3「青龙爪」、「白虎牙」、「朱雀羽」、「玄武甲」各5个/c9，再去找妲己制作法宝',1997),
  (345,2,'[主线任务] 破邪显正','冰霜高地有两个瞭望台/c3 (436，309)、(203，85)/c9到台顶安置宝珠即可，但必须在安置好一个宝珠后，6分钟内再安置好另外一个宝珠，不然宝珠会失去效用。',1998),
  (345,3,'[主线任务] 破邪显正','安置好一个宝珠时间有限，赶紧去下个瞭望台吧。',1999),
  (345,4,'[主线任务] 破邪显正','赶在时间内安置好两个宝珠了，瞭望台下面好像有骚动，下去调查看看。',2000),
  (345,5,'[主线任务] 破邪显正','妲己似乎有事相谈，透过神灵分身问看看好了。',2001),
  (346,1,'[主线任务] 寒羽荒原','阵法的源头查出来了，妲己要仙童前往寒羽荒原调查，与九黎平原的卫兵(92/242)交谈，就会让你过去。',2003),
  (346,2,'[主线任务] 寒羽荒原','妲己似乎有事相谈，透过神灵分身问看看好了',2004),
  (346,3,'[主线任务] 寒羽荒原','寒羽荒原上好像有个上古石阵，那应该就是源头了吧，前往调查看看。',2005),
  (346,4,'[主线任务] 寒羽荒原','妲己似乎有事相谈，透过神灵分身问看看好了。',2006),
  (346,5,'[主线任务] 寒羽荒原','虽然打到了敌人但是阵法依然存在，妲己建议去甘城询问，将军-方守正 (145 ，71)近期内是否有消息。',2007),
  (347,1,'[主线任务] 地底迷宫','城外的地底迷宫(63，432) ，凡是进去过的人们渐渐的变邪恶。难道…阵法的源头在哪里？',2009),
  (347,2,'[主线任务] 地底迷宫','邪恶的气息充斥整个迷宫，到2F去查看',2010),
  (347,3,'[主线任务] 地底迷宫','这一层没有彭遵的气息，到3F查看',2011),
  (347,4,'[主线任务] 地底迷宫','感应到些微彭遵的气息，到4F查看',2012),
  (347,5,'[主线任务] 地底迷宫','彭遵的气息…应该就在5F，快去吧',2013),
  (347,6,'[主线任务] 地底迷宫','感应到了！彭遵就在( 126，95 )的位置',2014),
  (347,7,'[主线任务] 地底迷宫','妲己似乎有事相谈，透过神灵分身问看看好了',2015),
  (348,1,'[主线任务] 九曲黄河阵','九曲黄河阵的入口在(57，14)，彭遵一定是逃到那里了。会是陷阱吗？不过妲己好像说有帮手…',2017),
  (348,2,'[主线任务] 九曲黄河阵','彭遵位于九曲黄河阵的深处 (47，31)，总觉得有股莫名的压力。根据妲己形容好像超过15分钟就有机会被赶出阵法外…',2018),
  (348,3,'[主线任务] 九曲黄河阵','妲己请你到妲己神殿一趟，她会说明一切。',2019),
  (349,1,'[主线任务] 远方的希望','满足转生条件后。即可到葛城洞府神像进行第七次转生。',2021),
  (350,1,'[城镇任务] 孝子送信','小狗子请你将信送给他母亲李大娘。她在甘城的井旁边。',2023),
  (350,2,'[城镇任务] 孝子送信','李大娘也请你送封信给小狗子',2024),
  (351,1,'[城镇任务] 牛言牛语','牛小僮的牛走失了，但无法得知哪头才是他想找的小明。听说/c3(135，105)/c9有位牛道人会让人听懂牛所说的话，去请他帮忙好了',2026),
  (351,2,'[城镇任务] 牛言牛语','牛道人给的符一张可以听懂牛的话语一次，用完可以在找他拿。牛群在城外/c3(254，320)/c9附近，去找出哪个是小明吧',2027),
  (351,3,'[城镇任务] 牛言牛语','成功找到小明了，快把好消息跟牛小僮说。',2028),
  (352,1,'[城镇任务] 杀手挽歌','你阻止了一场杀戮，向房间内的陆承轩询问看看事情始末',2030),
  (352,2,'[城镇任务] 杀手挽歌','你阻止了一场杀戮，向陆承轩询问看看事情始末',2031),
  (352,3,'[城镇任务] 杀手挽歌','陆承轩请你送丹蔘给另外一栋房子内的养女胡晓菁',2032),
  (352,4,'[城镇任务] 杀手挽歌','胡晓菁有点担心爷爷的情况，请你回去找陆承轩看看他状况如何。',2033),
  (352,5,'[城镇任务] 杀手挽歌','陆承轩最后的愿望，希望你能将这玉佩交给聂萍。',2034),
  (352,6,'[城镇任务] 杀手挽歌','跟胡晓菁说他爷爷希望能好好照顾奶奶…',2035),
  (353,1,'[城镇任务] 失散的亲情','林平想找回失散多年的孩子，听说葛城的李老翁/c3(113，190)/c9好像领养了他们的孩子。',2037),
  (353,2,'[城镇任务] 失散的亲情','那个孩子的确是林家失散多年的小孩，李明正在帮李老翁买药中，快去跟他说这个好消息吧。',2038),
  (353,3,'[城镇任务] 失散的亲情','李明想先好好照顾李老翁，这封家书想请你先拿回去给林平。',2039),
  (354,1,'[转生任务] 抉择','甘城的方正守指出，甘城正受到攻击希望仙童能够前往帮忙，只要释出「甘城令牌」甘城的/c3守卫大将军(122，81)/c9就会了解你的来意。',2041),
  (355,1,'[转生任务] 甘城守卫战','甘城的守卫大将军指出甘城四门皆受到袭击，希望仙童能等待十分钟，再来找守卫大将军。有最新战报就会告诉仙童该前往何处支持。',2043),
  (355,2,'[转生任务] 甘城守卫战','战报出来了，目前东门危急。请前往东门，协助东门守兵长(116，137)抵挡敌人攻击',2044),
  (355,3,'[转生任务] 甘城守卫战','成功守住第一波的攻击了，先回去回报守卫大将军这个好消息。',2045),
  (355,4,'[转生任务] 甘城守卫战','虽然成功守住东门，不过剩下的三门竟然被开始猛攻，守卫大将军必须慎重的下判断决定剩下三门的守卫顺序，请等待五分钟，再来找守卫大将军。',2046),
  (355,5,'[转生任务] 甘城守卫战','守卫大将军决定了，请仙童依照「南」、「北」、「西」的顺序，依序前往帮忙各门的守兵长排除敌人，首先请前往南门，协助南门守兵长(94，146)抵挡敌人攻击。',2047),
  (355,6,'[转生任务] 甘城守卫战','请前往北门，北门守兵长(88，53)就快要撑不下去了。',2048),
  (355,7,'[转生任务] 甘城守卫战','最后剩下西门，赶紧前往吧。西门守兵长(57，119)是最后的了。',2049),
  (355,8,'[转生任务] 甘城守卫战','成功守住甘城，向守卫大将军回报战况。',2050),
  (356,1,'[转生任务] 谁是内奸？','守卫大将军认为有内奸泄露军情，才会让守军措手不及。只要释出「军令文件」就可询问四门守兵长，请携带四份口供回来找守卫大将军。',2052),
  (356,2,'[转生任务] 谁是内奸？','已经取得一份口供，还有三份。',2053),
  (356,3,'[转生任务] 谁是内奸？','已经取得两份口供，还有两份。',2054),
  (356,4,'[转生任务] 谁是内奸？','已经取得三份口供，还有一份。',2055),
  (356,5,'[转生任务] 谁是内奸？','已经取得四份口供，拿去给守门大军看看。',2056),
  (357,1,'[转生任务] 找出内奸！','以下是四份口供内容，只有一份是真话，其他都是说谎。/c3东门守兵长说︰「西门是内贼」/c9，/c6西门守兵长说︰「北门是背叛者」/c9，/c3南门守兵长说︰「我绝对效忠甘城不会背叛」/c9，/c6北门守兵长说︰「我不知道谁是背叛者，但是西门一定会说谎」/c9，请仙童判断出谁是真的内奸，并将他拿下交给守卫大将军。',2058),
  (357,2,'[转生任务] 找出内奸！','成功拿下对方，目前由副队长暂代队长之职，把犯人交回给守卫大将军审问。',2059),
  (357,3,'[转生任务] 找出内奸！','成功拿下内奸了，回去找守卫大将军吧。',2060),
  (358,1,'[转生任务] 潜入搜查','本次主谋是西北方的「刺客联盟」但也无法操控怪物才对，守卫大将军请仙童前往猛兽崖，向/c3刺客连络员(426，51)/c9探听消息。',2062),
  (358,2,'[转生任务] 潜入搜查','看来对方不疑有他，立刻相信仙童是来自甘城的联络员，不过还没探查到消息就被交待事物。持有「能源水晶」前往地底洞窟２楼收集30个「水晶碎片」',2063),
  (358,3,'[转生任务] 潜入搜查','接下来要到地底迷宫５楼/c3深处(122，93)/c9取出控制装置，当初澎遵也是在地底迷宫深处…这之间有什么关联吗？',2064),
  (358,4,'[转生任务] 潜入搜查','经过一场战斗取得了控制装置，看来这是控制魔物的关键，不过没必要交给刺客联盟的人，拿去给/c3方正守(144，138)/c9看看好了。或许这就是他请仙童守卫甘城的原因。',2065),
  (359,1,'[转生任务] 收尾工作','方正守提议利用/c3上古石阵(270，353)/c9的力量破坏「控制装置」虽然不能让怪物消失，但最少「刺客联盟」无法再操控怪物。',2067),
  (359,2,'[转生任务] 收尾工作','经过一番激斗，成功破坏「控制装置」至于还剩下一个「能源水晶」回去问问/c3方正守(144，138)/c9怎么处里好了。',2068),
  (359,3,'[转生任务] 收尾工作','由于仙童的协助了却了甘城的危机，而残留的「能源水晶」也成了追查澎遵的方向，将「能源水晶」交给妲己神殿的妲己吧。',2069),
  (360,1,'[转生任务] 黎明初探','妲己提升了你的主神修炼上限，满足条件后即可到葛城洞府神像进行八转。',2071),
  (361,1,'[转生任务] 黎明曙光','「狐族侍卫」向你传送了一个消息，感应到商受辛(纣王)了，虽然波动很轻微…请先到/c3寒羽荒原(175 90)/c9寻找看看',2073),
  (362,1,'[转生任务] 意外插曲','到了/c3寒羽荒原(175 90)/c9，没有看到商受辛的踪影。却发现遭受攻击的九黎人，九黎人为什么会出现在这里？询问这个「受伤的九黎人」看看。',2075),
  (363,1,'[转生任务] 新九黎机器人','九黎人似乎没有放弃开发九黎机器人的想法，自从听到地底迷宫有装置可以控制怪物后，就开始派人前往调查，并将能源水晶提炼给九黎机器人使用。前往/c3果城(135 140)/c9询问「新开发队长」',2077),
  (364,1,'[转生任务] 探测雷达制作','果然，九黎人又重新制作了新的机器人，外型一样但是威力更强。要阻止九黎人使用这个危险的能源，看来只有使用实力劝退「新开发队长」/c3(果城 135 140)/c9吧。',2079),
  (364,2,'[转生任务] 探测雷达制作','打到了「新九黎机器人」成功让「新开发队长」/c3(果城 135 140)/c9改变了想法此外还愿意帮忙制作「寻人雷达」，但是需求材料很麻烦/c3金、木、水、火、土之精各15个白虎牙、青龙爪、朱雀羽、玄武甲、麒麟角各20个/c9还很说蛇族的洞穴都可以找的到。',2080),
  (365,1,'[转生任务] 搜寻再开','取得「寻人雷达」，打开后发现了两个亮点「/c3岚壁迷穴(300 60)/c9」 、「/c3傲狼穴(88 54)/c9」这个雷达到底有没有问题啊，看来先去岚壁迷穴看看好了。',2082),
  (365,2,'[转生任务] 搜寻再开','到达指定的地方只发现怪物的踪迹，却没有半点人影。那去「/c3傲狼穴(88 54)/c9」也是有可能扑空？只是说是这么说，还是去看看吧。',2083),
  (366,1,'[转生任务] 探索终点？','搜寻了许多位置，却是每每扑空。还与众多怪物打斗，难道商受辛目前是被怪物追杀中？新的探索位置出来了！前往/c3九天冰屋3F(100 175)/c9吧',2085),
  (367,1,'[转生任务] 失控的纣王','商受辛/c3(九天冰屋3F 100 175)/c9的给你的感觉十分奇怪，身上带着一股未知的邪气，希望收集30个灵狐之气压制身上的邪气。',2087),
  (368,1,'[转生任务] 无穷无尽','收集了两种荒魂，没想到蚩尤现身的肉体竟然就是商受辛，一阵激战之下…仙童们受了重伤，如果妲己没将仙童传走后果将不堪设想。将「仙狐锦囊」和「寻人雷达」交给狐族侍卫吧',2089),
  (368,2,'[转生任务] 无穷无尽','透过妲己的力量提升了主神修炼上限，满足条件后即可到葛城洞府神像转生。',2090),
  (369,1,'[成就任务]事前准备很重要','请去收集「蜗牛黏液」60个。九黎半岛上面的「云蜗牛」身上拥有。收集好后交给/c3「收集专用机关人」(九黎半岛310 335)/c9',2092),
  (369,2,'[成就任务]事前准备很重要','请去收集「巨瓢虫卵」60个。九黎半岛上面的火炬虫身上拥有。收集好后交给/c3「收集专用机关人」(九黎半岛310 335)/c9',2093),
  (369,3,'[成就任务]事前准备很重要','请将「压缩包裹」交给「收货专用机关人」(九黎半岛270 60)',2094),
  (369,4,'[成就任务]事前准备很重要','请去收集「蜘蛛毒囊」60个。九黎半岛上面的赤条蜘蛛身上拥有。收集好后交给/c3「收货专用机关人」(九黎半岛270 60)/c9',2095),
  (369,5,'[成就任务]事前准备很重要','等下似乎是场战斗，准备好后再向/c3「收货专用机关人」(九黎半岛270 60)/c9交谈。',2096),
  (369,6,'[成就任务]事前准备很重要','完成任务了，回去向/c3「收集专用机关人」(九黎半岛310 335)/c9报告吧。',2097),
  (370,1,'[成就任务] 持续的努力不懈','收集「蛇牙」、「蛇胆」、「蛇鳞」各30个，请打倒岚壁迷穴的蛇就有机会获得。收集完成后请交给/c3努力向上生菜人(青采聚落60 60)/c9',2099),
  (370,2,'[成就任务] 持续的努力不懈','等下会有场战斗，先准备好再去向/c3努力向上生菜人(青采聚落60 60)/c9挑战吧。',2100),
  (370,3,'[成就任务] 持续的努力不懈','连续耐力测试第一场︰请去找/c3「热血樱桃」(九黎半岛 449 348)/c9',2101),
  (370,4,'[成就任务] 持续的努力不懈','连续耐力测试第二场︰请去找/c3「毅力桃子」(茄城 150 70)/c9',2102),
  (370,5,'[成就任务] 持续的努力不懈','连续耐力测试第三场︰请去找/c3「奋斗萝卜」(果城 150 70)/c9',2103),
  (370,6,'[成就任务] 持续的努力不懈','完成耐力测试︰快回去找/c3「努力向上生菜人」(青采聚落60 60)/c9吧',2104),
  (370,7,'[成就任务] 持续的努力不懈','等下会有场战斗，先准备好再去向/c3努力向上生菜人(青采聚落60 60)/c9挑战吧。',2105),
  (370,8,'[成就任务] 持续的努力不懈','为了奖励你完成所有挑战，请准备10万仙币。就可以向/c3努力向上生菜人(青采聚落60 60)/c9领取你想要的奖励了。',2106),
  (371,1,'[成就任务] 成功的果实','冰霜高地的冻原飞貂身上有这个「飞貂尾巴」道具，请收集60个给传递希望小狐狸(冰霜高地 355 420)。',2108),
  (371,2,'[成就任务] 成功的果实','请去找「训练专用机关人」(冰霜高地 145 365)完成训练吧。',2109),
  (371,3,'[成就任务] 成功的果实','完成训练了，再来找「苦行修练者」(冰霜高地 440 315)继续修练。',2110),
  (371,4,'[成就任务] 成功的果实','完成训练了，回去跟「传递希望小狐狸」(冰霜高地 355 420)说吧。他会告诉你「巨型怪兽」的位置。',2111),
  (371,5,'[成就任务] 成功的果实','「巨型怪兽」在/c3冰霜高地(360 75)/c9，请讨伐他吧。万事拜托了',2112),
  (371,6,'[成就任务] 成功的果实','成功打倒「巨型怪兽」回去跟「传递希望小狐狸」(冰霜高地 355 420)说吧。',2113),
  (372,1,'[每日任务] 炼丹修行一','1',2115),
  (373,1,'[每日任务] 炼丹修行二','1',2117),
  (374,1,'[每日任务] 鲜鱼宴','1',2119),
  (375,1,'[每日任务] 丢失的货物','1',2121),
  (376,1,'[每日任务] 珍奇异宝','1',2123),
  (377,1,'[每日任务] 仙界警戒','1',2125),
  (378,1,'[每日任务] 守墓人','1',2127),
  (379,1,'[每日任务] 盗墓贼反扑','1',2129),
  (380,1,'[每日任务] 仙界警戒II','1',2131),
  (381,1,'[每日任务] 竞技换奖励','1',2133),
  (382,1,'[每日任务] BOSS挑战','1',2135),
  (383,1,'[每日任务] 拯救仙兔','1',2137),
  (384,1,'[每日任务] 省钱之道','1',2139),
  (385,1,'[取神任务] 黄帝的试炼','你接受了黄帝的试炼，那么就先前往/c3「圣樵原野的曲湖(246，402)」/c9调查看看那边的人有没有甚么线索吧。',2141),
  (385,2,'[取神任务] 黄帝的试炼','打赢了在此地作乱的「大湖主」，完成一个试炼了。回去跟黄帝回报消息吧。',2142),
  (385,3,'[取神任务] 黄帝的试炼','第二个试炼是前往/c3「夹龙纵谷(403，469)」/c9探索看看。如果出现吃人怪物的话，打到他就是这次的试炼。',2143),
  (385,4,'[取神任务] 黄帝的试炼','成功打赢大量的小蛟龙了，先回去像黄帝回报吧。',2144),
  (385,5,'[取神任务] 黄帝的试炼','要收集制作「大玄龟诱饵」的材料，才能继续进行试炼。/c3前往太极境收集「海豹头骨 30个」、「牛肉30个」、「蜥蜴的骨头30个」/c9让黄帝制作成「大玄龟诱饵」。',2145),
  (385,6,'[取神任务] 黄帝的试炼','第三个试炼是打到「大玄龟」位置在/c3雨龙森林的鲤鱼岛(581，467)/c9，携带这个「大玄龟诱饵」应该很容易碰到「大玄龟」。如果不小心将「大玄龟诱饵」丢失，只能回去找黄帝重做了。',2146),
  (385,7,'[取神任务] 黄帝的试炼','终于打赢大玄龟了，回去找黄帝报备吧。希望这次是最后的试炼了。',2147),
  (385,8,'[取神任务] 黄帝的试炼','黄帝认同你的实力，也说出了接下来就是最后的试炼了。准备完成后再向黄帝来挑战吧。',2148),
  (385,9,'[取神任务] 黄帝的试炼','恭喜你完成了所有试炼，请先确定身上的神仙空间没有满15个，再向黄帝交谈取神。/c3否则会因神仙空间不足导致取神任务失败。/c9',2149),
  (385,10,'[取神任务] 黄帝的试炼','没有诱饵无法让「大玄龟」出现，回去找黄帝看看，有没有办法重新制作「大玄龟诱饵」。',2150),
  (386,1,'[取神任务] 伏羲的测试','终于是听完唠叨的「伏羲童子」所说的话了，首要目标就是每天找「伏羲童子」领取一本「伏羲之书」。累积十二本后，才会有下个测试。',2152),
  (386,2,'[取神任务] 伏羲的测试','你完成了「伏羲童子」上半部的测试，准备好的话，就再跟「伏羲童子」进行下半部的测试。',2153),
  (386,3,'[取神任务] 伏羲的测试','「伏羲童子」给了你一个锦囊，说是打开后会指示你收集一些东西给他合成。所以先打开「伏羲锦囊」看看接下来的提示吧。',2154),
  (386,4,'[取神任务] 伏羲的测试','根据提示请到「九黎平原」打「弓弩、毒水、重炮机车」收集「南瓜轮胎」30个后，回去找伏羲童子回报。合成成功收集三个「成功的碎片」或是合成失败收集十个「失败的碎片」都可以完成本次的测试。',2155),
  (386,5,'[取神任务] 伏羲的测试','根据提示请到「参天林」打「红顶鹤」收集「红顶鹤的蛋」20个后，回去找伏羲童子回报。合成成功收集三个「成功的碎片」或是合成失败收集十个「失败的碎片」都可以完成本次的测试。',2156),
  (386,6,'[取神任务] 伏羲的测试','根据提示请到「圣樵原野」打「马贼」收集「普通的钱袋」20个，回去找伏羲童子回报。合成成功收集三个「成功的碎片」或是合成失败收集十个「失败的碎片」都可以完成本次的测试。',2157),
  (386,7,'[取神任务] 伏羲的测试','拿到「伏羲童子」给的「伏羲锦囊」打开后可以获得指示，收集相关需求素材后交给「伏羲童子」进行合成。无论成功或是失败，只要收集到一定量就算是完成测试。',2158),
  (386,8,'[取神任务] 伏羲的测试','「伏羲童子」告知你一个消息：合成成功获得「成功的碎片」有三个可以完成测试，合成失败也别担心，有十个「失败的碎片」也可以完成测试。所以再向「伏羲童子」索取新的「伏羲锦囊」吧。',2159),
  (386,9,'[取神任务] 伏羲的测试','「伏羲童子」承认你拥有取得「伏羲神灵」的资格了。但是要注意，如果神仙已满的情况下会造成取神任务失败。请先确认身上神仙空间有空位下，再向「伏羲童子」进行取神。',2160),
  (387,1,'[取神任务] 神农的考验','你接受了「神农童子」的神农取神任务，请先打开「神农锦囊」里面会告诉你指令。收集必要的药材、前往治疗需要的病人，完成后可以获得一个「神农考验纪录卡」。收集完20个就算完成神农的考验。',2162),
  (387,2,'[取神任务] 神农的考验','请打开「神农锦囊」里面会告诉你指令。收集必要的药材、前往治疗需要的病人，完成后可以获得一个「神农考验纪录卡」。收集完20个就算完成神农的考验。',2163),
  (387,3,'[取神任务] 神农的考验','/c3果城有个「伤病萝卜人(131，62)」/c9因为长期病症需要治疗，/c3收集果城外「果城巨花」和「果城树精」的药草和树精的根各30个/c9，交给那个萝卜人就可以了。',2164),
  (387,4,'[取神任务] 神农的考验','/c3昆吾镇有个「腰痛老人(150，61)」/c9长期因为腰部闪到所苦，/c3制作保护腰的护垫需要「雨龙森林」外棕熊和老虎掉落的「熊皮」、「虎皮」各20张/c9，收集完成交给那位老人吧。',2165),
  (387,5,'[取神任务] 神农的考验','/c3暮汐村有个「肥胖男子(55，70)」/c9太胖了需要减肥，/c3直接在夹龙纵谷收集「黑岩树精」的青藤20个和「鸿鹰」的巨鹰羽20个，交给那个肥胖男子。/c9就算完成任务了。',2166),
  (387,6,'[取神任务] 神农的考验','/c3焰霜镇有个「冻伤女子(170，97)/c9因为工作长期需要在寒冷的地方，/c3冻伤的药需要太极境外「蓝星海豹」的海豹须20个、「钢喙鹤」的鹤羽20个、「火山灰泥怪」泥怪的卵10个。/c9收集完成后交给那个女子即可。',2167),
  (387,7,'[取神任务] 神农的考验','/c3九天冰屋2F有个「气闷狐狸(237，74)」/c9长期的空气不流通造成肺部病症，/c3药材是九尾国外「冻原飞貂」的飞貂尾巴50个。/c9，收集完成后交给她就可以了。',2168),
  (387,8,'[取神任务] 神农的考验','恭喜你完成了神农的考验，「神农童子」给予你一个「神农考验证明」，只要再向「神农童子」交谈，即可取得神农神灵。/c3请先确认身上神仙空间有空位，否则会因为无法取神导致任务失败。/c9',2169),
  (387,9,'[取神任务] 神农的考验','你完成了今天的「神农的考验」，请记得明天继续向「神农童子」领取「神农锦囊」。累积满20个「神农考验纪录卡」时，就代表你完成「神农的考验」了。到时可以向「神农童子」回报完成任务。',2170),
  (388,1,'[取神任务] 女娲的考核','你接受了女娲的考验，首先是素材的收集「妲己神殿」的狐族可以打到「灵狐之气」，「圣樵原野」的野狐可以打到「狐尾」，各收集10个后拿来找女娲。',2172),
  (388,2,'[取神任务] 女娲的考核','「灵狐之气」和「狐尾」各10个，可以兑换成「阴石」、「阳石」各一个。将两者进行合成，并收集30个合成成功的「七彩基石」就算是完呈第二阶段的「合成」考验。当然，要收合成到30个「七彩基石」是要重复的进行收集兑换素材。',2173),
  (388,3,'[取神任务] 女娲的考核','完成了合成的考验，接下来是战斗的考核，准备好以后再向女娲交谈。',2174),
  (388,4,'[取神任务] 女娲的考核','成功打倒女娲召唤出来的怪物，下个考核也是战斗测试。请先准备好吧。',2175),
  (388,5,'[取神任务] 女娲的考核','恭喜完成女娲的考核，接下来就是取得女娲的神灵了。请注意，先确认身上有足够的神仙空位可以取得女娲神，否则会造成任务失败。',2176),
  (389,1,'[神仙任务] 黄帝委托','黄帝给予你一个令牌，算是作为接下任务的信物。那么当务之急应该是和「千里眼」与「顺风耳」交谈看看',2178),
  (390,1,'[神仙任务] 黄帝委托-千里眼','你决定协助「千里眼」那么过五分钟后再问问「千里眼」有甚么发现吧。',2180),
  (390,2,'[神仙任务] 黄帝委托-千里眼','「千里眼」发现有受伤的人需要救助。希望先收集「枫木」、「蜜蜂的翅膀」各60个制作成药品。打到雨龙树精；食人蜂就有机会获得。',2181),
  (390,3,'[神仙任务] 黄帝委托-千里眼','「千里眼」制作出「强力治疗药」，要你交给「困扰的胖子」(雨龙森林490，405)这样就完成任务了。',2182),
  (390,4,'[神仙任务] 黄帝委托-千里眼','这下糟糕了，没有想到因为体质关系，「强力治疗药」反而弄巧成拙，先赶快回去问问「千里眼」该怎么办。',2183),
  (390,5,'[神仙任务] 黄帝委托-千里眼','这下「千里眼」也不知道该怎么办了，赶快前往「伏羲神农庙」询问「神农木像」看看神农有没有办法解决这个事情。',2184),
  (390,6,'[神仙任务] 黄帝委托-千里眼','被神农数落的一顿，这下子变成要长期治疗才可以医治好「困扰的胖子」了。问看看神农要收集什么东西吧。',2185),
  (390,7,'[神仙任务] 黄帝委托-千里眼','「冬虫夏草」九黎半岛的「大蝴蝶」会掉落，「药草」九黎平原的「果城巨花」会掉落，「红花蝶的卵」参天林的「红花蝶」会掉落。各收集30个以后，拿去给「神农木像」制作药品。',2186),
  (390,8,'[神仙任务] 黄帝委托-千里眼','「良性治疗药」做好了，先拿去给「困扰的胖子(雨龙森林 490，405)」服用吧。',2187),
  (390,9,'[神仙任务] 黄帝委托-千里眼','看样子这次有好一点，但是没有完全治好。这份「治疗记录单」等隔日服务器开机后再拿给「神农木像」确认吧。',2188),
  (390,10,'[神仙任务] 黄帝委托-千里眼','总算是治疗好了，不过为了保险起见。这份「治疗记录单」等隔日服务器重开机后再拿给「神农木像」确认吧。',2189),
  (390,11,'[神仙任务] 黄帝委托-千里眼','治疗完成了。赶快回去跟「千里眼」报告吧。',2190),
  (390,12,'[神仙任务] 黄帝委托-千里眼','总算是完成任务了，就向「黄帝木像」报告吧。',2191),
  (391,1,'[神仙任务] 黄帝委托-顺风耳','你决定协助「顺风耳」那么等一下再问问「顺风耳」有甚么发现吧。',2193),
  (391,2,'[神仙任务] 黄帝委托-顺风耳','虽然不知道是怎么听到的，不过先前往雨龙森林(95，520)寻找「虚弱的瘦子」吧',2194),
  (391,3,'[神仙任务] 黄帝委托-顺风耳','的确找到一个脸色苍白的「虚弱的瘦子」先帮他弄20个「疗伤药」吧。',2195),
  (391,4,'[神仙任务] 黄帝委托-顺风耳','嗯，看他服用「疗伤药」后感觉有好一点了，那这就回去跟「顺风耳」说吧。',2196),
  (391,5,'[神仙任务] 黄帝委托-顺风耳','没想到「顺风耳」还是感觉到有异，既然如此只好前往「伏羲神农庙」找「神农木像」询问了。',2197),
  (391,6,'[神仙任务] 黄帝委托-顺风耳','「神农」听过后诊断出原因，那就先去九黎半岛找「大蝴蝶」收集30个「冬虫夏草」吧',2198),
  (391,7,'[神仙任务] 黄帝委托-顺风耳','药品制作好了，拿去给雨龙森林(95，520)的「虚弱的瘦子」吧。',2199),
  (391,8,'[神仙任务] 黄帝委托-顺风耳','这次的症状变得有些气闷，再回去找「神农木像」确认看看。',2200),
  (391,9,'[神仙任务] 黄帝委托-顺风耳','这次为了调养身体，要去九黎平原找「果城巨花」收集30个「药草」',2201),
  (391,10,'[神仙任务] 黄帝委托-顺风耳','药品制作好了，拿去给雨龙森林(95，520)的「虚弱的瘦子」吧。',2202),
  (391,11,'[神仙任务] 黄帝委托-顺风耳','感觉应该都好了，不过脸色还是怪怪的，还是再找「神农木像」确认一下好了。',2203),
  (391,12,'[神仙任务] 黄帝委托-顺风耳','这次为了强化身体，要去参天林找「红花蝶」收集30个「红花蝶的卵」',2204),
  (391,13,'[神仙任务] 黄帝委托-顺风耳','药品制作好了，拿去给雨龙森林(95，520)的「虚弱的瘦子」吧。',2205),
  (391,14,'[神仙任务] 黄帝委托-顺风耳','这样应该就没有问题了，就回去找「顺风耳」报告吧。',2206),
  (391,15,'[神仙任务] 黄帝委托-顺风耳','总算是完成任务了，就向「黄帝木像」报告吧。',2207),
  (392,1,'[神仙任务] 黄帝委托II-千里眼','情况紧急「上古凶兽」突然现身，四处作乱。「黄帝」希望你立刻找「千里眼」一同处理此事。',2209),
  (392,2,'[神仙任务] 黄帝委托II-千里眼','「千里眼」二话不说开始搜索「上古凶兽」的踪迹，先别打扰他。五分钟后再过去询问看看。',2210),
  (392,3,'[神仙任务] 黄帝委托II-千里眼','找到了，但「千里眼」担心移动中的「上古凶兽」可能会在仙童赶到「雨龙森林(130，300)」之前就会跑走，赶快追击吧。',2211),
  (392,4,'[神仙任务] 黄帝委托II-千里眼','「千里眼」对没追到「上古凶兽」好像不太意外，这次要花十分钟细细观察，先别吵他吧。',2212),
  (392,5,'[神仙任务] 黄帝委托II-千里眼','再度发现踪迹，跑去取夹龙纵谷了。根据「千里眼」所说，赶紧去「夹龙纵谷(466，539)」吧。',2213),
  (392,6,'[神仙任务] 黄帝委托II-千里眼','面对如此狡猾的怪物，还真是令「千里眼」伤透脑筋，先让他想个15分钟看看有甚么好方法。',2214),
  (392,7,'[神仙任务] 黄帝委托II-千里眼','没想到「上古凶兽」已经进入到圣樵原野了，这样难保不会有村落受到攻击。「千里眼」在你身上施加了法术，趁这机会前往「圣樵原野(600，635」打到「上古凶兽」',2215),
  (392,8,'[神仙任务] 黄帝委托II-千里眼','「千里眼」能想到的方法都用尽了，这下子只能听从建议，问问「顺风耳」有没有甚么建议了。',2216),
  (392,9,'[神仙任务] 黄帝委托II-千里眼','唉，果然让「上古凶兽」给跑了，赶快回去找「千里眼」说明情况吧。',2217),
  (392,10,'[神仙任务] 黄帝委托II-千里眼','没想到「上古凶兽」如此狡猾，一但被发现就立即跑个没影。没办法，回去再问问「千里眼」该怎么办。',2218),
  (392,11,'[神仙任务] 黄帝委托II-千里眼','打赢了但是「上古凶兽」的尸体却消失了，应该是被逃掉了，回去跟「千里眼」回报。',2219),
  (393,1,'[神仙任务] 黄帝委托II-顺风耳','情况紧急「上古凶兽」突然现身，四处作乱。「黄帝」希望你立刻找「顺风耳」一同处理此事。',2221),
  (393,2,'[神仙任务] 黄帝委托II-顺风耳','「顺风耳」愿意协助你搜寻「上古凶兽」的位置，等一下再过去询问。',2222),
  (393,3,'[神仙任务] 黄帝委托II-顺风耳','虽然「上古凶兽」四处移动，不过「顺风耳」推断出他的动作路径。前往「雨龙森林(85，515)」这个位置守株待兔吧。',2223),
  (393,4,'[神仙任务] 黄帝委托II-顺风耳','「上古凶兽」的位置飘忽不定，等下再问「顺风耳」他会经过的位置，再次挑战。',2224),
  (393,5,'[神仙任务] 黄帝委托II-顺风耳','目前还不清楚「上古凶兽」是怎么逃跑，不过还是先前往「夹龙纵谷(460，565)」等候。',2225),
  (393,6,'[神仙任务] 黄帝委托II-顺风耳','虽然又让「上古凶兽」给逃了，不过「顺风耳」也想到对策，等下再去问问「顺风耳」该去哪里找到「上古凶兽」',2226),
  (393,7,'[神仙任务] 黄帝委托II-顺风耳','「顺风耳」在你身上附加一个法术，虽然有可能会被「上古凶兽」发现，但却可以确保不让他逃跑。前往「圣樵原野(430，600)」拦截「上古凶兽」。',2227),
  (393,8,'[神仙任务] 黄帝委托II-顺风耳','「顺风耳」也惊讶于「上古凶兽」的狡猾，这下只能请教看看「千里眼」能不能想出其他方法。',2228),
  (393,9,'[神仙任务] 黄帝委托II-顺风耳','打赢了，但是尸体化做烟雾消失，回去跟「顺风耳」报告。',2229),
  (393,10,'[神仙任务] 黄帝委托II-顺风耳','没想到「上古凶兽」竟然发现有人埋伏于此就立即逃跑，回去跟「顺风耳」报告。',2230),
  (394,1,'[神仙任务] 黄帝委托II-合作','「千里眼」想了想，只有制作诱饵让「上古凶兽」主动攻击仙童，再打倒他才可以了。回去跟「顺风耳」报告了。',2232),
  (394,2,'[神仙任务] 黄帝委托II-合作','「顺风耳」想了想，只有制作诱饵让「上古凶兽」主动攻击仙童，再打倒他才可以了。回去跟「千里眼」报告了。',2233),
  (394,3,'[神仙任务] 黄帝委托II-合作','统合两方的意见后，结论是制作某种诱饵让「上古凶兽」主动攻击你，制作诱饵需要找「黄帝木像」请求协助。',2234),
  (394,4,'[神仙任务] 黄帝委托II-合作','想要制作「特殊诱饵」就需要特殊的素材，前往「昆仑仙界-天池」进行钓鱼，将「仙鱼LV2」、「仙鱼LV3」交给「黄帝木像」制作。',2235),
  (394,5,'[神仙任务] 黄帝委托II-合作','「特殊诱饵」制作好了，那么接下来就是询问「千里眼」和「顺风耳」看看那个「上古凶兽」目前的位置在哪。',2236),
  (394,6,'[神仙任务] 黄帝委托II-合作','「上古凶兽」目前在「圣樵原野(278，471)」在他造成更多伤害之前，讨伐他。',2237),
  (394,7,'[神仙任务] 黄帝委托II-合作','确定这次是真的打倒「上古凶兽」回去报告好消息吧。',2238),
  (394,8,'[神仙任务] 黄帝委托II-合作','没有「特殊诱饵」不行啊，赶快回去找「黄帝木像」制作一个。',2239),
  (395,1,'[每日任务] 白虎试炼I','1',2241),
  (396,1,'[每日任务] 朱雀试炼I','1',2243),
  (397,1,'[城镇任务]空心菜','姜子牙请你将这个「锦囊妙计」交给「比干(枫华镇83，103)」的目的是？既然已经接受委托，就先去一趟好了。',2245),
  (397,2,'[城镇任务]空心菜','回答「无心还活」；则可保不死。回答「无心即死」，立即毙命。与比干相约「葛城(146，158)」见面回答问题。届时要回答的答案是…',2246),
  (397,3,'[城镇任务]空心菜','由于你的回答，让「比干」成功渡过此劫难，接下来就带着「比干玉佩」交付给「姜子牙(枫华镇64，59)」告知不负期望完成任务。',2247),
  (397,4,'[城镇任务]空心菜','由于你的回答，再加上击败了「比干」看来他是无法渡过此劫难了。不知为何，「卖菜老太婆(葛城147，159)」好像在呼唤你过去。',2248),
  (397,5,'[城镇任务]空心菜','或许注定「比干」命不该绝。不知为何，「卖菜老太婆(葛城147，159)」好像在呼唤你过去。',2249),
  (398,1,'[城镇任务]救公明','你答应了「慈善老人」协助将「老人宠物笼」交给「开天门天将(南原部落136，111)」。但是需要在特定的时间内给予才有效果，请于「游戏时间23：00-01：00(参考右上角小地图标示时间)」将物品交付。',2251),
  (398,2,'[城镇任务]救公明','你看「开天门天将」施法将「老人宠物笼」内的「不吠叫黑狗、不生蛋母鸡」变化为「银锭黑狗、金蛋母鸡」并将他们重新装在「天将宠物笼」内。快将这两个宝物交还给「慈善老人(南原部落106，87)」吧。',2252),
  (398,3,'[城镇任务]救公明','开天门天将委托你使用「替身符咒」依照顺序保护：「金匠(南原部落81，101)」、「银匠(南原部落92，111)」、「慈善老人(南原部落106，87)」获得三种「安全证」后回去找「开天门天将(南原部落136，111)」回报。',2253),
  (398,4,'[城镇任务]救公明','成功保护「金匠」了，接下来去找「银匠(南原部落92，111)」',2254),
  (398,5,'[城镇任务]救公明','成功保护「银匠」了，接下来去找「慈善老人(南原部落106，87)」',2255),
  (398,6,'[城镇任务]救公明','这么一来三个需要保护的对象都已经确认完毕，回去「开天门天将(南原部落136，111)」那边回报消息。',2256),
  (398,7,'[城镇任务]救公明','你决定参加「抢匪头领」的打劫计划，依序前往打劫「金匠(南原部落81，101)」、「银匠(南原部落92，111)」、「慈善老人(南原部落106，87)」将获得的东西拿「抢匪头领(南原部落 99/119)」，就能分到好东西了。',2257),
  (398,8,'[城镇任务]救公明','你从「金匠」的手中打劫了「一袋金蛋」。根据「抢匪头领」所叙述，再来是找「银匠(南原部落92，111)」',2258),
  (398,9,'[城镇任务]救公明','「银匠」自己缴纳了「一袋银锭」给你，就连超大钱袋都半满了。最后去找「慈善老人(南原部落106，87)」吧。',2259),
  (398,10,'[城镇任务]救公明','大功告成「超大钱袋」也都装满了财宝，回去找「抢匪头领(南原部落99，119)」分赃。',2260),
  (398,11,'[城镇任务]救公明','成功将装有「银锭黑狗、金蛋母鸡」的「天将宠物笼」交给老人，老人再度请你将「谢公明卡」交给「开天门天将(南原部落136，111)」告知，已经确实收到物品。',2261),
  (398,12,'[城镇任务]救公明','没有想到竟然有神仙帮忙，这下失手了。回去找「抢匪头领(南原部落99，119)」报告吧。',2262),
  (399,1,'[城镇任务]战公明','「赵公明」十分坚持己见，看来继续下去连自己都会有危险。先去「昆仑仙界(68，149)」找「陆压道人」商讨看看有没有其他方法能说服「赵公明」。不过要证明「赵公明」的危险性，要保持自己血量低于90%',2264),
  (399,2,'[城镇任务]战公明','取得法宝「斩魂法」接下来打倒「赵公明(妲己神殿167，275」将他封神即可。但是「陆压道人」也有提出，不希望仙童造杀孽，那么到时候的选择应该是？',2265),
  (399,3,'[城镇任务]战公明','虽然说服了「赵公明」但是双方都了解这只是暂时的，不过也算是完成了任务。回去找「陆压道人(昆仑仙界68，149)」报告情况吧。',2266),
  (399,4,'[城镇任务]战公明','既然决定要打倒「赵公明」看来是要连番恶战了。',2267),
  (399,5,'[城镇任务]战公明','成功阻止「赵公明」只是，自己也真如他所说，多造杀孽…回去找「陆压道人(昆仑仙界68，149)」报告情况吧。',2268),
  (399,6,'[城镇任务]战公明','虽然夸口说要打倒「赵公明」却反被击倒，回去找「陆压道人(昆仑仙界68，149)」报告情况吧。',2269),
  (400,1,'[神器搜寻任务] 打神鞭','因缘际会之下获得「姜子牙的委托」得知姜子牙成名法宝「打神鞭」流落到人间不知所踪。姜子牙提及寻回的过程凶险甚多，需要多加注意。事不宜迟，就先问问身为仙人同时擅长寻宝的「普贤真人(九黎平原-九黎工房外)」吧。',2271),
  (400,2,'[神器搜寻任务] 打神鞭','「请人帮忙就要先帮忙人」这句话好像哪边怪怪的。不过既然有求于人，帮对方个忙也算合情合理。前往「寒羽荒原-猛兽崖(429，54)」击败守护宝物的怪物吧。',2272),
  (400,3,'[神器搜寻任务] 打神鞭','获得一个宝箱，细看了一下上面写着「普贤真人拥有，非请勿开」几个字。这根本是普贤真人自己藏到忘掉的东西嘛。拿回去给「普贤真人(九黎平原-九黎工房外)」交差吧。',2273),
  (400,4,'[神器搜寻任务] 打神鞭','「击败镇守钥匙的怪物」。姜子牙提及到此任务凶险甚多还真的没说错，这次是潜入「寒羽荒园」内的「地底迷宫五楼(112，5)」击败镇守钥匙的怪物。',2274),
  (400,5,'[神器搜寻任务] 打神鞭','费了一番功夫获得钥匙，果不其然上面写着「普贤真人拥有，非请勿用」拿回去给「普贤真人(九黎平原-九黎工房外)」交差吧。',2275),
  (400,6,'[神器搜寻任务] 打神鞭','「普贤真人(九黎平原-九黎工房外)」解释，法宝的制造是由吸收天地精华的物品炼制，法宝消逝也是回归于天地之间。既然如此重新锻造相同的法宝即可，宝箱内放有法宝雏型，先收集金、木、水、火、土之精各三十个，让其吸收天地精华。但是，好像哪边怪怪的。',2276),
  (400,7,'[神器搜寻任务] 打神鞭','再来收集各三十个的青龙爪、白虎牙、朱雀羽、玄武甲、麒麟角。锻炼其根骨，准备好物品就拿去交给「普贤真人(九黎平原-九黎工房外)」吧。',2277),
  (400,8,'[神器搜寻任务] 打神鞭','最后再为其注入灵魂，请准备「武器灵魂」20个；「武器灵魂LV2」10个，「普贤真人(九黎平原-九黎工房外)」正在等你。',2278),
  (400,9,'[神器搜寻任务] 打神鞭','吸收天地精华、锻炼法宝根骨、注入武器灵魂，似乎还是不太够。普贤真人建议你前往「九尾国-冰霜高地-百叶林内」打倒「精元凝聚体」',2279),
  (400,10,'[神器搜寻任务] 打神鞭','成功击倒「精元凝聚体」的你也感觉法宝散发出华光，拿去给「普贤真人(九黎平原-九黎工房外)」看看吧。',2280),
  (400,11,'[神器搜寻任务] 打神鞭','嗯？「属于我的打神鞭」？不是「姜子牙的打神鞭」？，再问一次「普贤真人(九黎平原-九黎工房外)」吧。',2281),
  (400,12,'[神器搜寻任务] 打神鞭','这下糟糕了，普贤真人从头到尾误会一场。这并不是「姜子牙的打神鞭」，不过也没其他方法了，只好将它交给「姜尚(雨龙森林-望潮台828，407))」看看怎么处理吧。',2282),
  (401,1,'[神器搜寻任务] 法力灌注','姜子牙似乎并不介意没有寻回「姜子牙的打神鞭」，还愿意协助灌注法力到「失去法力的打神鞭」内。需要取得打倒「梅山七怪」后取得的「收怪令」给予「姜尚(雨龙森林-望潮台828，407))」来灌注法力。关于各个「收怪令」的获得方法到「昆仑仙界(67，110)」看看说不定有些消息。',2284),
  (401,2,'[神器搜寻任务] 法力灌注','每日可找「姜尚(雨龙森林-望潮台828，407))」领取一个「无限法力石」。从「梅山七怪」获得「收怪令」可灌一点法力，从「魔家四将」获得「除魔令」可灌两点法力，「千年三妖」获得「斩妖令」可灌四点法力。一日只能灌注一次，总共要八十点法力才能灌注完成。关于各个令旗的获得方法到「昆仑仙界(67，110)」看看说不定有些消息。',2285),
  (401,3,'[神器搜寻任务] 法力灌注','恩，经过多日的法力灌注，「失去法力的打神鞭」如经也充满了法力，请将他交给「姜尚(雨龙森林-望潮台828，407))」进行转化吧。',2286),
  (402,1,'[城镇任务] 忠犬小金与小奇','除了走失的小金和小奇，还有其他动物需要喂食。老人在慌乱之下竟然忘了准备食物，请先收集「半筋肉」、「大腿肉」、「黄金米粒」、「五色谷粒」各三十个协助老人准备喂食用的饲料。',2288),
  (402,2,'[城镇任务] 忠犬小金与小奇','协助「和蔼的老人」喂食宠物后，得知「小奇喜欢肉食」、「小金喜欢谷物」、「小奇比较贪吃」等几个线索。经过多日想必他们一定肚子饿了，携带「五花肉」三十个，或是「杂粮」三十个前往「冰霜高地(186，153)」应该可以吸引到走失的「小奇」或是「小金」吧。',2289),
  (402,3,'[城镇任务] 忠犬小金与小奇','身上带着「五花肉」还真的有吸引到…怪物。不过好像获得某个奇怪东西，带回去找「和蔼的老人(九天冰屋1F58，87)」看看，说不定老人知道这是甚么东西。',2290),
  (402,4,'[城镇任务] 忠犬小金与小奇','身上带着「杂粮」还真的有吸引到…怪物。不过好像获得某个奇怪东西，带回去找「和蔼的老人(九天冰屋1F58，87)」看看，说不定老人知道这是甚么东西。',2291),
  (402,5,'[城镇任务] 忠犬小金与小奇','看着「和蔼的老人」颤抖的双手，得知这其实是走失的小家伙项圈的一部分，不过放弃还太早。老人告知有位「古怪的家伙(谯云关139，100)」可透过穿戴的物品来找寻其主人位置，却因为太古怪所以无人能得到他的协助。去试看看能不能获得他的帮助吧。',2292),
  (402,6,'[城镇任务] 忠犬小金与小奇','这个「古怪的家伙」说先猜拳猜赢他，才愿意帮忙。但是每次要缴交1000仙币才能猜拳，之前人们的钱应该都是被他榨干，所以才无法获得协助。为了「和蔼的老人」只好硬着头皮上了。',2293),
  (402,7,'[城镇任务] 忠犬小金与小奇','获胜后「古怪的家伙」也很爽快的帮忙，说是带上好吃的肉类就可以发现走失的小金。既然如此准备「里肌肉」三十个，前往「冰霜高地(92，286)」找看看。',2294),
  (402,8,'[城镇任务] 忠犬小金与小奇','获胜后「古怪的家伙」也很爽快的帮忙，说是带上好吃的谷物就可以发现走失的小金。既然如此准备「五谷杂粮」三十个，前往「冰霜高地(91，338)」找看看。',2295),
  (402,9,'[城镇任务] 忠犬小金与小奇','从怪物的嘴下抢救回受伤的宠物赶快带牠回去找找「和蔼的老人(九天冰屋1F58，87)」看要怎么治疗。',2296),
  (402,10,'[城镇任务] 忠犬小金与小奇','「和蔼的老人」介绍我们找「动物医生(南原冰穴124，81)」制作必须的药品给予受伤的小狗。每天治疗一次应该也要治疗的十多天吧。',2297),
  (402,11,'[城镇任务] 忠犬小金与小奇','「动物医生(南原冰穴124，81)」其实也有饲养许多动物，只要仙童愿意每天提供「肉块」10个，就兑换一个「动物用治疗药」一天只能换一次「多换只会收走肉块不给治疗药」。将「动物用治疗药」交给「和蔼的老人(九天冰屋1F58，87)」使用在「受伤的宠物」身上只要十天就能治疗好。',2298),
  (402,12,'[城镇任务] 忠犬小金与小奇','每天提供「肉块」10个「动物医生(南原冰穴124，81)」兑换一个「动物用治疗药」一天只能换一次「多换只会收走肉块不给治疗药」。将「动物用治疗药」交给「和蔼的老人(九天冰屋1F58，87)」使用在「受伤的宠物」身上十天后就会见效。',2299),
  (402,13,'[城镇任务] 忠犬小金与小奇','多亏仙童不离不弃的照顾，受伤宠物也恢复了健康。「小奇」为了报答愿意在仙童身边侍奉，协助仙童，请向「和蔼的老人(九天冰屋1F58，87)」领取「神仙配件。忠犬哈士奇」',2300),
  (402,14,'[城镇任务] 忠犬小金与小奇','多亏仙童不离不弃的照顾，受伤宠物也恢复了健康。「小金」为了报答愿意在仙童身边侍奉，协助仙童，请向「和蔼的老人(九天冰屋1F58，87)」领取「神仙配件。忠犬黄金猎犬」',2301),
  (403,1,'[主线任务] 界限解除I','收集道具的第一步，请先收集「山叉怪的武器碎片」30个后，拿给「限界天尊(甘城127，138)」',2303),
  (403,2,'[主线任务] 界限解除I','收集道具的第一步，请先收集「银色矿石」30个后，拿给「限界天尊(甘城127，138)」',2304),
  (403,3,'[主线任务] 界限解除I','收集道具的第一步，请先收集「青藤」30个后，拿给「限界天尊(甘城127，138)」',2305),
  (403,4,'[主线任务] 界限解除I','收集道具的第一步，请先收集「黑坛木」30个后，拿给「限界天尊(甘城127，138)」',2306),
  (403,5,'[主线任务] 界限解除I','收集道具的第二步，请先收集「穿山甲的皮」30个后，拿给「限界天尊(甘城127，138)」',2307),
  (403,6,'[主线任务] 界限解除I','收集道具的第二步，请先收集「僵尸长袍」30个后，拿给「限界天尊(甘城127，138)」',2308),
  (403,7,'[主线任务] 界限解除I','收集道具的第二步，请先收集「熊皮」30个后，拿给「限界天尊(甘城127，138)」',2309),
  (403,8,'[主线任务] 界限解除I','收集道具的第二步，请先收集「豹皮」30个后，拿给「限界天尊(甘城127，138)」',2310),
  (403,9,'[主线任务] 界限解除I','收集道具的第三步，请先收集「魂魄宝珠」30个后，拿给「限界天尊(甘城127，138)」',2311),
  (403,10,'[主线任务] 界限解除I','收集道具的第三步，请先收集「蜜蜂的毒针」30个后，拿给「限界天尊(甘城127，138)」',2312),
  (403,11,'[主线任务] 界限解除I','收集道具的第三步，请先收集「泥怪的卵」30个后，拿给「限界天尊(甘城127，138)」',2313),
  (403,12,'[主线任务] 界限解除I','收集道具的第三步，请先收集「蚌精产的干贝」30个后，拿给「限界天尊(甘城127，138)」',2314),
  (403,13,'[主线任务] 界限解除I','收集道具的第四步，请先收集「金之精」30个后，拿给「限界天尊(甘城127，138)」',2315),
  (403,14,'[主线任务] 界限解除I','收集道具的第四步，请先收集「木之精」30个后，拿给「限界天尊(甘城127，138)」',2316),
  (403,15,'[主线任务] 界限解除I','收集道具的第四步，请先收集「水之精」30个后，拿给「限界天尊(甘城127，138)」',2317),
  (403,16,'[主线任务] 界限解除I','收集道具的第四步，请先收集「火之精」30个后，拿给「限界天尊(甘城127，138)」',2318),
  (403,17,'[主线任务] 界限解除I','收集道具的第四步，请先收集「土之精」30个后，拿给「限界天尊(甘城127，138)」',2319),
  (403,18,'[主线任务] 界限解除I','收集道具的第五步，请先收集「千年冰晶心脏」30个后，拿给「限界天尊(甘城127，138)」前往「冰魂谷」找寻稀有的菁英怪物「冰魂巨石长牙」击倒后有机率可以获得。',2320),
  (403,19,'[主线任务] 界限解除I','请准备仙币200万，拿给「限界天尊(甘城127，138)」即可完成「限界解除I」任务。',2321),
  (404,1,'[地图任务] 游鸿蒙','你向「鸿蒙土地公」接取了「游鸿蒙」任务。第一站的记录点是(鸿蒙境393，87)你可以看到「地烈黑洞」',2323),
  (404,2,'[地图任务] 游鸿蒙','你向「鸿蒙土地公」接取了「游鸿蒙」任务。第二站的记录点是(鸿蒙境576，82)你可以看到「太乙真人庙」',2324),
  (404,3,'[地图任务] 游鸿蒙','你向「鸿蒙土地公」接取了「游鸿蒙」任务。第三站的记录点是(鸿蒙境526，304)你可以看到「玉鼎真人庙」',2325),
  (404,4,'[地图任务] 游鸿蒙','你向「鸿蒙土地公」接取了「游鸿蒙」任务。第四站的记录点是(鸿蒙境111，289)你可以看到「化血黑洞」',2326),
  (404,5,'[地图任务] 游鸿蒙','你向「鸿蒙土地公」接取了「游鸿蒙」任务。第五站的记录点是(鸿蒙境421，377)你可以看到「张奎庙」',2327),
  (404,6,'[地图任务] 游鸿蒙','你向「鸿蒙土地公」接取了「游鸿蒙」任务。第六站的记录点是(鸿蒙境276，457)你可以看到「碧游宫」',2328),
  (404,7,'[地图任务] 游鸿蒙','你向「鸿蒙土地公」接取了「游鸿蒙」任务。第七站的记录点是(鸿蒙境636，458)你可以看到「金光黑洞」',2329),
  (404,8,'[地图任务] 游鸿蒙','你向「鸿蒙土地公」接取了「游鸿蒙」任务。最终站请找「鸿蒙土地婆」回报。地点是(鸿蒙境610，586)你可以看到「邓婵玉庙」',2330),
  (405,1,'[地图任务] 游截仙','你向「截仙土地公」接取了「游截仙」任务。第一站的记录点是(截仙遗址669，287)你可以看到「红沙黑洞」',2332),
  (405,2,'[地图任务] 游截仙','你向「截仙土地公」接取了「游截仙」任务。第二站的记录点是(截仙遗址517，338)你可以看到「圣灵洞」',2333),
