  (412,6,'[地图任务] 闯冰霜','你向「冰霜土地公」接取了「闯冰霜」任务。第六站的记录点是(冰霜高地372，135)旁边就是「冰魂谷入口」',2387),
  (412,7,'[地图任务] 闯冰霜','你向「冰霜土地公」接取了「闯冰霜」任务。第七站的记录点是(冰霜高地377，247)旁边就是「黄天化庙」',2388),
  (412,8,'[地图任务] 闯冰霜','你向「冰霜土地公」接取了「闯冰霜」任务。第八站的记录点是(冰霜高地411，304)旁边就是「赵公明庙」',2389),
  (412,9,'[地图任务] 闯冰霜','你向「冰霜土地公」接取了「闯冰霜」任务。最终站请找「冰霜土地婆」回报。地点是(冰霜高地358，411)旁边就是「南原冰穴」',2390),
  (413,1,'[地图任务] 闯太极','你向「太极土地公」接取了「闯太极」任务。第一站的记录点是(太极境258，333)旁边就是「冰火庙」',2392),
  (413,2,'[地图任务] 闯太极','你向「太极土地公」接取了「闯太极」任务。第二站的记录点是(太极境217，118)旁边就是「雪晶洞」',2393),
  (413,3,'[地图任务] 闯太极','你向「太极土地公」接取了「闯太极」任务。第三站的记录点是(太极境370，239)旁边就是「烈焱穴」',2394),
  (413,4,'[地图任务] 闯太极','你向「太极土地公」接取了「闯太极」任务。最终站请找「太极土地婆」回报。地点是(太极境370，59)旁边就是「北熇石塔」',2395),
  (414,1,'[战宠破顶] 驯宠达人I','你发现一位可怜人士，但是口气上却又十分高傲。或许是心血来潮吧，你答应了他的要求。收集：「里肌肉、火之精、绒毛鸭的肉、蘑菇各30个」交给「无名乞丐(甘城156，138)」',2397),
  (414,2,'[战宠破顶] 驯宠达人I','辛辛苦苦的帮忙却被痛骂一顿，真是何苦来之。从言谈之中，感觉「无名乞丐」好像对于饲养动物十分在行。下个考验是耐心与实力，请先经过3小时后再过来，届时要准备好：「蛮力散，延命散，强脑散，驰行散」各五个。交给「无名乞丐(甘城156，138)」',2398),
  (414,3,'[战宠破顶] 驯宠达人I','诚意感动了「无名乞丐」而他也述说起自己的身世，过往曾是位专门饲育「战宠」的专家，因得罪了他人不得不隐姓埋名，沦落于此。但对于饲育战宠还是充满热诚，当然你愿意继续协助。目前要调配收集来的饲料与药品，请经过5小时后再过来找「无名乞丐(甘城156，138)」看看。',2399),
  (414,4,'[战宠破顶] 驯宠达人I','嗯？应该没有听错吧，因为肚子饿所以想要吃些东西补一下？不是说要如何培养，怎么变成去抓，而且要吃掉？高人的想法总是不一样，先去「枫华镇外抓一只绒毛鸭」带给「无名乞丐(甘城156，138)」吧。',2400),
  (414,5,'[战宠破顶] 驯宠达人I','基本关过了，现在是进阶关卡。请去抓一头「双头风虎」回来，但是不告知要去哪抓，说那个也是训练的一环。抓到「双头风虎」后再回去找「无名乞丐(甘城156，138)」',2401),
  (414,6,'[战宠破顶] 驯宠达人I','又是绒毛鸭？除了要会捕捉，当然也要会培育。请带一只「等级有50级(含)以上的绒毛鸭」过来给「无名乞丐(甘城156，138)」。说甚么这样肉质比较结实，该不会受骗上当了？',2402),
  (414,7,'[战宠破顶] 驯宠达人I','总共交付两只绒毛鸭、一头双头风虎，而全部都经过培育后成为最终的试炼的挑战。请单人打倒「无名乞丐」所培育的三个战宠。准备好以后再与「无名乞丐(甘城156，138)」进行交谈，好开始挑战。',2403),
  (414,8,'[战宠破顶] 驯宠达人I','挑战成功「无名乞丐(甘城156，138)」也花费了大量精力，请准备10万仙币。可开启身上的某种特殊能力，可锻炼装备中的战宠等级上限突破200级。',2404),
  (415,1,'[城镇任务] 三仙姑战天尊','你先是答应了「碧霄」寻回她的坐骑「花翎鸟」但是，一但寻回坐骑就会前往找「元始天尊」复仇吧。这样真的好吗？自己苦想也没用，先前往「鸿蒙境-金光黑洞外639，448」寻回「花翎鸟」后带回去给「碧霄」',2406),
  (415,2,'[城镇任务] 三仙姑战天尊','找回「花翎鸟」了，带回去交给「碧霄(果城156，158)」完成一件事情。',2407),
  (415,3,'[城镇任务] 三仙姑战天尊','再次接受「碧霄」的委托，前往找寻「琼霄(果城113，175)」协助帮忙处理她的坐骑病情。',2408),
  (415,4,'[城镇任务] 三仙姑战天尊','根据「琼霄」的说法，旁边那位病恹恹的小童就是她的坐骑「鸿鹄」变换而成，且根据「碧霄」的诊治需要前往「参天林-巨林圣殿(220，520)」找寻「树灵心叶」才能进行医治。',2409),
  (415,5,'[城镇任务] 三仙姑战天尊','抵达「巨林圣殿」却发现「琼霄」已经先行前往，还被「巨林圣殿守卫」给包围了起来。准备好再过来，再次与「巨林圣殿守卫」交谈就是要打到他们救出「琼霄」了。',2410),
  (415,6,'[城镇任务] 三仙姑战天尊','打到「巨林圣殿守卫」后成功获得「树灵心叶」接下来将其带回去医治「鸿鹄(果城118，174)」。',2411),
  (415,7,'[城镇任务] 三仙姑战天尊','将「树灵心叶」给予「鸿鹄」后看样子恢复许多了。告诉「琼霄(果城113，175)」再完成一件事。',2412),
  (415,8,'[城镇任务] 三仙姑战天尊','与「琼霄」交谈后得知，她也与「碧霄」相同，想要对「元始天尊」进行复仇，希望仙童能找「云霄(果城90，156)」一同前往。',2413),
  (416,1,'[城镇任务] 黄河阵救仙姑','你与「赵公明灵体」交谈，得知其实此场战斗乃是命中注定。但是赵公明也不愿几位妹妹就此消逝。希望仙童前往「寒羽荒原62，433」进入「地底迷宫」并且深入「地底迷宫五楼59，，14」的「九曲黄河阵入口」内。入阵后前往「九曲黄河阵(最深处63，109)」内，救助「云霄三姊妹」',2415),
  (416,2,'[城镇任务] 黄河阵救仙姑','战或不战？既然决定要帮「赵公明」救助云霄三姊妹，那么无论胜负都只能努力下去了。',2416),
  (416,3,'[城镇任务] 黄河阵救仙姑','最终还是与「元始天尊」进行战斗了。这个行动是对是错回去找「赵公明灵体(果城87，160)」询问便知。',2417),
  (417,1,'[战宠破顶] 驯宠达人II','「无名乞丐」十分兴奋的说了一堆话，简单说就是带「灵狐之气」60个、「疗伤药」90个、「益气药」60个。再回来「甘城156，138」交给「无名乞丐」',2419),
  (417,2,'[战宠破顶] 驯宠达人II','给予物品后，「无名乞丐」就开始调配起药剂了。说是这次的药剂效果较强，希望抓比较强的动物做实验，前往「雨龙森林」捕捉一个「棕熊」战宠。再回来「甘城156，138」交给「无名乞丐」',2420),
  (417,3,'[战宠破顶] 驯宠达人II','为了确保实验正确，「无名乞丐」希望你可以捕捉更强的战宠，听说「夹龙纵谷」有更为强大的「流氓熊」请前往捕捉一头后，交给「无名乞丐(甘城156，138)」',2421),
  (417,4,'[战宠破顶] 驯宠达人II','药剂和实验用的战宠均已准备完成，接下来请稍后五小时，等待准备完成之后再过来。届时就可以挑战「无名乞丐」培育的新战宠了。',2422),
  (417,5,'[战宠破顶] 驯宠达人II','看样子这次的结果并不让「无名乞丐」感到满意，想要调整配方。请再准备「灵狐之气」90个、「益气药」30个，另外再去「枫华镇-炼丹房」买「圣兽粮食」30个。交给「无名乞丐(甘城156，138)」',2423),
  (417,6,'[战宠破顶] 驯宠达人II','再次收集完成后，经过一番思考「无名乞丐」希望你再次前往「夹龙纵谷」捕捉一头「流氓熊」并且将他锻炼到LV70交给「无名乞丐(甘城156，138)」',2424),
  (417,7,'[战宠破顶] 驯宠达人II','「无名乞丐」这次自信满满地说出，保证没有问题。请准备完全后再过来挑战。',2425),
  (417,8,'[战宠破顶] 驯宠达人II','经过一连串的帮忙，成功的验证出想要提升战宠能力的方法。请准备20万仙币提供给「无名乞丐(甘城156，138)」就能打通身上的经脉，让装备中的战宠最高等级提升到224级。',2426),
  (418,1,'[主线任务] 界限解除II','材料准备第一步骤，请准备「完美木材」、「完美石材」各30个，拿给「限界天尊(甘城127，138)」',2428),
  (418,2,'[主线任务] 界限解除II','材料准备第一步骤，请准备「完美石材」、「完美陶瓦」各30个，拿给「限界天尊(甘城127，138)」',2429),
  (418,3,'[主线任务] 界限解除II','材料准备第一步骤，请准备「完美构件」、「完美石材」各30个，拿给「限界天尊(甘城127，138)」',2430),
  (418,4,'[主线任务] 界限解除II','材料准备第二步骤，请准备「稀材-青龙石」、「稀材-白虎石」各4个，拿给「限界天尊(甘城127，138)」',2431),
  (418,5,'[主线任务] 界限解除II','材料准备第二步骤，请准备「稀材-白虎石」、「稀材-朱雀石」各4个，拿给「限界天尊(甘城127，138)」',2432),
  (418,6,'[主线任务] 界限解除II','材料准备第二步骤，请准备「稀材-玄武石」、「稀材-麒麟石」各4个，拿给「限界天尊(甘城127，138)」',2433),
  (418,7,'[主线任务] 界限解除II','材料准备第三步骤，请前往「冰魂谷」找寻稀有的菁英怪物「冰魂巨石长牙」击倒后有机率获得「千年冰晶心脏」收集30个后，拿给「限界天尊(甘城127，138)」。',2434),
  (418,8,'[主线任务] 界限解除II','请准备仙币250万，拿给「限界天尊(甘城127，138)」即可完成「限界解除II」任务。',2435);

