  (12,0,'仙界警戒',5045,'11111111',0,2400,30,9255,5046,'与莫莫聚落仙界守卫兵长对话， 将警戒令交给驻守在茄城仙界守卫兵长。 (茄城客栈-神兽仓管旁)','4.仙币+EXP(人)/9.名声+EXP(人)+木钥匙',1,27),
  (13,0,'仙界警戒',5046,'11111111',0,2400,30,9255,5047,'与茄城仙界守卫兵长对话， 将警戒令交给驻守在果城仙界守卫兵长。 (果城炼丹房前方)','5.仙币+EXP(人)/9.名声+EXP(人)+木钥匙',1,28),
  (14,0,'仙界警戒',5047,'11111111',0,2400,30,9255,5048,'与果城仙界守卫兵长对话， 将警戒令交给驻守在青采聚落仙界守卫兵长。 (进门正右方)','6.仙币+EXP(人)/9.名声+EXP(人)+木钥匙',1,29),
