  (18,0,'普贤秘宝',0,'11111111',0,2400,1,9255,0,'仙界内散布着普贤真人封神前所遗留的宝箱， 传说内有神兵利器，开启时需有对应的钥匙。 (普贤木箱、铜箱、铁箱、银箱、金箱)',NULL,0,33),
  (19,0,'周末领经验',0,'11100011',0,2400,1,9255,0,'每周星期五开机至星期一 11:00 关机， 每天可与NPC「活动仙童」领取效果一次。 (经验提升100%%(1HR))(直接使用)',NULL,0,34),
  (20,0,'守墓人',5065,'11111111',0,2400,70,9255,5065,'与太极境 受伤的守墓人对话， 进入陵寝打倒盗墓贼，收集盗墓贼刀柄， 收集15个后找 受伤的守墓人回报任务。','名声+御雷符',1,35),
  (20,1,'守墓人',5065,'11111111',0,2400,70,9255,5065,'与太极境 受伤的守墓人对话， 进入陵寝打倒秘密部队，收集部队徽章， 收集10个后找 受伤的守墓人回报任务。','名声+御火符',1,36),
  (20,2,'守墓人',5065,'11111111',0,2400,70,9255,5065,'与太极境 受伤的守墓人对话， 进入陵寝打倒刀剑师傅，收集刀剑师傅手镯， 收集5个后找 受伤的守墓人回报任务。','名声+御风符',1,37),
  (20,3,'守墓人',5065,'11111111',0,2400,70,9255,5065,'与太极境 受伤的守墓人对话， 进入陵寝祭祀遗族亡魂，取得感谢文， 收集10个后找 受伤的守墓人回报任务。','名声+10000仙币+雷/火/风石各1',1,38),
