CREATE OR REPLACE VIEW god2_game.vw_xjz_current_evidence_pack_summary AS
SELECT 'sources' AS evidence_area, COUNT(*) AS row_count, MIN(source_path) AS first_key FROM god2_game.xjz_evidence_pack_sources
UNION ALL SELECT 'god_menu', COUNT(*), MIN(name_zh_tw) FROM god2_game.xjz_god_menu_evidence
UNION ALL SELECT 'combat_pet_quality_star', COUNT(*), MIN(CAST(quality_level AS char)) FROM god2_game.xjz_combat_pet_quality_star_evidence
UNION ALL SELECT 'item_effect_visual', COUNT(*), MIN(CONCAT(source_table, ':', effect_key)) FROM god2_game.xjz_item_effect_visual_evidence
UNION ALL SELECT 'monster_visual', COUNT(*), MIN(CONCAT(source_table, ':', visual_id)) FROM god2_game.xjz_monster_visual_evidence
UNION ALL SELECT 'mission_text', COUNT(*), MIN(CONCAT(mission_id, ':', step_no)) FROM god2_game.xjz_mission_text_evidence
UNION ALL SELECT 'daily_mission', COUNT(*), MIN(CONCAT(daily_mission_id, ':', branch_id)) FROM god2_game.xjz_daily_mission_evidence;


